        #region Instant student list for individual staff based on class course staff 

        public async Task<ActionResult> InstantStudentForSubjectStaff()
        {
            try
            {
                if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
                {
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                    ExaminationViewModel objExamination = new ExaminationViewModel();

                    objExamination.liClassList = await Task.Run(() => (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new CourseWiseStaffList() { STAFF_ID = sUserId },
                         ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClassList), sAcademicYear).DataSource.Data);

                    return View(objExamination);
                }
                else
                {
                    return RedirectToAction("ErrorMessage", "error");
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "InternalAssessment", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("ExaminationController", "InternalAssessment", ex.Message);
                }
                return RedirectToAction("Index", "Account");
            }
        }
        public async Task<string> GetCourseByClassIdAndStaffId(string sClassId)
        {
            string sOption = string.Empty;
            DataTable dtCourseList = new DataTable();
            DataTable dtClassList = new DataTable();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                using (ExaminationViewModel objExamination = new ExaminationViewModel())
                {
                    try
                    {

                        var liCourseList = await Task.Run(() => (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CourseWiseStaffInfo() { CLASS_ID = sClassId, STAFF_ID = sUserId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseListbyStaffId), sAcademicYear).DataSource.Data);
                        if (liCourseList != null && liCourseList.Count > 0)
                        {
                            var liCiaBlockList = await Task.Run(() => (List<CIA_BLOCK_LIST>)CMSHandler.FetchData<CIA_BLOCK_LIST>(null,
                                SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCIABlockList), sAcademicYear).DataSource.Data);

                            foreach (var item in liCourseList)
                            {
                                sOption += "<option value=" + item.COURSE_ID + " >" + item.COURSE_TITLE + " </option>";
                            }// End Loop ....
                        }// End If Course List ....
                    }
                    catch (Exception ex)
                    {
                        using (ErrorLog objHandler = new ErrorLog())
                        {
                            objHandler.WriteError("ExaminationController", "GetCourseListByClassIdAndStaffId", "Err MSg: " + ex.Message, "Query is empty!");
                            objHandler.WriteError("ExaminationController", "GetCourseListByClassIdAndStaffId", ex.Message);
                        }
                    }
                }
            }
            else
            {
                sOption = "204";

            }
            return sOption;
        }
        public ActionResult BindInstantExamStudentsByClassCourseWise(string sClassId, string sCoursId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            var liCIATotal = new List<CIA_TOTAL>();

            var liInstantStudent = new List<CIA_TOTAL>();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    CIA_COURSE_INFO.COURSE_ID = sCoursId;
                    ObjViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    var checkClassId = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new CP_CLASSES() { CLASS_ID = sClassId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckClassType)).DataSource.Data;
                    if (checkClassId != null && checkClassId.Count > 0)
                    {
                        var classType = checkClassId.FirstOrDefault().CLASS_TYPE;
                        if (classType != Common.CLASS_TYPE.R_Regular)
                        {
                            //var FetchRegularClass = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckClassType)).DataSource.Data;

                            var FetchRegularClass = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new CP_CLASSES { CLASS_ID = sClassId, COURSE_ID = sCoursId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalStuIdandClassId), sAcademicYear).DataSource.Data;
                            if (FetchRegularClass != null && FetchRegularClass.Count > 0)
                            {

                                CIA_COURSE_INFO.COURSE_ID = sCoursId;
                                var groupClassId = FetchRegularClass.GroupBy(o => o.CLASS_ID).ToList();
                                foreach (var classItem in groupClassId)
                                {
                                    string student_id = string.Empty;
                                    foreach (var regStudent in FetchRegularClass)
                                    {
                                        if (regStudent.CLASS_ID == classItem.FirstOrDefault().CLASS_ID)
                                        {
                                            student_id += regStudent.STUDENT_ID + ',';
                                        }
                                    }
                                    student_id = student_id.TrimEnd(',');
                                    CIA_COURSE_INFO.CLASS_ID = classItem.FirstOrDefault().CLASS_ID;
                                    string opSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseListForInstant).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester);
                                    var liOpCourse = (List<ClassCourse>)CMSHandler.FetchData<ClassCourse>(CIA_COURSE_INFO, opSQL, sAcademicYear).DataSource.Data;
                                    if (liOpCourse != null && liOpCourse.Count > 0)
                                    {
                                        foreach (var item in liOpCourse)
                                        {
                                            CIA_COURSE_INFO.COURSE_ID = item.COURSE_ID;
                                            var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATotalforIndivudalStaffInstant), sAcademicYear).DataSource.Data;
                                            if (liCIA_Total != null && liCIA_Total.Count > 0)
                                            {
                                                liCIA_Total.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                                liCIATotal = (liCIATotal != null && liCIATotal.Count > 0) ? liCIATotal.Concat(liCIA_Total).ToList() : liCIA_Total;
                                            }
                                        }
                                        var liStudent = (List<INSTANT_STUDENT>)CMSHandler.FetchData<INSTANT_STUDENT>(CIA_COURSE_INFO, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByClassIdAndStudentId).Replace("?STUDENT_ID", student_id), sAcademicYear).DataSource.Data;
                                        if (liStudent != null && liStudent.Count > 0 && liCIATotal != null && liCIATotal.Count > 0)
                                        {
                                            int nInstantMark = 0;
                                            foreach (var item in liStudent)
                                            {
                                                if (item.CLASS_YEAR == "1")
                                                {

                                                    nInstantMark = (item.PROGRAMME_LEVEL == "1") ? 16 : 20;
                                                }
                                                else
                                                {
                                                    nInstantMark = (item.PROGRAMME_LEVEL == "1") ? 10 : 13;

                                                }
                                                var liExist = liCIATotal.Where(x => x.STUDENT_ID == item.STUDENT_ID).ToList();
                                                if (liExist != null && liExist.Count > 0)
                                                {
                                                    var liInstant = liExist.Where(x => Convert.ToInt32(x.TOTAL) < nInstantMark).ToList();
                                                    if (liInstant != null && liInstant.Count > 0)
                                                    {
                                                        var licheckount = liInstant.GroupBy(o => o.COURSE_ID).ToList();
                                                        if (licheckount.Count == 1)
                                                        {
                                                            var courseCount = liInstant.Where(o => o.COURSE_ID == sCoursId).ToList();
                                                            if (courseCount != null && courseCount.Count > 0)
                                                            {
                                                                liInstantStudent = (liInstantStudent != null && liInstantStudent.Count > 0) ? liInstantStudent.Concat(liInstant).ToList() : liInstant;
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                            ObjViewModel.liCIA_Total = liInstantStudent;
                                        }
                                        else
                                        {
                                            ObjJsonData.Message = "No Student Marks Found !!! .";
                                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                        }
                                        ObjViewModel.liCIA_Total = liInstantStudent;
                                    }
                                    else
                                    {
                                        ObjJsonData.Message = "No Course Found !!! .";
                                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                    }
                                }
                            }
                        }
                        else
                        {
                            string sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseListCourseIDByClassId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester);
                            var liCourse = (List<ClassCourse>)CMSHandler.FetchData<ClassCourse>(CIA_COURSE_INFO, sSQL, sAcademicYear).DataSource.Data;
                            if (liCourse != null && liCourse.Count > 0)
                            {
                                foreach (var item in liCourse)
                                {
                                    CIA_COURSE_INFO.COURSE_ID = item.COURSE_ID;
                                    var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATotal), sAcademicYear).DataSource.Data;
                                    if (liCIA_Total != null && liCIA_Total.Count > 0)
                                    {
                                        liCIA_Total.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                        liCIATotal = (liCIATotal != null && liCIATotal.Count > 0) ? liCIATotal.Concat(liCIA_Total).ToList() : liCIA_Total;
                                    }
                                }
                                var liStudent = (List<INSTANT_STUDENT>)CMSHandler.FetchData<INSTANT_STUDENT>(CIA_COURSE_INFO, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByClassId), sAcademicYear).DataSource.Data;
                                if (liStudent != null && liStudent.Count > 0 && liCIATotal != null && liCIATotal.Count > 0)
                                {
                                    int nInstantMark = 0;
                                    foreach (var item in liStudent)
                                    {
                                        if (item.CLASS_YEAR == "1")
                                        {

                                            nInstantMark = (item.PROGRAMME_LEVEL == "1") ? 16 : 20;
                                        }
                                        else
                                        {
                                            nInstantMark = (item.PROGRAMME_LEVEL == "1") ? 10 : 13;

                                        }
                                        var liExist = liCIATotal.Where(x => x.STUDENT_ID == item.STUDENT_ID).ToList();
                                        if (liExist != null && liExist.Count > 0)
                                        {
                                            var liInstant = liExist.Where(x => Convert.ToInt32(x.TOTAL) < nInstantMark).ToList();
                                            if (liInstant != null && liInstant.Count > 0)
                                            {
                                                var licheckount = liInstant.GroupBy(o => o.COURSE_ID).ToList();
                                                if (licheckount.Count == 1)
                                                {
                                                    var courseCount = liInstant.Where(o => o.COURSE_ID == sCoursId).ToList();
                                                    if (courseCount != null && courseCount.Count > 0)
                                                    {
                                                        liInstantStudent = (liInstantStudent != null && liInstantStudent.Count > 0) ? liInstantStudent.Concat(liInstant).ToList() : liInstant;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    ObjViewModel.liCIA_Total = liInstantStudent;
                                }
                                else
                                {
                                    ObjJsonData.Message = "No Student Marks Found !!! .";
                                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                }
                                ObjViewModel.liCIA_Total = liInstantStudent;
                            }
                            else
                            {
                                ObjJsonData.Message = "No Course Found !!! .";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindInstantExamStudentsByClassId", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
