        public string SendOTP(string sJson)
        {
            string sResult = string.Empty;
            string sOTP = string.Empty;
            string sOTPContent = string.Empty;
            string sTempId = string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string academicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            CommunicationController communicationCon = new CommunicationController();
            if (sUserId != null)
            {
                // 
                var fetchStaff = (List<STF_PERSONAL_INFO>)CMSHandler.FetchData<STF_PERSONAL_INFO>(new STF_PERSONAL_INFO() { STAFF_ID = sUserId }, StaffSQL.GetStaffSQL(StaffSQLCommands.FetchStaffListbyStaffId), academicYear).DataSource.Data;
                if (fetchStaff != null && fetchStaff.Count > 0)
                {
                    if (Session[Common.SESSION_VARIABLES.OTP] != null)
                        sOTP = Session[Common.SESSION_VARIABLES.OTP].ToString();
                    else
                    {

                        sOTP = CommonMethods.GenerateOTP();
                        Session[Common.SESSION_VARIABLES.OTP] = sOTP;
                    }
                    communicationCon.sSmsMode = Common.MessageType.OTP;
                    communicationCon.acdemicYear = academicYear;
                    communicationCon.sTextMessage = "CIA Submission OTP";

                    var MessageContent = (List<SMS_USERDEFINED_TEMPLATE>)CMSHandler.FetchData<SMS_USERDEFINED_TEMPLATE>(
                        new SMS_USERDEFINED_TEMPLATE() { TEMPLATE_ID = Common.SMS_TEMPLATE.MARK_SUBMISSION_OTP },
                        SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSMSTemplateText),
                        academicYear).DataSource.Data;

                    if (MessageContent != null && MessageContent.Count > 0)
                    {
                        sOTPContent = MessageContent.FirstOrDefault().TEMPLATE_TEXT
                            .Replace(Common.Delimiter.AT + Common.STU_PERSONAL_INFO.FIRST_NAME, fetchStaff.FirstOrDefault().FIRST_NAME)
                            .Replace(Common.Delimiter.AT + "sOTP", sOTP)
                            .Replace(Common.Delimiter.AT + "OPTHEADER", "CIA Submission")
                            .Replace(Common.Delimiter.AT + "OTP", sOTP);
                        sTempId = MessageContent.FirstOrDefault().FIELDS_IDS;
                    }
                    else
                    {
                        sOTPContent = "Dear " + fetchStaff.FirstOrDefault().FIRST_NAME + ", Your Verification code is " + sOTP + " For CIA Submission. St. Joseph's College of Arts & Science (Autonomous) - Cuddalore.";
                    }

                    communicationCon.liSMS.Add(new MessageResult.sms() { to = fetchStaff.FirstOrDefault().MOBILE_NO, message = sOTPContent, custom = fetchStaff.FirstOrDefault().STAFF_ID, custom1 = null, custom2 = "0", CreditCount = Convert.ToString(1) });
                    communicationCon.listbulkSMS.Add(new MessageResult.listsms() { mobiles = fetchStaff.FirstOrDefault().MOBILE_NO, sms = sOTPContent, class_id = null, receipient_id = fetchStaff.FirstOrDefault().STAFF_ID, tempid = sTempId });
                }
                communicationCon.SendMessageV1();
                // communicationCon.SendSMSFromDovesoft();
            }
            else
            {
                sResult = "Something went wrong try again!!!";
            }
            return sResult;
        }
