        [HttpPost]
        public string SaveCIAMarks(string jsonCIA_MARKS, string sCourseId, string sClassId, string sOTP)
        {
            string sResult = string.Empty;

            try
            {
                if (Session[Common.SESSION_VARIABLES.OTP] != null)
                {
                    string OTP = sOTP;
                    string sSessionOTP = CommonMethods.CreateMD5(Session[Common.SESSION_VARIABLES.OTP].ToString());
                    string sContent = string.Empty;
                    string sUserAccountId = string.Empty;
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    if (string.Equals(sSessionOTP.ToUpper(), CommonMethods.CreateMD5(OTP.ToUpper())))
                    {

                        sResult = SaveCIAAsync(jsonCIA_MARKS, sCourseId, sClassId);
                    }
                    else
                    {
                        sResult = "OTP Invalid";
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "SaveCIAMarks", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("ExaminationController", "SaveCIAMarks", ex.Message);
                }
                sResult = Common.Messages.FailedToSaveRecords;
            }
            return sResult;
        }
        [HttpPost]
        public string SaveCIAMarksFromCOE(string jsonCIA_MARKS, string sCourseId, string sClassId)
        {
            string sResult = string.Empty;

            try
            {
                sResult = SaveCIAAsync(jsonCIA_MARKS, sCourseId, sClassId);

            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "SaveCIAMarks", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("ExaminationController", "SaveCIAMarks", ex.Message);
                }
                sResult = Common.Messages.FailedToSaveRecords;
            }
            return sResult;
        }
        private string SaveCIAAsync(string jsonCIA_MARKS, string sCourseId, string sClassId)
        {
            string sResult = string.Empty;
            bool insertFlag = false;
            bool updateFlag = false;
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                string sInsertQuery = string.Empty;
                string sInsertQueryCom = string.Empty;
                string sUpdateQuery = string.Empty;
                ResultArgs resultArgs = new ResultArgs();
                System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
                JSON_CIA_MARKS objJson = serializer.Deserialize<JSON_CIA_MARKS>(jsonCIA_MARKS);
                if (objJson.SAVE_CIA_MARKS != null && objJson.SAVE_CIA_MARKS.Count > 0)
                {
                    sInsertQuery = @"INSERT INTO CIA_GROUP_MARKS_?AC_YEAR (
                                STUDENT_ID,
                                COURSE_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK,
                                SEMESTER_ID,
                                ENTRY_ID)VALUES";
                    sInsertQueryCom = sInsertQuery;
                    foreach (var item in objJson.SAVE_CIA_MARKS)
                    {
                        if (string.IsNullOrEmpty(item.COURSE_GROUP_MARK))
                            item.COURSE_GROUP_MARK = "0";

                        if (string.IsNullOrEmpty(item.CIA_GROUP_MARK_ID))
                        {
                            sInsertQuery += "('" + item.STUDENT_ID.Trim() + "','" + item.COURSE_ID.Trim() + "','" + item.COURSE_GROUP_ID.Trim() + "','" + item.COURSE_GROUP_MARK.Trim() + "','" + item.SEMESTER_ID.Trim() + "','" + sUserId + "'),";
                            insertFlag = true;
                        }
                        else
                        {
                            sUpdateQuery += @"UPDATE CIA_GROUP_MARKS_?AC_YEAR SET STUDENT_ID='" + item.STUDENT_ID.Trim() + "', COURSE_ID='" + item.COURSE_ID.Trim() + "', COURSE_GROUP_ID='" + item.COURSE_GROUP_ID.Trim() + "', COURSE_GROUP_MARK='" + item.COURSE_GROUP_MARK.Trim() + "', SEMESTER_ID='" + item.SEMESTER_ID.Trim() + "', ENTRY_ID='" + sUserId + "' WHERE CIA_GROUP_MARK_ID='" + item.CIA_GROUP_MARK_ID.Trim() + "';";
                            updateFlag = true;
                        }
                    }
                    if (insertFlag)
                    {
                        sInsertQuery = sInsertQuery.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                        sInsertQuery = sInsertQuery.TrimEnd(',');
                        sInsertQuery = sInsertQuery + ";";
                    }

                    using (ExaminationViewModel objExamination = new ExaminationViewModel())
                    {
                        if (updateFlag)
                        {
                            sUpdateQuery = sUpdateQuery.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                            resultArgs = objExamination.ExcuteCIA_Marks(sUpdateQuery);

                        }
                        if (insertFlag)
                        {
                            resultArgs = objExamination.ExcuteCIA_Marks(sInsertQuery);
                        }
                        sResult = resultArgs.Success ? "Marks have been updated successfully...!" : Common.Messages.FailedToSaveRecords;
                    }


                    // var liFetchStudent = (List<STU_CLASS>)CMSHandler.FetchData<STU_CLASS>(new Stu_Course_Info() { CLASS_ID=sClassId,COURSE_ID=sCourseId},ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentByCourseIdAndClassId)).DataSource.Data;
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    CIA_COURSE_INFO.COURSE_ID = sCourseId;
                    CIA_COURSE_INFO.STAFF_ID = sUserId;
                    string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
                    var liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId), sAcademicYear).DataSource.Data;
                    if (liCIACourse_Info != null && liCIACourse_Info.Count > 0)
                    {
                        CIA_COURSE_INFO.COURSE_TYPE_ID = liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                        CIA_COURSE_INFO.SEMESTER_ID = liCIACourse_Info.FirstOrDefault().SEMESTER_ID;
                    }

                    var liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseTypeId), sAcademicYear).DataSource.Data;
                    if (liCIA_Component != null && liCIA_Component.Count > 0)
                    {
                        var liCIA_Marks_Info = new CIA_MARKS_INFO();
                        var liCIA_Total = new List<CIA_TOTAL>();
                        //var markInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIA_Marks_Info), sAcademicYear).DataSource.Data;
                        var componentInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAComponentsByCourseId), sAcademicYear).DataSource.Data;
                        var markInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIA_Marks_Info), sAcademicYear).DataSource.Data;
                        if (componentInfo != null && componentInfo.Count > 0)
                        {
                            foreach (var item in componentInfo)
                            {
                                var temp = markInfo.Where(o => o.STUDENT_ID == item.STUDENT_ID && o.COURSE_GROUP_ID == item.COURSE_GROUP_ID).ToList();
                                if (temp != null && temp.Count > 0) { item.COURSE_GROUP_MARK = temp.FirstOrDefault().COURSE_GROUP_MARK; item.CIA_GROUP_MARK_ID = temp.FirstOrDefault().CIA_GROUP_MARK_ID; }
                            }
                            componentInfo.ForEach(o => o.COURSE_GROUP_MARK = string.Equals(o.COURSE_GROUP_MARK, "0") ? "" : o.COURSE_GROUP_MARK);

                            var student = componentInfo.GroupBy(o => o.STUDENT_ID).Select(x => new CIA_TOTAL() { STUDENT_ID = x.FirstOrDefault().STUDENT_ID }).ToList();
                            // liCIA_Marks_Info = componentInfo;
                            liCIA_Total = student;
                        }
                        string sComponent = string.Empty;
                        string sInsert = "INSERT INTO `cia_status`(`CLASS_ID`,`COURSE_ID`,`STAFF_ID`,`ACADEMIC_YEAR`,`SEMESTER_ID`,?COMPONENT)VALUES";
                        string status = "0";
                        string Update = string.Empty;
                        string sValues = "(" + "'" + sClassId + "','" + sCourseId + "','" + sUserId + "'," + "'" + sAcademicYear + "','" + CIA_COURSE_INFO.SEMESTER_ID + "',";
                        int i = 1;
                        // Loop By Component ...
                        foreach (var item in liCIA_Component)
                        {
                            var liJsonStudent = (List<FETCH_CIA_MARKS>)CMSHandler.FetchData<FETCH_CIA_MARKS>(
                                new FETCH_CIA_MARKS()
                                {
                                    COURSE_ID = sCourseId,
                                    COURSE_GROUP_ID = item.CIA_GROUP_COMPONENT_ID,
                                    SEMESTER_ID = CIA_COURSE_INFO.SEMESTER_ID,
                                    STAFF_ID = sUserId,
                                    CLASS_ID = sClassId
                                },
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCiaMarkByComponent), sAcademicYear).DataSource.Data;
                            if (liJsonStudent != null && liJsonStudent.Count > 0)
                            {
                                if (liJsonStudent.Count == liCIA_Total.Count)
                                    status = "1";
                                else
                                    status = "2";
                            }
                            sValues += "'" + item.CIA_GROUP_COMPONENT_ID + " | " + status + "',";
                            sComponent += "COMPONENT_STATUS" + Convert.ToString(i) + ",";
                            Update += "COMPONENT_STATUS" + Convert.ToString(i) + "=" + "'" + item.CIA_GROUP_COMPONENT_ID + " | " + status + "',";
                            status = "0";
                            i++;
                        }
                        sInsert += sValues.TrimEnd(',') + ")";
                        string sUpdate = "UPDATE CIA_STATUS SET CLASS_ID = " + sClassId + ", COURSE_ID = " + sCourseId + ", STAFF_ID = " + sUserId + "," + Update.TrimEnd(',') + ",ACADEMIC_YEAR =" + sAcademicYear + ",SEMESTER_ID=" + CIA_COURSE_INFO.SEMESTER_ID + " WHERE UPLOAD_ID=";
                        var liExist = (List<Cia_Status>)CMSHandler.FetchData<Cia_Status>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.Fetch_CIA_Is_Exist), sAcademicYear).DataSource.Data;
                        if (liExist != null && liExist.Count > 0)
                        {
                            using (ExaminationViewModel objExamination = new ExaminationViewModel())
                            {
                                sUpdate += liExist.FirstOrDefault().UPLOAD_ID;
                                sUpdate = sUpdate.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                                resultArgs = objExamination.ExcuteCIA_Marks(sUpdate);
                            }
                        }
                        else
                        {
                            using (ExaminationViewModel objExamination = new ExaminationViewModel())
                            {
                                sInsert = sInsert.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                                sInsert = sInsert.Replace(Common.Delimiter.QUS + Common.SUP_CIA_COMPONENTS.COMPONENT, sComponent.TrimEnd(','));
                                resultArgs = objExamination.ExcuteCIA_Marks(sInsert);
                            }
                        }
                    }
                }
                else
                {
                    sResult = "No changes made !!";
                }
            }
            else
            {
                sResult = "Sorry Your Session is Expired.Please Login again !!";
            }

            return sResult;
        }

