        // Component Based CIA Entry
        public ActionResult ComponentBasedInternalAssessment()
        {
            try
            {
                if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
                {
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    ExaminationViewModel objExamination = new ExaminationViewModel();
                    CourseWiseStaffList objModel = new CourseWiseStaffList();

                    string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                    objModel.STAFF_ID = sUserId;
                    objModel.PAPER_TYPE = Common.PAPER_TYPE.Value_Education;
                    var licls = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClassList), sAcademicYear).DataSource.Data;
                    if (licls != null && licls.Count > 0)
                    {
                        var liCiaBlockList = (List<CIA_BLOCK_LIST>)CMSHandler.FetchData<CIA_BLOCK_LIST>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCIABlockList), sAcademicYear).DataSource.Data;
                        if (liCiaBlockList != null && liCiaBlockList.Count > 0)
                        {
                            foreach (var item in licls)
                            {
                                // Staff Wise Cia Block List ....
                                var liStaffWise = liCiaBlockList.Where(x => x.S_STAFF_ID == sUserId).ToList();
                                if (liStaffWise != null && liStaffWise.Count > 0)
                                {
                                    item.CIA_DISABLE = "disabled";
                                }
                                else
                                {
                                    // ClassWise Cia Block List ....
                                    var liClassWise = liCiaBlockList.Where(x => x.S_CLASS_ID == item.CLASS_ID).ToList();
                                    if (liClassWise != null && liClassWise.Count > 0)
                                    {
                                        item.CIA_DISABLE = "disabled";
                                    }

                                    // Programme Wise Cia Block List ....
                                    var liProgrammeWise = liCiaBlockList.Where(x => x.PROGRAMME_GROUP_ID == item.PROGRAMME_GROUP_ID).ToList();
                                    if (liProgrammeWise != null && liProgrammeWise.Count > 0)
                                    {
                                        item.CIA_DISABLE = "disabled";
                                    }

                                    // Programme Level (UG / PG) Wise Cia Block List ....
                                    var liProgrammeLevelWise = liCiaBlockList.Where(x => x.PROGRAMME_LEVEL == item.CLASS_LEVEL).ToList();
                                    if (liProgrammeLevelWise != null && liProgrammeLevelWise.Count > 0)
                                    {
                                        item.CIA_DISABLE = "disabled";
                                    }

                                    // Shift Wise Cia Block List ....
                                    var liShiftWise = liCiaBlockList.Where(x => x.SHIFT_ID == item.SHIFT).ToList();
                                    if (liShiftWise != null && liShiftWise.Count > 0)
                                    {
                                        item.CIA_DISABLE = "disabled";
                                    }
                                }
                                // End Else ...
                            }
                            // End Loop ...
                        }
                        objExamination.liClassList = licls;
                    }
                    return View(objExamination);
                }
                else
                {
                    return RedirectToAction("ErrorMessage", "error");
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "StaffBasedInternalAssessment", ex.Message);
                }
                return RedirectToAction("Index", "Account");
            }
        }

        public JsonResult BindComponentByCourseId(string sClassId, string sCourseId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    CIA_COURSE_INFO.COURSE_ID = sCourseId;

                    var liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId), sAcademicYear).DataSource.Data;
                    if (liCIACourse_Info != null && liCIACourse_Info.Count > 0)
                    {
                        CIA_COURSE_INFO.COURSE_TYPE_ID = liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                        CIA_COURSE_INFO.SEMESTER_ID = liCIACourse_Info.FirstOrDefault().SEMESTER_ID;

                        var liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseTypeId), sAcademicYear).DataSource.Data;
                        if (liCIA_Component != null && liCIA_Component.Count > 0)
                        {
                            ObjJsonData.sResult = "<option value='0'> -- Select -- </option>";
                            foreach (var item in liCIA_Component)
                            {
                                ObjJsonData.sResult += "<option value='" + item.CIA_GROUP_COMPONENT_ID + "'>" + item.COMPONENT + " - " + item.MAX_MARK + "</option>";
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindComponentByCourseId", ex.Message);
                    }
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        public ActionResult BindStudentComponentBasedEntry(string sClassId, string sCourseId, string sComponentId)
        {

            string sSQL = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            using (ExaminationViewModel objExamination = new ExaminationViewModel())
            {
                try
                {
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    CIA_COURSE_INFO.COURSE_ID = sCourseId;
                    CIA_COURSE_INFO.STAFF_ID = sUserId;
                    CIA_COURSE_INFO.COURSE_GROUP_ID = sComponentId;

                    // Fetch Course Details ....
                    objExamination.liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId), sAcademicYear).DataSource.Data;
                    if (objExamination.liCIACourse_Info != null && objExamination.liCIACourse_Info.Count > 0)
                    {
                        if (!string.IsNullOrEmpty(objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID) && !objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID.Equals("0"))
                        {
                            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
                            if (!string.IsNullOrEmpty(sActiveSemester))
                            {
                                if (sActiveSemester.Equals("1,3,5"))
                                    CIA_COURSE_INFO.SEMESTER = "ODD";
                                else
                                    CIA_COURSE_INFO.SEMESTER = "EVEN";
                            }

                            CIA_COURSE_INFO.COURSE_TYPE_ID = objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                            CIA_COURSE_INFO.SEMESTER_ID = objExamination.liCIACourse_Info.FirstOrDefault().SEMESTER_ID;
                            // Fetchl Component Details ...
                            objExamination.liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseGroupId), sAcademicYear).DataSource.Data;
                            // FetchMarks ...

                            var componentInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAComponentsByCourseAndComponentId), sAcademicYear).DataSource.Data;
                            var markInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIA_Marks_InfoByComponentId), sAcademicYear).DataSource.Data;

                            if (componentInfo != null && componentInfo.Count > 0)
                            {
                                foreach (var item in componentInfo)
                                {
                                    var temp = markInfo.Where(o => o.STUDENT_ID == item.STUDENT_ID && o.COURSE_GROUP_ID == item.COURSE_GROUP_ID).ToList();
                                    if (temp != null && temp.Count > 0)
                                    {
                                        item.COURSE_GROUP_MARK = temp.FirstOrDefault().COURSE_GROUP_MARK;
                                        item.CIA_GROUP_MARK_ID = temp.FirstOrDefault().CIA_GROUP_MARK_ID;
                                    }
                                }
                            }
                            componentInfo.ForEach(o => o.COURSE_GROUP_MARK = string.Equals(o.COURSE_GROUP_MARK, "0") ? "" : o.COURSE_GROUP_MARK);

                            var student = componentInfo.GroupBy(o => o.STUDENT_ID).Select(x => new CIA_TOTAL() { STUDENT_ID = x.FirstOrDefault().STUDENT_ID }).ToList();
                            objExamination.liCIA_Marks_Info = componentInfo;
                            objExamination.liCIA_Total = student;

                            // string SQL = string.Join(",", componentInfo.Select(o => o.CIA_GROUP_MARK_ID));
                            return View(objExamination);
                        }
                        else
                        {
                            return Json("Missing Course Type For This Course Please Meet Admin!!!", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("Missing Course Please Meet Admin!!!", JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "BindStudentsByCourseId", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "BindStudentsByCourseId", ex.Message);
                    }
                    return View(objExamination);
                }
            }
        }

