                if (programmes != null)
                {
                    examViewModel.Program = new SelectList(programmes, Common.CP_PROGRAMME_2017.PROGRAMME_GROUP_ID, Common.CP_PROGRAMME_2017.PROGRAMME_NAME);
                }

