                if (liFrequencyList != null && liFrequencyList.Count > 0)
                {
                    examViewModel.FrequencyList = new SelectList(liFrequencyList, Common.SUP_FEE_FREQUENCY.FREQUENCY_ID, Common.SUP_FEE_FREQUENCY.FREQUENCY_NAME);
                }
                return View(examViewModel);
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }


        }

        [UserRights("STUDENT")]
        public async Task<ActionResult> ExamRegistration()
        {
            string sSql = string.Empty;
            int nSemester = 0;
            string sSemesters = string.Empty;
            ExaminationViewModel ExamRegistrastionViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sAcademicYearId = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            if (!string.IsNullOrEmpty(sUserId))
            {
                try
                {
                    var objExamViewModel = new List<EXAM_REGISTRATION>();
                    var ObjExamRegistration = new EXAM_REGISTRATION();
                    var liBatchAndProgramme = new List<GET_PROGRAMME_AND_BATCH>();
                    var liSemesterResult = new List<SEMESTER_RESULT>();
                    var SemesterResult = new SEMESTER_RESULT();
                    var CollegeDetails = new CollegeDetails();
                    // Fetch College Details ....
                    ExamRegistrastionViewModel.liCollegeDetails = await Task.Run(() => (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data);
                    ObjExamRegistration.STUDENT_ID = sUserId;
                    List<EXAM_REGISTRATION> ObjExamRegistrationList = new List<EXAM_REGISTRATION>();
                    GET_ACTIVE_SEMESTER_BATCH objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();
                    List<GET_ACTIVE_SEMESTER_BATCH> liActiveSemester = new List<GET_ACTIVE_SEMESTER_BATCH>();
                    GET_PROGRAMME_AND_BATCH ObjProgramAndBatch = new GET_PROGRAMME_AND_BATCH();

                    // Fetch Program and Batch By Student Id .....
                    ObjProgramAndBatch.STUDENT_ID = sUserId;
                    liBatchAndProgramme = await Task.Run(() => (List<GET_PROGRAMME_AND_BATCH>)CMSHandler.FetchData<GET_PROGRAMME_AND_BATCH>(ObjProgramAndBatch,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchProgramAndBatchByStudentID), sAcademicYear).DataSource.Data);

                    // Fetch Active Semester By Batch Id .....
                    objActiveSemester.STUDENT_ID = sUserId;
                    objActiveSemester.BATCH = liBatchAndProgramme.FirstOrDefault().BATCH;
                    objActiveSemester.PROGRAMME = liBatchAndProgramme.FirstOrDefault().PROGRAMME;
                    liActiveSemester = await Task.Run(() => (List<GET_ACTIVE_SEMESTER_BATCH>)CMSHandler.FetchData<GET_ACTIVE_SEMESTER_BATCH>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveSemesterWithBatches), sAcademicYear).DataSource.Data);

                    // Get Student Information ...
                    ExamRegistrastionViewModel.liExamRegistrationModel = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjExamRegistration,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentDetailsForExamRegistration), sAcademicYear).DataSource.Data);
                    if (ExamRegistrastionViewModel.liExamRegistrationModel != null && ExamRegistrastionViewModel.liExamRegistrationModel.Count > 0)
                    {
                        if (ExamRegistrastionViewModel.liExamRegistrationModel.FirstOrDefault().SEMESTER_TYPE == "3")
                        {
                            liActiveSemester = await Task.Run(() => (List<GET_ACTIVE_SEMESTER_BATCH>)CMSHandler.FetchData<GET_ACTIVE_SEMESTER_BATCH>(objActiveSemester,
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentAllYearAndBatchWithSemester), sAcademicYear).DataSource.Data);
                        }
                    }

                    // Check Supplementry Exam Active By Programme ,...
                    var liFetchProgrammeNonSemester = (List<EXAM_SUPPLEMENTARY_SETTING_FOR_PROGRAMME>)CMSHandler.FetchData<EXAM_SUPPLEMENTARY_SETTING_FOR_PROGRAMME>(new EXAM_SUPPLEMENTARY_SETTING_FOR_PROGRAMME() { PROGRAMME_GROUP_ID = objActiveSemester.PROGRAMME, PROGRAMME_YEAR_ID = liBatchAndProgramme.FirstOrDefault().CLASS_YEAR, EXAM_SETTING_ID = ExamRegistrastionViewModel.liExamRegistrationModel.FirstOrDefault().EXAM_SETTING_ID },
                          ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckSupplementryExamByProgrammeGroupId), sAcademicYear).DataSource.Data;
                    if (liFetchProgrammeNonSemester != null && liFetchProgrammeNonSemester.Count > 0)
                    {
                        var Semester = (List<GET_ACTIVE_SEMESTER_BATCH>)CMSHandler.FetchData<GET_ACTIVE_SEMESTER_BATCH>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveSemesterWithBatchesForSupplementry), sAcademicYear).DataSource.Data;
                        string SQL = string.Empty;
                        var BatchExpiredYear = (List<SUP_BATCH_DURATION>)CMSHandler.FetchData<SUP_BATCH_DURATION>(new SUP_BATCH_DURATION { BATCH_ID = liBatchAndProgramme.FirstOrDefault().BATCH, APPLICATION_TYPE_ID = liFetchProgrammeNonSemester.FirstOrDefault().PROGRAMME_LEVEL_ID, }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchBatchExpiredYear)).DataSource.Data;
                        if (BatchExpiredYear != null && BatchExpiredYear.Count > 0)
                        {
                            SQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterResultForSupplementryRegistration).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.SEMESTER, string.Join(",", Semester.Select(o => o.SEMESTER).ToArray()));
                            for (int i = Convert.ToInt16(BatchExpiredYear.FirstOrDefault().BEGIN_YEAR); i < Convert.ToInt16(BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR); i++)
                            {

                                var tempSemesterResult = await Task.Run(() => (List<SEMESTER_RESULT>)CMSHandler.FetchData<SEMESTER_RESULT>(new SEMESTER_RESULT { STUDENT_ID = sUserId }, SQL, i.ToString()).DataSource.Data);
                                if (tempSemesterResult != null && tempSemesterResult.Count > 0)
                                {
                                    foreach (var sem in tempSemesterResult)
                                    {
                                        sem.AC_YEAR = i.ToString();
                                        liSemesterResult.Add(sem);
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        // Get All The Written Papers By Active Semester and Academic Year and Student Id .....
                        int.TryParse(liActiveSemester.Where(o => o.AC_YEAR == sAcademicYear).SingleOrDefault().SEMESTER, out nSemester);
                        sSemesters = CommonMethods.SemestersInComma(nSemester);
                        foreach (var item in liActiveSemester)
                        {
                            item.STUDENT_ID = sUserId;
                            int.TryParse(item.SEMESTER, out nSemester);
                            item.SEMESTER = sSemesters;
                            var tempSemesterResult = new List<SEMESTER_RESULT>();
                            sSql = string.Empty;
                            sSql = await Task.Run(() => ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterResult).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.SEMESTER, sSemesters));
                            tempSemesterResult = await Task.Run(() => (List<SEMESTER_RESULT>)CMSHandler.FetchData<SEMESTER_RESULT>(item, sSql, item.AC_YEAR).DataSource.Data);
                            if (tempSemesterResult != null)
                            {
                                foreach (var sem in tempSemesterResult)
                                {
                                    sem.AC_YEAR = item.AC_YEAR;
                                    liSemesterResult.Add(sem);
                                }
                            }
                        }
                    }

                    var arrearList = new List<SEMESTER_RESULT>();
                    var objGroup = new List<SEMESTER_RESULT>();
                    var objGp = new List<SEMESTER_RESULT>();

                    // Get Only Arrear Papers group By Course Code ....
                    var result = liSemesterResult.GroupBy(u => u.COURSE_CODE).ToList();

                    for (int i = 0; i < result.Count(); i++)
                    {
                        var code = result[i].Key.ToString();
                        objGp = (List<SEMESTER_RESULT>)liSemesterResult.Where(o => o.COURSE_CODE == code).ToList();
                        if (objGp.FindAll(o => o.RESULT == "PASS").Count() == 0)
                            arrearList.Add(objGp.FirstOrDefault());
                    }
                    ExamRegistrastionViewModel.liSemesterList = arrearList;
                    var liArearList = new List<SEMESTER_RESULT>();
                    // Get All The Regular Papers By Student_Id ...
                    var liRegularCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamRegistration), sAcademicYear).DataSource.Data);
                    var liOptionalCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                          ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data);

                    // var liTemp = liRegularCourses.Where(o => o.COURSE_STRUCTURE_ID == "579").ToList();
                    // Loop Optional Papers  To Remove Unnecessary Courses...
                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                    {
                        foreach (var item in liOptionalCourses)
                        {
                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (IsExist != null && IsExist.Count > 0)
                            {
                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                liRegularCourses.Add(item);
                            }
                        }
                    }


                    ExamRegistrastionViewModel.liExamRegistrationList = liRegularCourses;
                    //Filter Arear papers by Reguler papers 
                    foreach (var item in arrearList)
                    {
                        if (ExamRegistrastionViewModel.liExamRegistrationList.FirstOrDefault().SEMESTER_ID != item.WRITTEN_SEMESTER)
                        {
                            liArearList.Add(item);
                        }
                    }
                    ExamRegistrastionViewModel.liSemesterList = liArearList;
                    return View(ExamRegistrastionViewModel);
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "ExamRegistration", "Err MSg: " + ex.Message, "Query is empty!");
                    }
                    return RedirectToAction("ErrorMessage", "Error");
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
        }


