                    }

                    var arrearList = new List<SEMESTER_RESULT>();
                    var objGroup = new List<SEMESTER_RESULT>();
                    var objGp = new List<SEMESTER_RESULT>();

                    // Get Only Arrear Papers group By Course Code ....
                    var result = liSemesterResult.GroupBy(u => u.COURSE_CODE).ToList();

                    for (int i = 0; i < result.Count(); i++)
                    {
                        var code = result[i].Key.ToString();
                        objGp = (List<SEMESTER_RESULT>)liSemesterResult.Where(o => o.COURSE_CODE == code).ToList();
                        if (objGp.FindAll(o => o.RESULT == "PASS").Count() == 0)
                            arrearList.Add(objGp.FirstOrDefault());
                    }
                    ExamRegistrastionViewModel.liSemesterList = arrearList;
                    var liArearList = new List<SEMESTER_RESULT>();
                    // Get All The Regular Papers By Student_Id ...
                    var liRegularCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamRegistration), sAcademicYear).DataSource.Data);
                    var liOptionalCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                          ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data);

                    // var liTemp = liRegularCourses.Where(o => o.COURSE_STRUCTURE_ID == "579").ToList();
                    // Loop Optional Papers  To Remove Unnecessary Courses...
                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                    {
                        foreach (var item in liOptionalCourses)
                        {
                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (IsExist != null && IsExist.Count > 0)
                            {
                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                liRegularCourses.Add(item);
                            }
                        }
                    }


                    ExamRegistrastionViewModel.liExamRegistrationList = liRegularCourses;
                    //Filter Arear papers by Reguler papers 
                    foreach (var item in arrearList)
                    {
                        if (ExamRegistrastionViewModel.liExamRegistrationList.FirstOrDefault().SEMESTER_ID != item.WRITTEN_SEMESTER)
                        {
                            liArearList.Add(item);
                        }
                    }
                    ExamRegistrastionViewModel.liSemesterList = liArearList;


                    // fetch fee 
                    ExamRegistrastionViewModel.liFeeStudentAccount = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(new FEE_STUDENT_ACCOUNT() { STUDENT_ID = Session[Common.SESSION_VARIABLES.USER_ID].ToString() },
                       ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllFeeTransactionByFrequency), Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString()).DataSource.Data;


                    return View(ExamRegistrastionViewModel);
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "ExamRegistration", "Err MSg: " + ex.Message, "Query is empty!");
                    }
                    return RedirectToAction("ErrorMessage", "Error");
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
        }

        // New Flow ,..
        [HttpPost]
        public JsonResult SaveExamRegistration(string ExamDetails)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            string sResult = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    sResult = ValidateStudent();
                    if (sResult != "1")
                    {
                        var liExamSetting = (List<ListArrerPapers>)CMSHandler.FetchData<ListArrerPapers>(new STU_CLASS() { STUDENT_ID = sUserId },
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveExamSettingByProgrammeType), sAcademicYear).DataSource.Data;
                        if (liExamSetting != null && liExamSetting.Count > 0)
                        {
                            string sExamSettingId = liExamSetting.FirstOrDefault().EXAM_SETTING_ID;
                            string sFine = liExamSetting.FirstOrDefault().FINE;
                            // Fetch Frequency With Amount ,...
                            var liFrequencyWithAmount = (List<SaveExamSubjects>)CMSHandler.FetchData<SaveExamSubjects>(new SaveExamSubjects() { FEE_ROOT_ID = Common.FeeRoot.CollegeFee, STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamSettingId },
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFrequencyWithAmount), sAcademicYear).DataSource.Data;
                            if (liFrequencyWithAmount != null && liFrequencyWithAmount.Count > 0)
                            {
                                var ObjJson = JsonConvert.DeserializeObject<SaveExamDetails>(ExamDetails);
                                int nExamFee = 0;
                                int nArrerFee = 0;
                                string sErrorMessage = string.Empty;
                                //string sSettingId = string.Empty;
                                if (ObjJson.SubjectDetails != null && ObjJson.SubjectDetails.Count > 0)
                                {
                                    // Loop Subjects To Get Course Cost ,...
                                    foreach (var item in ObjJson.SubjectDetails)
                                    {
                                        var liCourseHeads = (List<EXAM_COURSE_WISE_COST>)CMSHandler.FetchData<EXAM_COURSE_WISE_COST>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseWiseCost), sAcademicYear).DataSource.Data;
                                        if (liCourseHeads != null && liCourseHeads.Count > 0)
                                        {
                                            //sSettingId = liCourseHeads.FirstOrDefault().EXAM_SETTING_ID;
                                            if (item.STATUS != "R") // Arrer Fee
                                                nArrerFee += Convert.ToInt32(liCourseHeads.FirstOrDefault().COST);
                                            else // Reguler Fee
                                                nExamFee += Convert.ToInt32(liCourseHeads.FirstOrDefault().COST);
                                        }
                                        else
                                        {
                                            sErrorMessage += item.COURSE_CODE + ",";
                                        }
                                    }

                                    if (!string.IsNullOrEmpty(sErrorMessage)) // True When Course Cost Not Available 
                                    {
                                        sErrorMessage = sErrorMessage.TrimEnd(',');
                                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                        ObjJsonData.Message = sErrorMessage + "Course Amount Are Not Mapped ! Please Meet Admin !";
                                    }
                                    else
                                    {
                                        bool sTrue = false;
                                        // Insert Exam Registration ,...
                                        foreach (var item in ObjJson.SubjectDetails)
                                        {
                                            item.EXAM_SETTING_ID = sExamSettingId;
                                            var sInsert = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamDetails), sAcademicYear);
                                            sTrue = sInsert.Success;
                                        }

                                        // Insert Student Account ,..
                                        if (sTrue)
                                        {

                                            foreach (var item in liFrequencyWithAmount)
                                            {
                                                var ObjModel = new FEE_STUDENT_ACCOUNT();
                                                ObjModel.STUDENT_ID = item.STUDENT_ID;
                                                ObjModel.FREQUENCY_ID = item.FEE_FREQUENCY_FEE_MODE_ID;
                                                ObjModel.HEAD = item.HEAD_ID;
                                                ObjModel.ACADEMIC_YEAR = sAcademicYear;
                                                ObjModel.CREDIT = item.COST;
                                                ObjModel.FEE_MAIN_HEAD_ID = item.FEE_MAIN_HEAD_ID;
                                                if (item.HEAD_ID == "8")
                                                    ObjModel.CREDIT = nExamFee.ToString();
                                                else if (item.HEAD_ID == "11")
                                                    ObjModel.CREDIT = nArrerFee.ToString();
                                                else if (sFine == "1" && item.HEAD_ID == "16")
                                                    ObjModel.CREDIT = "100";
                                                if (!string.IsNullOrEmpty(ObjModel.CREDIT))
                                                {
                                                    if (ObjModel.CREDIT != "0")
                                                    {
                                                        var sInsertStudentAccount = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamCreditAmountToStudentAccount));
                                                        sTrue = sInsertStudentAccount.Success;
                                                    }
                                                }
                                            }
                                        }
                                        if (sTrue)
                                        {
                                            ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                            ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                        }
                                        else
                                        {
                                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                            ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                        }
                                    }
                                }
                                else
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                    ObjJsonData.Message = "Invalied Input ! Check Your Input Details !";
                                }
                            }
                            else
                            {
                                ObjJsonData.ErrorCode = "2";
                                ObjJsonData.Message = Common.Messages.LedgersAreNotMapped;
                            }
                        }
                        else
                        {
                            ObjJsonData.ErrorCode = "2";
                            ObjJsonData.Message = " No Active Setting Mached ! Please Meet Admin ...!";
                        }
                    }
                    else
                    {
                        ObjJsonData.ErrorCode = sResult;
                        ObjJsonData.Message = " You have Registered Already ...!";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamRegistration", ex.Message);
                    }
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

