                                                            var tempExtraCredit = regularList.Where(o => o.SUBJECT_TYPE_ID == HeadsWithAmount.Where(k => k.HEAD_ID == sExtraCredit).FirstOrDefault().SUBJECT_TYPE).ToList();
                                                            if (tempExtraCredit != null && tempExtraCredit.Count > 0)
