        // Save Exam Course Wise Cost ,...
        public JsonResult SaveExamCourseWiseCost(string sJsonExamCourseWiseCost)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    int nSuccessCount = 0;
                    int nFailedCount = 0;
                    var ObjJson = JsonConvert.DeserializeObject<JSON_SAVE_ONLINE_EXAMINFO>(sJsonExamCourseWiseCost);
                    if (ObjJson.liExamCourseWiseCost != null && ObjJson.liExamCourseWiseCost.Count > 0)
                    {
                        foreach (var item in ObjJson.liExamCourseWiseCost)
                        {
                            item.STAFF_ID = sUserId;
                            if (string.IsNullOrEmpty(item.COURSE_WISE_COST_ID))
                            {
                                var sInsert = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamCourseWiseCost), sAcademicYear);
                                if (sInsert.Success)
                                    nSuccessCount++;
                                else
                                    nFailedCount++;
                            }
                            else
                            {
                                var sUpdate = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamCourseWiseCost), sAcademicYear);
                                if (sUpdate.Success)
                                    nSuccessCount++;
                                else
                                    nFailedCount++;
                            }
                        }

                        ObjJsonData.Message = "( " + nSuccessCount + " )" + Common.Messages.RecordsSavedSuccessfully + "\n ( " + nFailedCount + " )" + Common.Messages.FailedToSaveRecords;
                    }
                    else
                    {
                        ObjJsonData.Message = "Invalid Entry ! Please Check Your Input !";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog OBjLog = new ErrorLog())
                    {
                        OBjLog.WriteError("ExaminationController", "SaveExamCourseWiseCost", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
