            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjModel = new FeeMainHead() { FREQUENCY_ID = sFrequencyId, APPLICATION_TYPE_ID = sProgrammeType, PROGRAMME_MODE = sProgrammeMode, SHIFT = sShift, FEE_ROOT_ID = Common.FeeRoot.CollegeFee };
                    var liFetchMainHeads = (List<SUP_FEE_MAIN_HEAD>)CMSHandler.FetchData<SUP_FEE_MAIN_HEAD>(ObjModel,
                          SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchMainHeadsByFrequencyAndApplicationType), sAcademicYear).DataSource.Data;
                    if (liFetchMainHeads != null && liFetchMainHeads.Count > 0)
                    {
                        foreach (var item in liFetchMainHeads)
                        {
                            ObjJsonData.sResult += "<option value=" + item.FEE_MAIN_HEAD_ID + " SELECTED>" + item.MAIN_HEAD + "</option>";
