        // Save Exam Heads ,...
        public JsonResult SaveExamHeads(string sJsonSaveExamHeads)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    int nSuccessCount = 0;
                    int nFailedCount = 0;
                    var ObjJson = JsonConvert.DeserializeObject<JSON_SAVE_ONLINE_EXAMINFO>(sJsonSaveExamHeads);
                    if (ObjJson.liExamHeads != null && ObjJson.liExamHeads.Count > 0)
                    {
                        foreach (var item in ObjJson.liExamHeads)
                        {
                            if (!string.IsNullOrEmpty(item.EXAM_HEAD_ID))
                            {
                                var sUpdate = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamHeads), sAcademicYear);
                                if (sUpdate.Success)
                                {
                                    nSuccessCount++;
                                }
                                else
                                {
                                    nFailedCount++;
                                }
                            }
                            else
                            {
                                var sInsert = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamHeads), sAcademicYear);
                                if (sInsert.Success)
                                {
                                    nSuccessCount++;
                                }
                                else
                                {
                                    nFailedCount++;
                                }
                            }
                        }

                        ObjJsonData.Message = "( " + nSuccessCount + " )" + Common.Messages.RecordsSavedSuccessfully + "\n ( " + nFailedCount + " ) " + Common.Messages.FailedToSaveRecords;
                    }
                    else
                    {
                        ObjJsonData.Message = "Sorry Something Went Wrong !\n Please Check Your Input !";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamHeads", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
