        /// <summary>
        /// Arrer Course Wise Cost,..
        /// </summary>
        /// <returns></returns>

        public ActionResult ArrerCourseWiseCostList()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var liArrerList = new List<ListArrerPapers>();
                    var liArrerCourseList = new List<ListArrerPapers>();
                    var liAcYear = new List<ACADEMIC_YEAR>();
                    var ObjModel = new ListArrerPapers();
                    // Fetch  Academic Year List ,..
                    var liAcademicYearList = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(null,
                        SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList)).DataSource.Data;
                    string ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrerCourseByAcYear);
                    string sQuery = string.Empty;
                    if (liAcademicYearList != null && liAcademicYearList.Count > 0)
                    {
                        foreach (var item in liAcademicYearList)
                        {

                            // Check Table Is Exist ,..
                            var liIsExist = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(null,
                                 SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.IsTableExistForSemesterMarks), item.AC_YEAR).DataSource.Data;
                            if (liIsExist.FirstOrDefault().IS_EXIST != "0")
                            {
                                liAcYear.Add(item);
                                // Fetch Arrer Papers ,..
                                sQuery = ssql;
                                sQuery = sQuery.Replace(Common.Delimiter.QUS + Common.CP_COURSE_PATTERN.ACADEMIC_YEAR, item.AC_YEAR);
                                var liArrerPapers = (List<ListArrerPapers>)CMSHandler.FetchData<ListArrerPapers>(ObjModel,
                                       sQuery, sAcademicYear).DataSource.Data;
                                if (liArrerPapers != null && liArrerPapers.Count > 0)
                                {
                                    liArrerList = (liArrerList != null && liArrerList.Count > 0) ? liArrerList.Concat(liArrerPapers).ToList() : liArrerPapers;
                                }
                            }
                        }

                        // Loop Arrer List For Remove Passed Courses ,..
                        if (liArrerList != null && liArrerList.Count > 0)
                        {
                            int sAcYear = 0;
                            sQuery = string.Empty;
                            // Loop Ac Year ,...
                            foreach (var item in liAcYear)
                            {
                                var liFetchYearBased = liArrerList.Where(x => x.ACADEMIC_YEAR == item.AC_YEAR).ToList(); // Filter by academic year
                                if (liFetchYearBased != null && liFetchYearBased.Count > 0)
                                {
                                    foreach (var Arritem in liFetchYearBased)
                                    {
                                        sAcYear = Convert.ToInt32(Arritem.ACADEMIC_YEAR);
                                        sAcYear++;

                                        var liIsPassed = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(Arritem,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CourseCheckIsPassedByStudentIdAndCourseId), sAcYear.ToString()).DataSource.Data;
                                        if (liIsPassed != null && liIsPassed.Count > 0)
                                        {
                                            continue;
                                        }
                                        else
                                        {
                                            liArrerCourseList.Add(Arritem);
                                        }
                                    }
                                }
                            }
                            liArrerList.Clear();
                            sQuery = string.Empty;
                            // Group Courses To Avoid Duplicates ,..
                            var liCoureList = liArrerCourseList.GroupBy(x => x.COURSE_CODE)
                                        .Select(x => new ListArrerPapers()
                                        {
                                            STUDENT_ID = x.FirstOrDefault().STUDENT_ID,
                                            COURSE_CODE = x.FirstOrDefault().COURSE_CODE,
                                            COURSE_TITLE = x.FirstOrDefault().COURSE_TITLE,
                                            COURSE_ID = x.FirstOrDefault().COURSE_ID,
                                            ACADEMIC_YEAR = x.FirstOrDefault().ACADEMIC_YEAR,
                                            PROGRAMME_GROUP_ID = x.FirstOrDefault().PROGRAMME_GROUP_ID,
                                            PROGRAMME_MODE = x.FirstOrDefault().PROGRAMME_MODE,
                                            PROGRAMME_TYPE_ID = x.FirstOrDefault().PROGRAMME_TYPE_ID,
                                            PROGRAMME_TYPE = x.FirstOrDefault().PROGRAMME_TYPE,
                                            SEMESTER_ID = x.FirstOrDefault().SEMESTER_ID,
                                            SHIFT = x.FirstOrDefault().SHIFT,
                                            SUBJECT_TYPE = x.FirstOrDefault().SUBJECT_TYPE,
                                            UGC_COURSE_TYPE = x.FirstOrDefault().UGC_COURSE_TYPE,
                                            EXAM_SETTING_ID = x.FirstOrDefault().EXAM_SETTING_ID,
                                            BATCH = x.FirstOrDefault().BATCH,
                                            COURSE_WISE_COST_ID = x.FirstOrDefault().COURSE_WISE_COST_ID,
                                            RESULT = x.FirstOrDefault().RESULT,
                                            DEPARTMENT = x.FirstOrDefault().DEPARTMENT,
                                            UGC_TYPE_COST_ID = x.FirstOrDefault().UGC_TYPE_COST_ID,
                                        }).ToList();
                            sQuery = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllCoursesFromExamCourseWiseCost);


                            //.Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester);
                            var liExamCourseWiseCost = (List<EXAM_COURSE_WISE_COST>)CMSHandler.FetchData<EXAM_COURSE_WISE_COST>(null, sQuery, sAcademicYear).DataSource.Data;
                            if (liExamCourseWiseCost != null && liExamCourseWiseCost.Count > 0)
                            {
                                // Loop Arrer Courses To Remove Course If Exist In Course Wise Cost ,...

                                foreach (var item in liCoureList)
                                {
                                    var liList = liExamCourseWiseCost.Where(x => x.COURSE_ID == item.COURSE_ID).ToList();
                                    if (liList != null && liList.Count > 0)
                                        continue;
                                    else
                                        liArrerList.Add(item);
                                }
                            }
                            else
                            {
                                liArrerList = liCoureList;
                            }

                            ObjViewModel.liArrerPapers = liArrerList.OrderBy(x => x.PROGRAMME_TYPE_ID).ThenBy(x => x.SUBJECT_TYPE).ThenBy(x => x.DEPARTMENT).ThenBy(x => x.SEMESTER_ID).ToList();

                            // Fetch UGC Type Cost DDL ,...
                            ObjViewModel.liExamUGCTypeCost = (List<EXAM_UGC_COURSE_TYPE_COST>)CMSHandler.FetchData<EXAM_UGC_COURSE_TYPE_COST>(null,
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllExamUGCCourseTypeCostForDDLByExamSettingId), sAcademicYear).DataSource.Data;
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "ArrerCourseWiseCostList", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
