        public async Task<ActionResult> LoadSubjectsForHallTicket()
        {
            var sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            ExaminationViewModel ExamRegistrastionViewModel = new ExaminationViewModel();
            if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
            {
                ExamRegistrastionViewModel.sessionFlag = true;
                try
                {

                    ExamRegistrastionViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    string sStudentId = string.Empty;
                    var objExamRegistraion = new List<FetchHallTicket>();
                    GET_ACTIVE_SEMESTER_BATCH objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();
                    sStudentId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

                    if (ExamRegistrastionViewModel.liCollegeDetails != null && ExamRegistrastionViewModel.liCollegeDetails.Count > 0)
                    {
                        if (ExamRegistrastionViewModel.liCollegeDetails.FirstOrDefault().COLLEGE_CODE == "SJC")
                        {
                            objExamRegistraion = await Task.Run(() => (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(new FetchHallTicket() { STUDENT_ID = sStudentId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketListForSJC), sAcademicYear).DataSource.Data);
                            if (objExamRegistraion != null && objExamRegistraion.Count > 0)
                            {
                                ExamRegistrastionViewModel.sSemester = objExamRegistraion.FirstOrDefault().SEMESTER_ID;
                                ExamRegistrastionViewModel.Month_Year = objExamRegistraion.FirstOrDefault().MONTH_YEAR;
                            }
                        }
                        else
                        {
                            objExamRegistraion = await Task.Run(() => (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(new FetchHallTicket() { STUDENT_ID = sStudentId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketList), sAcademicYear).DataSource.Data);
                            if (objExamRegistraion != null && objExamRegistraion.Count > 0)
                            {
                                ExamRegistrastionViewModel.sSemester = objExamRegistraion.FirstOrDefault().SEMESTER_ID;
                                ExamRegistrastionViewModel.Month_Year = objExamRegistraion.FirstOrDefault().MONTH_YEAR;
                            }
                        }
                    }

                    //------
                    //var liExamRegistration = new FetchHallTicket();
                    ExamRegistrastionViewModel.liFetchHallTicket = objExamRegistraion;
                    objActiveSemester.STUDENT_ID = sStudentId;
                    ExamRegistrastionViewModel.liRegistration = (List<HallTicketDetails>)CMSHandler.FetchData<HallTicketDetails>(objActiveSemester, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicket), sAcademicYear).DataSource.Data;
                    ExamRegistrastionViewModel.liHallTicketValidation = (List<HALL_TICKET_VALIDATION>)CMSHandler.FetchData<HALL_TICKET_VALIDATION>(objActiveSemester, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketValidationByStudentId), sAcademicYear).DataSource.Data;

                    // Fetch Student Payment Details .
                    var liFetchFeeDetails = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFeeTransaction), sAcademicYear).DataSource.Data;
                    bool bFlag = true;
                    if (liFetchFeeDetails != null && liFetchFeeDetails.Count > 0)
                    {
                        foreach (var item in liFetchFeeDetails)
                        {
                            if (item.BALANCE != "0")
                            {
                                bFlag = false;
                                ExamRegistrastionViewModel.sErrorMessage += item.FREQUENCY_NAME + " , ";
                            }
                        }
                    }

                    if (bFlag)
                    {
                        string sDateFrom = string.Empty;
                        string sDateTo = string.Empty;
                        string sSQL = string.Empty;
                        // Fetch absent Hours ...
                        var liFetchAbsentHours = (List<ATTENDANCE_REPORT>)CMSHandler.FetchData<ATTENDANCE_REPORT>(new STU_CLASS() { STUDENT_ID = sStudentId },
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalAbsentHours), sAcademicYear).DataSource.Data;


                        // Get All The Regular Papers By Student_Id ...
                        var liRegularCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamRegistration), sAcademicYear).DataSource.Data);
                        var liOptionalCourses = await Task.Run(() => (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                              ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data);

                        // var liTemp = liRegularCourses.Where(o => o.COURSE_STRUCTURE_ID == "579").ToList();
                        // Loop Optional Papers  To Remove Unnecessary Courses...
                        if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                        {
                            foreach (var item in liOptionalCourses)
                            {
                                var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                                if (IsExist != null && IsExist.Count > 0)
                                {
                                    liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                    item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                    liRegularCourses.Add(item);
                                }
                            }
                        }

                        string sCourseIds = string.Join(",", liRegularCourses.Select(x => x.COURSE_ROOT_ID).ToArray());
                        sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalHours).Replace(Common.Delimiter.QUS + Common.CP_CLASS_COURSE_2017.COURSE_ID, sCourseIds);
                        sSQL = sSQL.Replace(Common.Delimiter.QUS + Common.STU_CLASS.STUDENT_ID, sStudentId);
                        // Fetch Total Hours ...
                        var liFetchTotalHours = (List<ATTENDANCE_REPORT>)CMSHandler.FetchData<ATTENDANCE_REPORT>(null, sSQL, sAcademicYear).DataSource.Data;

                        // Attendace Calculation ...
                        if (liFetchTotalHours != null && liFetchTotalHours.Count > 0 && liFetchAbsentHours != null && liFetchAbsentHours.Count > 0)
                        {
                            int nTotal = Convert.ToInt32(liFetchTotalHours.FirstOrDefault().TOTAL_HRS);
                            double nTotalHrs = Convert.ToDouble(liFetchTotalHours.FirstOrDefault().TOTAL_HRS);
                            double nAbsentHrs = Convert.ToDouble(liFetchTotalHours.FirstOrDefault().TOTAL_HRS);
                            double nAverageHrs = (nTotalHrs - nAbsentHrs / nTotalHrs) * 100;
                            if (nAverageHrs < 75)
                            {
                                bFlag = false;
                                ExamRegistrastionViewModel.sErrorMessage = "Sorry Your Attendance Percentage Is Low ! <br>  Please Meet ERP Admin For More Details !";
                            }
                        }
                    }
                    return View(ExamRegistrastionViewModel);
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "LoadSubjectsForHallTicket", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "LoadSubjectsForHallTicket", ex.Message);
                    }
                    return View(ExamRegistrastionViewModel);
                }
            }
            else
            {
                return View(ExamRegistrastionViewModel);
            }
        }

