        public async Task<ActionResult> ExamRegistrationPriview()
        {
            var sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();
            var ExamRegistrastionViewModel = new ExaminationViewModel();
            var sAcYear = ConfigurationManager.AppSettings["AcYearForAlumini"]; // 
            try
            {
                objActiveSemester.STUDENT_ID = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                string sRole = (Session[Common.SESSION_VARIABLES.USER_ROLE_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ROLE_ID].ToString() : string.Empty;
                if (sRole == Common.SupRole.ALUMINI)
                {
                    sAcademicYear = (!string.IsNullOrEmpty(sAcYear)) ? sAcYear : sAcademicYear;
                }
                // Get ExamRegistrationPriview ...
                ExamRegistrastionViewModel.liFetchHallTicket = (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(objActiveSemester,
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketListPreview), sAcademicYear).DataSource.Data;
                if (ExamRegistrastionViewModel.liFetchHallTicket != null && ExamRegistrastionViewModel.liFetchHallTicket.Count > 0)
                {
                    ExamRegistrastionViewModel.liFetchHallTicket = ExamRegistrastionViewModel.liFetchHallTicket
                        .OrderBy(x =>
                        {
                            if (string.IsNullOrEmpty(x.SEMESTER)) return 999;
                            int semVal;
                            if (int.TryParse(x.SEMESTER.Trim(), out semVal)) return semVal;
                            switch (x.SEMESTER.Trim().ToUpper())
                            {
                                case "I": return 1;
                                case "II": return 2;
                                case "III": return 3;
                                case "IV": return 4;
                                case "V": return 5;
                                case "VI": return 6;
                                case "VII": return 7;
                                case "VIII": return 8;
                                default: return 999;
                            }
                        })
                        .ToList();
                }

                // Get All Student Information ...
                ExamRegistrastionViewModel.liExamRegistrationModel = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentDetailsForExamRegistration), sAcademicYear).DataSource.Data;
                if (ExamRegistrastionViewModel.liExamRegistrationModel != null && ExamRegistrastionViewModel.liExamRegistrationModel.Count > 0 && ExamRegistrastionViewModel.liExamRegistrationModel.FirstOrDefault().NAME_IN_NATIVE != "")
                {
                    ExamRegistrastionViewModel.liExamRegistrationModel.FirstOrDefault().NAME_IN_NATIVE = Encoding.UTF8.GetString(Convert.FromBase64String(ExamRegistrastionViewModel.liExamRegistrationModel.FirstOrDefault().NAME_IN_NATIVE));
                }
                // Get College Infomation ...
                ExamRegistrastionViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                // Get Fee Transaction .
                ExamRegistrastionViewModel.feeTransactions = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(
                    new FEE_TRANSACTION() { ACADEMIC_YEAR = sAcademicYear, STUDENT_ID = objActiveSemester.STUDENT_ID, FEE_MODE = Common.FrequencyType.ExamFee },
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamHeadsByStudentId), sAcademicYear).DataSource.Data;

                return View(ExamRegistrastionViewModel);
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "ExamRegistrationPriview", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("ExaminationController", "ExamRegistrationPriview", ex.Message);
                }
