        public JsonResult PushExamRegistration(string ExamSettingId)
        {
            JsonResultData ObjJsonData = new JsonResultData();
            string sSql = string.Empty;
            string Sql = string.Empty;
            try
            {
                if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
                {
                    string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                    string sResult = string.Empty;
                    EXAM_SETTING objModel = new EXAM_SETTING();
                    EXAM_REGISTRATION_2017 objModels = new EXAM_REGISTRATION_2017();
                    objModel.EXAM_SETTING_ID = ExamSettingId;

                    var ExamRegistrationCourse = (List<EXAM_REGISTRATION_2017>)CMSHandler.FetchData<EXAM_REGISTRATION_2017>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseFromExamRegistrationByProgrammeGroup), sAcademicYear).DataSource.Data;
                    var ArrierRegistration = (List<EXAM_REGISTRATION_2017>)CMSHandler.FetchData<EXAM_REGISTRATION_2017>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseFromExamRegistrationByProgrammeGroup), sAcademicYear).DataSource.Data;
                    if (ExamRegistrationCourse != null && ExamRegistrationCourse.Count > 0)
                    {
                        foreach (var item in ExamRegistrationCourse)
                        {
                            sSql = @"INSERT INTO `SEMESTER_MARKS_?AC_YEAR`(`STUDENT_ID`,`COURSE_ID`,`INTERNAL_MARK`,`APPLIED`,`SEMESTER`,`M_PASS`,`IS_ARREAR`,`EXAM_SETTING_ID`)VALUES";
                            sSql = sSql.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                            var LiClassId = ExamRegistrationCourse.GroupBy(s => s.CLASS_ID).ToList();
                            foreach (var Itemcl in LiClassId)
                            {
                                objModels.CLASS_ID = Itemcl.FirstOrDefault().CLASS_ID;
                                var LiCourse = ExamRegistrationCourse.Where(s => s.CLASS_ID == Itemcl.FirstOrDefault().CLASS_ID).ToList();
                                foreach (var ItemCourse in LiCourse)
                                {
                                    objModels.COURSE_ID = ItemCourse.COURSE_ID;
                                    objModels.CLASS_YEAR = ItemCourse.CLASS_YEAR;
                                    objModels.PROGRAMME_GROUP_ID = ItemCourse.PROGRAMME_GROUP_ID;
                                    objModels.SEMESTER = ItemCourse.SEMESTER;
                                    objModels.EXAM_SETTING_ID = ExamSettingId;
                                    //var LiCourseId = ExamRegistrationCourse.Where(s => s.PROGRAMME_GROUP_ID == Itempg.FirstOrDefault().PROGRAMME_GROUP_ID && s.CLASS_YEAR== ItemCY.FirstOrDefault().CLASS_YEAR).ToList();
                                    // objModels.COURSE_ID = string.Join(",", LiCourseId.Select(o => o.COURSE_ID).ToArray());
                                    //Sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindCIAMarksForCOE).Replace(Common.Delimiter.QUS+Common.CP_CLASS_COURSE_2017.COURSE_ID, sCourseId);
                                    var TotalMark = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(objModels, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAgroupmarkForSemester), sAcademicYear).DataSource.Data;

                                    var ListExamRegistration = (List<EXAM_REGISTRATION_2017>)CMSHandler.FetchData<EXAM_REGISTRATION_2017>(objModels, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRegularExamRegisteredStudentByProgramme), sAcademicYear).DataSource.Data;
                                    if (ListExamRegistration != null && ListExamRegistration.Count > 0)
                                    {
                                        foreach (var studentItem in ListExamRegistration)
                                        {
                                            objModels.SEMESTER = studentItem.SEMESTER;
                                            objModels.M_PASS = studentItem.M_PASS;
                                            //objModels.EXAM_SETTING_ID = ExamSettingId;
                                            if (TotalMark != null && TotalMark.Count > 0)
                                            {
                                                TotalMark.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                                //foreach (var itemARR in TotalMark)
                                                //{
                                                //    sSql += @"('" + itemARR.STUDENT_ID + "','" + itemARR.COURSE_ID + "','" + itemARR.TOTAL + "','N','" + objModels.SEMESTER + "','" + objModels.M_PASS + "','0','" + objModels.EXAM_SETTING_ID + "'),";
                                                //}
                                                var SubMark = TotalMark.Where(s => s.STUDENT_ID == studentItem.STUDENT_ID && s.COURSE_ID == studentItem.COURSE_ID).ToList();
                                                TotalMark.RemoveAll(s => s.STUDENT_ID == studentItem.STUDENT_ID && s.COURSE_ID == studentItem.COURSE_ID);
                                                if (SubMark != null && SubMark.Count > 0)
                                                {
                                                    sSql += @"('" + SubMark.FirstOrDefault().STUDENT_ID + "','" + SubMark.FirstOrDefault().COURSE_ID + "','" + SubMark.FirstOrDefault().TOTAL + "','Y','" + studentItem.SEMESTER + "','" + studentItem.M_PASS + "','0','" + ExamSettingId + "'),";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            sSql = sSql.TrimEnd(',');
                            using (MySQLHandler ObjHandler = new MySQLHandler())
                            {
                                var resultArg = ObjHandler.ExecuteAsScripts(sSql);
                                if (resultArg.Success)
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.Accepted;
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                }
                                else
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.ExpectationFailed;
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                        }
                    }

                    //Arrier Course
                    if (ArrierRegistration != null && ArrierRegistration.Count > 0)
                    {
                        foreach (var itemArrReg in ArrierRegistration)
                        {
                            sSql = @"INSERT INTO `SEMESTER_MARKS_?AC_YEAR`(`STUDENT_ID`,`COURSE_ID`,`INTERNAL_MARK`,`APPLIED`,`SEMESTER`,`M_PASS`,`IS_ARREAR`,`EXAM_SETTING_ID`)VALUES";
                            sSql = sSql.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                            var LiClassId = ArrierRegistration.GroupBy(s => s.CLASS_ID).ToList();
                            foreach (var Itemcl in LiClassId)
                            {
                                var LiCourse = ArrierRegistration.Where(s => s.CLASS_ID == Itemcl.FirstOrDefault().CLASS_ID).ToList();
                                foreach (var item in LiCourse)
                                {
                                    var ArrierStudent = (List<EXAM_REGISTRATION_2017>)CMSHandler.FetchData<EXAM_REGISTRATION_2017>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearStudentByCourse), sAcademicYear).DataSource.Data;
                                    if (ArrierStudent != null && ArrierStudent.Count > 0)
                                    {
                                        foreach (var itemast in ArrierStudent)
                                        {
                                            objModels.ACADEMIC_YEAR = sAcademicYear;
                                            objModels.STUDENT_ID = itemast.STUDENT_ID;
                                            var SemAcademicYear = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(objModel, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAcademicYearForSemesterMark)).DataSource.Data;
                                            if (SemAcademicYear != null && SemAcademicYear.Count > 0)
                                            {
                                                foreach (var itemac in SemAcademicYear)
                                                {
                                                    objModels.ACADEMIC_YEAR = itemac.ACTIVE_YEAR;
                                                    objModels.STUDENT_ID = itemast.STUDENT_ID;
                                                    var SemMark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrierStudentInternal), itemac.ACTIVE_YEAR).DataSource.Data;
                                                    if (SemMark != null && SemMark.Count > 0)
                                                    {
                                                        sSql += @"('" + itemast.STUDENT_ID + "','" + itemast.COURSE_ID + "','" + SemMark.FirstOrDefault().INTERNAL_MARK + "','Y','" + itemast.SEMESTER + "','" + itemast.M_PASS + "','1','" + itemast.EXAM_SETTING_ID + "'),";
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            sSql = sSql.TrimEnd(',');
                            using (MySQLHandler ObjHandler = new MySQLHandler())
                            {
                                var resultArg = ObjHandler.ExecuteAsScripts(sSql);
                                if (resultArg.Success)
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.Accepted;
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                }
                                else
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.ExpectationFailed;
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                        }
                    }


                }
                else
                {
                    ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                }
            }
            catch (Exception Ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("Examination", "PushExamRegistration", "Err MSg: " + Ex.Message, "Query is empty!");
                    objHandler.WriteError("Examination", "PushExamRegistration", Ex.Message);
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
