                        string sTotalQuestionsCount = string.Empty;
                        var liActiveSettingId = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(ObjSaveQuestion,
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.GetActiveSettingByClassAndCourseAndStaffIds), sAcademicYear).DataSource.Data;
                        if (liActiveSettingId != null && liActiveSettingId.Count > 0)
                        {
                            sSettingId = liActiveSettingId.FirstOrDefault().SETTING_ID;
                            sTotalQuestionsCount = liActiveSettingId.FirstOrDefault().NO_OF_QUESTIONS;
                            if (liActiveSettingId.FirstOrDefault().ACTIVE_DATE == "0")
                            {
                                ObjJsonData.Message = "Sorry ... Your Date Is Expired !";
                                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                            }
                        }
                        else
                        {
                            ObjJsonData.Message = "Sorry ... Course Setting Not Mapped! Active Course Setting And Try Again !";
                            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                        }
                        ObjSaveQuestion.SETTING_ID = sSettingId;
                        ObjSaveQuestion.NO_OF_QUESTIONS = sTotalQuestionsCount;


                        // Check Questions Limit ,...
                        var liCheckLimit = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizQuestionCount), sAcademicYear).DataSource.Data;
                        if (liCheckLimit != null && liCheckLimit.Count > 0)
                        {
                            int nQuestionCount = Convert.ToInt32(liCheckLimit.FirstOrDefault().NO_OF_QUESTIONS);
                            int nTotalCount = Convert.ToInt32(sTotalQuestionsCount);
                            if (nTotalCount > nQuestionCount)
                            {
                                // Do Nothing When Condition True .
                            }
                            else
                            {
                                ObjJsonData.Message = "You Have Reached Maximum Question Limit For This Set ! ";
                                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                            }
                        }
                        string sSemsterId = string.Empty;
                        string Quiz_Id = string.Empty;
                        // Fetch SemesterId By Course Id .
                        var liFetchSemsterByCourse = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(ObjSaveQuestion,
                                SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSemesterByCourseId), sAcademicYear).DataSource.Data;
                        if (liFetchSemsterByCourse != null && liFetchSemsterByCourse.Count > 0)
                        {
                            sSemsterId = liFetchSemsterByCourse.FirstOrDefault().SEMESTER_ID;
                        }
                        ObjSaveQuestion.SEMESTER_ID = sSemsterId;

                        if (ObjSaveQuestion.QUESTION_TYPE == Common.Quiz_Question_Type.ObjectiveType)
                        {
                            // Objective Type ...

                            var HasItem = Result.liMF_Option.Where(x => x.OPTION == ObjSaveQuestion.ANSWER_ID).ToList();
                            if (HasItem != null && HasItem.Count > 0)
                            {

                                ObjSaveQuestion.QUESTION = ObjSaveQuestion.QUESTION;

                                // Save Questions ...
                                var sSaveQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizQuestion), sAcademicYear, true);
                                if (sSaveQuestions.Success)
                                {
                                    Quiz_Id = sSaveQuestions.RowUniqueId.ToString();
                                    ObjSaveQuestion.QUIZ_ID = Quiz_Id;
                                    foreach (var item in Result.liMF_Option)
                                    {
                                        item.SEMESTER_ID = sSemsterId;
                                        item.QUIZ_ID = Quiz_Id;
                                        item.SET_ID = ObjSaveQuestion.SET_ID;
                                        item.OPTIONS = item.OPTION;
                                        item.SETTING_ID = sSettingId;
                                        var sSaveQuizOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizOption), sAcademicYear);
                                    }
                                    var FetchOptionIdByAnswer = (List<QUIZ_OPTIONS_2017>)CMSHandler.FetchData<QUIZ_OPTIONS_2017>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionIdByOption), sAcademicYear).DataSource.Data;
                                    if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                    {
                                        ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                        var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForObjectiveQuestions), sAcademicYear);
                                    }
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "Your Answer Not Valuable ! Please Check You Input !";
                            }

                        }
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Quiz_Question_Type.FillInTheBlank)
                        {
                            // Fill In The Blanks ...

                            var HasItem = Result.liMF_Option.Where(x => x.OPTION == ObjSaveQuestion.ANSWER_ID).ToList();
                            if (HasItem != null && HasItem.Count > 0)
                            {
                                // Save Questions ...
                                var sSaveQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizFillInBlankQuestions), sAcademicYear, true);

                                if (sSaveQuestions.Success)
                                {
                                    Quiz_Id = sSaveQuestions.RowUniqueId.ToString();
                                    ObjSaveQuestion.QUIZ_ID = Quiz_Id;

                                    foreach (var item in Result.liMF_Option)
                                    {
                                        item.SEMESTER_ID = sSemsterId;
                                        item.QUIZ_ID = Quiz_Id;
                                        item.SET_ID = ObjSaveQuestion.SET_ID;
                                        item.OPTIONS = item.OPTION;
                                        item.SETTING_ID = sSettingId;
                                        var sSaveQuizOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizFillInBlankOptions), sAcademicYear);
                                    }
                                    var FetchOptionIdByAnswer = (List<QUIZ_OPTIONS_2017>)CMSHandler.FetchData<QUIZ_OPTIONS_2017>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizFillInBlankOptionIdByOption), sAcademicYear).DataSource.Data;
                                    if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                    {
                                        ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                        var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForFillInBlankQuestions), sAcademicYear);
                                    }
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "Your Answer Not Valuable ! Please Check You Input !";
                            }


                        }
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Quiz_Question_Type.MatchTheFollowing)
                        {
                            // Match The Following ...


                            // Save Quiz Questions .
                            var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveMathTheFollowingQuestions), sAcademicYear, true);
                            if (SaveMFQuestions.Success)
                            {
                                Quiz_Id = SaveMFQuestions.RowUniqueId.ToString();
                                // Save Quiz Options .
                                foreach (var item in Result.liMF_Option)
                                {
                                    item.SEMESTER_ID = sSemsterId;
                                    item.QUIZ_ID = Quiz_Id;
                                    item.SET_ID = ObjSaveQuestion.SET_ID;
                                    var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveMathTheFollowingOptions), sAcademicYear);
                                }
                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        // List Match The Following ...
        public ActionResult ListMatchTheFollowing()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sAcademicYearId = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjModel = new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS();

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                ObjModel.ENTRY_ID = sUserId;
                // Fetch Active Setting Ids ...
                string sSettingId = string.Empty;
                var liActiveSettingId = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(new QUIZ_SETTING() { STAFF_ID = sUserId },
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveQuizSettingId), sAcademicYear).DataSource.Data;
                if (liActiveSettingId != null && liActiveSettingId.Count > 0)
                {
                    sSettingId = string.Join(",", liActiveSettingId.Select(x => x.SETTING_ID).ToArray());
                }
                if (!string.IsNullOrEmpty(sSettingId))
                {
                    string ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ListMathTheFollowingQuiz).Replace(Common.Delimiter.QUS + "SETTING_ID", sSettingId);
                    ObjViewModel.liQuizMFQuestions = (List<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>(ObjModel, ssql, sAcademicYear).DataSource.Data;

                    ssql = string.Empty;
                    ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ListObjectiveQuiz).Replace(Common.Delimiter.QUS + "SETTING_ID", sSettingId);
                    ObjViewModel.liListQuiz = (List<LIST_QUIZ>)CMSHandler.FetchData<LIST_QUIZ>(ObjModel, ssql, sAcademicYear).DataSource.Data;

                    ssql = string.Empty;
                    ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ListFillInBlankQuiz).Replace(Common.Delimiter.QUS + "SETTING_ID", sSettingId);
                    ObjViewModel.liQuizFillInBlanks = (List<LIST_QUIZ>)CMSHandler.FetchData<LIST_QUIZ>(ObjModel, ssql, sAcademicYear).DataSource.Data;
                }
                else
                    ObjViewModel.sErrorMessage = "No Active Setting Match Here";

            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

