                                        else
                                        {
                                            // Insert ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizOption), sAcademicYear);
                                        }
                                    }

                                    // Fetch Option Id For Update Answer ...
                                    var FetchOptionIdByAnswer = (List<QUIZ_OPTIONS_2017>)CMSHandler.FetchData<QUIZ_OPTIONS_2017>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionIdByOption), sAcademicYear).DataSource.Data;

                                    if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                    {
                                        ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                        var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForObjectiveQuestions), sAcademicYear);
                                    }
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "Your Answer Not Valuable ! Please Check You Input !";
                            }

                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        // Delete Match The Following ...
        public JsonResult DeleteMatchTheFollowing(string sQuizId, string sQuestionType)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var sResultArgs = new ResultArgs();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var UnSafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.UnSafeUpdateMode));
                    var ObjModel = new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { QUIZ_ID = sQuizId, QUESTION_TYPE = sQuestionType };

                    // Objective Type ,...
                    if (sQuestionType == Common.Quiz_Question_Type.ObjectiveType)
                    {
                        var DeleteObjectiveQuizQuestions = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteObjectiveQuizQuestion), sAcademicYear);
                        if (DeleteObjectiveQuizQuestions.Success)
                        {
                            sResultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteObjectiveQuizOption));
                            ObjJsonData.Message = Common.Messages.RecordDeletedSuccessfully;
                        }
                        else
                        {
                            ObjJsonData.Message = Common.Messages.FailedToDeletedTryAgain;
                        }
                    }
                    // Fill In Blank Type ...
                    else if (sQuestionType == Common.Quiz_Question_Type.FillInTheBlank)
                    {
                        var DeleteObjectiveQuizQuestions = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteFillInTheBlanksQuestion), sAcademicYear);
                        if (DeleteObjectiveQuizQuestions.Success)
                        {
                            sResultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteFillInTheBlanksOption));
                            ObjJsonData.Message = Common.Messages.RecordDeletedSuccessfully;
                        }
                        else
                        {
                            ObjJsonData.Message = Common.Messages.FailedToDeletedTryAgain;
                        }
                    }
                    // Match The Following Type ,...
                    else if (sQuestionType == Common.Quiz_Question_Type.MatchTheFollowing)
                    {
                        var DeleteObjectiveQuizQuestions = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteMatchTheFollowingQuestion), sAcademicYear);
                        if (DeleteObjectiveQuizQuestions.Success)
                        {
                            sResultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteMatchTheFollowingOption));
                            ObjJsonData.Message = Common.Messages.RecordDeletedSuccessfully;
                        }
                        else
                        {
                            ObjJsonData.Message = Common.Messages.FailedToDeletedTryAgain;
                        }
                    }
                    var SafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.SafeUpdateMode));
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "DeleteMatchTheFollowing", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "DeleteMatchTheFollowing", "Err.Msg:" + ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }


