        // Save And Update Quiz Setting ...
        public JsonResult SaveQuizSetting(string sSaveQuizSetting)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                var Result = JsonConvert.DeserializeObject<QUIZ_SETTING>(sSaveQuizSetting);
                Result.START_DATE = CommonMethods.ConvertdatetoyearFromat(Result.START_DATE);
                // Result.END_DATE = CommonMethods.ConvertdatetoyearFromat(Result.END_DATE);
                Result.STAFF_ID = sUserId;
                // Get Class Course Staff Id ...
                var liQuizClassCourseStaff = (List<QUIZ_CLASS_COURSE_STAFF>)CMSHandler.FetchData<QUIZ_CLASS_COURSE_STAFF>(Result,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.GetClassCourseStaffIdForQuizSetting), sAcademicYear).DataSource.Data;
                if (liQuizClassCourseStaff != null && liQuizClassCourseStaff.Count > 0)
                {
                    Result.QUIZ_STF_ID = liQuizClassCourseStaff.FirstOrDefault().QUIZ_STF_ID;
                }
                else
                {
                    ObjJsonData.Message = "Sorry ... Something Went Wrong ! Please Meet ERP Admin !";
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
                if (!string.IsNullOrEmpty(Result.SETTING_ID))
                {
                    var UpdateQuiz = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizSetting), sAcademicYear);
                    ObjJsonData.Message = (UpdateQuiz.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                }
                else
                {
                    var SaveQuiz = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizSetting), sAcademicYear);
                    ObjJsonData.Message = (SaveQuiz.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                }

            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        // ActiveAndDeActive Quiz Setting ...
        public JsonResult UpdateActiveQuizSetting(string sQuizSettingId, string sActive, string sClassId, string sCourseId)
        {

            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                if (sActive == "1")
                {
                    string sClsStfId = string.Empty;
                    // Get Class Course Staff Id ...
                    var liQuizClassCourseStaff = (List<QUIZ_CLASS_COURSE_STAFF>)CMSHandler.FetchData<QUIZ_CLASS_COURSE_STAFF>(new QUIZ_CLASS_COURSE_STAFF() { CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sUserId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.GetClassCourseStaffIdForQuizSetting), sAcademicYear).DataSource.Data;
                    if (liQuizClassCourseStaff != null && liQuizClassCourseStaff.Count > 0)
                    {
                        sClsStfId = liQuizClassCourseStaff.FirstOrDefault().QUIZ_STF_ID;
                    }
                    string sSQL = string.Empty;
                    sSQL = @"SET SQL_SAFE_UPDATES=0;
                             UPDATE QUIZ_SETTING SET IS_ACTIVE=0 WHERE QUIZ_STF_ID=?STAFF_ID ;
                             SET SQL_SAFE_UPDATES=1;";
                    sSQL = sSQL.Replace(Common.Delimiter.QUS + Common.STF_PERSONAL_INFO.STAFF_ID, sClsStfId);
                    using (MySQLHandler objHandler = new MySQLHandler())
                    {

                        var sTrue = objHandler.ExecuteAsScripts(sSQL);
                    }
                }


                var UpateActiveQuizSetting = CMSHandler.SaveOrUpdate(new QUIZ_SETTING() { SETTING_ID = sQuizSettingId, IS_ACTIVE = sActive },
                       ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ActiveOrDeactiveQuizSetting), sAcademicYear);
                ObjJsonData.Message = (UpateActiveQuizSetting.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

