        // Save ExamTimetable .
        public JsonResult SaveExamTimeTable(string sSaveExamTimeTable)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                string sUpdateQuery = string.Empty;
                string sInsertQuery = string.Empty;
                int nInsert = 0;
                var ObjJason = JsonConvert.DeserializeObject<JSON_CIA_MARKS>(sSaveExamTimeTable);

                if (ObjJason.liTimeTable != null && ObjJason.liTimeTable.Count > 0)
                {
                    string sLockQuery = "LOCK TABLES CIA_EXAM_TIMETABLE WRITE;";
                    sInsertQuery += @"INSERT INTO CIA_EXAM_TIMETABLE
                                  (
                                    EXAM_DATE,
                                    COURSE_ID,
                                    COURSE_CODE,
                                    EXAM_SESSION_ID,
                                    ACADEMIC_YEAR,
                                    EXAM_SETTING_ID
                                  )
                                  VALUES";
                    foreach (var item in ObjJason.liTimeTable)
                    {
                        item.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(item.EXAM_DATE);
                        if (!string.IsNullOrEmpty(item.TIMETABLE_ID))
                        {
                            sUpdateQuery += "UPDATE CIA_EXAM_TIMETABLE SET EXAM_DATE='" + item.EXAM_DATE + "' ,EXAM_SESSION_ID='" + item.EXAM_SESSION_ID + "',COURSE_ID='" + item.COURSE_ID + "',COURSE_CODE='" + item.COURSE_CODE + "',ACADEMIC_YEAR='" + item.ACADEMIC_YEAR + "',EXAM_SETTING_ID='" + item.EXAM_SETTING_ID + "' WHERE TIMETABLE_ID='" + item.TIMETABLE_ID + "';";
                        }
                        else
                        {
                            sInsertQuery += "('" + item.EXAM_DATE + "','" + item.COURSE_ID + "','" + item.COURSE_CODE + "','" + item.EXAM_SESSION_ID + "','" + item.ACADEMIC_YEAR + "','" + item.EXAM_SETTING_ID + "'),";
                            nInsert = 1;
                        }

                    }


                    using (MySQLHandler ObjHandler = new MySQLHandler())
                    {
                        ResultArgs ObjResulrArgs = new ResultArgs();
                        if (nInsert != 0)
                        {
                            sInsertQuery = sInsertQuery.TrimEnd(',');
                            sInsertQuery += ";";
                            sInsertQuery = sLockQuery + sInsertQuery + "UNLOCK TABLES;";
                            ObjResulrArgs = ObjHandler.ExecuteAsScripts(sInsertQuery);
                        }
                        if (!string.IsNullOrEmpty(sUpdateQuery))
                        {
                            sUpdateQuery = sLockQuery + sUpdateQuery + "UNLOCK TABLES;";
                            ObjResulrArgs = ObjHandler.ExecuteAsScripts(sUpdateQuery);
                        }
                        if (ObjResulrArgs.Success)
                        {
                            ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                            ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                        }
                        else
                        {
                            ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        }
                    }
                }
                else
                {
                    ObjJsonData.Message = "Your Input Not Acceptable ! Please Check You Input !";
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                }

                //if (!string.IsNullOrEmpty(Result.TIMETABLE_ID))
                //{
                //    var UpdateExamTimeTable = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamTimeTable), sAcademicYear);
                //    ObjJsonData.Message = (UpdateExamTimeTable.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                //}
                //else
                //{
                //    var SaveExamTimeTable = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamTimeTable), sAcademicYear);
                //    ObjJsonData.Message = (SaveExamTimeTable.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                //}
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData);
        }
        // Delete Exam TimeTable ...
        public JsonResult DeleteExamTimeTable(string sExamTimeTableId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var DeleteExamTimetable = CMSHandler.SaveOrUpdate(new EXAM_TIMETABLE() { TIMETABLE_ID = sExamTimeTableId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteCIAExamTimeTable), sAcademicYear);
                    if (DeleteExamTimetable.Success)
                    {
                        ObjJsonData.Message = Common.Messages.RecordDeletedSuccessfully;
                        ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                    }
                    else
                    {
                        ObjJsonData.Message = Common.Messages.FailedToDeletedTryAgain;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "DeleteExamTimeTable", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
