        // Bind CIA Marks For COE .
        public ActionResult BindCIAMarksForCOE(string sClassYear, string sProgrammeGroupId, string sAcYear)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sAcademicYearId = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR_ID].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            var liCIATotal = new List<CIA_TOTAL>();
            var liCoursePattern = new List<CP_COURSE_PATTERN>();
            var liCourse = new List<CP_COURSE_PATTERN>();
            string sCourseIds = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    sAcademicYear = (!string.IsNullOrEmpty(sAcYear)) ? sAcYear : sAcademicYear;
                    ObjViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    var sProgrammeIds = sProgrammeGroupId.Split(',');
                    foreach (var item in sProgrammeIds)
                    {
                        // Fetch Class Course Staff Details ..
                        liCoursePattern = (List<CP_COURSE_PATTERN>)CMSHandler.FetchData<CP_COURSE_PATTERN>(new CP_CLASSES() { CLASS_YEAR = sClassYear, PROGRAMME_GROUP_ID = item },
                                          ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClass_Course_StaffByProgrammeGroupId), sAcademicYear).DataSource.Data;
                        if (liCoursePattern != null && liCoursePattern.Count > 0)
                        {
                            ObjViewModel.liCoursePattern = (ObjViewModel.liCoursePattern != null) ? ObjViewModel.liCoursePattern.Concat(liCoursePattern).ToList() : liCoursePattern;

                            // Fetch CIA Marks .
                            foreach (var tempitem in liCoursePattern)
                            {
                                // Fetch Optional Course ...
                                liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(new CP_CLASSES() { CLASS_YEAR = sClassYear, PROGRAMME_GROUP_ID = item, COURSE_ID = tempitem.COURSE_ID },
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindOptionalCourseCIAMarksForCOE), sAcademicYear).DataSource.Data;

                                if (liCIATotal != null && liCIATotal.Count > 0)
                                {
                                    liCIATotal.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                    ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                                }
                                else
                                {
                                    // Fetch Regular Course ...
                                    liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(new CP_CLASSES() { CLASS_YEAR = sClassYear, PROGRAMME_GROUP_ID = item, COURSE_ID = tempitem.COURSE_ID },
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindCIAMarksForCOE), sAcademicYear).DataSource.Data;
                                    if (liCIATotal != null && liCIATotal.Count > 0)
                                    {
                                        liCIATotal.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                        ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                                    }
                                }
                                // ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                            }
                        }
                    }

                    ObjJsonData.Message += ";";
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "BindCIAMarksForCOE", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "BindCIAMarksForCOE", "Err.Msg:" + ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return View(ObjViewModel);
        }
