                            //string sSQLOptionalCourse = string.Empty;
                            //sSQLOptionalCourse = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCoursesByStudentIdAndSemesterIds);

                            // Fetch Semester Marks By Student Id ...
