        public ActionResult BindStudentForRescapesMarkEntry(string sClassId, string sCourseId, string sAcademicYear)
        {
            string sAcYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjviewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    CIA_COURSE_INFO.COURSE_ID = sCourseId;

                    ObjviewModel.liCIA_Staff_Info = (List<CIA_STAFF_INFO>)CMSHandler.FetchData<CIA_STAFF_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByCourseIdForRescapes), sAcademicYear).DataSource.Data;
                    ObjviewModel.liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId), sAcademicYear).DataSource.Data;
                    CIA_COURSE_INFO.COURSE_TYPE_ID = ObjviewModel.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                    CIA_COURSE_INFO.SEMESTER_ID = ObjviewModel.liCIACourse_Info.FirstOrDefault().SEMESTER_ID;

                    ObjviewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    // Fetch Component Details ...
                    ObjviewModel.liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseTypeId), sAcademicYear).DataSource.Data;
                    // FetchMarks ...
                    var componentInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAComponentsByCourseIdForRescapes), sAcademicYear).DataSource.Data;
                    var markInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentsForRescapesCIAEntry), sAcademicYear).DataSource.Data;

                    if (markInfo != null && markInfo.Count > 0)
                    {
                        foreach (var item in componentInfo)
                        {
                            var temp = markInfo.Where(o => o.STUDENT_ID == item.STUDENT_ID && o.COURSE_GROUP_ID == item.COURSE_GROUP_ID).ToList();
                            if (temp != null && temp.Count > 0) { item.COURSE_GROUP_MARK = temp.FirstOrDefault().COURSE_GROUP_MARK; item.CIA_GROUP_MARK_ID = temp.FirstOrDefault().CIA_GROUP_MARK_ID; }
                            item.COURSE_GROUP_MARK = (item.COURSE_GROUP_MARK == "0") ? "" : item.COURSE_GROUP_MARK;
                        }
                    }
                    // componentInfo.ForEach(o => o.COURSE_GROUP_MARK = string.Equals(o.COURSE_GROUP_MARK, "0") ? "" : o.COURSE_GROUP_MARK);

                    var student = componentInfo.GroupBy(o => o.STUDENT_ID).Select(x => new CIA_TOTAL() { STUDENT_ID = x.FirstOrDefault().STUDENT_ID }).ToList();
                    ObjviewModel.liCIA_Marks_Info = componentInfo;
                    ObjviewModel.liCIA_Total = student;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindStudentForRescapesMarkEntry", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjviewModel);
        }

        public string SaveRescapesCIAEntry(string jsonCIA_MARKS, string sCourseId, string sClassId, string sAcademicYear)
        {
            string sResult = string.Empty;
            bool insertFlag = false;
            bool updateFlag = false;
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                string sAcYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                string sInsertQuery = string.Empty;
                string sInsertQueryCom = string.Empty;
                string sUpdateQuery = string.Empty;
                ResultArgs resultArgs = new ResultArgs();
                System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
                JSON_CIA_MARKS objJson = serializer.Deserialize<JSON_CIA_MARKS>(jsonCIA_MARKS);
                if (objJson.SAVE_CIA_MARKS != null && objJson.SAVE_CIA_MARKS.Count > 0)
                {
                    sInsertQuery = @"INSERT INTO CIA_RESCAPES_MARKS (
                                STUDENT_ID,
                                COURSE_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK,
                                SEMESTER_ID,,ACADEMIC_YEAR)VALUES";
                    sInsertQueryCom = sInsertQuery;
                    foreach (var item in objJson.SAVE_CIA_MARKS)
                    {
                        if (string.IsNullOrEmpty(item.COURSE_GROUP_MARK))
                            item.COURSE_GROUP_MARK = "0";

                        if (string.IsNullOrEmpty(item.CIA_GROUP_MARK_ID))
                        {
                            sInsertQuery += "('" + item.STUDENT_ID.Trim() + "','" + item.COURSE_ID.Trim() + "','" + item.COURSE_GROUP_ID.Trim() + "','" + item.COURSE_GROUP_MARK.Trim() + "','" + item.SEMESTER_ID.Trim() + "','" + sAcademicYear + "'),";
                            insertFlag = true;
                        }
                        else
                        {
                            sUpdateQuery += @"UPDATE CIA_RESCAPES_MARKS_?AC_YEAR SET STUDENT_ID='" + item.STUDENT_ID.Trim() + "', COURSE_ID='" + item.COURSE_ID.Trim() + "', COURSE_GROUP_ID='" + item.COURSE_GROUP_ID.Trim() + "', COURSE_GROUP_MARK='" + item.COURSE_GROUP_MARK.Trim() + "', SEMESTER_ID='" + item.SEMESTER_ID.Trim() + "',ACADEMIC_YEAR='" + sAcademicYear + "' WHERE CIA_GROUP_MARK_ID='" + item.CIA_GROUP_MARK_ID.Trim() + "';";
                            updateFlag = true;
                        }
                    }


                    using (ExaminationViewModel objExamination = new ExaminationViewModel())
                    {
                        if (updateFlag)
                        {
                            sUpdateQuery = sUpdateQuery.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                            resultArgs = objExamination.ExcuteCIA_Marks(sUpdateQuery);
                        }
                        if (insertFlag)
                        {
                            sInsertQuery = sInsertQuery.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                            sInsertQuery = sInsertQuery.TrimEnd(',');
                            sInsertQuery = sInsertQuery + ";";
                            resultArgs = objExamination.ExcuteCIA_Marks(sInsertQuery);
                        }
                        sResult = resultArgs.Success ? "Marks have been updated successfully...!" : Common.Messages.FailedToSaveRecords;
                    }
                }
            }
            return sResult;
        }

