                    ObjViewModel.liCIA_Staff_Info = (List<CIA_STAFF_INFO>)CMSHandler.FetchData<CIA_STAFF_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByCourseIdForRescapes), sAcademicYear).DataSource.Data;
                    ObjViewModel.liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoForLanguage), sAcademicYear).DataSource.Data;
                    if (ObjViewModel.liCIACourse_Info != null && ObjViewModel.liCIACourse_Info.Count > 0)
                    {
                        CIA_COURSE_INFO.COURSE_TYPE_ID = ObjViewModel.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                        CIA_COURSE_INFO.SEMESTER_ID = ObjViewModel.liCIACourse_Info.FirstOrDefault().SEMESTER_ID;
                    }

                    ObjViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    // Fetch Component Details ...
                    ObjViewModel.liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseTypeId), sAcademicYear).DataSource.Data;
                    // FetchMarks ...
                    ObjViewModel.liCIA_Marks_Info = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindCIAComponentMarksReportForRescapes), sAcademicYear).DataSource.Data;
                    // FetchCIATotal ...
                    ObjViewModel.liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindCIAMarksReportForRescapes), sAcademicYear).DataSource.Data;
                    ObjViewModel.liCIA_Total.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                    return View(ObjViewModel);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindStudentsForRescaprsCIAComponentMarks", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }
