        public JsonResult SaveOnlineExamSetting(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<ONLINE_EXAM_SETTING>(sJsonData);
                    Result.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(Result.EXAM_DATE);
                    Result.STAFF_ID = sUserId;

                    if (!string.IsNullOrEmpty(Result.EXAM_SETTING_ID))
                    {
                        // update ..
                        var sUpdateSetting = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateOnlineExamSetting), sAcademicYear);
                        ObjJsonData.Message = (sUpdateSetting.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                    }
                    else
                    {
                        var IsExist = (List<ONLINE_EXAM_SETTING>)CMSHandler.FetchData<ONLINE_EXAM_SETTING>(Result,
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsOnlineExamSettingExist), sAcademicYear).DataSource.Data;
                        if (IsExist != null && IsExist.Count > 0)
                        {
                            ObjJsonData.Message = "Sorry ! Record Already Exist !";
                        }
                        else
                        {
                            // insert ...
                            var sSaveSetting = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertOnlineExamSetting), sAcademicYear);
                            ObjJsonData.Message = (sSaveSetting.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveOnlineExamSetting", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
