        public JsonResult SaveOnlineExamQuestions(string sJsonSaveData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    var Result = JsonConvert.DeserializeObject<JSON_SAVE_ONLINE_EXAMINFO>(sJsonSaveData);
                    if (Result.liExamQuestions != null && Result.liExamQuestions.Count > 0)
                    {
                        string sInertQuery = @"INSERT INTO ONLINE_EXAM_QUESTIONS
                                                (
	                                                CLASS_ID,
	                                                COURSE_ID,
	                                                EXAM_SETTING_ID,
	                                                ENTRY_DATE,
	                                                QUESTION,
	                                                ACADEMIC_YEAR,
	                                                STAFF_ID,
	                                                SEMESTER_ID
                                                )
                                                VALUES";
                        string sUpdateQuery = string.Empty;
                        int nInsertCount = 0;
                        int nUpdateCount = 0;
                        foreach (var item in Result.liExamQuestions)
                        {
                            if (!string.IsNullOrEmpty(item.EXAM_QUESTIONS_ID))
                            {
                                // Update Mode ,...
                                sUpdateQuery += "UPDATE ONLINE_EXAM_QUESTIONS SET CLASS_ID='" + item.CLASS_ID + "',COURSE_ID='" + item.COURSE_ID + "',QUESTION='" + item.QUESTION + "' WHERE EXAM_QUESTIONS_ID='" + item.EXAM_QUESTIONS_ID + "';";
                                nUpdateCount++;
                            }
                            else
                            {
                                // Check Exist ,...
                                var IsExist = (List<ONLINE_EXAM_QUESTIONS>)CMSHandler.FetchData<ONLINE_EXAM_QUESTIONS>(item,
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsOnlineExamQuestionExist), sAcademicYear).DataSource.Data;
                                if (IsExist != null && IsExist.Count > 0)
                                {
                                    // Exist Alert ,..
                                    ObjJsonData.Message += "" + item.QUESTION + " is Already Exist Try Another Question ! \n";
                                }
                                else
                                {
                                    // Insert Mode ,....
                                    sInertQuery += "('" + item.CLASS_ID + "','" + item.COURSE_ID + "','" + item.EXAM_SETTING_ID + "',curdate(),'" + item.QUESTION + "','" + sAcademicYear + "','" + sUserId + "','" + item.SEMESTER_ID + "'),";
                                    nInsertCount++;
                                }
                            }
                        }

                        // Execute Update Query ,...
                        if (nUpdateCount != 0)
                        {
                            using (MySQLHandler ObjHandler = new MySQLHandler())
                            {
                                ObjHandler.ExecuteAsScripts(sUpdateQuery);
                            }
                        }

                        // Execute Insert Query ,...
                        if (nInsertCount != 0)
                        {
                            using (MySQLHandler ObjHandler = new MySQLHandler())
                            {
                                sInertQuery = sInertQuery.TrimEnd(',');
                                sInertQuery = sInertQuery + ";";
                                ObjHandler.ExecuteAsScripts(sInertQuery);
                            }
                        }

                        if (nInsertCount != 0)
                        {
                            ObjJsonData.Message += "( " + nInsertCount + " ) Records Saved Successfully ! \n";
                        }
                        else if (nUpdateCount != 0)
                        {
                            ObjJsonData.Message += "( " + nUpdateCount + " ) Records Updated Successfully !";
                        }
                    }
                    else
                    {
                        ObjJsonData.Message = "Oops ! Something Went Wrong ! \n Please Check Your Input !";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveOnlineExamQuestions", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

