        public JsonResult SaveExamSeatting(string sExamType)
        {
            var ObjJsonData = new JsonResultData();
            var ObjModel = new EXAM_SEATINGS();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var RoomList = (List<SUP_ROOM>)CMSHandler.FetchData<SUP_ROOM>(new EXAM_SEATINGS { EXAM_TYPE = sExamType }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupRoomListByExamType)).DataSource.Data;
                    if (RoomList != null && RoomList.Count > 0)
                    {
                        foreach (var itemRoom in RoomList)
                        {
                            int k = 1;
                            for (int i = 1; i <= Convert.ToInt16(itemRoom.COLUMN); i++)
                            {
                                for (int j = 1; j <= Convert.ToInt16(itemRoom.ROW); j++)
                                {
                                    ObjModel.ROOM_ID = itemRoom.ROOM_ID;
                                    ObjModel.COLUMN_NO = i.ToString();
                                    ObjModel.ROW_NO = j.ToString();
                                    ObjModel.SEAT_POSITION = string.Concat(i.ToString(), ",", j.ToString());
                                    ObjModel.SEAT_CODE = itemRoom.BLOCK_CODE + Common.Delimiter.IPHEN + itemRoom.ROOM_NO + Common.Delimiter.IPHEN + k.ToString();
                                    ObjModel.EXAM_TYPE = sExamType;
                                    var UpdateQuiz = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertExamSeating), sAcademicYear);
                                    ObjJsonData.Message = (UpdateQuiz.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                    k++;
                                }
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamSeatting", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
