        // this is to order courses for columns nad rows by studen count 
        public List<COUNT_STATUS_BY_COURSE> GetCourseOrderByStudentCount(List<COUNT_STATUS_BY_COURSE> liCourseAndCount)
        {
            List<COUNT_STATUS_BY_COURSE> tempCountlist = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> tempOddCountlist = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> tempEvenCountlist = new List<COUNT_STATUS_BY_COURSE>();
            try
            {
                liCourseAndCount = liCourseAndCount.OrderByDescending(o => Convert.ToInt32(o.STUDENT_COUNT)).ToList();
                foreach (var item in liCourseAndCount)
                {
                    if (tempOddCountlist.Count == 0)
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "odd";
                        tempOddCountlist.Add(tempCourseCount);
                        continue;
                    }
                    if (tempEvenCountlist.Count == 0)
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "even";
                        tempEvenCountlist.Add(tempCourseCount);
                        continue;
                    }
                    if (tempOddCountlist.Sum(o => Convert.ToInt32(o.STUDENT_COUNT)) <= tempEvenCountlist.Sum(o => Convert.ToInt32(o.STUDENT_COUNT)))
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "odd";
                        tempOddCountlist.Add(tempCourseCount);
                        continue;
                    }
                    else
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "even";
                        tempEvenCountlist.Add(tempCourseCount);
                        continue;

                    }
                }

                //tempOddCountlist.AddRange(tempEvenCountlist);
                if (tempEvenCountlist != null && tempEvenCountlist.Count() > 0)
                {
                    tempOddCountlist = tempOddCountlist.Concat(tempEvenCountlist).ToList();
                }

                tempCountlist = tempOddCountlist;
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "GetCourseOrderByStudentCount", ex.Message);
                }
            }

            //tempEvenCountlist = tempOddCountlist;
            return tempCountlist;
        }
