        public JsonResult AssignExamSeatingAllotementsjc(string sExamType, string sExamsettingId, string sArrearSettingId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var objmodel = new EXAM_SEATING_ALLOTEMENT();
            string sSQL = string.Empty;
            objmodel.EXAM_SETTING_ID = sExamsettingId;

            string sDbString = string.Empty;

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ListExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE { EXAM_SETTING_ID = sExamsettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamTimeTableBySettingId), sAcademicYear).DataSource.Data;

                    if (ListExamTimeTable != null && ListExamTimeTable.Count > 0)
                    {
                        foreach (var item in ListExamTimeTable)
                        {
                            objmodel.EXAM_DATE = item.EXAM_DATE;
                            objmodel.EXAM_SESSION_ID = item.EXAM_SESSION_ID;
                            objmodel.ARREAR_SETTING_ID = "8";
                            sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseFromExamRegistrationByCourseAndSettingId).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.COURSE_ID, item.COURSE_ID);
                            var liExamRegistration = (List<CourseList>)CMSHandler.FetchData<CourseList>(objmodel, sSQL, sAcademicYear).DataSource.Data;
                            var liSeating = (List<EXAM_SEATINGS>)CMSHandler.FetchData<EXAM_SEATINGS>(objmodel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSeating), sAcademicYear).DataSource.Data;
                            sSQL = string.Empty;
                            sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseAndStudentCount).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.COURSE_ID, item.COURSE_ID);
                            var liCourseCount = (List<COUNT_STATUS_BY_COURSE>)CMSHandler.FetchData<COUNT_STATUS_BY_COURSE>(objmodel, sSQL, sAcademicYear).DataSource.Data;
                            if (liExamRegistration != null && liExamRegistration.Count > 0 && liCourseCount != null && liCourseCount.Count > 0)
                            {
                                #region Course Seating Allotment
                                sSQL = string.Empty;
                                sSQL = @"INSERT INTO `EXAM_SEATING_ALLOTEMENT`(`SEATING_ID`,`COURSE_ID`,`STUDENT_ID`,`EXAM_DATE`,`EXAM_SESSION_ID`,`EXAM_SETTING_ID`,`EXAM_TYPE`,`ACADEMIC_YEAR`)VALUES";
                                sDbString = sSQL;
                                //var liRegularCourseCount = liCourseCount.Where(x => x.STATUS == "R").ToList();
                                if (liCourseCount != null && liCourseCount.Count > 0)
                                {
                                    var liRegularCourseAndStudentCount = GetCourseOrderByStudentCount(liCourseCount);
                                    var liRegularOdd = liRegularCourseAndStudentCount.Where(x => x.STATUS == "odd").OrderBy(x => x.STUDENT_COUNT).ToList();
                                    var liRegularEven = liRegularCourseAndStudentCount.Where(x => x.STATUS == "even").OrderBy(x => x.STUDENT_COUNT).ToList();
                                    var liRegularOddSeating = liSeating.Where(x => x.COLUMN_NO == "1" || x.COLUMN_NO == "3" || x.COLUMN_NO == "5" || x.COLUMN_NO == "7" || x.COLUMN_NO == "9").ToList();
                                    var liRegularEvenSeating = liSeating.Where(x => x.COLUMN_NO == "2" || x.COLUMN_NO == "4" || x.COLUMN_NO == "6" || x.COLUMN_NO == "8").ToList();

                                    //var RoomList = (List<SUP_ROOM>)CMSHandler.FetchData<SUP_ROOM>(new EXAM_SETTING { EXAM_TYPE = sExamType }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupRoomListByExamType)).DataSource.Data;
                                    //if (RoomList!=null && RoomList.Count>0)
                                    //{
                                    //    foreach (var Roomitem in RoomList)
                                    //    {
                                    //        var liAllottement = liSeating.Where(x => x.ROOM_ID == Roomitem.ROOM_ID).OrderBy(x => x.SEATING_ID).ToList();
                                    //        foreach (var AssignItem in liAllottement)
                                    //        {

                                    //        }
                                    //    }
                                    //}


                                    #region For Girls

                                    // Odd Seating ...
                                    if (liRegularOdd != null && liRegularOdd.Count > 0)
                                    {
                                        foreach (var Odditem in liRegularOdd)
                                        {
                                            var liRegular = liExamRegistration.Where(x => x.STATUS == "R" && x.COURSE_ID == Odditem.COURSE_ID && x.SHIFT == "2").OrderBy(x => x.ROLL_NO).ToList();
                                            if (liRegular != null && liRegular.Count > 0)
                                            {
                                                foreach (var Courseitem in liRegular)
                                                {
                                                    if (liRegularOddSeating != null && liRegularOddSeating.Count > 0)
                                                    {
                                                        sSQL += "('" + liRegularOddSeating.FirstOrDefault().SEATING_ID + "','" + Courseitem.COURSE_ID + "','" + Courseitem.STUDENT_ID + "','" + item.EXAM_DATE + "','" + item.EXAM_SESSION_ID + "','" + item.EXAM_SETTING_ID + "','" + sExamType + "','" + sAcademicYear + "'),";
                                                        liExamRegistration.RemoveAll(x => x.COURSE_ID == Courseitem.COURSE_ID && x.STUDENT_ID == Courseitem.STUDENT_ID);
                                                        liSeating.RemoveAll(x => x.SEATING_ID == liRegularOddSeating.FirstOrDefault().SEATING_ID);
                                                        liRegularOddSeating.RemoveAt(0);
                                                    }
                                                }
                                            }
                                        }
                                    }



                                    // Even Seating ...
