        public JsonResult AssignExamSeatingAllotementForSJC(string sExamType, string sExamsettingId)
        {
            var ObjJsonData = new JsonResultData();
            var ObjModel = new EXAM_SEATINGS();
            var objmodel = new EXAM_SEATING_ALLOTEMENT();
            List<COUNT_STATUS_BY_COURSE> oddList = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> evenList = new List<COUNT_STATUS_BY_COURSE>();
            var oddcourseList = new List<ListStudents>();
            var ExceptioncourseList = new List<ListStudents>();
            var EvencourseList = new List<ListStudents>();
            var Exceptioncourse = new List<EXAM_TIMETABLE>();
            var ExceptiRoom = new List<SUP_ROOM>();
            string sSql = string.Empty;
            string sDbString = string.Empty;
            string ExceptionRooms = string.Empty;
            string ExceptionCourse = string.Empty;
            bool Startlist = false;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    //var ExamType = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new EXAM_SETTING { EXAM_SETTING_ID = sExamsettingId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchExamTypeByExamSetting), sAcademicYear).DataSource.Data;
                    var ExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE { EXAM_SETTING_ID = sExamsettingId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseByExamSettingForExternal), sAcademicYear).DataSource.Data;
                    //var SeatingExceptionCourse = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE { EXAM_SETTING_ID = sExamsettingId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExceptionCourseByExamSettingForExternal), sAcademicYear).DataSource.Data;
                    var ExamDate = ExamTimeTable.GroupBy(o => o.EXAM_DATE).ToList();
                    var ExamSession = ExamTimeTable.GroupBy(o => o.EXAM_SESSION_ID).ToList();
                    foreach (var dateitem in ExamDate)
                    {
                        foreach (var sessitem in ExamSession)
                        {
                            ExceptiRoom.Clear();
                            var FetchCourses = ExamTimeTable.Where(O => O.EXAM_DATE == dateitem.FirstOrDefault().EXAM_DATE && O.EXAM_SESSION_ID == sessitem.FirstOrDefault().EXAM_SESSION_ID).ToList();

                            if (FetchCourses != null && FetchCourses.Count > 0)
                            {
                                var liShift = FetchCourses.GroupBy(s => s.SHIFT).OrderByDescending(x => x.FirstOrDefault().SHIFT).ToList();
                                if (liShift != null && liShift.Count > 0)
                                {
                                    foreach (var itempro in liShift)
                                    {
                                        var FetchCourseses = FetchCourses.Where(s => s.SHIFT == itempro.FirstOrDefault().SHIFT).ToList();
                                        oddList.Clear();
                                        evenList.Clear();
                                        if (FetchCourseses != null && FetchCourseses.Count > 0)
                                        {
                                            sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentCountByCourseIdForExternal).Replace(Common.Delimiter.QUS + Common.STU_COURSE_REMARK.COURSE_ID, string.Join(",", FetchCourseses.Select(t => t.COURSE_ID))/*"148,147,142,138,1392,145,141,149,1488,1465,139,1365,268,261,253,1395"*/);
                                            var liCourseAndStudentCount = (List<COUNT_STATUS_BY_COURSE>)CMSHandler.FetchData<COUNT_STATUS_BY_COURSE>(new EXAM_TIMETABLE { EXAM_SETTING_ID = sExamsettingId }, sSql, sAcademicYear).DataSource.Data;
                                            liCourseAndStudentCount = GetCourseOrderByStudentCount(liCourseAndStudentCount);

                                            oddList = liCourseAndStudentCount.Where(x => x.STATUS == "odd").ToList();
                                            evenList = liCourseAndStudentCount.Where(x => x.STATUS == "even").ToList();

                                            int tempodcrscnt = 0;
                                            int tempevcrscnt = 0;
                                            int coursecount = FetchCourseses.Count();
                                            int oddcoursecount = coursecount / 2;
                                            var RoomList = (List<SUP_ROOM>)CMSHandler.FetchData<SUP_ROOM>(new EXAM_SETTING { EXAM_TYPE = sExamType }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupRoomListByExamType)).DataSource.Data;
                                            if (ExceptiRoom != null && ExceptiRoom.Count > 0)
                                            {
                                                ExceptiRoom.GroupBy(S => S.ROOM_ID).ToList();
                                                foreach (var items in ExceptiRoom)
                                                {
                                                    RoomList.RemoveAll(S => S.ROOM_ID == items.ROOM_ID);
                                                }
                                            }
                                            string OddCourseId = string.Join(",", oddList.Select(t => t.COURSE_ID));
                                            string EvenCourseId = string.Join(",", evenList.Select(t => t.COURSE_ID));
                                            if (!string.IsNullOrEmpty(OddCourseId))
                                            {
                                                sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentByCourseForSeatingAllotmentForExternal).Replace(Common.Delimiter.QUS + Common.STU_COURSE_REMARK.COURSE_ID, OddCourseId);
                                                oddcourseList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new EXAM_TIMETABLE { COURSE_ID = OddCourseId, EXAM_SETTING_ID = sExamsettingId }, sSql, sAcademicYear).DataSource.Data;
                                            }
                                            else
                                            {
                                                oddcourseList.Clear();
                                            }
                                            if (!string.IsNullOrEmpty(EvenCourseId))
                                            {
                                                sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentByCourseForSeatingAllotmentForExternal).Replace(Common.Delimiter.QUS + Common.STU_COURSE_REMARK.COURSE_ID, EvenCourseId);
                                                EvencourseList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new EXAM_TIMETABLE { COURSE_ID = EvenCourseId, EXAM_SETTING_ID = sExamsettingId }, sSql, sAcademicYear).DataSource.Data;
                                            }
                                            else
                                            {
                                                EvencourseList.Clear();
                                            }
                                            var ExamSeatingList = (List<EXAM_SEATINGS>)CMSHandler.FetchData<EXAM_SEATINGS>(new EXAM_TIMETABLE { EXAM_TYPE = sExamType }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchExamSeatingsList)).DataSource.Data;
                                            foreach (var item in RoomList)
                                            {
                                                sSql = string.Empty;
                                                sSql = @"INSERT INTO `EXAM_SEATING_ALLOTEMENT`(`SEATING_ID`,`COURSE_ID`,`STUDENT_ID`,`EXAM_DATE`,`EXAM_SESSION_ID`,`EXAM_SETTING_ID`,`EXAM_TYPE`,`ACADEMIC_YEAR`)VALUES";
                                                sDbString = sSql;
                                                int examcapacity = 0;
                                                // do
                                                // {
                                                for (int i = 1; i <= Convert.ToInt16(item.COLUMN); i++)
                                                {
                                                    if (Startlist)
                                                    {
                                                        var RoomAllogation = ExamSeatingList.Where(s => s.ROOM_ID == item.ROOM_ID && s.COLUMN_NO == i.ToString()).ToList();
                                                        Startlist = false;
                                                        foreach (var evenitem in RoomAllogation)
                                                        {
                                                            if (tempevcrscnt < EvencourseList.Count() && examcapacity < Convert.ToInt16(item.EXAM_CAPACITY))
                                                            {
                                                                ExceptiRoom.Add(new SUP_ROOM { ROOM_ID = item.ROOM_ID });
                                                                objmodel.SEATING_ID = evenitem.SEATING_ID;
                                                                objmodel.COURSE_ID = EvencourseList.ElementAt(tempevcrscnt).COURSE_ID;
                                                                objmodel.STUDENT_ID = EvencourseList.ElementAt(tempevcrscnt).STUDENT_ID;
                                                                objmodel.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE);
                                                                objmodel.EXAM_SESSION_ID = sessitem.FirstOrDefault().EXAM_SESSION_ID;
                                                                objmodel.EXAM_TYPE = sExamType;
                                                                objmodel.EXAM_SETTING_ID = dateitem.FirstOrDefault().EXAM_SETTING_ID;
                                                                objmodel.ACADEMIC_YEAR = sAcademicYear;
                                                                sSql += "('" + evenitem.SEATING_ID + "','" + EvencourseList.ElementAt(tempevcrscnt).COURSE_ID + "','" + EvencourseList.ElementAt(tempevcrscnt).STUDENT_ID + "','" + CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE) + "','" + sessitem.FirstOrDefault().EXAM_SESSION_ID + "','" + dateitem.FirstOrDefault().EXAM_SETTING_ID + "','" + sExamType + "','" + sAcademicYear + "'),";
                                                                tempevcrscnt++;
                                                                examcapacity++;

                                                            }

                                                        }
                                                    }
                                                    else
                                                    {
                                                        var RoomAllogation = ExamSeatingList.Where(s => s.ROOM_ID == item.ROOM_ID && s.COLUMN_NO == i.ToString()).ToList();
                                                        Startlist = true;
                                                        foreach (var Oddrowsitem in RoomAllogation)
                                                        {
                                                            if (tempodcrscnt < oddcourseList.Count() && examcapacity < Convert.ToInt16(item.EXAM_CAPACITY))
                                                            {
                                                                ExceptiRoom.Add(new SUP_ROOM { ROOM_ID = item.ROOM_ID });
                                                                objmodel.SEATING_ID = Oddrowsitem.SEATING_ID;
                                                                objmodel.COURSE_ID = oddcourseList.ElementAt(tempodcrscnt).COURSE_ID;
                                                                objmodel.STUDENT_ID = oddcourseList.ElementAt(tempodcrscnt).STUDENT_ID;
                                                                objmodel.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE);
                                                                objmodel.EXAM_SESSION_ID = sessitem.FirstOrDefault().EXAM_SESSION_ID;
                                                                objmodel.EXAM_TYPE = sExamType;
                                                                objmodel.EXAM_SETTING_ID = dateitem.FirstOrDefault().EXAM_SETTING_ID;
                                                                objmodel.ACADEMIC_YEAR = sAcademicYear;
                                                                sSql += "('" + Oddrowsitem.SEATING_ID + "','" + oddcourseList.ElementAt(tempodcrscnt).COURSE_ID + "','" + oddcourseList.ElementAt(tempodcrscnt).STUDENT_ID + "','" + CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE) + "','" + sessitem.FirstOrDefault().EXAM_SESSION_ID + "','" + dateitem.FirstOrDefault().EXAM_SETTING_ID + "','" + sExamType + "','" + sAcademicYear + "'),";
                                                                var result = CMSHandler.SaveOrUpdate(objmodel, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertExamSeatingAllotment), sAcademicYear);
                                                                tempodcrscnt++;
                                                                examcapacity++;
                                                            }
                                                        }
                                                    }
                                                }
                                                if (sDbString != sSql)
                                                {
                                                    sSql = sSql.Trim(',') + ";";
                                                    var sresultArgs = CMSHandler.SaveOrUpdate(null, sSql);
                                                    ObjJsonData.ErrorCode = (sresultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                                                    ObjJsonData.Message = (sresultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                                }
                                            }
                                        }
                                    }
                                }

                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "AssignExamSeatingAllotementForExternal", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }


