        public ActionResult ExamSeatingCourseWiseReport()
        {
            var ObjModel = new EXAM_SEATINGS();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var AcademicYear = (List<SUP_ACADEMIC_YEAR_LIST>)CMSHandler.FetchData<SUP_ACADEMIC_YEAR_LIST>(null, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList)).DataSource.Data;
                    if (AcademicYear != null && AcademicYear.Count > 0)
                        ObjViewModel.AcademicYearList = new SelectList(AcademicYear, Common.ACADEMIC_YEAR.ACADEMIC_YEAR_ID, Common.ACADEMIC_YEAR.AC_YEAR);
                    var ExamType = (List<SUP_EXAM_TYPE>)CMSHandler.FetchData<SUP_EXAM_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupExamType), sAcademicYear).DataSource.Data;
                    if (ExamType != null && ExamType.Count > 0)
                        ObjViewModel.ExamType = new SelectList(ExamType, Common.SUP_EXAM_TYPE.EXAM_TYPE, Common.SUP_EXAM_TYPE.EXAM_TYPE_NAME);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "ExamSeattingList", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
        public ActionResult BindExamSeatingCourseWiseReport(string sAcademicYear, string sExamType, string sExamsettingId, string sExamDate, string sExamSessionId)
        {
            var ObjModel = new EXAM_SEATING_ALLOTEMENT();
            string AcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(AcademicYear))
            {
                try
                {
                    ObjModel.EXAM_SETTING_ID = sExamsettingId;
                    ObjModel.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(sExamDate);
