        public JsonResult AddStaffForExamSeating(string sJsonData)
        {
            JsonResultData objResultData = new JsonResultData();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                try
                {
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
                    JSON_EVALUATOR objJson = serializer.Deserialize<JSON_EVALUATOR>(sJsonData);
                    if (objJson.JSON_EXAM_SEATING_INVIGILATOR != null && objJson.JSON_EXAM_SEATING_INVIGILATOR.Count > 0)
                    {
                        foreach (var result in objJson.JSON_EXAM_SEATING_INVIGILATOR)
                        {
                            result.ACADEMIC_YEAR = sAcademicYear;
                            result.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(result.EXAM_DATE);
                            if (!string.IsNullOrEmpty(result.SEATING_INVIGILATOR_ID))
                            {
                                result.SEATING_INVIGILATOR_ID = (result.SEATING_INVIGILATOR_ID).Trim();
                            }
                            if (!string.IsNullOrEmpty(result.SEATING_INVIGILATOR_ID) && result.SEATING_INVIGILATOR_ID != "0")
                            {
                                ResultArgs resultArgs = CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamSeatingInvigilatorbyId), sAcademicYear);
                                objResultData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                            }
                            else
                            {
                                if (result.STAFF_ID != "0")
                                {
                                    ResultArgs resultArgs = CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddExamSeatingInvigilator), sAcademicYear);
                                    objResultData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                }

                            }

                        }

                    }
                    else
                    {

                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("Examination", "AddStaffForExamSeating", ex.Message);
                    }
                }

            }
            return Json(objResultData, JsonRequestBehavior.AllowGet);
        }
