        public JsonResult AssignExamSeatingInvigilatorList(string sExamType, string sExamsettingId)
        {
            JsonResultData objResultData = new JsonResultData();
            Random random = new Random();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                var SupervisionRoomList = new List<EXAM_SEATING_ALLOTEMENT>();
                double IndHourStaff;
                var LiSupervisionStafflist = new List<EXAM_SEATING_INVIGILATOR>();
                var LicheckForMaximumAllotementForStaff = new List<EXAM_SEATING_INVIGILATOR>();
                var ObjModel = new EXAM_SEATING_INVIGILATOR();
                string sSql = string.Empty;
                try
                {
                    var ExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE { EXAM_SETTING_ID = sExamsettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseByExamSessionFromTimeTable), sAcademicYear).DataSource.Data;
                    var IndSupervisionRooms = (List<EXAM_SEATING_ALLOTEMENT>)CMSHandler.FetchData<EXAM_SEATING_ALLOTEMENT>(new EXAM_SEATING_ALLOTEMENT { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalRoomsForSupervision), sAcademicYear).DataSource.Data;
                    var DoubSupervisionRooms = (List<EXAM_SEATING_ALLOTEMENT>)CMSHandler.FetchData<EXAM_SEATING_ALLOTEMENT>(new EXAM_SEATING_ALLOTEMENT { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalRoomsForDoubleSupervision), sAcademicYear).DataSource.Data;
                    var ExamDate = ExamTimeTable.GroupBy(o => o.EXAM_DATE).ToList();
                    var ExamSession = ExamTimeTable.GroupBy(o => o.EXAM_SESSION_ID).ToList();
                    var SupervisionType = (List<SUP_SUPERVISON_STAFF_TYPE>)CMSHandler.FetchData<SUP_SUPERVISON_STAFF_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupervisionStafftype)).DataSource.Data;
                    var LiAllStaffBySupervisiontype = (List<EXAM_SEATING_INVIGILATOR>)CMSHandler.FetchData<EXAM_SEATING_INVIGILATOR>(new STF_PERSONAL_INFO { SUPERVISION_TYPE = "1" }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStaffBySupervisiontype), sAcademicYear).DataSource.Data;
                    var LiSupervisionStaffCountAlldpt = (List<EXAM_SEATING_INVIGILATOR>)CMSHandler.FetchData<EXAM_SEATING_INVIGILATOR>(new STF_PERSONAL_INFO { SUPERVISION_TYPE = "1" }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalStaffCountForSupervision), sAcademicYear).DataSource.Data;
                    double dIndSuperRooms = IndSupervisionRooms.Count();
                    double dDoubSuperRooms = DoubSupervisionRooms.Count();
                    double DFetchStaffSupervisionType = LiAllStaffBySupervisiontype.Count();
                    IndHourStaff = Math.Round((dIndSuperRooms + dDoubSuperRooms) / DFetchStaffSupervisionType);
                    if (true)
                    {
                        //var ExamSettings = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new EXAM_SETTING { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStaffBySupervisiontype), sAcademicYear).DataSource.Data;
                        var ExceptionStaff = (List<EXAM_SEATING_INVIGILATOR>)CMSHandler.FetchData<EXAM_SEATING_INVIGILATOR>(new STF_PERSONAL_INFO { SUPERVISION_TYPE = "2" }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStaffBySupervisiontype), sAcademicYear).DataSource.Data;
                        var IndividualRooms = (List<EXAM_SEATING_ALLOTEMENT>)CMSHandler.FetchData<EXAM_SEATING_ALLOTEMENT>(new EXAM_SEATING_ALLOTEMENT { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalRoomsForIndividualSupervision), sAcademicYear).DataSource.Data;
                        if (ExceptionStaff != null && ExceptionStaff.Count > 0)
                        {

                            foreach (var itemstaff in ExceptionStaff)
                            {
                                var vRandomCounts = IndividualRooms[random.Next(IndividualRooms.Count)];
                                for (int i = 1; i < 2; i++)
                                {
                                    ObjModel.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(vRandomCounts.EXAM_DATE);
                                    ObjModel.EXAM_SESSION_ID = vRandomCounts.EXAM_SESSION_ID;
                                    ObjModel.EXAM_TYPE = sExamType;
                                    ObjModel.EXAM_SETTING_ID = sExamsettingId;
                                    ObjModel.ROOM_ID = vRandomCounts.ROOM_ID;
                                    ObjModel.STAFF_ID = itemstaff.STAFF_ID;
                                    ResultArgs resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddExamSeatingInvigilator), sAcademicYear);
                                    IndividualRooms.RemoveAll(p => p.ROOM_ID == vRandomCounts.ROOM_ID && p.EXAM_DATE == vRandomCounts.EXAM_DATE && p.EXAM_SESSION_ID == vRandomCounts.EXAM_SESSION_ID);
                                }
                            }
                        }

                    }

                    foreach (var sessitem in ExamSession)
                    {
                        foreach (var dateitem in ExamDate)
                        {
                            // Individual Allotement
                            int tempRoomcount = 0;
                            bool Fdouble = true;
                            SupervisionRoomList = (List<EXAM_SEATING_ALLOTEMENT>)CMSHandler.FetchData<EXAM_SEATING_ALLOTEMENT>(new EXAM_SEATING_ALLOTEMENT { EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE), EXAM_SESSION_ID = sessitem.FirstOrDefault().EXAM_SESSION_ID, EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSeatinAllotedRoomByExamdateandExamSession), sAcademicYear).DataSource.Data;
                            // check For full Room
                            while (tempRoomcount < SupervisionRoomList.Count())
                            {
                                // have to check for individual staff allotement for the exam
                                foreach (var dptStffcount in LiSupervisionStaffCountAlldpt)
                                {
                                    // DeparmentTotalHour=departmentstaffcount*individualstaffHour
                                    double deptToalHours = Math.Round(Convert.ToInt16(LiSupervisionStaffCountAlldpt.FirstOrDefault().TOTAL_STAFF) * Math.Round((dIndSuperRooms + dDoubSuperRooms) / DFetchStaffSupervisionType, 2));
                                    // AllotedHourByDateForDepartment=DeparmentTotalHour/ExamDatesCount
                                    double totaldpthourfordate = Math.Round(deptToalHours / ExamDate.Count());
                                    // AllotedHourForDepartmentStaffThisSession= AllotedHourByDateForDepartment/AlldepartmentAlloteHourbyDate*supervionNeededTodayThisSession
                                    double inddpthourfordate = Math.Round(totaldpthourfordate / ((IndSupervisionRooms.Count() + DoubSupervisionRooms.Count()) / ExamDate.Count()) * SupervisionRoomList.Count());
                                    // check for the department whether they have the allotement today/Session
                                    if (inddpthourfordate >= 1)
                                    {
                                        int staffid = 0;
                                        for (int i = 1; i <= inddpthourfordate; i++)
                                        {
                                            if (tempRoomcount < SupervisionRoomList.Count())
                                            {
                                                sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllSupervisionStaffByDepartment).Replace(Common.Delimiter.QUS + Common.EXAM_SEATING_INVIGILATOR.INDIVIDUAL_HOUR, IndHourStaff.ToString());
                                                LiSupervisionStafflist = (List<EXAM_SEATING_INVIGILATOR>)CMSHandler.FetchData<EXAM_SEATING_INVIGILATOR>(new EXAM_SEATING_INVIGILATOR { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType, SUPERVISION_TYPE = "1", DEPARTMENT = dptStffcount.DEPARTMENT }, sSql, sAcademicYear).DataSource.Data;
                                                sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckForMaximumAllotementForStaff).Replace(Common.Delimiter.QUS + Common.EXAM_SEATING_INVIGILATOR.INDIVIDUAL_HOUR, IndHourStaff.ToString());
                                                LicheckForMaximumAllotementForStaff = (List<EXAM_SEATING_INVIGILATOR>)CMSHandler.FetchData<EXAM_SEATING_INVIGILATOR>(new EXAM_SEATING_INVIGILATOR { EXAM_SETTING_ID = sExamsettingId, EXAM_TYPE = sExamType, STAFF_ID = LiSupervisionStafflist.ElementAt(staffid).STAFF_ID }, sSql, sAcademicYear).DataSource.Data;
                                                ObjModel.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(dateitem.FirstOrDefault().EXAM_DATE);
                                                ObjModel.EXAM_SESSION_ID = sessitem.FirstOrDefault().EXAM_SESSION_ID;
                                                ObjModel.EXAM_TYPE = sExamType;
                                                ObjModel.EXAM_SETTING_ID = sExamsettingId;
                                                ObjModel.ROOM_ID = SupervisionRoomList.ElementAt(tempRoomcount).ROOM_ID;
                                                if (LiSupervisionStafflist != null && LiSupervisionStafflist.Count > 0)
                                                {
                                                    var DoubleSupervisionrooms = DoubSupervisionRooms.Where(s => s.ROOM_ID == SupervisionRoomList.ElementAt(tempRoomcount).ROOM_ID && s.EXAM_DATE == dateitem.FirstOrDefault().EXAM_DATE && s.EXAM_SESSION_ID == sessitem.FirstOrDefault().EXAM_SESSION_ID).ToList();

                                                    if (DoubleSupervisionrooms != null && DoubleSupervisionrooms.Count > 0)
                                                    {
                                                        // For Double Supervision
                                                        if (LicheckForMaximumAllotementForStaff.FirstOrDefault().STAFF_ID != "1")
                                                        {
                                                            // staffid = 0;
                                                            if (Fdouble)
                                                            {
                                                                Fdouble = false;
                                                                ObjModel.ROOM_ID = SupervisionRoomList.ElementAt(tempRoomcount).ROOM_ID;
                                                                ObjModel.STAFF_ID = LiSupervisionStafflist.ElementAt(staffid).STAFF_ID;
                                                                ResultArgs resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddExamSeatingInvigilator), sAcademicYear);
                                                            }
                                                            else
                                                            {
                                                                Fdouble = true;
                                                                ObjModel.ROOM_ID = SupervisionRoomList.ElementAt(tempRoomcount).ROOM_ID;
                                                                ObjModel.STAFF_ID = LiSupervisionStafflist.ElementAt(staffid).STAFF_ID;
                                                                ResultArgs resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddExamSeatingInvigilator), sAcademicYear);
                                                                tempRoomcount++;
                                                            }

                                                        }
                                                        else
                                                        {
                                                            // staffid ++;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        if (LicheckForMaximumAllotementForStaff.FirstOrDefault().STAFF_ID != "1")
                                                        {
                                                            staffid = 0;
                                                            ObjModel.STAFF_ID = LiSupervisionStafflist.ElementAt(staffid).STAFF_ID;
                                                            ResultArgs resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddExamSeatingInvigilator), sAcademicYear);
                                                            tempRoomcount++;
                                                        }
                                                        else
                                                        {
                                                            //staffid++;
                                                        }
                                                    }
                                                }
                                                else
                                                {
                                                    continue;
                                                }

                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    objResultData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "AssignExamSeatingInvigilatorList", ex.Message);
                    }
                }
            }
            else
            {

            }



            return Json(objResultData, JsonRequestBehavior.AllowGet);
        }



