        public JsonResult SaveExaminationSeatingAttendance(string sJsonExamSeatingAttandance)
        {
            JavaScriptSerializer serializer = new JavaScriptSerializer();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    if (sJsonExamSeatingAttandance != null)
                    {
                        var Result = serializer.Deserialize<JSON_EVALUATOR>(sJsonExamSeatingAttandance);
                        if (Result.JSON_EXAM_SEATING_ATTENDANCE != null && Result.JSON_EXAM_SEATING_ATTENDANCE.Count > 0)
                        {
                            foreach (var item in Result.JSON_EXAM_SEATING_ATTENDANCE)
                            {
                                if (!string.IsNullOrEmpty(item.EXAM_ATTENDANCE_ID) && (item.IS_CHECKED == "0"))
                                {
                                    item.STAFF_ID = sUserId;
                                    item.EXAM_DATE = DateTime.Now.ToString("yyyy-MM-dd");
                                    resultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamSeatingAttendanceAbsentees));
                                }
                                else if (string.IsNullOrEmpty(item.EXAM_ATTENDANCE_ID) && (item.IS_CHECKED == "1"))
                                {
                                    item.STAFF_ID = sUserId;
                                    item.EXAM_DATE = DateTime.Now.ToString("yyyy-MM-dd");
                                    resultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertExamSeatingAttendanceAbsentees));
                                }
                            }
                            objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                            objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                        }
                        else
                        {
                            objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            objJsonData.Message = Common.Messages.NoRecordsfound;
                        }
                    }
                    else
                    {
                        objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        objJsonData.Message = Common.ErrorMessage.BadRequest;
                    }
                }
                catch (Exception ex)
                {
