        /// <summary>
        /// Bind Online Exam Report
        /// </summary>
        /// <param name="sClassId"></param>
        /// <param name="sCourseId"></param>
        /// <param name="sStudentId"></param>
        /// <param name="sClass"></param>
        /// <param name="sCourse"></param>
        /// <returns></returns>
        public ActionResult BindOnlinExamReportByClassandCourseandStudent(string sClassId, string sCourseId, string sStudentId, string sClass, string sCourse)
        {
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                try
                {
                    string sSql = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindReportForOnlineExamByClassandCourseandStudent);
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    objViewModel.Class = sClass;
                    objViewModel.Course = sCourse;
                    //Fetch online Exam Details by Class and Course and Student
                    objViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
                    var liOnlineExamFields = (List<ONLINEEXAMINATION_REPORTFIELDS>)CMSHandler.FetchData<ONLINEEXAMINATION_REPORTFIELDS>(null,
                       sSql.Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.CLASS_ID, sClassId)
                       .Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.COURSE_ID, sCourseId)
                       .Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sStudentId), sAcademicYear).DataSource.Data;
                    if (liOnlineExamFields != null && liOnlineExamFields.Count > 0)
                    {
                        foreach (var item in liOnlineExamFields)
                        {
                            byte[] bytes = Convert.FromBase64String(item.ANSWER);
                            item.ANSWER = Encoding.UTF8.GetString(bytes);
                        }
                        objViewModel.liOnlinExamReportFields = liOnlineExamFields;
                    }
                    string sSql1 = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentDetailsByStudentId);
                    objViewModel.liStudentPersonalInfo = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(null,
                      sSql1.Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sStudentId), sAcademicYear).DataSource.Data;
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("Examination", "BindOnlinExamReportByClassandCourseandStudent", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(objViewModel);
        }
