        public ActionResult BindCourseCompleted(string sProgrammeGroupId, string sApplicationType, string sBatch, string sClassyear, string sPassmonth, string passmonth)
        {
            string sAcademicYear = string.Empty;
            string sSql = string.Empty;
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            SEMESTER_MARKS objModel = new SEMESTER_MARKS();
            List<SEMESTER_MARKS> liSemestermarks = new List<SEMESTER_MARKS>();
            List<SEMESTER_MARKS> liFirstsemmarks = new List<SEMESTER_MARKS>();
            List<SEMESTER_MARKS> liSecondsemmarks = new List<SEMESTER_MARKS>();
            List<SEMESTER_MARKS> liFinalsemmarks = new List<SEMESTER_MARKS>();
            SUP_BATCH_DURATION objbatchduartion = new SUP_BATCH_DURATION();
            AcademicBatches objAcyear = new AcademicBatches();
            sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                ViewBag.monthpass = passmonth;
                objAcyear.ACADEMIC_YEAR_ID = sBatch;
                objAcyear.BATCH_YEAR = sClassyear;
                var Ac_yearbatchid = (List<AcademicBatches>)CMSHandler.FetchData<AcademicBatches>(objAcyear, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicBatchid)).DataSource.Data;
                objbatchduartion.BATCH_ID = Ac_yearbatchid.FirstOrDefault().BATCH_ID;
                objbatchduartion.APPLICATION_TYPE_ID = sApplicationType;
                try
                {
                    var BatchExpiredYear = (List<SUP_BATCH_DURATION>)CMSHandler.FetchData<SUP_BATCH_DURATION>(objbatchduartion, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchBatchExpiredYear)).DataSource.Data;
                    if (BatchExpiredYear != null && BatchExpiredYear.Count > 0)
                    {
                        for (int i = Convert.ToInt16(BatchExpiredYear.FirstOrDefault().BEGIN_YEAR); i < Convert.ToInt16(BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR); i++)
                        {
                            objModel.ACADEMIC_YEAR = i.ToString();
                            objModel.APPLICATION_TYPE_ID = sApplicationType;
                            objModel.BATCH = sBatch;
                            sSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseCompletedByDeptId).Replace(Common.Delimiter.QUS + Common.CP_PROGRAMME_2017.PROGRAMME_GROUP_ID, sProgrammeGroupId);
                            sSql = sSql.Replace(Common.Delimiter.QUS + Common.SUP_CLASS_YEAR.CLASS_YEAR, sClassyear);
                            var CourseCompletedmark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, i.ToString()).DataSource.Data;
                            if (CourseCompletedmark != null)
                            {
                                liSemestermarks = liSemestermarks.Concat(CourseCompletedmark).ToList();
                            }
                        }
                        var groupstudentandexam = liSemestermarks.GroupBy(o => new { o.STUDENT_ID, o.EXAM_SETTING_ID }).ToList();

                        foreach (var groupitem in groupstudentandexam)
                        {
                            if (groupitem.FirstOrDefault().EXAM_SETTING_ID == sPassmonth.ToString())
                            {
                                liSecondsemmarks.Add(new SEMESTER_MARKS { STUDENT_ID = groupitem.FirstOrDefault().STUDENT_ID });
                            }
                        }
                        if (liSecondsemmarks != null && liSecondsemmarks.Count > 0)
                        {
                            foreach (var item in liSecondsemmarks)
                            {
                                liFirstsemmarks = liSemestermarks.Where(o => o.STUDENT_ID == item.STUDENT_ID).ToList();
                                if (liFirstsemmarks != null && liFirstsemmarks.Count > 0)
                                {
                                    liFinalsemmarks = liFinalsemmarks.Concat(liFirstsemmarks).ToList();
                                }
                            }
                        }



                        objViewModel.LiSemesterMarks = liFinalsemmarks;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "BindCourseCompleted", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "BindCourseCompleted", ex.Message);
                    }
                }

            }
            return View(objViewModel);
        }
        #endregion

