        //For Fetch Courses By Class and Staff
        public string FethCourseByClassIdAndStaffId(string Class_Id, string Staff_Id)
        {
            string sOption = string.Empty;
            if (Class_Id != null && Staff_Id != null)
            {
                ClassList ObjClass = new ClassList();
                List<CourseList> liCourse = new List<CourseList>();
                ObjClass.CLASS_ID = Class_Id;
                ObjClass.STAFF_ID = Staff_Id;
                string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

                liCourse = (List<CourseList>)CMSHandler.FetchData<CourseList>(ObjClass, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseByStaffId), sAcademicYear).DataSource.Data;
                if (liCourse != null && liCourse.Count > 0)
                {
                    foreach (var item in liCourse)
                    {
                        sOption += "<option value=" + item.COURSE_ROOT_ID + "   cms-clscourse-staff-id=" + item.CLSCRSSTF_ID + ">" + item.COURSE_TITLE + "</option>";
                    }
                }

            }
            return sOption;
        }
        //Save Quiz Setting
        public JsonResult SaveQuizSettingFromAdmin(string sSaveQuizSetting)
        {
            JsonResultData ObjJsonData = new JsonResultData();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null && sSaveQuizSetting != null)
            {
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                var result = JsonConvert.DeserializeObject<QUIZ_SETTING>(sSaveQuizSetting);
                result.START_DATE = CommonMethods.ConvertdatetoyearFromat(result.START_DATE);
                if (!string.IsNullOrEmpty(result.SETTING_ID))
                {
                    var UpdateQuiz = CMSHandler.SaveOrUpdate(result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizSetting), sAcademicYear);
                    ObjJsonData.Message = (UpdateQuiz.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                }
                else
                {
