                    var liActiveSettingId = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(new QUIZ_SETTING() { SETTING_ID = SettingId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizSettingByQuizSetting), sAcademicYear).DataSource.Data;
                    //var liActiveSettingId = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(new QUIZ_SETTING() { SETTING_ID=SettingId},
                    //       ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.GetActiveSettingByClassAndCourseAndStaffIds), sAcademicYear).DataSource.Data;
                    if (liActiveSettingId != null && liActiveSettingId.Count > 0)
                    {
                        sSettingId = liActiveSettingId.FirstOrDefault().SETTING_ID;
                    }
                    else
                    {
                        ObjJsonData.Message = "No Active Setting For The Course !";
                        return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                    }
                    string sSemsterId = string.Empty;
                    string sClassId = string.Empty;
                    string sCourseId = string.Empty;
                    string Quiz_Id = string.Empty;
                    // Fetch SemesterId and class and course  By settingId  .
                    var liFetchSemsterandClassandCourseByCourse = (List<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>(new QUIZ_SETTING() { SETTING_ID = SettingId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClassandCourseandSemesterByQuizSetting), sAcademicYear).DataSource.Data;
                    if (liFetchSemsterandClassandCourseByCourse != null && liFetchSemsterandClassandCourseByCourse.Count > 0)
                    {
                        sSemsterId = liFetchSemsterandClassandCourseByCourse.FirstOrDefault().SEMESTER_ID;
                        sClassId = liFetchSemsterandClassandCourseByCourse.FirstOrDefault().CLASS_ID;
                        sCourseId = liFetchSemsterandClassandCourseByCourse.FirstOrDefault().COURSE_ID;
                    }
                    else
                    {
                        ObjJsonData.Message = "Something went wrong please try again later!";
                        return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                    }


                    var ObjModel = new QUIZ_STUDENT_SHUFFLE()
                    { ENTRY_ID = sStaffId, SETTING_ID = sSettingId, CLASS_ID = sClassId, COURSE_ID = sCourseId };
                    string ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ListQuizStudentShuffle).Replace(Common.Delimiter.QUS + "SETTING_ID", sSettingId);
                    // Student Shuffle List ...
                    ObjViewModel.liQuizStudentShuffle = (List<ListQuizStudent>)CMSHandler.FetchData<ListQuizStudent>(ObjModel, ssql, sAcademicYear).DataSource.Data;

                    // Fetch Set List ...
                    ObjViewModel.liBatch = (List<SUP_SETS>)CMSHandler.FetchData<SUP_SETS>(null,
                            SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSet), sAcademicYear).DataSource.Data;
                    var liMFSet = (List<SUP_SETS>)CMSHandler.FetchData<SUP_SETS>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMathTheFollowingGroupSet), sAcademicYear).DataSource.Data;
                    var liObjSet = (List<SUP_SETS>)CMSHandler.FetchData<SUP_SETS>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveGroupSet), sAcademicYear).DataSource.Data;
                    var liFillInBlank = (List<SUP_SETS>)CMSHandler.FetchData<SUP_SETS>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFillInBlankGroupSet), sAcademicYear).DataSource.Data;
                    var liSet = new List<SUP_SETS>();
                    if (liMFSet != null && liMFSet.Count > 0)
                    {
                        liSet = (liSet != null && liSet.Count > 0) ? liSet.Concat(liMFSet).ToList() : liMFSet;
                    }
                    if (liObjSet != null && liObjSet.Count > 0)
                    {
                        liSet = (liSet != null && liSet.Count > 0) ? liSet.Concat(liObjSet).ToList() : liObjSet;
                    }

                    if (liFillInBlank != null && liFillInBlank.Count > 0)
                    {
                        liSet = (liSet != null && liSet.Count > 0) ? liSet.Concat(liFillInBlank).ToList() : liFillInBlank;
                    }

                    ObjViewModel.liBatch = liSet.GroupBy(x => x.SET_ID).Select(x => new SUP_SETS() { SET_ID = x.FirstOrDefault().SET_ID, SET_NAME = x.FirstOrDefault().SET_NAME }).ToList();
                    //if (liMF_SET != null && liMF_SET.Count > 0)
                    //{
                    //    ObjViewModel.Batch = new SelectList(liMF_SET, Common.SUP_SETS.SET_ID, Common.SUP_SETS.SET_NAME);
                    //}
                    return View(ObjViewModel);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "QuizStudentShuffle", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            // return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

