                    var Result = JsonConvert.DeserializeObject<JSON_SAVE_QUIZ>(sSaveQuizStudentShuffle);

                    if (Result.liQuizStudentShuffle != null && Result.liQuizStudentShuffle.Count > 0)
                    {
