                        int nSuccessCount = 0;
                        int nFailureCount = 0;
                        foreach (var item in Result.liQuizStudentShuffle)
                        {
                            item.SEMESTER_ID = sSemesterId;
                            item.SETTING_ID = sSettingId;
                            item.CLASS_ID = sClassId;
