                                }
                            }
                        }
                        ObjJsonData.Message = "( " + nSuccessCount + " ) - " + Common.Messages.RecordsSavedSuccessfully + "\n" + "( " + nFailureCount + " ) - " + Common.Messages.FailedToSaveRecords;
                    }


                    //var sArray = Result.STUDENT_ID.Split(',');
                    //// Fetch Shuffled Student List ...
                    //var IsExist = (List<QUIZ_STUDENT_SHUFFLE>)CMSHandler.FetchData<QUIZ_STUDENT_SHUFFLE>(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsExistQuizStudentShuffle), sAcademicYear).DataSource.Data;
