                    //            var UpdateQuizShuffle = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizStudentShuffle), sAcademicYear);
                    //            ObjJsonData.Message = (UpdateQuizShuffle.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
