                    //        if (hasItem == false && item.SET_ID == Result.SET_ID)
                    //        {
                    //            var DeleteQuizShuffle = CMSHandler.SaveOrUpdate(new QUIZ_STUDENT_SHUFFLE() { QUIZ_SHUFFLE_ID = item.QUIZ_SHUFFLE_ID },
                    //                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteQuizStudentShuffle), sAcademicYear);
