        #region CIA HallticketForClassIncharge
        public ActionResult CIAHallTicketForClassIncharge()
        {
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            string sSTaff_Id = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ClassIncharge = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new CLASS_INCHARGE() { STAFF_ID = sSTaff_Id }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchClassByClassIncharge), sAcademicYear).DataSource.Data;
                    objViewModel.ClassList = new SelectList(ClassIncharge, Common.CP_CLASSES_2017.CLASS_ID, Common.CP_CLASSES_2017.CLASS_NAME);
                    var ExamType = (List<SUP_EXAM_TYPE>)CMSHandler.FetchData<SUP_EXAM_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupExamType), sAcademicYear).DataSource.Data;
                    if (ExamType != null && ExamType.Count > 0)
                        objViewModel.ExamType = new SelectList(ExamType, Common.SUP_EXAM_TYPE.EXAM_TYPE, Common.SUP_EXAM_TYPE.EXAM_TYPE_NAME);
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("CIAHallTicketForClassIncharge", "ExaminationController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("CIAHallTicketForClassIncharge", "ExaminationController", Ex.Message);
                    }

                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");
            return View(objViewModel);
        }
