        public ActionResult BindOnlineQuizPreviewForAdmin(string sClassId, string sCourseId, string sSetId, string sSettingId, string sStaffId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            //string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    //   Fetch Class & Course Info  By Staff...
                    var liFetchCourse = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId },
                        SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoForQuizByStaff), sAcademicYear).DataSource.Data;
                    ObjViewModel.liCourseInfo = liFetchCourse;

                    // Fetch Match The Following Quiz Questions ...
                    var liQuizMatchTheFollowingQuestions = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(
                        new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId, SET_ID = sSetId, SETTING_ID = sSettingId },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchTheFollowingQuizQuestionsByStaff), sAcademicYear).DataSource.Data;
                    var liQuizQuestions = liQuizMatchTheFollowingQuestions;


                    // Fetch Match The Following Quiz Options ...
                    var liQuizMatchTheFollowingOptions = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(
                       new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId, SET_ID = sSetId, SETTING_ID = sSettingId },
                        SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchTheFollowingQuizOptionsByStaff), sAcademicYear).DataSource.Data;
                    var liQuizOptions = liQuizMatchTheFollowingOptions;


                    // Fetch Objective Quiz Questions ...
                    var liQuizObjectiveQuestions = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(
                        new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId, SET_ID = sSetId, SETTING_ID = sSettingId },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveQuizQuestionsByStaff), sAcademicYear).DataSource.Data;
                    if (liQuizObjectiveQuestions != null && liQuizObjectiveQuestions.Count > 0)
                    {
                        liQuizQuestions = (liQuizQuestions != null && liQuizQuestions.Count > 0) ? liQuizQuestions.Concat(liQuizObjectiveQuestions).ToList() : liQuizObjectiveQuestions;
                        ObjViewModel.liOnlineQuizQuestions = liQuizQuestions;
                    }

                    // Fetch Objective Quiz Options ...
                    var liQuizObjectiveOptions = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(
                        new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId, SET_ID = sSetId, SETTING_ID = sSettingId },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveQuizOptionsByStaff), sAcademicYear).DataSource.Data;
                    if (liQuizObjectiveOptions != null && liQuizObjectiveOptions.Count > 0)
