        public ActionResult BindQuizStudentMarkListForAdmin(string sClassId, string sCourseId, string sSettingId, string sStaffId)
        {
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null && Session[Common.SESSION_VARIABLES.USER_ID] != null)
            {
                try
                {
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
