                    objViewModel.liCourseInfo = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(new QUIZ_CLASS_COURSE_STAFF() { STAFF_ID = sStaffId, CLASS_ID = sClassId, COURSE_ID = sCourseId },
