                    var liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new QUIZ_CLASS_COURSE_STAFF() { CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sStaffId },
                               ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentByClassAndCourse), sAcademicYear).DataSource.Data;
                    objViewModel.liStudentPersonalInfo = liStudentList;

                    //Fetch Match The Following Exam MarkList
                    var liMatchtheFollowingMarkList = (List<QUIZ_STUDENT_MARKLIST>)CMSHandler.FetchData<QUIZ_STUDENT_MARKLIST>(new QUIZ_CLASS_COURSE_STAFF() { SETTING_ID = sSettingId },
                     SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchtheFollowingMarkListForStaff), sAcademicYear).DataSource.Data;
                    var liQuizMarkList = liMatchtheFollowingMarkList;

                    //Fetch Objective Exam MarkList
                    var liObjectiveMarkList = (List<QUIZ_STUDENT_MARKLIST>)CMSHandler.FetchData<QUIZ_STUDENT_MARKLIST>(new QUIZ_CLASS_COURSE_STAFF() { SETTING_ID = sSettingId },
                     SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveMarkListForStaff), sAcademicYear).DataSource.Data;
                    if (liObjectiveMarkList != null && liObjectiveMarkList.Count > 0)
                        liQuizMarkList = (liQuizMarkList != null && liQuizMarkList.Count > 0) ? liQuizMarkList.Concat(liObjectiveMarkList).ToList() : liObjectiveMarkList;


                    //Fetch Fill in the Blanks  MarkList
                    var liFillintheBlanksMarkList = (List<QUIZ_STUDENT_MARKLIST>)CMSHandler.FetchData<QUIZ_STUDENT_MARKLIST>(new QUIZ_CLASS_COURSE_STAFF() { SETTING_ID = sSettingId },
                     SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFillintheBlanksMarkListForStaff), sAcademicYear).DataSource.Data;
                    if (liFillintheBlanksMarkList != null && liFillintheBlanksMarkList.Count > 0)
                        liQuizMarkList = (liQuizMarkList != null && liQuizMarkList.Count > 0) ? liQuizMarkList.Concat(liFillintheBlanksMarkList).ToList() : liFillintheBlanksMarkList;

                    objViewModel.liQuizMarkList = liQuizMarkList;

                    // Fetch Quiz Setting By Id ,...
                    var liQuizSetting = (List<QUIZ_CLASS_COURSE_STAFF>)CMSHandler.FetchData<QUIZ_CLASS_COURSE_STAFF>(new QUIZ_SETTING() { SETTING_ID = sSettingId },
                           SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizSettingById), sAcademicYear).DataSource.Data;
                    objViewModel.liQuizSetting = liQuizSetting;
