                try
                {
                    // Fetch Course Info ,...
                    ObjViewModel.liCIA_Staff_Info = (List<CIA_STAFF_INFO>)CMSHandler.FetchData<CIA_STAFF_INFO>(new ClassCourse() { CLASS_ID = sClassId, COURSE_ID = sCourseId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseAndClassInfoByClassAndCourseId), sAcademicYear).DataSource.Data;

                    // Fetch Student Info By Class And CourseId ,..
                    var liFetchStudent = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new Stu_Course_Info() { CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sStaffId },
                            SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentIdByClassIdAndCourseId), sAcademicYear).DataSource.Data;
                    ObjViewModel.liStudentList = liFetchStudent;

                    // Online Quiz Match The Following Result ... 
                    var liMatchTheFollowing = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(new CourseWiseStaffInfo() { SETTING_ID = sSettingId, CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sStaffId },
                             ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.OnlineQuizMatchTheFollowingResultForCourseStaff), sAcademicYear).DataSource.Data;
                    ObjViewModel.liOnlineQuiz = liMatchTheFollowing;

                    // Online Quiz Objective Type Result ,..
                    var liObjectiveTypeResult = (List<OnlineQuizTest>)CMSHandler.FetchData<OnlineQuizTest>(new CourseWiseStaffInfo() { SETTING_ID = sSettingId, CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sStaffId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.OnlineQuizObjectiveTypeResultForCourseStaff), sAcademicYear).DataSource.Data;
                    ObjViewModel.liOnlineQuizQuestions = liObjectiveTypeResult;

                    // Online Quiz Fill In The Blank Result ,..
