                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "BindSubjectsForHallTicket", ex.Message);
                    }

                }
            }
            ExamRegistrastionViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;
            return View(ExamRegistrastionViewModel);
        }
        public JsonResult SaveDummyHallticketDistributed(string sStudentId)
        {
            var ObjJsonData = new JsonResultData();

            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                DUMMY_HALLTICKET_DISTRIBUTED objModel = new DUMMY_HALLTICKET_DISTRIBUTED();
                if (sStudentId != null)
                {
                    try
                    {
                        objModel.STUDENT_ID = sStudentId;
                        objModel.DISTRIBUTED_ID = Session[Common.SESSION_VARIABLES.USER_ID].ToString();
                        objModel.ACADEMIC_YEAR = sAcademicYear;
                        var CheckExist = CMSHandler.FetchData<DUMMY_HALLTICKET_DISTRIBUTED>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsStudentExist)).DataSource.Data;
