        /// <summary>
        /// this is for register revaluation by exam revaluation setting 
        /// </summary>
        /// <param name="sExamRevaluationSettingId"></param>
        /// <returns></returns>
        public ActionResult RegisterRevaluation(string sExamRevaluationSettingId)
        {
            string sOption = string.Empty;
            JsonResultData objResultData = new JsonResultData();
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sExamSettingAcyear = string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            // string sClassId = (Session[Common.SESSION_VARIABLES.CLASS_ID] != null) ? Session[Common.SESSION_VARIABLES.CLASS_ID].ToString() : string.Empty;


            try
            {

                //fetch academic year for exam revaluation  setting
                var liAcyear = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(new EXAM_REVALUATION_SETTING() { EXAM_REVALUATION_SETTING_ID = sExamRevaluationSettingId },
                    SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingAcademicYearByRevaluationSettingId)).DataSource.Data;
                if (liAcyear != null && liAcyear.Count > 0)
                {
                    sExamSettingAcyear = liAcyear.FirstOrDefault().AC_YEAR;
                }

                var ExamRegistrationCourse = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(new SEMESTER_MARKS() { EXAM_REVALUATION_SETTING_ID = sExamRevaluationSettingId, STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRegularCoursewithmarksByExamRevaluationSettingandStudentId), sExamSettingAcyear).DataSource.Data;

                if (ExamRegistrationCourse != null && ExamRegistrationCourse.Count > 0)
                {

                    objViewModel.LiSemesterMarks = ExamRegistrationCourse;
                }


                //fetch revaluation registration amount with credentials
                var FeeStructure = (List<FEE_STRUCTURE>)CMSHandler.FetchData<FEE_STRUCTURE>(new FEE_STRUCTURE() { STUDENT_ID = sUserId, FREQUENCY_TYPE_ID = Common.FrequencyType.RevaluationFee }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRevaluatoinAmountByProgrammeandClassYearAndStudent), sAcademicYear).DataSource.Data;

                if (FeeStructure != null && FeeStructure.Count > 0)
                {
                    objViewModel.objFeeStructure = FeeStructure[0];
                }


                // Fetch Exam Revaluation Setting ,...
                var liExamRevaluationSetting = (List<EXAM_REVALUATION_SETTING>)CMS.DAO.CMSHandler.FetchData<EXAM_REVALUATION_SETTING>(new EXAM_REVALUATION_SETTING() { EXAM_REVALUATION_SETTING_ID = sExamRevaluationSettingId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchExamRevaluationSettingByRevalutionSettingId), sAcademicYear).DataSource.Data;
                if (liExamRevaluationSetting != null && liExamRevaluationSetting.Count > 0)
                {
                    objViewModel.liExamRevaluationSetting = liExamRevaluationSetting;
                }


            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Examination", "RegisterRevaluation", ex.Message);
                }
            }

            return View(objViewModel);
        }

