        /// <summary>
        /// save revaluation registration
        /// </summary>
        /// <param name="sJsonData"></param>
        /// <returns></returns>
        public JsonResult SaveorUpdateExaminationRevaluationRegistration(string sJsonData)
        {
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            JsonResultData objResultData = new JsonResultData();
            string Status = string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var result = JsonConvert.DeserializeObject<EXAM_REVALUATION_REGISTRATION>(sJsonData);
                    if (result != null)
                    {


                        if (result.EXAM_REVALUATION_REGISTER_ID != null && result.EXAM_REVALUATION_REGISTER_ID != "")
                        {
                            // UPDATE setting 

                            result.STUDENT_ID = sUserId;
                            resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.UpdateExamRevaluationRegistrationById), sAcademicYear);
                            if (resultArgs.Success)
                            {
                                resultArgs = AddFeeStudentAccount(result.AMOUNT, Status = "0", result.FREQUENCY);
                            }

                            objResultData.Message = resultArgs.Success ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                            objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                        }
                        else
                        {
                            //check is record is already exist or not
                            if (CheckExamRevaluationRegistrationAlreadyExistsorNot(result.EXAM_REVALUATION_SETTING_ID))
                            {
                                objResultData.Message = Common.Messages.RecordsExistAlready;
                                objResultData.ErrorCode = Common.ErrorCode.Created;
                            }
                            else
                            {

                                // ADD setting 
                                result.STUDENT_ID = sUserId;
                                resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.SaveExamRevaluationRegistration), sAcademicYear);
                                if (resultArgs.Success)
                                {
                                    resultArgs = AddFeeStudentAccount(result.AMOUNT, Status = "1", result.FREQUENCY);
                                }
                                objResultData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                            }
                        }

                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveorUpdateExaminationRevaluationRegistration", ex.Message);
                    }
                }

            }
            return Json(objResultData);
        }
        /// <summary>
        /// add and update fee student account by frequency type
        /// </summary>
        /// <param name="sAmount"></param>
        /// <param name="Status"></param>
        /// <param name="sFrequencyType"></param>
        /// <returns></returns>
        public ResultArgs AddFeeStudentAccount(string sAmount, string Status, string sFrequencyId)
        {
            ResultArgs resultArgs = new ResultArgs();
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string FrequencyType = string.Empty;
            string FrequencyId = string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            try
            {

                // fetch fee structure by frequency

                var HeadsWithAmount = (List<FEE_STRUCTURE>)CMSHandler.FetchData<FEE_STRUCTURE>(new FEE_STRUCTURE() { STUDENT_ID = sUserId, FREQUENCY = sFrequencyId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFeetructureForRevaluationBytudentIdandFrequency), sAcademicYear).DataSource.Data;

                if (HeadsWithAmount != null && HeadsWithAmount.Count > 0)
                {
                    var ObjModel = new FEE_STUDENT_ACCOUNT();
                    ObjModel.STUDENT_ID = sUserId;
                    ObjModel.FREQUENCY_ID = HeadsWithAmount.FirstOrDefault().FREQUENCY;
                    ObjModel.HEAD = HeadsWithAmount.FirstOrDefault().HEAD;
                    ObjModel.ACADEMIC_YEAR = sAcademicYear;
                    ObjModel.CREDIT = sAmount;
                    ObjModel.FEE_MAIN_HEAD_ID = HeadsWithAmount.FirstOrDefault().FEE_MAIN_HEAD_ID;


                    if (Status == "0")
                    {
                        //update fee student account
                        resultArgs = CMSHandler.SaveOrUpdate(null, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.UnSafeUpdateMode));
                        resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateFeeStudentAccountByStudentandFrequencyandHead), sAcademicYear);
                        resultArgs = CMSHandler.SaveOrUpdate(null, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.SafeUpdateMode));
                    }
                    if (Status == "1")
                    {
                        //add fee student account
                        resultArgs = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamCreditAmountToStudentAccount));

                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Examination", "AddFeeStudentAccount", ex.Message);
                }
            }

            return resultArgs;
        }
