        public JsonResult SaveorUpdateExaminationPhotoCopySetting(string sJsonData)
        {
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            JsonResultData objResultData = new JsonResultData();

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var result = JsonConvert.DeserializeObject<EXAM_PHOTOCOPY_SETTING>(sJsonData);
                    if (result != null)
                    {
                        // formating date
                        if (!string.IsNullOrEmpty(result.START_DATE))
                        {
                            result.START_DATE = CommonMethods.ConvertdatetoyearFromat(result.START_DATE);
                        }
                        if (!string.IsNullOrEmpty(result.END_DATE))
                        {
                            result.END_DATE = CommonMethods.ConvertdatetoyearFromat(result.END_DATE);
                        }

                        if (result.EXAM_PHOTOCOPY_SETTING_ID != null && result.EXAM_PHOTOCOPY_SETTING_ID != "")
                        {
                            // UPDATE setting 
                            resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.UpdateExamPhotoCopySettingById), sAcademicYear);
                            objResultData.Message = resultArgs.Success ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                            objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                        }
                        else
                        {
                            //check is record is already exist or not
                            if (CheckExamPhotoCopyisAlreadyExistsorNot(result.EXAM_SETTING_ID, result.APPLICATION_TYPE_ID))
                            {
                                objResultData.Message = Common.Messages.RecordsExistAlready;
                                objResultData.ErrorCode = Common.ErrorCode.Created;
                            }
                            else
                            {

                                // ADD setting 
                                resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.SaveExamPhotoCopySetting), sAcademicYear);
                                objResultData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                            }
                        }

                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveorUpdateExaminationPhotoCopySetting", ex.Message);
                    }
                }

            }
            return Json(objResultData);
        }

