        /// <summary>
        /// register photo copy
        /// </summary>
        /// <param name="sExamPhotocopySettingId"></param>
        /// <returns></returns>
        public ActionResult RegisterPhotoCopy(string sExamPhotocopySettingId)
        {
            string sOption = string.Empty;
            JsonResultData objResultData = new JsonResultData();
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            // string sClassId = (Session[Common.SESSION_VARIABLES.CLASS_ID] != null) ? Session[Common.SESSION_VARIABLES.CLASS_ID].ToString() : string.Empty;


            try
            {
                var ExamRegistrationCourse = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(new SEMESTER_MARKS() { EXAM_PHOTOCOPY_SETTING_ID = sExamPhotocopySettingId, STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRegularCoursewithmarksByExamPhotoCopySettingandStudentId), sAcademicYear).DataSource.Data;

                if (ExamRegistrationCourse != null && ExamRegistrationCourse.Count > 0)
                {


                    objViewModel.LiSemesterMarks = ExamRegistrationCourse;
                }


                //fetch revaluation registration amount with credentials
                var FeeStructure = (List<FEE_STRUCTURE>)CMSHandler.FetchData<FEE_STRUCTURE>(new FEE_STRUCTURE() { STUDENT_ID = sUserId, FREQUENCY_TYPE_ID = Common.FrequencyType.PhotoCopyFee }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRevaluatoinAmountByProgrammeandClassYearAndStudent), sAcademicYear).DataSource.Data;

                if (FeeStructure != null && FeeStructure.Count > 0)
                {
                    objViewModel.objFeeStructure = FeeStructure[0];
                }


                // Fetch Exam Photo Copy Setting ,...
                var liExamPhotoCopySetting = (List<EXAM_PHOTOCOPY_SETTING>)CMS.DAO.CMSHandler.FetchData<EXAM_PHOTOCOPY_SETTING>(new EXAM_PHOTOCOPY_SETTING() { EXAM_PHOTOCOPY_SETTING_ID = sExamPhotocopySettingId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchExamPhotoCopySettingByRevalutionSettingId), sAcademicYear).DataSource.Data;
                if (liExamPhotoCopySetting != null && liExamPhotoCopySetting.Count > 0)
                {
                    objViewModel.liExamPhotoCopySetting = liExamPhotoCopySetting;

                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Examination", "RegisterPhotoCopy", ex.Message);
                }
            }

            return View(objViewModel);
        }

        /// <summary>
        /// save phot copy registration
        /// </summary>
        /// <param name="sJsonData"></param>
        /// <returns></returns>
        public JsonResult SaveorUpdateExaminationPhotoCopyRegistration(string sJsonData)
        {
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            JsonResultData objResultData = new JsonResultData();
            string Status = string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var result = JsonConvert.DeserializeObject<EXAM_PHOTOCOPY_REGISTRATION>(sJsonData);
                    if (result != null)
                    {


                        if (result.EXAM_PHOTOCOPY_REGISTER_ID != null && result.EXAM_PHOTOCOPY_REGISTER_ID != "")
                        {
                            // UPDATE setting 

                            result.STUDENT_ID = sUserId;
                            resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.UpdateExamPhotoCopyRegistrationById), sAcademicYear);
                            if (resultArgs.Success)
                            {
                                resultArgs = AddFeeStudentAccount(result.AMOUNT, Status = "0", Common.FrequencyType.PhotoCopyFee);
                            }

                            objResultData.Message = resultArgs.Success ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                            objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                        }
                        else
                        {
                            //check is record is already exist or not
                            if (CheckExamPhotoCopyRegistrationAlreadyExistsorNot(result.EXAM_PHOTOCOPY_SETTING_ID))
                            {
                                objResultData.Message = Common.Messages.RecordsExistAlready;
                                objResultData.ErrorCode = Common.ErrorCode.Created;
                            }
                            else
                            {

                                // ADD setting 
                                result.STUDENT_ID = sUserId;
                                resultArgs = CMS.DAO.CMSHandler.SaveOrUpdate(result, SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.SaveExamPhotoCopyRegistration), sAcademicYear);
                                if (resultArgs.Success)
                                {
                                    resultArgs = AddFeeStudentAccount(result.AMOUNT, Status = "1", Common.FrequencyType.PhotoCopyFee);
                                }
                                objResultData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.NotModified;
                            }
                        }

                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveorUpdateExaminationPhotoCopyRegistration", ex.Message);
                    }
                }

            }
            return Json(objResultData);
        }

