        /// <summary>
        /// for saving photo copy file 
        /// </summary>
        /// <param name="sJsonData"></param>
        /// <returns></returns>
        public JsonResult SaveorUpdateExaminationPhotoCopyFileRegistration(string sJsonData)
        {
            string sDirectorypath = string.Empty, sFilePath = string.Empty;
            var path = string.Empty;
            int Count = 0;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            JsonResultData objResultData = new JsonResultData();
            try
            {
                var result = JsonConvert.DeserializeObject<JSON_FILEDS>(Request.Form["sJsonData"]);
                var Result = new List<EXAM_PHOTOCOPY_FILES>();
                string sSQL = string.Empty;

                if (result.liExamPhotoCopyFiles != null && result.liExamPhotoCopyFiles.Count > 0 && !String.IsNullOrEmpty(sAcademicYear))
                {

                    ////check if user is existed or not
                    //if (UserExistedorNot(result.objAluRegistration.PROGRAMME_ID, result.objAluRegistration.BATCH_BEGIN_YEAR, result.objAluRegistration.EMAIL_ID))
                    //{
                    //    objResultData.Message = Common.Messages.RecordsExistAlready;
                    //    return Json(objResultData);
                    //}

                    //Photo savings
                    for (int i = 0; i < Request.Files.Count; i++)
                    {

                        sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.EXAM_PHOTOCOPY_IMAGE_PATH + "\\";
                        if (!Directory.Exists(sDirectorypath))
                        {
                            Directory.CreateDirectory(sDirectorypath);
                        }
                        var file = Request.Files[i];
                        Stream strm = file.InputStream;
                        var key = Request.Files.AllKeys[i];
                        var fileName = file.FileName;

                        var sFile = fileName.Split('.');
                        sFilePath = sDirectorypath + "\\" + sFile[0] + "_" + sUserId + "." + sFile[1];
                        string sSavePath = "\\" + Common.URLPages.EXAM_PHOTOCOPY_IMAGE_PATH + "\\" + sFile[0] + "_" + sUserId + "." + sFile[1];

                        //var item=result.liExamPhotoCopyFiles.Where(x => x.PHOTOCOPY == fileName).Select(new EXAM_PHOTOCOPY_FILES() {

                        //   // PHOTOCOPY.Replace(x.PHOTOCOPY, sSavePath),
                        //   PHOTOCOPY=sSavePath,

                        //});
                        var item = (from s in result.liExamPhotoCopyFiles
                                    where s.PHOTOCOPY == key
                                    select new EXAM_PHOTOCOPY_FILES
                                    {

                                        PHOTOCOPY = CommonMethods.CompressImageLowQuality(strm, sFilePath, file.FileName, sSavePath),
                                        COURSE_ID = s.COURSE_ID,
                                        ACADEMIC_YEAR = s.ACADEMIC_YEAR,
                                        EXAM_PHOTOCOPY_FILE_ID = s.EXAM_PHOTOCOPY_FILE_ID,
                                        EXAM_PHOTOCOPY_REGISTER_ID = s.EXAM_PHOTOCOPY_REGISTER_ID,
                                        IS_ACTIVE = s.IS_ACTIVE,
                                        IS_DELETED = s.IS_DELETED
                                    }).ToList();

                        if (item != null && item.Count > 0)
                        {
                            // Compression Method ....
                            // string FilePath = CommonMethods.CompressImageQuality(strm, sFilePath, file.FileName, sSavePath);
                            //  file.SaveAs(sFilePath);
                            Result.Add(item[0]);
                            Count++;
                        }


                    }

                    if (Count > 0)
                    {
                        string SQuery = string.Empty;
                        string IQuery = string.Empty;
                        IQuery = "INSERT INTO exam_photocopy_files(EXAM_PHOTOCOPY_REGISTER_ID,PHOTOCOPY,COURSE_ID,ACADEMIC_YEAR) VALUES";
                        foreach (var item in Result)
                        {
                            if (!string.IsNullOrEmpty(item.EXAM_PHOTOCOPY_FILE_ID))
                            {
                                //construct update query
                                //  SQuery += "UPDATE exam_photocopy_files SET EXAM_PHOTOCOPY_REGISTER_ID="+item.EXAM_PHOTOCOPY_REGISTER_ID+","+
                                //  "PHOTOCOPY="+item.PHOTOCOPY+ ",COURSE_ID='"+item.COURSE_ID+ "',ACADEMIC_YEAR=?AC_YEAR;";
                                resultArgs = CMSHandler.SaveOrUpdate(item, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamPhotoCopyFiles), sAcademicYear);
                                if (!resultArgs.Success)
                                {
                                    objResultData.Message = Common.Messages.FailedToSaveRecords;
                                    objResultData.ErrorCode = Common.ErrorCode.ExpectationFailed;
                                    return Json(objResultData);
                                }
                            }
                            else
                            {
                                //construct insert query
                                //  IQuery += "('"+item.EXAM_PHOTOCOPY_REGISTER_ID+"','"+item.PHOTOCOPY+"','"+item.COURSE_ID+"',?AC_YEAR),";
                                resultArgs = CMSHandler.SaveOrUpdate(item, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamPhotoCopyFiles), sAcademicYear);
                                if (!resultArgs.Success)
                                {
                                    objResultData.Message = Common.Messages.FailedToSaveRecords;
                                    objResultData.ErrorCode = Common.ErrorCode.ExpectationFailed;
                                    return Json(objResultData);
                                }
                            }
                        }
                        objResultData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                        objResultData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;

                        //if(!string.IsNullOrEmpty(IQuery))
                        //{
                        //    IQuery = IQuery.Trim(',') + ";";
                        //    resultArgs = CMSHandler.SaveOrUpdate(null,IQuery, sAcademicYear);
                        //    objResultData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                        //    objResultData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        //}
                        //if (!string.IsNullOrEmpty(SQuery))
                        //{
                        //    resultArgs = CMSHandler.SaveOrUpdate(null, SQuery, sAcademicYear);
                        //    objResultData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                        //    objResultData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        //}

                    }
                }

                else
                {
                    objResultData.Message = Common.Messages.FailedToSaveRecords;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "SaveorUpdateExaminationPhotoCopyFileRegistration", ex.Message);
                }
            }
            return Json(objResultData);
        }


