        #region Exam Arrear Registration
        /// <summary>
        /// This action is used to load Arrear Papers for Registration
        /// </summary>
        /// <returns></returns>
        public ActionResult ExamArrearRegistration()
        {
            ExaminationViewModel ExamRegistrastionViewModel = new ExaminationViewModel();
            string sSemesters = string.Empty;
            //int nSemester = 0;
            string sSql = string.Empty;
            var objExamViewModel = new List<EXAM_REGISTRATION>();
            var ObjExamRegistration = new EXAM_REGISTRATION();
            var liBatchAndProgramme = new List<GET_PROGRAMME_AND_BATCH>();
            var liSemesterResult = new List<SEMESTER_RESULT>();
            var SemesterResult = new SEMESTER_RESULT();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                try
                {
                    List<EXAM_REGISTRATION> ObjExamRegistrationList = new List<EXAM_REGISTRATION>();
                    GET_ACTIVE_SEMESTER_BATCH objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();
                    List<GET_ACTIVE_SEMESTER_BATCH> liActiveSemester = new List<GET_ACTIVE_SEMESTER_BATCH>();
                    GET_PROGRAMME_AND_BATCH ObjProgramAndBatch = new GET_PROGRAMME_AND_BATCH();
                    var CollegeDetails = new CollegeDetails();
                    // Fetch College Details ....
                    ExamRegistrastionViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                    string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                    // Fetch Program and Batch By Student Id .....
                    string sUserId = Session[Common.SESSION_VARIABLES.USER_ID].ToString();
                    var Academicyear = (List<AcademicBatches>)CMSHandler.FetchData<AcademicBatches>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicYearstudentId)).DataSource.Data;
                    if (Academicyear != null && Academicyear.Count > 0)
                    {
                        var liBatchAndProgrammes = (List<GET_PROGRAMME_AND_BATCH>)CMSHandler.FetchData<GET_PROGRAMME_AND_BATCH>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchBatchandProgrammeBystudentId), Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID).DataSource.Data;

                        // Fetch Active Semester By Batch Id .....
                        objActiveSemester.STUDENT_ID = sUserId;
                        objActiveSemester.BATCH = liBatchAndProgrammes.FirstOrDefault().BATCH;
                        objActiveSemester.PROGRAMME = liBatchAndProgrammes.FirstOrDefault().PROGRAMME;
                        liActiveSemester = (List<GET_ACTIVE_SEMESTER_BATCH>)CMSHandler.FetchData<GET_ACTIVE_SEMESTER_BATCH>(objActiveSemester, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveSemesterWithBatches), Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID).DataSource.Data;

                        // Get Student Information ...
                        ExamRegistrastionViewModel.liExamRegistrationModel = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId, ACADEMIC_YEAR = Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentInfoForExamRegistration), sAcademicYear).DataSource.Data;


                        // Check Supplementry Exam Active By Programme ,...
                        var liFetchProgrammeNonSemester = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new CP_COURSE_PATTERN() { PROGRAMME_GROUP_ID = objActiveSemester.PROGRAMME, PROGRAMME_YEAR = liBatchAndProgrammes.FirstOrDefault().CLASS_YEAR },
                              ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckSupplementryExamByProgrammeGroupId), sAcademicYear).DataSource.Data;
                        if (liFetchProgrammeNonSemester != null && liFetchProgrammeNonSemester.Count > 0)
                        {
                            foreach (var item in liActiveSemester)
                            {
                                item.STUDENT_ID = sUserId;
                                var tempSemesterResult = (List<SEMESTER_RESULT>)CMSHandler.FetchData<SEMESTER_RESULT>(item,
                                     ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterResultForSupplementryRegistration), item.AC_YEAR).DataSource.Data;
                                if (tempSemesterResult != null && tempSemesterResult.Count > 0)
                                {
                                    foreach (var sem in tempSemesterResult)
                                    {
                                        sem.AC_YEAR = item.AC_YEAR;
                                        liSemesterResult.Add(sem);
                                    }
                                }
                            }
                        }


                        var arrearList = new List<SEMESTER_RESULT>();
                        var objGroup = new List<SEMESTER_RESULT>();
                        var objGp = new List<SEMESTER_RESULT>();

                        // Get Only Arrear Papers group By Course Code ....
                        var result = liSemesterResult.GroupBy(u => u.COURSE_CODE).ToList();

                        for (int i = 0; i < result.Count(); i++)
                        {
                            var code = result[i].Key.ToString();
                            objGp = (List<SEMESTER_RESULT>)liSemesterResult.Where(o => o.COURSE_CODE == code).ToList();

                            if (objGp.FindAll(o => o.RESULT == "PASS").Count() == 0)
                                arrearList.Add(objGp.FirstOrDefault());
                        }
                        ExamRegistrastionViewModel.liSemesterList = arrearList.ToList();
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "ExamArrearRegistration", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "ExamArrearRegistration", ex.Message);

                    }
                }

            }
            return View(ExamRegistrastionViewModel);
        }
        /// <summary>
        /// This JsonResult is used to save the Exam Registration
        /// </summary>
        /// <param name="JsonData"></param>
        /// <returns></returns>
        public JsonResult SaveExamArrearRegistration(string ExamDetails)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            string sResult = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    sResult = ValidateStudent();
                    if (sResult != "1")
                    {
                        var liExamSetting = (List<ListArrerPapers>)CMSHandler.FetchData<ListArrerPapers>(new STU_CLASS() { STUDENT_ID = sUserId },
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchActiveExamSettingByProgrammeType), sAcademicYear).DataSource.Data;
                        if (liExamSetting != null && liExamSetting.Count > 0)
                        {
                            string sExamSettingId = liExamSetting.FirstOrDefault().EXAM_SETTING_ID;
                            string sFine = liExamSetting.FirstOrDefault().FINE;
                            // Fetch Frequency With Amount ,...
                            var Academicyear = (List<AcademicBatches>)CMSHandler.FetchData<AcademicBatches>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicYearstudentId)).DataSource.Data;
                            var FetchFrequency = (List<SUP_FEE_FREQUENCY>)CMSHandler.FetchData<SUP_FEE_FREQUENCY>(new SUP_FEE_FREQUENCY { FEE_MODE = Common.FrequencyType.Supplementary }, SQL.Fee.FeeSQL.GetFeeSQL(FeeSQLCommands.FetchFrequencyIdByFeeModeAndActiveSemester), sAcademicYear).DataSource.Data;

                            var liFrequencyWithAmount = (List<SaveExamSubjects>)CMSHandler.FetchData<SaveExamSubjects>(new SaveExamSubjects() { FEE_FREQUENCY_FEE_MODE_ID = FetchFrequency.FirstOrDefault().FREQUENCY_ID, FEE_ROOT_ID = Common.FeeRoot.CollegeFee, STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamSettingId, ACADEMIC_YEAR = Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID },
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSuppleFrequencyWithAmount), sAcademicYear).DataSource.Data;
                            if (liFrequencyWithAmount != null && liFrequencyWithAmount.Count > 0)
                            {
                                var ObjJson = JsonConvert.DeserializeObject<SaveExamDetails>(ExamDetails);
                                int nExamFee = 0;
                                int nArrerFee = 0;
                                string sErrorMessage = string.Empty;
                                //string sSettingId = string.Empty;
                                if (ObjJson.SubjectDetails != null && ObjJson.SubjectDetails.Count > 0)
                                {
                                    // Loop Subjects To Get Course Cost ,...
                                    foreach (var item in ObjJson.SubjectDetails)
                                    {
                                        var liCourseHeads = (List<EXAM_COURSE_WISE_COST>)CMSHandler.FetchData<EXAM_COURSE_WISE_COST>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseWiseCost), sAcademicYear).DataSource.Data;
                                        if (liCourseHeads != null && liCourseHeads.Count > 0)
                                        {
                                            //sSettingId = liCourseHeads.FirstOrDefault().EXAM_SETTING_ID;
                                            if (item.STATUS != "R") // Arrer Fee
                                                nArrerFee += Convert.ToInt32(liCourseHeads.FirstOrDefault().COST);

                                        }
                                        else
                                        {
                                            sErrorMessage += item.COURSE_CODE + ",";
                                        }
                                    }

                                    if (!string.IsNullOrEmpty(sErrorMessage)) // True When Course Cost Not Available 
                                    {
                                        sErrorMessage = sErrorMessage.TrimEnd(',');
                                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                        ObjJsonData.Message = sErrorMessage + "Course Amount Are Not Mapped ! Please Meet Admin !";
                                    }
                                    else
                                    {
                                        bool sTrue = false;
                                        // Insert Exam Registration ,...
                                        foreach (var item in ObjJson.SubjectDetails)
                                        {
                                            item.EXAM_SETTING_ID = sExamSettingId;
                                            var sInsert = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamDetails), sAcademicYear);
                                            sTrue = sInsert.Success;
                                        }
                                        // Insert Student Account,..
                                        if (sTrue)
                                        {
                                            foreach (var item in liFrequencyWithAmount)
                                            {
                                                var ObjModel = new FEE_STUDENT_ACCOUNT();
                                                ObjModel.STUDENT_ID = item.STUDENT_ID;
                                                ObjModel.FREQUENCY_ID = item.FEE_FREQUENCY_FEE_MODE_ID;
                                                ObjModel.HEAD = item.HEAD_ID;
                                                ObjModel.ACADEMIC_YEAR = sAcademicYear;
                                                ObjModel.CREDIT = item.COST;
                                                ObjModel.FEE_MAIN_HEAD_ID = item.FEE_MAIN_HEAD_ID;
                                                if (item.HEAD_ID == "11")
                                                    ObjModel.CREDIT = nArrerFee.ToString();
                                                if (!string.IsNullOrEmpty(ObjModel.CREDIT))
                                                {
                                                    if (ObjModel.CREDIT != "0")
                                                    {
                                                        var sInsertStudentAccount = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamCreditAmountToStudentAccount));
                                                        sTrue = sInsertStudentAccount.Success;
                                                    }
                                                }
                                            }
                                        }
                                        if (sTrue)
                                        {
                                            ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                            ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                        }
                                        else
                                        {
                                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                            ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                        }
                                    }
                                }
                                else
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                    ObjJsonData.Message = "Invalied Input ! Check Your Input Details !";
                                }
                            }
                            else
                            {
                                ObjJsonData.ErrorCode = "2";
                                ObjJsonData.Message = Common.Messages.LedgersAreNotMapped;
                            }
                        }
                        else
                        {
                            ObjJsonData.ErrorCode = "2";
                            ObjJsonData.Message = " No Active Setting Mached ! Please Meet Admin ...!";
                        }
                    }
                    else
                    {
                        ObjJsonData.ErrorCode = sResult;
                        ObjJsonData.Message = " You have Registered Already ...!";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamRegistration", ex.Message);
                    }
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        /// <summary>
        /// This action is used to load preview of Exam  Registration
        /// </summary>
        /// <returns></returns>
        public ActionResult ExamArrearRegistrationPreview()
        {
            var ExamRegistrastionViewModel = new ExaminationViewModel();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                var sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                var objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();

                try
                {
                    string sUserId = Session[Common.SESSION_VARIABLES.USER_ID].ToString();
                    var Academicyear = (List<AcademicBatches>)CMSHandler.FetchData<AcademicBatches>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicYearstudentId)).DataSource.Data;
                    objActiveSemester.STUDENT_ID = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                    // Get ExamRegistrationPriview ...
                    ExamRegistrastionViewModel.liFetchHallTicket = (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(objActiveSemester,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketListPreview), sAcademicYear).DataSource.Data;
                    if (ExamRegistrastionViewModel.liFetchHallTicket != null && ExamRegistrastionViewModel.liFetchHallTicket.Count > 0)
                    {
                        ExamRegistrastionViewModel.liFetchHallTicket = ExamRegistrastionViewModel.liFetchHallTicket
                            .OrderBy(x =>
                            {
                                if (string.IsNullOrEmpty(x.SEMESTER)) return 999;
                                int semVal;
                                if (int.TryParse(x.SEMESTER.Trim(), out semVal)) return semVal;
                                switch (x.SEMESTER.Trim().ToUpper())
                                {
                                    case "I": return 1;
                                    case "II": return 2;
                                    case "III": return 3;
                                    case "IV": return 4;
                                    case "V": return 5;
                                    case "VI": return 6;
                                    case "VII": return 7;
                                    case "VIII": return 8;
                                    default: return 999;
                                }
                            })
                            .ToList();
                    }

                    // Get All Student Information ...

                    ExamRegistrastionViewModel.liExamRegistrationModel = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId, ACADEMIC_YEAR = Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentInfoForExamRegistration), sAcademicYear).DataSource.Data;

                    // Get College Infomation ...
                    ExamRegistrastionViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                    // Get Fee Transaction .
                    ExamRegistrastionViewModel.feeTransactions = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(
                        new FEE_TRANSACTION() { ACADEMIC_YEAR = Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID, STUDENT_ID = objActiveSemester.STUDENT_ID, FEE_MODE = Common.FrequencyType.ExamFee },
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamArrearFeeStatus), sAcademicYear).DataSource.Data;

                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "ExamArrearRegistrationPreview", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "ExamArrearRegistrationPreview", ex.Message);

                    }

                }
            }

            return View(ExamRegistrastionViewModel);

        }

