        public JsonResult FetchClassAndExamSettingByProgrammeGroupId(string sProgrammeGroupId)
        {
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjModel = new CP_PROGRAMME_GROUP();
                    ObjModel.PROGRAMME_GROUP_ID = sProgrammeGroupId;
                    var liClass = (List<cp_Classes_2017>)CMSHandler.FetchData<cp_Classes_2017>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchClassByProgrammeGroupId)).DataSource.Data;
                    ObjJsonData.sResult = "<option value=''> -- Select -- </option>";
                    if (liClass != null && liClass.Count > 0)
                    {
                        foreach (var item in liClass)
                        {
                            ObjJsonData.sResult += "<option value='" + item.CLASS_ID + "'> " + item.CLASS_NAME + " </option>";
                        }
                    }

                    ObjJsonData.ErrorCode = "<option value=''> -- Select -- </option>";
                    var liExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchExamSettingByProgrammeGroupId), sAcademicYear).DataSource.Data;
                    if (liExamSetting != null && liExamSetting.Count > 0)
                    {
                        foreach (var item in liExamSetting)
                        {
                            ObjJsonData.ErrorCode += "<option value='" + item.EXAM_SETTING_ID + "'> " + item.EXAM_NAME + " </option>";
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "FetchClassAndExamSettingByProgrammeGroupId", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        public JsonResult SaveExamRegistrationForSJC(string sProgrammeGroupId, string sClassId, string sExamSettingId)
        {
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    bool sFlag = false;

                    var ObjModel = new STU_CLASS();
                    ObjModel.CLASS_ID = sClassId;
                    ObjModel.PROGRAMME_GROUP_ID = sProgrammeGroupId;
                    ObjModel.EXAM_SETTING_ID = sExamSettingId;

                    var liClass = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByClassId), sAcademicYear).DataSource.Data;
                    var liCourse = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel, SQL.Academics.AcademicsSQL.GetAcademicSQL(AcademicSQLCommands.FetchCoursesFromCoursePatternByProgrammeGroupId), sAcademicYear).DataSource.Data;
                    var liCourseWiseCost = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCoursesWiseCostForExam), sAcademicYear).DataSource.Data;

                    if (liCourseWiseCost != null && liCourseWiseCost.Count > 0)
                    {
                        if (liCourse != null && liCourse.Count > 0)
                        {
                            if (liClass != null && liClass.Count > 0)
                            {
                                foreach (var item in liClass)
                                {
                                    ObjModel.STUDENT_ID = item.STUDENT_ID;
                                    var liStudentExist = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsExamRegistrationExistByStudentId), sAcademicYear).DataSource.Data;
                                    if (liStudentExist != null && liStudentExist.Count > 0)
                                    {
                                        continue;
                                    }
                                    int nExamFee = 0;
                                    int nArearFee = 0;
                                    string sSQL = @"INSERT INTO EXAM_REGISTRATION_" + sAcademicYear + " (STUDENT_ID, COURSE_ID, STATUS, ACADEMIC_YEAR,EXAM_SEMESTER, EXAM_SETTING_ID)VALUES";
                                    //sFlag = true;
                                    var liCourseInfo = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel, SQL.Academics.AcademicsSQL.GetAcademicSQL(AcademicSQLCommands.FetchCoursesFromCoursePatternByProgrammeGroupId), sAcademicYear).DataSource.Data;
                                    var liRegularCourses = liCourseInfo;
                                    var liOptionalCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel,
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data;

                                    // var liTemp = liRegularCourses.Where(o => o.COURSE_STRUCTURE_ID == "579").ToList();
                                    // Loop Optional Papers  To Remove Unnecessary Courses...
                                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                                    {
                                        foreach (var Optionalitem in liOptionalCourses)
                                        {
                                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == Optionalitem.COURSE_ROOT_ID).ToList();
                                            if (IsExist != null && IsExist.Count > 0)
                                            {
                                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                                Optionalitem.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                                liRegularCourses.Add(Optionalitem);
                                            }
                                        }
                                    }

                                    // Loop For Course Wise Cost ....
                                    foreach (var Courseitem in liRegularCourses)
                                    {
                                        var liExist = liCourseWiseCost.Where(x => x.COURSE_ROOT_ID == Courseitem.COURSE_ROOT_ID).ToList();
                                        if (liExist != null && liExist.Count > 0)
                                        {
                                            // Save Exam Registration 
                                            sSQL += "('" + item.STUDENT_ID + "','" + Courseitem.COURSE_ROOT_ID + "','R','" + sAcademicYear + "','" + Courseitem.SEMESTER_ID + "','" + sExamSettingId + "'),";
                                            nExamFee += Convert.ToInt32(liExist.FirstOrDefault().COST);
                                            sFlag = true;
                                        }
                                        else
                                        {
                                            ObjJsonData.Message += Courseitem.COURSE_CODE + ",";
                                            sFlag = false;
                                        }
                                    }


                                    // Arrear Course .. ( This proccess is hold for time period due to covid -19 )
                                    //string ssql = string.Empty;
                                    //string sSemesterIds = "1,2,3,4,5,6";
                                    //var liSemesterMarks = new List<SEMESTER_RESULT>();
                                    if (sFlag)
                                    {
                                        //int nAcademicYear = Convert.ToInt32(sAcademicYear);
                                        //for (int i = 0; i < 4; i++)
                                        //{

                                        //    ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterResult).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.SEMESTER, sSemesterIds);
                                        //    var liTempSemester = (List<SEMESTER_RESULT>)CMSHandler.FetchData<SEMESTER_RESULT>(item, ssql, nAcademicYear.ToString()).DataSource.Data;
                                        //    nAcademicYear--;
                                        //    if (liTempSemester != null && liTempSemester.Count > 0)
                                        //    {
                                        //        liSemesterMarks = (liSemesterMarks != null && liSemesterMarks.Count > 0) ? liSemesterMarks.Concat(liTempSemester).ToList() : liTempSemester;
                                        //    }
                                        //}

                                        //var liArearList = new List<SEMESTER_RESULT>();
                                        //var objGroup = new List<SEMESTER_RESULT>();
                                        //var objGp = new List<SEMESTER_RESULT>();

                                        // Get Only Arrear Papers group By Course Code ....
                                        //var result = liSemesterMarks.GroupBy(u => u.COURSE_CODE).ToList();

                                        //for (int i = 0; i < result.Count(); i++)
                                        //{
                                        //    var code = result[i].Key.ToString();
                                        //    objGp = (List<SEMESTER_RESULT>)liSemesterMarks.Where(o => o.COURSE_CODE == code).ToList();
                                        //    if (objGp.FindAll(o => o.RESULT == "PASS").Count() == 0)
                                        //        liArearList.Add(objGp.FirstOrDefault());
                                        //}
                                        //if (liArearList != null && liArearList.Count > 0)
                                        //{
                                        //    liArearList.RemoveAll(x => x.WRITTEN_SEMESTER == liSemesterMarks.FirstOrDefault().SEMESTER_ID);
                                        //}

                                        //if (liArearList != null && liArearList.Count > 0)
                                        //{
                                        //    sFlag = true;
                                        //    foreach (var Arearitem in liArearList)
                                        //    {
                                        //        var liExist = liCourseWiseCost.Where(x => x.COURSE_ROOT_ID == Arearitem.COURSE_ROOT_ID).ToList();
                                        //        if (liExist != null && liExist.Count > 0)
                                        //        {
                                        //            // Save Exam Registration 
                                        //            sSQL += "('" + item.STUDENT_ID + "','" + Arearitem.COURSE_ROOT_ID + "','A','" + sAcademicYear + "','" + Arearitem.WRITTEN_SEMESTER + "','" + sExamSettingId + "'),";
                                        //            nArearFee += Convert.ToInt32(liExist.FirstOrDefault().COST);
                                        //        }
                                        //        else
                                        //        {
                                        //            ObjJsonData.Message += Arearitem.COURSE_CODE + ",";
                                        //            sFlag = false;
                                        //        }
                                        //    }
                                        //}

                                        if (sFlag)
                                        {
                                            string sAccountSQL = @"INSERT INTO FEE_STUDENT_ACCOUNT(STUDENT_ID,ACADEMIC_YEAR,FREQUENCY_ID,HEAD,CREDIT,FEE_MAIN_HEAD_ID)VALUES";
                                            var liFrequencyWithAmount = (List<SaveExamSubjects>)CMSHandler.FetchData<SaveExamSubjects>(new SaveExamSubjects() { FEE_ROOT_ID = Common.FeeRoot.CollegeFee, CLASS_ID = sClassId, EXAM_SETTING_ID = sExamSettingId },
                                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamHeadsWithFrequencyAndCost), sAcademicYear).DataSource.Data;
                                            if (liFrequencyWithAmount != null && liFrequencyWithAmount.Count > 0)
                                            {
                                                foreach (var Headsitem in liFrequencyWithAmount)
                                                {
                                                    if (Headsitem.HEAD_ID == "8")
                                                    {
                                                        Headsitem.COST = nExamFee.ToString();
                                                    }
                                                    else if (Headsitem.HEAD_ID == "11")
                                                    {
                                                        Headsitem.COST = nArearFee.ToString();
                                                    }

                                                    if (Headsitem.COST != "0" && !string.IsNullOrEmpty(Headsitem.COST))
                                                    {
                                                        sAccountSQL += "('" + item.STUDENT_ID + "','" + sAcademicYear + "','" + Headsitem.FEE_FREQUENCY_FEE_MODE_ID + "','" + Headsitem.HEAD_ID + "','" + Headsitem.COST + "','" + Headsitem.FEE_MAIN_HEAD_ID + "'),";
                                                    }
                                                }

                                                using (MySQLHandler ObjHandler = new MySQLHandler())
                                                {
                                                    sSQL = sSQL.TrimEnd(',') + ";";
                                                    var sExamRegistration = ObjHandler.ExecuteAsScripts(sSQL);
                                                    if (sExamRegistration.Success && sExamRegistration.RowsAffected != 0)
                                                    {
                                                        sAccountSQL = sAccountSQL.TrimEnd(',') + ";";
                                                        var SaveAccount = ObjHandler.ExecuteAsScripts(sAccountSQL);
                                                        ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                                        ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                                        sSQL = string.Empty;
                                                        sAccountSQL = string.Empty;
                                                    }
                                                }
                                            }
                                            else
                                            {
                                                ObjJsonData.Message = "Exam Heads Not Mapped ! Please Meet Exam Incharge .";
                                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                                sSQL = string.Empty;
                                            }
                                        }
                                        else
                                        {
                                            ObjJsonData.Message += "Arear Cost Not Mapped ! Please Meet Exam Incharge .";
                                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                            sSQL = string.Empty;
                                        }
                                    }
                                    else
                                    {
                                        sSQL = string.Empty;
                                        ObjJsonData.Message += "Course Cost Not Mapped ! Please Meet Exam Incharge .";
                                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                        return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                                    }
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "No Student Details Found For This Class";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }
                        }
                        else
                        {
                            ObjJsonData.Message = "No Course Details Found For This Programme";
                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        }
                    }
                    else
                    {
                        ObjJsonData.Message = "Leggers Are Not Mapped ! Please Meet Exam Incharge .";
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamRegistrationForSJC", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            if (string.IsNullOrEmpty(ObjJsonData.Message))
            {
                ObjJsonData.Message = "No Changes Made !";
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
