        public ActionResult BindStudentExamRegistration(string sExamSettingId, string sClassId, string sStudentId)
        {
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjModel = new EXAM_REGISTRATION();
                    ObjModel.CLASS_ID = sClassId;
                    ObjModel.STUDENT_ID = sStudentId;
                    ObjModel.EXAM_SETTING_ID = sExamSettingId;
                    ObjViewModel.liExamRegistrationList = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(ObjModel,
                                 ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamRegisteredListByStudentId), sAcademicYear).DataSource.Data;


                    // To Bind Course List For Add/Edit ,..
                    var liRegularCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new EXAM_REGISTRATION() { STUDENT_ID = sStudentId },
                       ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamRegistration), sAcademicYear).DataSource.Data;
                    var liOptionalCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new EXAM_REGISTRATION() { STUDENT_ID = sStudentId },
                          ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data;

                    // Loop Optional Papers  To Remove Unnecessary Courses...
                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                    {
                        foreach (var item in liOptionalCourses)
                        {
                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (IsExist != null && IsExist.Count > 0)
                            {
                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                liRegularCourses.Add(item);
                            }
                        }
                    }


                    // Arrear Course ..
                    string ssql = string.Empty;
                    string sSemesterIds = "1,2,3,4,5,6";
                    var liSemesterMarks = new List<SEMESTER_RESULT>();
                    int nAcademicYear = Convert.ToInt32(sAcademicYear);
                    for (int i = 0; i < 3; i++)
                    {
                        ssql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterResult).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.SEMESTER, sSemesterIds);
                        var liTempSemester = (List<SEMESTER_RESULT>)CMSHandler.FetchData<SEMESTER_RESULT>(new EXAM_REGISTRATION() { STUDENT_ID = sStudentId }, ssql, nAcademicYear.ToString()).DataSource.Data;
                        nAcademicYear--;
                        if (liTempSemester != null && liTempSemester.Count > 0)
                        {
                            liSemesterMarks = (liSemesterMarks != null && liSemesterMarks.Count > 0) ? liSemesterMarks.Concat(liTempSemester).ToList() : liTempSemester;
                        }
                    }

                    var liArearList = new List<SEMESTER_RESULT>();
                    var objGroup = new List<SEMESTER_RESULT>();
                    var objGp = new List<SEMESTER_RESULT>();

                    // Get Only Arrear Papers group By Course Code ....
                    var result = liSemesterMarks.GroupBy(u => u.COURSE_CODE).ToList();

                    for (int i = 0; i < result.Count(); i++)
                    {
                        var code = result[i].Key.ToString();
                        objGp = (List<SEMESTER_RESULT>)liSemesterMarks.Where(o => o.COURSE_CODE == code).ToList();
                        if (objGp.FindAll(o => o.RESULT == "PASS").Count() == 0)
                            liArearList.Add(objGp.FirstOrDefault());
                    }
                    if (liArearList != null && liArearList.Count > 0)
                    {
                        liArearList.RemoveAll(x => x.WRITTEN_SEMESTER == liSemesterMarks.FirstOrDefault().SEMESTER_ID);
                    }

                    if (ObjViewModel.liExamRegistrationList != null && ObjViewModel.liExamRegistrationList.Count > 0)
                    {
                        foreach (var item in ObjViewModel.liExamRegistrationList)
                        {
                            if (liRegularCourses != null && liRegularCourses.Count > 0)
                            {
                                var liExist = liRegularCourses.Where(x => x.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                                if (liExist != null && liExist.Count > 0)
                                {
                                    liRegularCourses.RemoveAll(x => x.COURSE_ROOT_ID == item.COURSE_ROOT_ID);
                                }
                            }
                            if (liArearList != null && liArearList.Count > 0)
                            {
                                var liExist = liArearList.Where(x => x.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                                if (liExist != null && liExist.Count > 0)
                                {
                                    liArearList.RemoveAll(x => x.COURSE_ROOT_ID == item.COURSE_ROOT_ID);
                                }
                            }
                        }
                    }

                    if (liRegularCourses != null && liRegularCourses.Count > 0)
                    {
                        ObjViewModel.Course = "<option value=''> -- Select -- </option>";
                        foreach (var item in liRegularCourses)
                        {
                            ObjViewModel.Course += "<option value='" + item.COURSE_ROOT_ID + "' cms-sStatus='R' cms-sSemesterId='" + item.SEMESTER_ID + "'> " + item.COURSE_TITLE + " </option>";
                        }
                    }

                    if (liArearList != null && liArearList.Count > 0)
                    {
                        if (string.IsNullOrEmpty(ObjViewModel.Course))
                        {
                            ObjViewModel.Course = "<option value=''> -- Select -- </option>";
                        }
                        foreach (var item in liArearList)
                        {
                            ObjViewModel.Course += "<option value='" + item.COURSE_ROOT_ID + "' cms-sStatus='A' cms-sSemesterId='" + item.WRITTEN_SEMESTER + "'> " + item.COURSE_TITLE + " </option>";
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindStudentExamRegistration", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return View(ObjViewModel);
        }

