        public List<COUNT_STATUS_BY_COURSE> GetCourseOrderByStudentCountForSJC(List<COUNT_STATUS_BY_COURSE> liCourseAndCount, string sAvgCount)
        {
            List<COUNT_STATUS_BY_COURSE> tempCountlist = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> tempACountlist = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> tempBCountlist = new List<COUNT_STATUS_BY_COURSE>();
            List<COUNT_STATUS_BY_COURSE> tempCCountlist = new List<COUNT_STATUS_BY_COURSE>();
            try
            {
                liCourseAndCount = liCourseAndCount.OrderByDescending(o => Convert.ToInt32(o.STUDENT_COUNT)).ToList();
                foreach (var item in liCourseAndCount)
                {
                    if (tempACountlist.Count == 0)
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "A";
                        tempACountlist.Add(tempCourseCount);
                        continue;
                    }
                    if (tempCCountlist.Count == 0)
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "C";
                        tempCCountlist.Add(tempCourseCount);
                        continue;
                    }
                    if (tempBCountlist.Count == 0)
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "B";
                        tempBCountlist.Add(tempCourseCount);
                        continue;
                    }

                    if (tempACountlist.Sum(o => Convert.ToInt32(o.STUDENT_COUNT)) < Convert.ToInt16(sAvgCount))
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "A";
                        tempACountlist.Add(tempCourseCount);
                        continue;
                    }

                    if (tempCCountlist.Sum(o => Convert.ToInt32(o.STUDENT_COUNT)) < Convert.ToInt16(sAvgCount))
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "C";
                        tempCCountlist.Add(tempCourseCount);
                        continue;
                    }

                    if (tempBCountlist.Sum(o => Convert.ToInt32(o.STUDENT_COUNT)) < Convert.ToInt16(sAvgCount))
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "B";
                        tempBCountlist.Add(tempCourseCount);
                        continue;
                    }
                    else
                    {
                        var tempCourseCount = new COUNT_STATUS_BY_COURSE();
                        tempCourseCount.COURSE_ID = item.COURSE_ID;
                        tempCourseCount.STUDENT_COUNT = item.STUDENT_COUNT;
                        tempCourseCount.STATUS = "A";
                        tempACountlist.Add(tempCourseCount);
                        continue;
                    }

                }

                //tempOddCountlist.AddRange(tempEvenCountlist);
                if (tempBCountlist != null && tempBCountlist.Count() > 0)
                {
                    tempACountlist = tempACountlist.Concat(tempBCountlist).ToList();
                }

                if (tempCCountlist != null && tempCCountlist.Count() > 0)
                {
                    tempACountlist = tempACountlist.Concat(tempCCountlist).ToList();
                }
                tempCountlist = tempACountlist;
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "GetCourseOrderByStudentCount", ex.Message);
                }
            }

            //tempEvenCountlist = tempOddCountlist;
            return tempCountlist;
        }

