        public JsonResult NewExamSeatingAllotementForCoronaIssueSJC()
        {
            string sAcademicYear = ConfigurationManager.AppSettings["AcYearForAlumini"];
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var objmodel = new EXAM_SEATING_ALLOTEMENT();
            string sSQL = string.Empty;
            string sDbString = string.Empty;
            if (!string.IsNullOrEmpty(sUserId))
            {
                try
                {
                    var liExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingByAcitveId)).DataSource.Data;
                    if (liExamSetting != null && liExamSetting.Count > 0)
                    {
                        objmodel.EXAM_SETTING_ID = liExamSetting.FirstOrDefault().EXAM_SETTING_ID;
                        var liExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = liExamSetting.FirstOrDefault().EXAM_SETTING_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamTimeTableBySettingId), liExamSetting.FirstOrDefault().ACADEMIC_YEAR).DataSource.Data;
                        if (liExamTimeTable != null && liExamTimeTable.Count > 0)
                        {
                            //var liRoom = (List<SUP_ROOM>)CMSHandler.FetchData<SUP_ROOM>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupRoomList)).DataSource.Data;
                            foreach (var item in liExamTimeTable)
                            {
                                var sArrCourseId = item.COURSE_ID.Split(',');
                                sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseFromExamRegistrationByCourseAndSettingId).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.COURSE_ID, item.COURSE_ID);
                                var liExamRegistration = (List<CourseList>)CMSHandler.FetchData<CourseList>(objmodel, sSQL, liExamSetting.FirstOrDefault().ACADEMIC_YEAR).DataSource.Data;
                                if (liExamRegistration != null && liExamRegistration.Count > 0)
                                {
                                    objmodel.EXAM_DATE = item.EXAM_DATE;
                                    objmodel.EXAM_SESSION_ID = item.EXAM_SESSION_ID;
                                    var liSeating = (List<EXAM_SEATINGS>)CMSHandler.FetchData<EXAM_SEATINGS>(objmodel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSeating), liExamSetting.FirstOrDefault().ACADEMIC_YEAR).DataSource.Data;
                                    if (liSeating != null && liSeating.Count > 0)
                                    {
                                        sSQL = string.Empty;
                                        sDbString = string.Empty;
                                        sSQL = @"INSERT INTO `EXAM_SEATING_ALLOTEMENT`(`SEATING_ID`,`COURSE_ID`,`STUDENT_ID`,`EXAM_DATE`,`EXAM_SESSION_ID`,`EXAM_SETTING_ID`,`EXAM_TYPE`,`ACADEMIC_YEAR`)VALUES";
                                        sDbString = sSQL;
                                        var liShift = liExamRegistration.GroupBy(x => x.SHIFT).OrderByDescending(x => x.FirstOrDefault().SHIFT).ToList();
                                        foreach (var Shiftitem in liShift)
                                        {
                                            foreach (var Courseitem in sArrCourseId)
                                            {
                                                var liRegistration = liExamRegistration.Where(x => x.SHIFT == Shiftitem.FirstOrDefault().SHIFT && x.STATUS == "R" && x.COURSE_ID == Courseitem).OrderBy(x => x.ROLL_NO).ToList();
                                                if (liRegistration != null && liRegistration.Count > 0)
                                                {
                                                    foreach (var Studentitem in liRegistration)
                                                    {
                                                        sSQL += "('" + liSeating.FirstOrDefault().SEATING_ID + "','" + Courseitem + "','" + Studentitem.STUDENT_ID + "','" + item.EXAM_DATE + "','" + item.EXAM_SESSION_ID + "','" + item.EXAM_SETTING_ID + "','2','" + liExamSetting.FirstOrDefault().ACADEMIC_YEAR + "'),";
                                                        liExamRegistration.RemoveAll(x => x.COURSE_ID == Courseitem && x.STUDENT_ID == Studentitem.STUDENT_ID);
                                                        liSeating.RemoveAt(0);
                                                    }
                                                }
                                            }
                                        }

                                        if (sDbString != sSQL)
                                        {
                                            sSQL = sSQL.Trim(',') + ";";
                                            var sresultArgs = CMSHandler.SaveOrUpdate(null, sSQL);
                                            ObjJsonData.ErrorCode = (sresultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                                            ObjJsonData.Message = (sresultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                                            sSQL = string.Empty; sSQL = sDbString;
                                        }
                                    }
                                    else
                                    {
                                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                        ObjJsonData.Message += " No Seating Available For Date : " + objmodel.EXAM_DATE + " Session : " + objmodel.EXAM_SESSION_ID;
                                    }
                                }
                                else
                                {
                                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                    ObjJsonData.Message += " No Student Available For This Course : " + item.COURSE_ID + " , Date : " + objmodel.EXAM_DATE + " Session : " + objmodel.EXAM_SESSION_ID;
                                }
                            }
                        }
                        else
                        {
                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            ObjJsonData.Message = "No Exam TimeTable Available For Active Setting";
                        }
                    }
                    else
                    {
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        ObjJsonData.Message = "No Active Exam Setting";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "NewExamSeatingAllotementForCoronaIssueSJC", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
