                            var liStudent = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(CIA_COURSE_INFO, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByClassId), sAcademicYear).DataSource.Data;
                            if (liStudent != null && liStudent.Count > 0 && liCIATotal != null && liCIATotal.Count > 0)
                            {
                                foreach (var item in liStudent)
                                {
                                    var liExist = liCIATotal.Where(x => x.STUDENT_ID == item.STUDENT_ID).ToList();
                                    if (liExist != null && liExist.Count > 0)
                                    {
                                        var liInstant = liExist.Where(x => Convert.ToInt32(x.TOTAL) < 10).ToList();
                                        if (liInstant != null && liInstant.Count > 0)
                                        {
                                            if (liInstant.Count > 1)
                                            {
                                                liCIAFail = (liCIAFail != null && liCIAFail.Count > 0) ? liCIAFail.Concat(liInstant).ToList() : liInstant;
                                            }
                                        }
                                    }
                                }

                                ObjViewModel.liCIA_Total = liCIAFail;
                            }
                            else
                            {
                                ObjJsonData.Message = "No Student Marks Found !!! .";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }
                            ObjViewModel.liCIA_Total = liCIAFail;
                        }
                        else
                        {
                            ObjJsonData.Message = "No Course Found !!! .";
                            ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        }
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "BindHallTicketByClass", ex.Message);
                    }
                    ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }

        public ActionResult BindHallTicketForPassedOut(string sExamSettingId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjModel = new STU_CLASS();
                    ObjModel.EXAM_SETTING_ID = sExamSettingId;
                    // Student List By Class ....
                    var liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByExamSettingId), sAcademicYear).DataSource.Data;

                    // Hall Ticket Blocked Students ...
                    var liBlockHallTicket = (List<HALL_TICKET_VALIDATION>)CMSHandler.FetchData<HALL_TICKET_VALIDATION>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketValidation), sAcademicYear).DataSource.Data;
                    if (liBlockHallTicket != null && liBlockHallTicket.Count > 0)
                    {
                        foreach (var item in liBlockHallTicket)
                        {
                            liStudentList.RemoveAll(x => x.STUDENT_ID == item.STUDENT_ID);
                        }
                    }
                    ObjViewModel.liStudentList = liStudentList;

                    // Fetch Hall Ticket List
                    ObjViewModel.liFetchHallTicket = (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemHallTicketByExamSettingId), sAcademicYear).DataSource.Data;

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "BindHallTicketForPassedOut", ex.Message);
                    }
                    ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }
