        public ActionResult BindCIAExamMarkForCOE(string sClassId, string sCourseId, string sAcYear)
        {
            DataTable dtCourseInfo = new DataTable();
            DataTable dtCourseComponents = new DataTable();
            DataTable dtCIAMarks = new DataTable();
            string sSQL = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            using (ExaminationViewModel objExamination = new ExaminationViewModel())
            {
                try
                {
                    sAcademicYear = (!string.IsNullOrEmpty(sAcYear)) ? sAcYear : sAcademicYear;
                    var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                    //var CIA_TOTAL = new CIA_TOTAL();
                    CIA_COURSE_INFO.CLASS_ID = sClassId;
                    //CIA_COURSE_INFO.COURSE_ROOT_ID = sCourseId;
                    CIA_COURSE_INFO.COURSE_ID = sCourseId;
                    CIA_COURSE_INFO.STAFF_ID = sUserId;
                    // Fetch Course Details ....

                    objExamination.liCIACourse_Info = (List<CIA_FETCH_COURSE_INFO>)CMSHandler.FetchData<CIA_FETCH_COURSE_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId), sAcademicYear).DataSource.Data;
                    if (objExamination.liCIACourse_Info != null && objExamination.liCIACourse_Info.Count > 0)
                    {
                        if (!string.IsNullOrEmpty(objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID) && !objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID.Equals("0"))
                        {
                            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString() : string.Empty;
                            if (!string.IsNullOrEmpty(sActiveSemester))
                            {
                                if (sActiveSemester.Equals("1,3,5"))
                                    CIA_COURSE_INFO.SEMESTER = "ODD";
                                else
                                    CIA_COURSE_INFO.SEMESTER = "EVEN";
                            }

                            CIA_COURSE_INFO.COURSE_TYPE_ID = objExamination.liCIACourse_Info.FirstOrDefault().COURSE_TYPE_ID;
                            CIA_COURSE_INFO.SEMESTER_ID = objExamination.liCIACourse_Info.FirstOrDefault().SEMESTER_ID;
                            // Fetch Component Details ...
                            objExamination.liCIA_Component = (List<CIA_COMPONENT>)CMSHandler.FetchData<CIA_COMPONENT>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseComponentByCourseTypeId), sAcademicYear).DataSource.Data;
                            // FetchMarks ...
                            // objExamination.liCIA_Marks_Info = await Task.Run(() => (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIA_Marks), sAcademicYear).DataSource.Data);
                            var componentInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAComponentsByCourseId), sAcademicYear).DataSource.Data;
                            var markInfo = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(CIA_COURSE_INFO, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIA_Marks_Info), sAcademicYear).DataSource.Data;
                            if (componentInfo != null && componentInfo.Count > 0)
                            {
                                foreach (var item in componentInfo)
                                {
                                    var temp = markInfo.Where(o => o.STUDENT_ID == item.STUDENT_ID && o.COURSE_GROUP_ID == item.COURSE_GROUP_ID).ToList();
                                    if (temp != null && temp.Count > 0) { item.COURSE_GROUP_MARK = temp.FirstOrDefault().COURSE_GROUP_MARK; item.CIA_GROUP_MARK_ID = temp.FirstOrDefault().CIA_GROUP_MARK_ID; }
                                }
                                componentInfo.ForEach(o => o.COURSE_GROUP_MARK = string.Equals(o.COURSE_GROUP_MARK, "0") ? "0" : o.COURSE_GROUP_MARK);
                                var student = componentInfo.GroupBy(o => o.STUDENT_ID).Select(x => new CIA_TOTAL() { STUDENT_ID = x.FirstOrDefault().STUDENT_ID }).ToList();
                                objExamination.liCIA_Marks_Info = componentInfo;
                                objExamination.liCIA_Total = student;
                            }
                            return View(objExamination);
                        }
                        else
                        {
                            return Json("Missing Course Type For This Course Please Meet Admin!!!", JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        return Json("Missing Course Please Meet Admin!!!", JsonRequestBehavior.AllowGet);
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("ExaminationController", "BindStudentsByCourseId", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("ExaminationController", "BindStudentsByCourseId", ex.Message);
                    }
                    return Json("Internal Server Error !", JsonRequestBehavior.AllowGet);
                }
            }
        }

        public JsonResult FetchCourseByClassIdAndSemTypeId(string sClassId, string sSemesterTypeId, string sAcYear)
        {
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                sAcademicYear = (!string.IsNullOrEmpty(sAcYear)) ? sAcYear : sAcademicYear;
                try
                {
                    string sSemesterId = string.Empty;
                    if (sSemesterTypeId == "1")
                    {
                        sSemesterId = "1,3,5";
                    }
                    else if (sSemesterTypeId == "2")
                    {
                        sSemesterId = "2,4,6";
                    }
                    else if (sSemesterTypeId == "3")
                    {
                        sSemesterId = "1";
                    }
                    var ObjModel = new CourseWiseStaffList();
                    ObjModel.CLASS_ID = sClassId;
                    ObjModel.SEMESTER_TYPE_ID = sSemesterTypeId;
                    ObjModel.SEMESTER_ID = sSemesterId;

                    ObjJsonData.sResult = "<option value='0'> -- Select -- </option>";
                    var liOptionalCourse = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseByOptionalClassId), sAcademicYear).DataSource.Data;
                    if (liOptionalCourse != null && liOptionalCourse.Count > 0)
                    {
                        foreach (var item in liOptionalCourse)
                        {
                            ObjJsonData.sResult += "<option value='" + item.COURSE_ROOT_ID + "' cms-sSemesterId='" + item.SEMESTER_ID + "'>( " + item.COURSE_CODE + " ) - " + item.COURSE_TITLE + "</option>";
                        }
                        objJsonData.ErrorCode = Common.ErrorCode.Ok;
                    }

                    string sSQL = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseByClassIdAndSemesterId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId);
                    var liCourseInfo = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL, sAcademicYear).DataSource.Data;
                    if (liCourseInfo != null && liCourseInfo.Count > 0)
                    {
                        foreach (var item in liCourseInfo)
                        {
                            ObjJsonData.sResult += "<option value='" + item.COURSE_ROOT_ID + "' cms-sSemesterId='" + item.SEMESTER_ID + "'>( " + item.COURSE_CODE + " ) - " + item.COURSE_TITLE + "</option>";
                        }
                        objJsonData.ErrorCode = Common.ErrorCode.Ok;
                    }

                    if (liOptionalCourse == null && liCourseInfo == null)
                    {
                        ObjJsonData.Message = Common.ErrorMessage.NotFound;
                        objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "FetchCourseByClassIdAndSemTypeId", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    objJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        #endregion

        #region cia marks for student all the year 
        public ActionResult OVerallCIAMarksForStudent()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStudentId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var liSemesterIds = (List<ACADEMIC_SEMESTER>)CMSHandler.FetchData<ACADEMIC_SEMESTER>(new STU_CLASS() { STUDENT_ID = sStudentId },
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterIdsByStudentIdAndAcademicYear), sAcademicYear).DataSource.Data;

                    if (liSemesterIds != null && liSemesterIds.Count > 0)
                    {
                        int nBeginYear = Convert.ToInt32(liSemesterIds.FirstOrDefault().BEGIN_YEAR);
                        int nExpiredYear = Convert.ToInt32(liSemesterIds.FirstOrDefault().EXPIRED_YEAR);
                        var liCIATotal = new List<CIA_TOTAL>();
                        var liAllRegularCourses = new List<EXAM_REGISTRATION>();

                        for (int i = nBeginYear; i <= nExpiredYear; i++)
                        {
                            string currentYear = i.ToString();

                            // Fetch Regular Papers .
                            var liRegularCourses = (List<EXAM_REGISTRATION>)CMS.DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sStudentId },
                                    SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOddAndEvenSemCourseByStudent), currentYear).DataSource.Data;

                            // Fetch Optional Papers .
                            var liOptionalCourses = (List<EXAM_REGISTRATION>)DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sStudentId },
                                         SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOddAndEvenSemOptionalCourseByStudent), currentYear).DataSource.Data;

                            // Loop Optional Papers  To Remove Unnecessary Courses...
                            if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                            {
                                if (liRegularCourses == null) liRegularCourses = new List<EXAM_REGISTRATION>();
                                foreach (var item in liOptionalCourses)
                                {
                                    var IsExist = (liRegularCourses != null) ? liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList() : null;
                                    if (IsExist != null && IsExist.Count > 0)
                                    {
                                        liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                        item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                        liRegularCourses.Add(item);
                                    }
                                    else
                                    {
                                        liRegularCourses.Add(item);
                                    }
                                }
                            }

                            if (liRegularCourses != null && liRegularCourses.Count > 0)
                            {
                                liRegularCourses = liRegularCourses.Where(o => o.IS_STUDENT_VIEW_CIA_MARK != "0").ToList();
                                liAllRegularCourses.AddRange(liRegularCourses);
                                foreach (var item in liRegularCourses)
                                {
                                    item.STUDENT_ID = sStudentId;
                                    item.COURSE_ID = item.COURSE_ROOT_ID;
                                    var liCIAMarks = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAMarksByCourseIdAndStudentId), currentYear).DataSource.Data;
                                    if (liCIAMarks != null && liCIAMarks.Count > 0)
                                    {
                                        ObjViewModel.liCIA_Marks_Info = (ObjViewModel.liCIA_Marks_Info != null && ObjViewModel.liCIA_Marks_Info.Count > 0) ? ObjViewModel.liCIA_Marks_Info.Concat(liCIAMarks).ToList() : liCIAMarks;
                                    }

                                    var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATotalByStudentAndCourseId), currentYear).DataSource.Data;
                                    if (liCIA_Total != null && liCIA_Total.Count > 0)
                                    {
                                        liCIA_Total.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                        liCIATotal = (liCIATotal != null && liCIATotal.Count > 0) ? liCIATotal.Concat(liCIA_Total).ToList() : liCIA_Total;
                                    }
                                }
                            }
                        }
                        ObjViewModel.liExamRegistrationList = liAllRegularCourses;
                        ObjViewModel.liCIA_Total = liCIATotal;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "OVerallCIAMarksForStudent", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
