                    foreach (var Stuitem in sStudent)
                    {
                        ObjModel.STUDENT_ID = Stuitem;
                        var liStudent = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(ObjModel,
