        public JsonResult BindArrearExamRegistrationForSJC()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var ObjViewModel = new ExaminationViewModel();
            bool isErrorInData = false;
            string sSQL = string.Empty;
            string sMessage = string.Empty;
            sSQL = @"INSERT INTO EXAM_REGISTRATION_" + sAcademicYear + "(STUDENT_ID,COURSE_ID,STATUS,ACADEMIC_YEAR,EXAM_SEMESTER,EXAM_SETTING_ID,AMOUNT)VALUES";
            //sSQL = @"INSERT INTO DEMO_TEST_TABLE(TEXT1,TEXT2)VALUES";
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var sname = Request.Files[0].FileName.Split('.');
                    string sFilename = string.Empty;
                    var sExamSetting = Request.Form["sExamSetting"];
                    bool sFlag = false;
                    DataTable dt = new DataTable();
                    if (Request.Files.Count > 0)
                    {
                        string[] validFileTypes = { ".xls", ".xlsx", ".csv" };
                        string path1 = string.Format("{0}/{1}", Server.MapPath("~/Content/Uploads/ArrearExamination/" + "SettingId_" + sExamSetting), Request.Files[0].FileName);

                        string extension = System.IO.Path.GetExtension(Request.Files[0].FileName).ToLower();

                        string connString = string.Empty;

                        if (!Directory.Exists(path1))
                        {
                            Directory.CreateDirectory(Server.MapPath("~/Content/Uploads/ArrearExamination/" + "SettingId_" + sExamSetting));
                        }
                        if (validFileTypes.Contains(extension))
                        {
                            if (System.IO.File.Exists(path1))
                            {
                                System.IO.File.Delete(path1);
                            }
                            Request.Files[0].SaveAs(path1);
                            if (extension == ".csv")
                            {
                                dt = CommonMethods.ConvertCSVtoDataTable(path1);
                            }
                            //Connection String to Excel Workbook  
                            else if (extension.Trim() == ".xls")
                            {
                                connString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + path1 + ";Extended Properties=Excel 8.0";// string.Format("Provider=Microsoft.ACE.OLEDB.12.0;Data Source={0}; Extended Properties=\"Excel 12.0 Xml;HDR=No;IMEX=1\";", path1);
                                dt = CommonMethods.ConvertXSLXtoDataTable(path1, connString);
                            }
                            else if (extension.Trim() == ".xlsx")
                            {
                                connString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + path1 + ";Extended Properties=Excel 8.0";// string.Format("Provider=Microsoft.ACE.OLEDB.12.0;Data Source={0}; Extended Properties=\"Excel 12.0 Xml;HDR=No;IMEX=1\";" , path1);
                                dt = CommonMethods.ConvertXSLXtoDataTable(path1, connString);
                            }
                        }
                    }

                    // Fetch Student Details
                    var liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(null, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentInfo), sAcademicYear).DataSource.Data;
                    //var liStudentList = DapperHandler.FetchAll<STU_PERSONAL_INFO>(SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchDemoTestTable)).ToList();
                    var liCourseList = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(null, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourse), sAcademicYear).DataSource.Data;
                    if (liStudentList != null && liStudentList.Count > 0)
                    {
                        string sCourseCode = string.Empty;
                        string sStatus = string.Empty;
                        foreach (DataRow dr in dt.Rows)
                        {
                            var liStudentExist = liStudentList.Where(x => x.ROLL_NO.ToUpper() == dr["ROLL_NO"].ToString().ToUpper()).ToList();
                            if (liStudentExist != null && liStudentExist.Count > 0)
                            {
                                for (int i = 1; i < 40; i++)
                                {
                                    sStatus = "R";
                                    sCourseCode = dr["SUB " + i].ToString();
                                    sCourseCode = sCourseCode.Replace(" ", "");
                                    if (!string.IsNullOrEmpty(sCourseCode))
                                    {
                                        if (sCourseCode.StartsWith("*"))
                                        {
                                            sStatus = "A";
                                        }
                                        var liCourseExist = liCourseList.Where(x => x.COURSE_TITLE == sCourseCode.Replace("*", "")).ToList();

                                        sFlag = true;
                                        // sSQL += "('"+ dr["ROLL_NO"].ToString() + "','"+ dr["NAME"].ToString() + "','"+ liCourseExist.FirstOrDefault().COURSE_ROOT_ID + "','"+ sCourseCode.Replace("*", "") + "'),";
                                        if (liCourseExist != null && liCourseExist.Count > 0)
                                        {
                                            sFlag = true;
                                            sSQL += "('" + liStudentExist.FirstOrDefault().STUDENT_ID + "','" + liCourseExist.FirstOrDefault().COURSE_ROOT_ID + "','" + sStatus + "','" + sAcademicYear + "','" + liCourseExist.FirstOrDefault().SEMESTER_ID + "','" + sExamSetting + "','" + dr["EXAM FEES"] + "'),";
                                            //sSQL += "('" + liStudentExist.FirstOrDefault().STUDENT_ID + "','" + liCourseExist.FirstOrDefault().COURSE_ROOT_ID + "'),";
                                        }
                                        else
                                        {

                                            sMessage = "Course Missing ::" + dr["ROLL_NO"].ToString() + "::" + dr["SUB " + i].ToString();
                                            using (ErrorLog ObjLog = new ErrorLog())
                                            {
                                                ObjLog.ExamRegistrationLog(sMessage, sname[0]);
                                            }
                                            // ObjJsonData.sResult += dr["SUB " + i].ToString() + ",";
                                            isErrorInData = true;
                                        }
                                    }
                                }
                            }
                            else
                            {

                                sMessage = "Student Missing ::" + dr["ROLL_NO"].ToString();
                                using (ErrorLog ObjLog = new ErrorLog())
                                {
                                    ObjLog.ExamRegistrationLog(sMessage, sname[0]);
                                }
                                isErrorInData = true;

                                //ObjJsonData.Message += dr["ROLL_NO"].ToString() + ",";
                            }
                        }

                        if (sFlag)
                        {
                            sSQL = sSQL.Trim(',') + ";";
                            using (ExaminationViewModel objExamination = new ExaminationViewModel())
                            {
                                sSQL = sSQL.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                                resultArgs = objExamination.ExcuteCIA_Marks(sSQL);
                                if (isErrorInData)
                                {
                                    ObjJsonData.Message = "Partially saved Please download the Log";
                                }
                                else

                                    ObjJsonData.Message = (resultArgs.Success && resultArgs.RowsAffected != 0) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }


                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindArrearExamRegistrationForSJC", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }

            var fname = Request.Files[0].FileName.Split('.');
            ObjJsonData.sResult = "/ExamRegisterLog/" + fname[0] + ".txt";
            ObjJsonData.ErrorCode = "";
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        #endregion

