                                        }
                                        searchCourseCode = searchCourseCode.Trim();
                                        var liCourseExist = liCourseList.Where(x => x.COURSE_TITLE == searchCourseCode).ToList();

                                        if (liCourseExist != null && liCourseExist.Count > 0)
                                        {
                                            sFlag = true;
                                            sSQL += "('" + liStudentExist.FirstOrDefault().STUDENT_ID + "','" + liCourseExist.FirstOrDefault().COURSE_ROOT_ID + "','" + currentExamSettingId + "','" + sAcademicYear + "','1'),";
                                        }
                                        else
                                        {

                                            sMessage = "Course Missing ::" + dr["ROLL_NO"].ToString().Trim() + "::" + dr["SUB " + i].ToString();
                                            using (ErrorLog ObjLog = new ErrorLog())
                                            {
                                                ObjLog.ExamRegistrationLog(sMessage, sname[0]);
                                            }
                                            isErrorInData = true;
                                        }
                                    }
                                }
                            }
                            else
                            {

                                sMessage = "Student Missing ::" + dr["ROLL_NO"].ToString().Trim();
                                using (ErrorLog ObjLog = new ErrorLog())
                                {
                                    ObjLog.ExamRegistrationLog(sMessage, sname[0]);
                                }
                                isErrorInData = true;

                                //ObjJsonData.Message += dr["ROLL_NO"].ToString() + ",";
                            }
                        }

                        if (sFlag)
                        {
                            sSQL = sSQL.Trim(',') + ";";
                            using (ExaminationViewModel objExamination = new ExaminationViewModel())
                            {
                                sSQL = sSQL.Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, sAcademicYear);
                                resultArgs = objExamination.ExcuteCIA_Marks(sSQL);
                                if (isErrorInData)
                                {
                                    ObjJsonData.Message = "Partially saved Please download the Log";
                                }
                                else

                                    ObjJsonData.Message = (resultArgs.Success && resultArgs.RowsAffected != 0) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }


                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindArrearExamRegistrationForoutgoneStudent", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }

            var fname = Request.Files[0].FileName.Split('.');
            ObjJsonData.sResult = "/ExamRegisterLog/" + fname[0] + ".txt";
            ObjJsonData.ErrorCode = "";
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        #endregion



