        public JsonResult CopyQuizQuestion(string sQuizSettingId, string sCourseId, string sClassId, string sStaffId)
        {
            JsonResultData ObjJsonData = new JsonResultData();
            ObjJsonData.oResult = 0;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sSettingId = string.Empty;
            string sSemesterId = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear) && !string.IsNullOrEmpty(sQuizSettingId) && !string.IsNullOrEmpty(sCourseId) && !string.IsNullOrEmpty(sClassId) && !string.IsNullOrEmpty(sStaffId))
            {

                try
                {

                    // Fetch SemesterId By Course Id .
                    var liFetchSemsterByCourse = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_ID = sCourseId },
                            SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSemesterByCourseId), sAcademicYear).DataSource.Data;
                    if (liFetchSemsterByCourse != null && liFetchSemsterByCourse.Count > 0)
                    {
                        sSemesterId = liFetchSemsterByCourse.FirstOrDefault().SEMESTER_ID;
                    }


                    var liQuizSetting = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(new QUIZ_SETTING() { SETTING_ID = sQuizSettingId },
                         ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizSettingById), sAcademicYear).DataSource.Data;

                    if (liQuizSetting != null && liQuizSetting.Count > 0)
                    {
                        // Get Class Course Staff Id ...
                        var liQuizClassCourseStaff = (List<QUIZ_CLASS_COURSE_STAFF>)CMSHandler.FetchData<QUIZ_CLASS_COURSE_STAFF>(new QUIZ_CLASS_COURSE_STAFF() { CLASS_ID = sClassId, COURSE_ID = sCourseId, STAFF_ID = sStaffId },
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.GetClassCourseStaffIdForQuizSetting), sAcademicYear).DataSource.Data;

                        if (liQuizClassCourseStaff != null && liQuizClassCourseStaff.Count > 0)
                        {
                            liQuizSetting.FirstOrDefault().QUIZ_STF_ID = liQuizClassCourseStaff.FirstOrDefault().QUIZ_STF_ID;
                            liQuizSetting.FirstOrDefault().STAFF_ID = liQuizClassCourseStaff.FirstOrDefault().STAFF_ID;

                        }
                        else
                        {
                            ObjJsonData.Message = "Class Course Staff Not Mapped!";
                            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                        }
                        if (!string.IsNullOrEmpty(liQuizSetting.FirstOrDefault().START_DATE))
                        {
                            liQuizSetting.FirstOrDefault().START_DATE = CommonMethods.ConvertdatetoyearFromat(liQuizSetting.FirstOrDefault().START_DATE);

                        }

                        //add setting 
                        resultArgs = CMSHandler.SaveOrUpdate(liQuizSetting.FirstOrDefault()
                        , ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizSetting), sAcademicYear, true);
                        if (resultArgs.Success)
                        {
                            sSettingId = resultArgs.RowUniqueId.ToString();

                        }
                        else
                        {
                            ObjJsonData.Message = "Failed to Creating Setting!";
                            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                        }
                    }

                    if (!string.IsNullOrEmpty(sSettingId))
                    {
                        //fetch the objective type questions by setting
                        var liObjectiveQuestions = (List<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { SETTING_ID = sQuizSettingId },
                         ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizObjectiveQuestionBySettingId), sAcademicYear).DataSource.Data;

                        //fetch option 
                        if (liObjectiveQuestions != null && liObjectiveQuestions.Count > 0)
                        {

                            foreach (var item in liObjectiveQuestions)
                            {
                                if (!string.IsNullOrEmpty(item.QUIZ_ID))
                                {
                                    var liOptions = (List<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { QUIZ_ID = item.QUIZ_ID },
                                             ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizObjectiveOptionsByQuizId), sAcademicYear).DataSource.Data;


                                    //check if it option match with answer
                                    var HasItem = liOptions.Where(x => x.OPTION == item.ANSWER_ID).ToList();

                                    if (HasItem != null && HasItem.Count > 0)
                                    {
                                        var objMatchQuestion = new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS()
                                        {
                                            ENTRY_ID = sStaffId,
                                            CLASS_ID = sClassId,
                                            COURSE_ID = sCourseId,
                                            QUESTION = item.QUESTION,
                                            MARK = item.MARK,
                                            SET_ID = item.SET_ID,
                                            QUESTION_TYPE = item.QUESTION_TYPE,
                                            ACADEMIC_YEAR = sAcademicYear,
                                            SEMESTER_ID = sSemesterId,
                                            SETTING_ID = sSettingId,
                                            ANSWER_ID = HasItem.FirstOrDefault().OPTION
                                        };
                                        // Save Questions ...
                                        var sSaveQuestions = CMSHandler.SaveOrUpdate(objMatchQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizQuestion), sAcademicYear, true);
                                        if (sSaveQuestions.Success)
                                        {
                                            ObjJsonData.oResult = Convert.ToInt16(ObjJsonData.oResult) + 1;
                                            string Quiz_Id = sSaveQuestions.RowUniqueId.ToString();
                                            objMatchQuestion.QUIZ_ID = Quiz_Id;
                                            foreach (var item1 in liOptions)
                                            {
                                                item1.SEMESTER_ID = sSemesterId;
                                                item1.QUIZ_ID = Quiz_Id;
                                                item1.SET_ID = objMatchQuestion.SET_ID;
                                                item1.OPTIONS = item1.OPTION;
                                                item1.SETTING_ID = sSettingId;
                                                var sSaveQuizOptions = CMSHandler.SaveOrUpdate(item1, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizOption), sAcademicYear);
                                            }
                                            var FetchOptionIdByAnswer = (List<QUIZ_OPTIONS_2017>)CMSHandler.FetchData<QUIZ_OPTIONS_2017>(objMatchQuestion,
                                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionIdByOption), sAcademicYear).DataSource.Data;
                                            if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                            {
                                                objMatchQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                                var sUpdateAnswer = CMSHandler.SaveOrUpdate(objMatchQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForObjectiveQuestions), sAcademicYear);
                                            }

                                        }
                                        else
                                        {

                                        }
                                    }
                                }
                            }
                        }

                        //fetch the fill the blanks question by setting
                        var liFillintheBlanksQuestions = (List<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { SETTING_ID = sQuizSettingId },
                             ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizFillinTheBlanksQuestionBySettingId), sAcademicYear).DataSource.Data;
                        if (liFillintheBlanksQuestions != null && liFillintheBlanksQuestions.Count > 0)
                        {

                            foreach (var fitem in liFillintheBlanksQuestions)
                            {
                                if (!string.IsNullOrEmpty(fitem.QUIZ_ID))
                                {
                                    var liFillOptions = (List<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { QUIZ_ID = fitem.QUIZ_ID },
                                             ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizFillintheBlanksOptionByQuizId), sAcademicYear).DataSource.Data;


                                    //check if it option match with answer
                                    var HasItem = liFillOptions.Where(x => x.OPTION == fitem.ANSWER_ID).ToList();
                                    if (HasItem != null && HasItem.Count > 0)
                                    {
                                        var objFillQuestion = new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS()
                                        {
                                            ENTRY_ID = sStaffId,
                                            CLASS_ID = sClassId,
                                            COURSE_ID = sCourseId,
                                            QUESTION = fitem.QUESTION,
                                            MARK = fitem.MARK,
                                            SET_ID = fitem.SET_ID,
                                            QUESTION_TYPE = fitem.QUESTION_TYPE,
                                            ACADEMIC_YEAR = sAcademicYear,
                                            SEMESTER_ID = sSemesterId,
                                            SETTING_ID = sSettingId,
                                            ANSWER_ID = HasItem.FirstOrDefault().OPTION
                                        };
                                        // Save Questions ...
                                        var sSaveQuestions = CMSHandler.SaveOrUpdate(objFillQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizFillInBlankQuestions), sAcademicYear, true);
                                        if (sSaveQuestions.Success)
                                        {
                                            ObjJsonData.oResult = Convert.ToInt16(ObjJsonData.oResult) + 1;
                                            string Quiz_Id = sSaveQuestions.RowUniqueId.ToString();
                                            objFillQuestion.QUIZ_ID = Quiz_Id;
                                            foreach (var fitem1 in liFillOptions)
                                            {
                                                fitem1.SEMESTER_ID = sSemesterId;
                                                fitem1.QUIZ_ID = Quiz_Id;
                                                fitem1.SET_ID = objFillQuestion.SET_ID;
                                                fitem1.OPTIONS = fitem1.OPTION;
                                                fitem1.SETTING_ID = sSettingId;
                                                var sSaveQuizOptions = CMSHandler.SaveOrUpdate(fitem1, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveQuizFillInBlankOptions), sAcademicYear);
                                            }
                                            var FetchOptionIdByAnswer = (List<QUIZ_OPTIONS_2017>)CMSHandler.FetchData<QUIZ_OPTIONS_2017>(objFillQuestion,
                                               ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizFillInBlankOptionIdByOption), sAcademicYear).DataSource.Data;
                                            if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                            {
                                                objFillQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                                var sUpdateAnswer = CMSHandler.SaveOrUpdate(objFillQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForFillInBlankQuestions), sAcademicYear);
                                            }

                                        }
                                        else
                                        {

                                        }
                                    }
                                }
                            }
                        }

                        //fetch match the following question by setting
                        var liMatchTheFollowingQuestions = (List<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_QUESTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { SETTING_ID = sQuizSettingId },
                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizMatchTheFollowingQuestionBySettingId), sAcademicYear).DataSource.Data;

                        if (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0)
                        {
                            foreach (var mitem in liMatchTheFollowingQuestions)
                            {
                                if (!string.IsNullOrEmpty(mitem.QUIZ_ID))
                                {

                                    var liMathOptions = (List<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>)CMSHandler.FetchData<QUIZ_MATCH_THE_FOLLOWING_OPTIONS>(new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS() { QUIZ_ID = mitem.QUIZ_ID },
                                             ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizMatchTheFollowingOptionByQuizId), sAcademicYear).DataSource.Data;

                                    var objMatchTheFollowingQuestion = new QUIZ_MATCH_THE_FOLLOWING_QUESTIONS()
                                    {
                                        ENTRY_ID = sStaffId,
                                        CLASS_ID = sClassId,
                                        COURSE_ID = sCourseId,
                                        QUESTION = mitem.QUESTION,
                                        MARK = mitem.MARK,
                                        SET_ID = mitem.SET_ID,
                                        QUESTION_TYPE = mitem.QUESTION_TYPE,
                                        ACADEMIC_YEAR = sAcademicYear,
                                        SEMESTER_ID = sSemesterId,
                                        SETTING_ID = sSettingId
                                    };

                                    // Save Quiz Questions .
                                    var SaveMFQuestions = CMSHandler.SaveOrUpdate(objMatchTheFollowingQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveMathTheFollowingQuestions), sAcademicYear, true);
                                    if (SaveMFQuestions.Success)
                                    {
                                        ObjJsonData.oResult = Convert.ToInt16(ObjJsonData.oResult) + 1;
                                        string Quiz_Id = SaveMFQuestions.RowUniqueId.ToString();
                                        // Save Quiz Options .
                                        foreach (var mitem1 in liMathOptions)
                                        {
                                            mitem1.SEMESTER_ID = sSemesterId;
                                            mitem1.QUIZ_ID = Quiz_Id;
                                            mitem1.SET_ID = objMatchTheFollowingQuestion.SET_ID;
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(mitem1, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveMathTheFollowingOptions), sAcademicYear);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        ObjJsonData.Message = "Failed to move questions!";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "CopyQuizQuestion", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "CopyQuizQuestion", "Err.Msg:" + ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }

            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
