        public JsonResult SaveExamEvaluatorStaffInfo(string sJsonData)
        {
            if (!string.IsNullOrEmpty(sJsonData))
            {
                var Result = JsonConvert.DeserializeObject<JSON_EVALUATOR>(sJsonData);
                USER_ACCOUNT_INFO objModel = new USER_ACCOUNT_INFO();

                if (Result != null)
                {
                    foreach (var item in Result.LiEvaluatorInfo)
                    {
                        var Is_EvaluatorExsit = (List<EXAM_EVALUATOR_STAFF_INFO>)CMSHandler.FetchData<EXAM_EVALUATOR_STAFF_INFO>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsEvaluatorExist)).DataSource.Data;
                        if (Is_EvaluatorExsit != null && Is_EvaluatorExsit.Count > 0)
                        {
                            //code has to write
                        }
                        else
                        {
                            resultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveEvaluatorStaffInfo), "", true);
                            if (resultArgs.Success)
                            {

                                var EvaluatorInfo = (List<EXAM_EVALUATOR_STAFF_INFO>)CMSHandler.FetchData<EXAM_EVALUATOR_STAFF_INFO>(new EXAM_EVALUATOR_STAFF_INFO() { EXAM_EVALUATOR_STAFF_ID = resultArgs.RowUniqueId.ToString() }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEvaluatorStaffinfoById)).DataSource.Data;
                                if (EvaluatorInfo != null && EvaluatorInfo.Count > 0)
                                {
                                    objModel.USERNAME = EvaluatorInfo.FirstOrDefault().USERNAME;
                                    objModel.NAME = EvaluatorInfo.FirstOrDefault().NAME;
                                    objModel.PASSWORD = EvaluatorInfo.FirstOrDefault().PASSWORD;
                                    objModel.MOBILE = EvaluatorInfo.FirstOrDefault().PHONE;
                                    objModel.USER_ID = EvaluatorInfo.FirstOrDefault().EXAM_EVALUATOR_STAFF_ID;
                                    objModel.ROLE = Common.ROLE.EVALUATORS;
                                    resultArgs = CMSHandler.SaveOrUpdate(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveUserAccountForEvaluator));
                                }


                            }
                        }
                    }
                    objJsonData.Message = resultArgs.Success ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                    objJsonData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                }
            }
            else
            {
                objJsonData.Message = Common.Messages.FailedToSaveRecords;
                objJsonData.ErrorCode = Common.ErrorCode.ExpectationFailed;
            }
