                        var Is_CourseExsit = (List<EXAM_EVALUATION_COURSE_SETTING>)CMSHandler.FetchData<EXAM_EVALUATION_COURSE_SETTING>(EvaluatinCourses, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsCourseExist)).DataSource.Data;
