                            resultArgs = CMSHandler.SaveOrUpdate(EvaluatinCourses, ExaminationSQL.GetExaminationSQL(!string.IsNullOrEmpty(EvaluatinCourses.EVALUATION_COURSE_SETTING_ID) ? ExaminationSQLCommands.UpdateEvaluationCourseSetting : ExaminationSQLCommands.SaveEvaluationCourseInfo));
