        public JsonResult SaveEvaluationStudentForEvaluators(string sJsonEvalauationStudent)
        {
            JsonResultData objResult = new JsonResultData();
            JavaScriptSerializer serializer = new JavaScriptSerializer();
            var objModel = new EXAM_EVALUATION_STUDENT_MARK();
            string sSQL = string.Empty;
            try
            {
                if (sJsonEvalauationStudent != null)
                {
                    if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
                    {
                        var sAcademicyear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                        var Result = serializer.Deserialize<JSON_EVALUATOR>(sJsonEvalauationStudent);
                        if (Result.JSON_EVSTUDENTMARK != null && Result.JSON_EVSTUDENTMARK.Count > 0)
                        {
                            sSQL = string.Empty;
                            sSQL = @"INSERT INTO EXAM_EVALUATION_STUDENT_MARK (EVALUATION_COURSE_SETTING_ID,STUDENT_ID,EXAM_EVALUATOR_STAFF_ID,COURSE_ID,ACDEMIC_YEAR) VALUES";
                            foreach (var list in Result.JSON_EVSTUDENTMARK)
                            {
                                objModel.EVALUATION_COURSE_SETTING_ID = list.EVALUATION_COURSE_SETTING_ID;
                                objModel.STUDENT_ID = list.STUDENT_ID;
                                objModel.EXAM_EVALUATOR_STAFF_ID = list.EXAM_EVALUATOR_STAFF_ID;
                                objModel.COURSE_ID = list.COURSE_ID;
                                objModel.ACDEMIC_YEAR = list.ACDEMIC_YEAR;
                                sSQL += "('" + list.EVALUATION_COURSE_SETTING_ID + "','" + list.STUDENT_ID + "','" + list.EXAM_EVALUATOR_STAFF_ID + "','" + list.COURSE_ID + "','" + sAcademicyear + "'),";
                            }
                            sSQL = sSQL.TrimEnd(',');
                            var sresultArgs = CMSHandler.SaveOrUpdate(objModel, sSQL, sAcademicyear);
                            objResult.ErrorCode = (sresultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                            objResult.Message = (sresultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        }
                        else
                        {
                            objResult.ErrorCode = Common.ErrorCode.NoContent;
                            objResult.Message = Common.ErrorMessage.BadRequest;
                        }
                    }
                    else
                    {
                        objResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                        objResult.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                    }
                }
                else
                {
                    objResult.ErrorCode = Common.ErrorCode.BadRequest;
                    objResult.Message = Common.ErrorMessage.BadRequest;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("SaveEvaluationStudentForEvaluators", "Examination", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("SaveEvaluationStudentForEvaluators", "Examination", ex.Message);
                }
            }
            return Json(objResult, JsonRequestBehavior.AllowGet);
        }
