        public JsonResult SaveBundlesForEvaluators(string sJsonEvalauationStudent)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var objModel = new EXAM_EVALUATION_STUDENT_MARK();
            string sSQL = string.Empty;
            int scount = 0; int fcount = 0;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                if (!string.IsNullOrEmpty(sJsonEvalauationStudent))
                {
                    try
                    {
                        JavaScriptSerializer serializer = new JavaScriptSerializer();
                        var Result = serializer.Deserialize<JSON_EVALUATOR>(sJsonEvalauationStudent);
                        if (Result.JSON_EVSTUDENTMARK != null && Result.JSON_EVSTUDENTMARK.Count > 0)
                        {
                            foreach (var list in Result.JSON_EVSTUDENTMARK)
                            {
                                sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveStudentsAssignForStaffByBundles);
                                sSQL = sSQL.Replace(Common.Delimiter.QUS + Common.EXAM_EVALUATION_COURSE_SETTING.EVALUATION_COURSE_SETTING_ID, list.EVALUATION_COURSE_SETTING_ID).Replace(Common.Delimiter.QUS + Common.EXAM_EVALUATION_STUDENT_MARK.EXAM_EVALUATOR_STAFF_ID, list.EXAM_EVALUATOR_STAFF_ID).Replace(Common.Delimiter.QUS + Common.EXAM_EVALUATION_STUDENT_MARK.EVALUATION, list.EVALUATION);
                                resultArgs = CMSHandler.SaveOrUpdate(list, sSQL, sAcademicYear);
                                if (resultArgs.Success)
                                {
                                    scount++;
                                }
                                else
                                {
                                    fcount++;
                                }
                            }
                            objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                            objJsonData.Message = scount + Common.Messages.RecordsSavedSuccessfully + "\n" + fcount + Common.Messages.FailedToSaveRecords;
                        }
                        else
                        {
                            objJsonData.Message = Common.ErrorMessage.BadRequest;
                        }
                    }
                    catch (Exception ex)
                    {

                        using (ErrorLog obj = new ErrorLog())
                        {
                            obj.WriteError("Examinations", "sExamBundleId", ex.Message);
                        }
                    }
                }
                else
                {
                    objJsonData.Message = Common.Messages.NoRecordsfound;
                }
            }
            else
            {
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }

