        public ActionResult BindExternalEvaluationStudentMarksForCOE(string sEvaluationDate, string sCourseId, string sEvaluatorId, string sCalculationType)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjModel = new EXAM_EVALUATION_STUDENT_MARK();
            var LiEXAM_EVALUATION_STUDENT_MARK = new List<EXAM_EVALUATION_STUDENT_MARK>();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                ObjModel.EVALUATION_DATE = CommonMethods.ConvertdatetoyearFromat(sEvaluationDate);
                ObjModel.COURSE_ID = sCourseId;
                ObjModel.EXAM_EVALUATOR_STAFF_ID = sEvaluatorId;
                sCalculationType = "1";
                try
                {
                    ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK = (List<EXAM_EVALUATION_STUDENT_MARK>)CMSHandler.FetchData<EXAM_EVALUATION_STUDENT_MARK>(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEvaluationStudenByEvaluatorAndCourseAndDate), sAcademicYear).DataSource.Data;
                    if (ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK != null && ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.Count > 0)
                    {
                        if (ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.FirstOrDefault().PROGRAMME_LEVEL_ID == "1")
                        {
                            ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.ForEach(o => o.EVALUATION_1 = string.IsNullOrEmpty(o.EVALUATION_1) ? "0" : o.EVALUATION_1);
                            ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.ForEach(o => o.TOTAL = Math.Round(((Convert.ToDecimal((o.EVALUATION_1).ToUpper().Equals("A") ? "0" : o.EVALUATION_1)) / (Convert.ToDecimal(o.EXAM_MARK)) * (Convert.ToDecimal(o.EXTERNAL))), MidpointRounding.AwayFromZero).ToString());
                        }
                        else if (ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.FirstOrDefault().PROGRAMME_LEVEL_ID == "2")
                        {
                            ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.ForEach(o => o.EVALUATION_1 = string.IsNullOrEmpty(o.EVALUATION_1) ? "0" : o.EVALUATION_1);
                            ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.ForEach(o => o.EVALUATION_2 = string.IsNullOrEmpty(o.EVALUATION_2) ? "0" : o.EVALUATION_2);
                            ObjViewModel.liEXAM_EVALUATION_STUDENT_MARK.ForEach(o => o.TOTAL = Math.Round((((Convert.ToDecimal((o.EVALUATION_1).ToUpper().Equals("A") ? "0" : o.EVALUATION_1)) + (Convert.ToDecimal((o.EVALUATION_2).ToUpper().Equals("A") ? "0" : o.EVALUATION_2))) / (Convert.ToDecimal(o.EXAM_MARK)) * (Convert.ToDecimal(o.EXTERNAL))), MidpointRounding.AwayFromZero).ToString());
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "ExternalEvaluationStudent", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
        public JsonResult SaveExternalEvaluationStudentMarksForCOE(string sJsonEvalauationStudentMark)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            JsonResultData objResult = new JsonResultData();
            JavaScriptSerializer serializer = new JavaScriptSerializer();
            var objModel = new EXAM_EVALUATION_STUDENT_MARK();
            string sSQL = string.Empty;
            int scount = 0; int fcount = 0;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    if (sJsonEvalauationStudentMark != null)
                    {
                        var Result = serializer.Deserialize<JSON_EVALUATOR>(sJsonEvalauationStudentMark);
                        if (Result.JSON_EVSTUDENTMARK != null && Result.JSON_EVSTUDENTMARK.Count > 0)
                        {
                            if (true)
                            {
                                foreach (var item in Result.JSON_EVSTUDENTMARK)
                                {
                                    objModel.EVALUATION_1 = item.EVALUATION_1;
                                    objModel.EVALUATION_2 = item.EVALUATION_2;
                                    objModel.TOTAL = item.TOTAL;
                                    objModel.EXAM_EV_STU_MARK_ID = item.EXAM_EV_STU_MARK_ID;
                                    resultArgs = CMSHandler.SaveOrUpdate(item, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveEvaluationMarkCOEByStuMarkId));
                                    if (resultArgs.Success)
                                    {
                                        scount++;
                                    }
                                    else
                                    {
                                        fcount++;
                                    }
                                }
                                objResult.Message = scount + Common.Messages.RecordsSavedSuccessfully + "\n" + fcount + Common.Messages.FailedToSaveRecords;
                            }
                            else
                            {
                                foreach (var item in Result.JSON_EVSTUDENTMARK)
                                {

                                    objModel.EVALUATION_1 = item.EVALUATION_1;
                                    objModel.EVALUATION_2 = item.EVALUATION_2;
                                    objModel.TOTAL = item.TOTAL;
                                    objModel.EXAM_EV_STU_MARK_ID = item.EXAM_EV_STU_MARK_ID;
                                    resultArgs = CMSHandler.SaveOrUpdate(objModel, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveEvaluationMarkCOEByStuMarkId));
                                    if (resultArgs.Success)
                                    {
                                        scount++;
                                    }
                                    else
                                    {
                                        fcount++;
                                    }
                                }
                                objResult.Message = scount + Common.Messages.RecordsSavedSuccessfully + "\n" + fcount + Common.Messages.FailedToSaveRecords;
                            }

                        }
                        else
                        {
                            objResult.ErrorCode = Common.ErrorCode.NoContent;
                            objResult.Message = Common.Messages.NoRecordsfound;
                        }
                    }
                    else
                    {
                        objResult.ErrorCode = Common.ErrorCode.BadRequest;
                        objResult.Message = Common.ErrorMessage.BadRequest;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("SaveEvaluationStudentForEvaluators", "Examination", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("SaveEvaluationStudentForEvaluators", "Examination", ex.Message);
                    }
                }
            }
            else
            {
                objResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                objResult.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objResult, JsonRequestBehavior.AllowGet);
        }

