        [HttpPost]
        public ActionResult BindInstantExamClassWiseAnalysis(string[] ClassList)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
                ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString()
                : string.Empty;

            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF] != null)
                ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_FOR_STAFF].ToString()
                : string.Empty;

            var ObjViewModel = new ExaminationViewModel();
            var lstFullStudentList = new List<CIA_TOTAL>();

            if (!string.IsNullOrEmpty(sAcademicYear) && ClassList != null && ClassList.Length > 0)
            {
                try
                {
                    foreach (var sClassId in ClassList)
                    {
                        if (string.IsNullOrEmpty(sClassId)) continue;

                        var liCIATotal = new List<CIA_TOTAL>();
                        var liInstantStudent = new List<CIA_TOTAL>();

                        // 🔹 Regular Courses
                        var liRegularCourses = (List<EXAM_REGISTRATION>)CMS.DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(
                            new STU_CLASS() { CLASS_ID = sClassId },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchClassWiseRegularCourseList),
                            sAcademicYear).DataSource.Data;

                        // 🔹 Optional Courses
                        var liOptionalCourses = (List<EXAM_REGISTRATION>)DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(
                            new STU_CLASS() { CLASS_ID = sClassId },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchClassWiseOptionalCourseList),
                            sAcademicYear).DataSource.Data;

                        var CIA_COURSE_INFO = new CIA_FETCH_COURSE_INFO();
                        CIA_COURSE_INFO.CLASS_ID = sClassId;

                        // 🔹 Fetch CIA for Regular Courses
                        if (liRegularCourses != null && liRegularCourses.Count > 0)
                        {
                            foreach (var item in liRegularCourses)
                            {
                                CIA_COURSE_INFO.COURSE_ID = item.COURSE_ROOT_ID;

                                var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(
                                    CIA_COURSE_INFO,
                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourseCIATotal),
                                    sAcademicYear).DataSource.Data;

                                if (liCIA_Total != null && liCIA_Total.Count > 0)
                                {
                                    liCIA_Total.ForEach(o =>
                                        o.TOTAL = Math.Round(Convert.ToDecimal(
                                            (o.TOTAL ?? "0").ToUpper().Equals("A") ? "0" : o.TOTAL),
                                            MidpointRounding.AwayFromZero).ToString()
                                    );

                                    liCIATotal = liCIATotal.Concat(liCIA_Total).ToList();
                                }
                            }
                        }

                        // 🔹 Fetch Students
                        var liStudent = (List<INSTANT_STUDENT>)CMSHandler.FetchData<INSTANT_STUDENT>(
                            CIA_COURSE_INFO,
                            SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentByClassId),
                            sAcademicYear).DataSource.Data;

                        if (liStudent != null && liStudent.Count > 0 && liCIATotal != null && liCIATotal.Count > 0)
                        {
                            foreach (var item in liStudent)
                            {
                                var removeCourseIDs = new List<string>();

                                // 🔹 Handle Optional Courses
                                if (liOptionalCourses != null && liOptionalCourses.Any())
                                {
                                    var studentOptionalCourses = liOptionalCourses
                                        .Where(o => o.STUDENT_ID == item.STUDENT_ID)
                                        .ToList();

                                    if (studentOptionalCourses.Any())
                                    {
                                        foreach (var optionalCourse in studentOptionalCourses)
                                        {
                                            // ✅ Replace logic
                                            var regularCoursesToReplace = liRegularCourses
                                                .Where(reg => reg.COURSE_STRUCTURE_ID == optionalCourse.COURSE_STRUCTURE_ID &&
                                                              reg.COURSE_ROOT_ID != optionalCourse.COURSE_ROOT_ID)
                                                .ToList();

                                            if (regularCoursesToReplace.Any())
                                            {
                                                removeCourseIDs.AddRange(
                                                    regularCoursesToReplace.Select(c => c.COURSE_ROOT_ID));
                                            }

                                            // ✅ NEW: Optional course NOT in regular → fetch CIA
                                            bool isExistsInRegular = liRegularCourses
                                                .Any(reg => reg.COURSE_ROOT_ID == optionalCourse.COURSE_ROOT_ID);

                                            if (!isExistsInRegular)
                                            {
                                                CIA_COURSE_INFO.COURSE_ID = optionalCourse.COURSE_ROOT_ID;

                                                var liCIA_Total_Optional = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(
                                                    CIA_COURSE_INFO,
                                                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOptionalCourseCIATotal),
                                                    sAcademicYear).DataSource.Data;

                                                if (liCIA_Total_Optional != null && liCIA_Total_Optional.Count > 0)
                                                {
                                                    liCIA_Total_Optional.ForEach(o =>
                                                        o.TOTAL = Math.Round(Convert.ToDecimal(
                                                            (o.TOTAL ?? "0").ToUpper().Equals("A") ? "0" : o.TOTAL),
                                                            MidpointRounding.AwayFromZero).ToString()
                                                    );

                                                    liCIATotal = liCIATotal.Concat(liCIA_Total_Optional).ToList();
                                                }
                                            }
                                        }
                                    }
                                }

                                // 🔹 Remove replaced courses
                                if (removeCourseIDs.Any())
                                {
                                    liCIATotal.RemoveAll(o =>
                                        o.STUDENT_ID == item.STUDENT_ID &&
                                        removeCourseIDs.Contains(o.COURSE_ID));
                                }

                                // 🔹 Remove duplicates (important after merge)
                                liCIATotal = liCIATotal
                                    .GroupBy(x => new { x.STUDENT_ID, x.COURSE_ID })
                                    .Select(g => g.First())
                                    .ToList();

                                int nInstantMark = (item.PROGRAMME_LEVEL == "1") ? 10 : 13;

                                var liExist = liCIATotal
                                    .Where(x => x.STUDENT_ID == item.STUDENT_ID)
                                    .ToList();

                                if (liExist != null && liExist.Count > 0)
                                {
                                    var liInstant = liExist
                                        .Where(x => Convert.ToInt32(x.TOTAL) < nInstantMark)
                                        .ToList();

                                    if (liInstant != null && liInstant.Count > 0)
                                    {
                                        var licheckount = liInstant.GroupBy(o => o.COURSE_ID).ToList();

                                        if (licheckount.Count == 1)
                                        {
                                            liInstantStudent = liInstantStudent.Any()
                                                ? liInstantStudent.Concat(liInstant).ToList()
                                                : liInstant;
                                        }
                                    }
                                }
                            }
                        }

                        // 🔹 Add to final list
                        if (liInstantStudent != null && liInstantStudent.Any())
                        {
                            lstFullStudentList.AddRange(liInstantStudent);
                        }
                    }

                    ObjViewModel.liCIA_Total = lstFullStudentList;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindInstantExamClassWiseAnalysis", ex.Message);
                    }
                }
            }
            else
            {
                ObjViewModel.liCIA_Total = lstFullStudentList;
            }

            return PartialView("_BindInstantExamClassWiseAnalysis", ObjViewModel);
        }
        #endregion

        #region CIA Cumulative Upload Copy For SJC
