        public ActionResult BindCIACumulativeForSJC(string sAcYear, string sClassId, string sSemesterTypeId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            var liCIATotal = new List<CIA_TOTAL>();

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    string sSemesterId = string.Empty;
                    if (sSemesterTypeId == "1")
                    {
                        sSemesterId = "1,3,5";
                    }
                    else if (sSemesterTypeId == "2")
                    {
                        sSemesterId = "2,4,6";
                    }
                    else if (sSemesterTypeId == "3")
                    {
                        sSemesterId = "1";
                    }
                    var ObjModel = new CourseWiseStaffList();
                    ObjModel.CLASS_ID = sClassId;
                    ObjModel.SEMESTER_TYPE_ID = sSemesterTypeId;
                    ObjModel.SEMESTER_ID = sSemesterId;
                    ObjViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                    // Fetch Courses From Course Pattern .
                    string sSQL = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseByClassIdAndSemesterId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId);
                    var liCourseInfo = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL, sAcYear).DataSource.Data;
                    liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(ObjModel,
                                     ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindOptionalCourseCIAMarksForCOESJC), sAcYear).DataSource.Data;
                    if (liCIATotal != null && liCIATotal.Count > 0)
                    {
                        var liCourse = new List<CourseInfo>();
                        liCourse.Add(new CourseInfo() { COURSE_ROOT_ID = liCIATotal.FirstOrDefault().COURSE_ID, COURSE_CODE = liCIATotal.FirstOrDefault().COURSE_CODE });
                        ObjViewModel.liCourseInfo = liCourse;
                        liCIATotal.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                        ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                    }

                    if (liCourseInfo != null && liCourseInfo.Count > 0)
                    {
                        //liCourseInfo.RemoveAll(x => x.UGC_COURSE_TYPE == "17");
                        //liCourseInfo.RemoveAll(x => x.COURSE_ROOT_ID!="369" && x.COURSE_ROOT_ID!="423" && x.COURSE_ROOT_ID != "83");
                        ObjViewModel.liCourseInfo = liCourseInfo;
                        foreach (var item in liCourseInfo)
                        {
                            ObjModel.COURSE_ID = item.COURSE_ROOT_ID;

                            liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(ObjModel,
                                ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindCIAMarksForCOESJC), sAcYear).DataSource.Data;
                            if (liCIATotal != null && liCIATotal.Count > 0)
                            {
                                liCIATotal.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "ListCIACumulativeCopy", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }
