                    // Fetch Student Payment Details .
                    var liFetchFeeDetails = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(ObjModel,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFeeTransaction), sAcademicYear).DataSource.Data;
                    bool bFlag = true;
                    if (liFetchFeeDetails != null && liFetchFeeDetails.Count > 0)
                    {
                        foreach (var item in liFetchFeeDetails)
                        {
                            if (item.BALANCE != "0")
