        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sExamId) && !string.IsNullOrEmpty(sCourseId))
            {
                ResultArgs Resultarg = new ResultArgs();
                Random random = new Random();
                int questionpatterntotal = 0;
                int questionsectiontotal = 0;
                double actualtoquestionpattren = 0;
                double questionsectionpercentage = 0;
                double assign = 0;
                // double agn = 0;
                double i = 0;

                try
                {
                    //Fetch Exam 
                    var Examdetails = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchExamdetails)).DataSource.Data;
                    //Fetch Semster marks
                    var Semstermark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(new SEMESTER_MARKS() { EXAM_SETTING_ID = sExamId, COURSE_ID = sCourseId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemsterMarksByExamIdandCourseId)).DataSource.Data;
                    var groupedcourse = Semstermark.GroupBy(o => o.COURSE_ID).ToList();
                    if (groupedcourse != null && groupedcourse.Count > 0)
                    {
                        foreach (var course in groupedcourse)
                        {
                            var studentmark = Semstermark.Where(o => o.COURSE_ID == course.FirstOrDefault().COURSE_ID).ToList();
                            if (studentmark != null && studentmark.Count > 0)
                            {
                                foreach (var mark in studentmark)
                                {
                                    //Fetch Question Structure
                                    var QuestionStructure = (List<OBE_QUESTION_STRUCTURE>)CMSHandler.FetchData<OBE_QUESTION_STRUCTURE>(new OBE_QUESTION_STRUCTURE() { APPLICATION_TYPE_ID = mark.PROGRAMME_LEVEL_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuestionStructureByAppId)).DataSource.Data;
                                    if (QuestionStructure != null && QuestionStructure.Count > 0)
                                    {
                                        foreach (var item in QuestionStructure)
                                        {
                                            questionpatterntotal += Convert.ToInt32(item.QUESTION_NO) * Convert.ToInt32(item.MARK_PER_QUESTION);
                                        }
                                    }
                                    actualtoquestionpattren = (double)questionpatterntotal * ((double)Convert.ToInt32(mark.EXTERNAL_MARK) / (double)Convert.ToInt32(mark.EXTERNAL));
                                    //Fetch Questions 
                                    var Questions = (List<OBE_QUESTIONS>)CMSHandler.FetchData<OBE_QUESTIONS>(new OBE_QUESTIONS() { EXAM_ID = mark.EXAM_SETTING_ID, COURSE_ID = mark.COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuestionsByExamIdandCourseId)).DataSource.Data;
                                    if (Questions != null && Questions.Count > 0)
                                    {
                                        var groupedsection = Questions.GroupBy(o => o.QUESTION_STRUCTURE_ID).ToList();
                                        if (groupedsection != null && groupedsection.Count > 0)
                                        {
                                            foreach (var question in groupedsection)
                                            {

                                                var questionstructure = QuestionStructure.Where(o => o.QUESTION_STRUCTURE_ID == question.FirstOrDefault().QUESTION_STRUCTURE_ID).ToList();
                                                if (questionstructure != null && questionstructure.Count > 0)
                                                {
                                                    questionsectiontotal = Convert.ToInt32(questionstructure.FirstOrDefault().QUESTION_NO) * Convert.ToInt32(questionstructure.FirstOrDefault().MARK_PER_QUESTION);
                                                    questionsectionpercentage = actualtoquestionpattren / questionpatterntotal * questionsectiontotal;

                                                    var sectionquestion = Questions.Where(o => o.QUESTION_STRUCTURE_ID == question.FirstOrDefault().QUESTION_STRUCTURE_ID).ToList();
                                                    if (sectionquestion != null && sectionquestion.Count > 0)
                                                    {
                                                        while (i < questionsectionpercentage)
                                                        {
                                                            var randomvalue = sectionquestion[random.Next(sectionquestion.Count)];
                                                            //if ((int)i == (int)questionsectionpercentage)
                                                            //{
                                                            //    assign = (double)questionsectionpercentage - (double)i;
                                                            //    i = (double)i + (double)assign;

                                                            //    Resultarg = CMSHandler.SaveOrUpdate(new OBE_SCORESHEET() { QUESTION_STRUCTRE_ID = questionstructure.FirstOrDefault().QUESTION_STRUCTURE_ID, QUESTION_ID = randomvalue.QUESTION_ID, COURSE_ID = course.FirstOrDefault().COURSE_ID, STUDENT_ID = mark.STUDENT_ID, MARK = assign.ToString(), ACTUAL_MARK = mark.EXTERNAL_MARK, EXAM_SETTING_ID = sExamId, ACADEMIC_YEAR = sAcademicYear }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOBEScoreSheet));
                                                            //    sectionquestion.RemoveAll(o => o.QUESTION_ID == randomvalue.QUESTION_ID);

                                                            //}
                                                            //else 
                                                            if ((double)i + (double)Convert.ToInt32(questionstructure.FirstOrDefault().MARK_PER_QUESTION) > (double)questionsectionpercentage)
                                                            {
                                                                assign = (double)questionsectionpercentage - (double)i;
                                                                i += Convert.ToInt32(questionstructure.FirstOrDefault().MARK_PER_QUESTION);
                                                                Resultarg = CMSHandler.SaveOrUpdate(new OBE_SCORESHEET() { QUESTION_STRUCTRE_ID = questionstructure.FirstOrDefault().QUESTION_STRUCTURE_ID, QUESTION_ID = randomvalue.QUESTION_ID, COURSE_ID = course.FirstOrDefault().COURSE_ID, STUDENT_ID = mark.STUDENT_ID, MARK = assign.ToString(), ACTUAL_MARK = mark.EXTERNAL_MARK, EXAM_SETTING_ID = sExamId, ACADEMIC_YEAR = sAcademicYear }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOBEScoreSheet));
                                                                sectionquestion.RemoveAll(o => o.QUESTION_ID == randomvalue.QUESTION_ID);
                                                            }
                                                            else
                                                            {
                                                                i += Convert.ToInt32(questionstructure.FirstOrDefault().MARK_PER_QUESTION);
                                                                Resultarg = CMSHandler.SaveOrUpdate(new OBE_SCORESHEET() { QUESTION_STRUCTRE_ID = questionstructure.FirstOrDefault().QUESTION_STRUCTURE_ID, QUESTION_ID = randomvalue.QUESTION_ID, COURSE_ID = course.FirstOrDefault().COURSE_ID, STUDENT_ID = mark.STUDENT_ID, MARK = questionstructure.FirstOrDefault().MARK_PER_QUESTION, ACTUAL_MARK = mark.EXTERNAL_MARK, EXAM_SETTING_ID = sExamId, ACADEMIC_YEAR = sAcademicYear }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOBEScoreSheet));
                                                                sectionquestion.RemoveAll(o => o.QUESTION_ID == randomvalue.QUESTION_ID);
                                                            }

                                                        }
                                                        i = 0;
                                                        assign = 0;
                                                    }
                                                }
                                                questionsectiontotal = 0;
                                                questionsectionpercentage = 0;
                                            }



                                        }
                                    }
                                    questionpatterntotal = 0;
                                    actualtoquestionpattren = 0;
                                }
                            }

                        }


                    }

                }
                catch (Exception ex)
                {

                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "GenerateOBEScoreSheet", ex.Message);
                    }
                }
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);

        }
