                                liquestionlevel.Add(new OBE_SCORESHEET() { QUESTION_LEVEL_ID = item.FirstOrDefault().QUESTION_LEVEL_ID, QUESTION_LEVEL = item.FirstOrDefault().QUESTION_LEVEL, COURSE_ID = item.FirstOrDefault().COURSE_ID });

                            }
                        }
                        ObjData = new OBE_OBJECT()
                        {
                            liQuestionlevel = liquestionlevel,
                            liOBECourese = licourse,
                            liStudentMark = Scorelist
