            {
                try
                {
                    var Studentmarks = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(new SEMESTER_MARKS() { ACADEMIC_YEAR = sAcademicYear, CLASS_ID = sClassId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClassWiseStudentsMarks), sAcademicYear).DataSource.Data;
                    if (Studentmarks != null && Studentmarks.Count > 0)
                    {
                        var groupedsemster = Studentmarks.GroupBy(o => o.SEMESTER).ToList();
                        foreach (var item in groupedsemster)
                        {
                            var semstermarks = Studentmarks.Where(o => o.SEMESTER == item.FirstOrDefault().SEMESTER).ToList();
                            var totalstu = semstermarks.GroupBy(o => o.STUDENT_ID).ToList();
                            totalstudent = totalstu.Count();
                            var Failstudent = semstermarks.Where(o => o.RESULT == "F").ToList();
                            foreach (var mark in Failstudent)
                            {
                                semstermarks.RemoveAll(o => o.STUDENT_ID == mark.STUDENT_ID);
                            }
                            passedstudent = semstermarks.GroupBy(o => o.STUDENT_ID).Count();
                            listudentmark.Add(new OBE_SCORESHEET() { TOTAL_REGISTER = totalstudent.ToString(), PASSED = passedstudent.ToString(), SEMSTER = item.FirstOrDefault().SEMESTER, SEMSTER_NAME = item.FirstOrDefault().SEMESTER_NAME, CLASS_NAME = item.FirstOrDefault().CLASS_NAME });

                        }
                        ObjData = new OBE_OBJECT()
                        {


                            liStudentMark = listudentmark.OrderBy(o => o.SEMSTER).ToList()
                        };
                    }

                }
                catch (Exception ex)
                {

                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "ChartDataforClasswise", ex.Message);
                    }
                }
            }
            return Json(ObjData, JsonRequestBehavior.AllowGet);
        }
