        public JsonResult SaveExamSetting(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<EXAM_SETTING>(sJsonData);
                    Result.START_DATE = CommonMethods.ConvertdatetoyearFromat(Result.START_DATE);
                    Result.END_DATE = CommonMethods.ConvertdatetoyearFromat(Result.END_DATE);
                    Result.LAST_DATE_FOR_EXAM_FEE = CommonMethods.ConvertdatetoyearFromat(Result.LAST_DATE_FOR_EXAM_FEE);
                    Result.HALL_TICKET_PUBLICATION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.HALL_TICKET_PUBLICATION_DATE);

                    // Result.STAFF_ID = sUserId;

                    if (!string.IsNullOrEmpty(Result.EXAM_SETTING_ID))
                    {
                        // update ..
                        var sUpdateSetting = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamSetting), sAcademicYear);
                        ObjJsonData.Message = (sUpdateSetting.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                        ObjJsonData.ErrorCode = (sUpdateSetting.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;
                    }
                    else
                    {
                        // insert ...
                        var sSaveSetting = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertExamSetting), sAcademicYear);
                        ObjJsonData.Message = (sSaveSetting.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        ObjJsonData.ErrorCode = (sSaveSetting.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;

                        //var IsExist = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(Result,
                        //    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsExamSettingExist), sAcademicYear).DataSource.Data;
                        //if (IsExist != null && IsExist.Count > 0)
                        //{
                        //    ObjJsonData.Message = "Sorry ! Record Already Exist !";
                        //    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        //}
                        //else
                        //{

                        //}
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveOnlineExamSetting", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

