        public ActionResult CourseApproval(string sCourseApprovalId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new CourseRootModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    ObjViewModel.sCourseApprovalId = sCourseApprovalId;
                    var liDepartment = (List<cp_Department_2017>)CMSHandler.FetchData<cp_Department_2017>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchDepartment), sAcademicYear).DataSource.Data;
                    if (liDepartment != null && liDepartment.Count > 0)
                    {
                        ObjViewModel.DEPARTMENT = new SelectList(liDepartment, Common.SUP_DEPARTMENT.DEPARTMENT_ID, Common.SUP_DEPARTMENT.DEPARTMENT);
                    }

                    var liPart = (List<SUP_PART>)CMSHandler.FetchData<SUP_PART>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchPart)).DataSource.Data;
                    if (liPart != null && liPart.Count > 0)
                    {
                        ObjViewModel.PART = new SelectList(liPart, Common.SUP_PART.PART_ID, Common.SUP_PART.PART);
                    }

                    var liCourseType = (List<CourseTypeInfo>)CMSHandler.FetchData<CourseTypeInfo>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseType), sAcademicYear).DataSource.Data; //SupportDataMethod.FetchCourseItems((Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "").DataSource.Table;
                    if (liCourseType != null && liCourseType.Count > 0)
                    {
                        ObjViewModel.COURSE_TYPE = new SelectList(liCourseType, Common.CP_COURSE_TYPE_2017.COURSE_TYPE_ID, Common.CP_COURSE_TYPE_2017.COURSE_TYPE);
                    }

                    var liSemester = (List<SupSemester>)CMSHandler.FetchData<SupSemester>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSemester)).DataSource.Data; //SupportDataMethod.FetchSemester().DataSource.Table;
                    if (liSemester != null && liSemester.Count > 0)
                    {
                        ObjViewModel.SEMESTER = new SelectList(liSemester, Common.SUP_SEMESTER.SUP_SEMESTER_ID, Common.SUP_SEMESTER.SEMESTER_NAME);
                    }

                    var liUGCCourseType = (List<CP_UGC_COURSE_TYPE>)CMSHandler.FetchData<CP_UGC_COURSE_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchUGCCoursetype)).DataSource.Data;//SupportDataMethod.FetchUGCCoursetype().DataSource.Table;
                    if (liUGCCourseType != null && liUGCCourseType.Count > 0)
                    {
                        ObjViewModel.UGC_COURSE_TYPE = new SelectList(liUGCCourseType, Common.CP_UGC_COURSE_TYPE.UGC_COURSE_TYPE_ID, Common.CP_UGC_COURSE_TYPE.UGC_COURSE_TYPE);
                    }

                    var liPaperType = (List<SupPaperType>)CMSHandler.FetchData<SupPaperType>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupPaperType)).DataSource.Data;//SupportDataMethod.FetchPaperType().DataSource.Table;
                    if (liPaperType != null && liPaperType.Count > 0)
                    {
                        ObjViewModel.PAPER_TYPE = new SelectList(liPaperType, Common.SUP_PAPER_TYPE.PAPER_TYPE_ID, Common.SUP_PAPER_TYPE.PAPER_TYPE);
                    }

                    var liSubjectType = (List<SUP_SUBJECT_TYPE>)CMSHandler.FetchData<SUP_SUBJECT_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupSubjectType)).DataSource.Data; //SupportDataMethod.FetchSubjectType().DataSource.Table;
                    if (liSubjectType != null && liSubjectType.Count > 0)
                    {
                        ObjViewModel.SUBJECT_TYPE = new SelectList(liSubjectType, Common.SUP_SUBJECT_TYPE.SUBJECT_TYPE_ID, Common.SUP_SUBJECT_TYPE.SUBJECT_TYPE);
                    }

                    var liProgrammeLevel = (List<SUP_PROGRAMME_LEVEL>)CMSHandler.FetchData<SUP_PROGRAMME_LEVEL>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchProgrammeLevel)).DataSource.Data; //SupportDataMethod.FetchSubjectType().DataSource.Table;
                    if (liProgrammeLevel != null && liProgrammeLevel.Count > 0)
                    {
                        ObjViewModel.sProgrammeLevel = new SelectList(liProgrammeLevel, Common.SUP_PROGRAMME_LEVEL.PROGRAMME_LEVEL_ID, Common.SUP_PROGRAMME_LEVEL.PROGRAMME_LEVEL);
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "CourseApproval", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

