        public JsonResult FetchExamDate(string sExamId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();

            string sOption = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingBySettingId), sAcademicYear).DataSource.Data;
                    if (ExamSetting != null && ExamSetting.Count > 0)
                    {
                        // Fetch Exam timetable .                      
                        var liexamdate = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchTimetableByExamId), sAcademicYear).DataSource.Data;
                        var groupdate = liexamdate.GroupBy(o => o.EXAM_DATE).ToList();
                        if (groupdate != null && groupdate.Count > 0)
                        {
                            foreach (var item in groupdate)
                            {
                                sOption += "<option value=" + item.FirstOrDefault().EXAM_DATE + ">" + item.FirstOrDefault().EXAM_TIME + "</option>";
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "FetchExamDate", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.SessionOut;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return Json(sOption, JsonRequestBehavior.AllowGet);
        }
