                                foreach (var itemCurSession in CurrentSession)
                                {
                                    var SelectUGCTYPE = Coursepattern.Where(s => s.PROGRAMME_LEVEL == itemCurSession.PROGRAMME_LEVEL && s.PROGRAMME_YEAR == itemCurSession.PROGRAMME_YEAR).ToList();
                                    //based on the ugc order, add finished as item

