        public List<EXAM_TT_SETTING> FindProgrammeGroupForTT()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            List<EXAM_TT_SETTING> TTProgrammeGroup = new List<EXAM_TT_SETTING>();
            string s = string.Empty;
            int J = 0;

            var PrgrammeStudentCount = (List<EXAM_TT_SETTING>)CMSHandler.FetchData<EXAM_TT_SETTING>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentCountbyProgrammeLevel), sAcademicYear).DataSource.Data;
            var SeatingsCount = (List<EXAM_SEATINGS>)CMSHandler.FetchData<EXAM_SEATINGS>(new EXAM_SEATINGS { EXAM_TYPE = Common.SupExamType.External }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchExamSeatingsList), sAcademicYear).DataSource.Data;
            int TodayCounts = 0;
            var ExamSession = (List<SUP_EXAM_SESSION>)CMSHandler.FetchData<SUP_EXAM_SESSION>(new EXAM_SETTING { EXAM_TYPE = Common.SupExamType.External }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSessionByExamtype), sAcademicYear).DataSource.Data;
            // to assign the Session for the programmeYear
            for (int i = 1; i <= 4; i++)
            {
                if (true)
                {
                    string Element = ExamSession.ElementAt(J).EXAM_SESSION_ID.ToString();
                    PrgrammeStudentCount.Where(o => o.PROGRAMME_YEAR == i.ToString()).ToList().ForEach(cc => cc.SESSION = Element);
                    J++;
                    if ((ExamSession.Count) == J)
                    {
                        J = 0;
                    }
                    continue;
                }
            }
            var AllAcademicYearList = (List<SUP_ACADEMIC_YEAR_LIST>)CMSHandler.FetchData<SUP_ACADEMIC_YEAR_LIST>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList), sAcademicYear).DataSource.Data;
            AllAcademicYearList.OrderBy(O => Convert.ToInt32(O.AC_YEAR));
            string sq1 = string.Empty;
            string sq2 = string.Empty;
            string sUnion = "UNION ALL ";
            string SFinalQuery = string.Empty;
            string sEndQuery = string.Empty;
            foreach (var AcYearlist in AllAcademicYearList)
            {
                if (Convert.ToInt32(AcYearlist.AC_YEAR) <= Convert.ToInt32(sAcademicYear) && Convert.ToInt32(AcYearlist.AC_YEAR) >= 2015)
                {
                    if (!string.IsNullOrEmpty(sq1))
                    {
                        sq1 += sUnion + ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFailQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    else
                    {
                        sq1 = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFailQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    if (!string.IsNullOrEmpty(sq2))
                    {
                        sq2 += sUnion + ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchPassQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    else
                    {
                        sq2 = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchPassQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                }

            }
            sEndQuery = @" ON T1.STUDENT_ID = T2.STUDENT_ID
                                AND T1.COURSE_ID = T2.COURSE_ID
                            WHERE
                                T2.SEMESTER_MARK_ID IS NULL) AS T3
                            GROUP BY COURSE_ID) AS T4
                                INNER JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = T4.COURSE_ID
                                INNER JOIN
                            CP_COURSE_PATTERN AS CP ON CP.COURSE_ID = T4.COURSE_ID
                                AND CP.ACADEMIC_YEAR = ?AC_YEAR
                                INNER JOIN
                            cp_course_structure AS CS ON CS.COURSE_STRUCTURE_ID = CP.COURSE_STRUCTURE_ID
                                AND CS.PROGRAMME_LEVEL = ?PROGRAMME_LEVEL
                                AND CS.PROGRAMME_YEAR = ?PROGRAMME_YEAR
                        GROUP BY T4.COURSE_ID;";
            SFinalQuery = @"SELECT 
                    T4.COUNTS AS STUDENT_COUNT,
                    T4.COURSE_ID,
                    CS.PROGRAMME_LEVEL,
                    CS.PROGRAMME_YEAR
                   -- CP.COURSE_ORDER
                FROM
                    (SELECT 
                        T3.SEMESTER_MARK_ID,
                            COUNT(T3.STUDENT_ID) AS COUNTS,
                            T3.COURSE_ID,
                            T3.RESULT,
                            T3.M_PASS
                    FROM
                        (SELECT 
                        T1.SEMESTER_MARK_ID,
                            T1.STUDENT_ID,
                            T1.COURSE_ID,
                            T1.RESULT,
                            T1.M_PASS
                    FROM
                        ( " + sq1 + ")  AS T1 LEFT JOIN (" + sq2 + ") AS T2 " + sEndQuery;

            foreach (var item in PrgrammeStudentCount)
            {
                var FethArrierStudents = (List<EXAM_TT_SETTING>)CMSHandler.FetchData<EXAM_TT_SETTING>(new EXAM_TT_SETTING { PROGRAMME_LEVEL = item.PROGRAMME_LEVEL, PROGRAMME_YEAR = item.PROGRAMME_YEAR }, SFinalQuery, sAcademicYear).DataSource.Data;
                if (FethArrierStudents != null && FethArrierStudents.Count > 0)
                {
                    FethArrierStudents.OrderByDescending(o => o.STUDENT_COUNT);
                    int ArrierStudents = Convert.ToInt16(FethArrierStudents.FirstOrDefault().STUDENT_COUNT);
                    var result = (SeatingsCount.Count >= ArrierStudents + TodayCounts) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                }
            }

            TTProgrammeGroup = PrgrammeStudentCount;
            return TTProgrammeGroup;
        }
        // FIND SUNDAY
        private DateTime FindSunday(DateTime date)
        {
            DayOfWeek DAY = date.DayOfWeek;
            if (DAY == DayOfWeek.Sunday)
            {
                date = date.AddDays(1);
            }
            return date;
        }
        private int FindDiffrenceDates(DateTime Date1, DateTime Date2)
        {
            int Intervaldays = Convert.ToInt16((Date1 - Date2).TotalDays);
            return Intervaldays;
        }
        public string ExamTTDateValidations(string sExamSession, string sExamSetting, string sProgrammeYear, string sProgrammeLevel)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sExamDate = string.Empty;
            string ExamDate = string.Empty;
            var ExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingByAcitveId), sAcademicYear).DataSource.Data;
            DateTime Date = new DateTime();
            DateTime dExamDate = new DateTime();

            var FetchSemesterByProgrammeLevelAndYear = (List<ACADEMIC_SEMESTER>)CMSHandler.FetchData<ACADEMIC_SEMESTER>(new ACADEMIC_SEMESTER { PROGRAMME_LEVEL = sProgrammeLevel, BATCH_YEAR = sProgrammeYear }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterByProgrammeLevelAndYear), sAcademicYear).DataSource.Data;
            string semsters = string.Join(",", FetchSemesterByProgrammeLevelAndYear.Select(o => o.SEMESTER));
            var CheckExamExisit = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE { PROGRAMME_LEVEL_ID = sProgrammeLevel, EXAM_SETTING_ID = sExamSetting, SEMESTER_ID = semsters }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckExamTTProgrammeLevelExist), sAcademicYear).DataSource.Data;
            var TTSetting = (List<EXAM_TT_SETTING>)CMSHandler.FetchData<EXAM_TT_SETTING>(new EXAM_TT_SETTING { EXAM_SETTING_ID = sExamSetting }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamTTSettingByExamSettingId), sAcademicYear).DataSource.Data;
            var ExamSession = (List<SUP_EXAM_SESSION>)CMSHandler.FetchData<SUP_EXAM_SESSION>(new SUP_EXAM_SESSION { EXAM_TYPE = Common.SupExamType.External }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSessionByExamtype), sAcademicYear).DataSource.Data;
            int TTInterval = Convert.ToInt16(TTSetting.FirstOrDefault().TT_INTERVAL_DAYS);
            if (CheckExamExisit != null && CheckExamExisit.Count > 0)
            {
                Date = DateTime.ParseExact(CommonMethods.ConvertdatetoyearFromat(CheckExamExisit.FirstOrDefault().EXAM_DATE), "yyyy-MM-dd", CultureInfo.InvariantCulture);
                dExamDate = DateTime.ParseExact(CommonMethods.ConvertdatetoyearFromat(CheckExamExisit.FirstOrDefault().EXAM_DATE), "yyyy-MM-dd", CultureInfo.InvariantCulture);
                Date = Date.AddDays(1);
                dExamDate = dExamDate.AddDays(1);
            }
            else
            {
                Date = DateTime.ParseExact(CommonMethods.ConvertdatetoyearFromat(ExamSetting.FirstOrDefault().START_DATE), "yyyy-MM-dd", CultureInfo.InvariantCulture);
                dExamDate = DateTime.ParseExact(CommonMethods.ConvertdatetoyearFromat(ExamSetting.FirstOrDefault().START_DATE), "yyyy-MM-dd", CultureInfo.InvariantCulture);
            }
            if (TTInterval > 0)
            {
                while (FindDiffrenceDates(Date, dExamDate) < TTInterval)
                {
                    Date = Date.AddDays(1);
                    FindDiffrenceDates(Date, dExamDate);
                }
            }
            Date = FindSunday(Date);
            var ExamExceptionDate = (List<EXAM_TT_LEAVE>)CMSHandler.FetchData<EXAM_TT_LEAVE>(new EXAM_TT_LEAVE { EXAM_SETTING_ID = sExamSetting }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamTTLeaveBySettingid), sAcademicYear).DataSource.Data;
            if (ExamExceptionDate != null && ExamExceptionDate.Count > 0)
            {
                var LeaveTrue = ExamExceptionDate.Where(o => o.LEAVE_DATE == Date.ToString("dd/MM/yyyy")).ToList();
                while (LeaveTrue != null && LeaveTrue.Count > 0)
                {
                    Date = Date.AddDays(1);
                    LeaveTrue = ExamExceptionDate.Where(o => o.LEAVE_DATE == Date.ToString("dd/MM/yyyy")).ToList();
                }
                Date = FindSunday(Date);
            }
            ExamDate = Date.ToString("yyyy/MM/dd");
            return ExamDate;
        }
        public bool InsertTT(List<CP_COURSE_PATTERN> Course, string sExamDate, string sExamSession, string sExamSetting)
        {
            bool Result = false;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sSql = string.Empty;
            string CheckSql = string.Empty;
            sSql = @"INSERT INTO EXAM_TIMETABLE(EXAM_DATE, EXAM_TIME, COURSE_ID, COURSE_CODE, ACADEMIC_YEAR,EXAM_SETTING_ID, EXAM_SESSION_ID, IS_ACTIVE) VALUES";
            CheckSql = sSql;
            foreach (var Vcourses in Course)
            {
                sSql += "('" + sExamDate + "','" + sExamSession + "'," + Vcourses.COURSE_ID + ",'" + Vcourses.COURSE_CODE + "'," + sAcademicYear + "," + sExamSetting + "," + sExamSession + ",'1'),";
            }
            if (CheckSql != sSql)
            {
                sSql = sSql.Trim(',') + ";";
                var sresultArgs = CMSHandler.SaveOrUpdate(null, sSql);
                Result = (sresultArgs.Success) ? true : false;
            }
            return Result;
        }
        private string GetArriearQuery()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sActiveSemester = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var PrgrammeStudentCount = (List<EXAM_TT_SETTING>)CMSHandler.FetchData<EXAM_TT_SETTING>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentCountbyProgrammeLevel), sAcademicYear).DataSource.Data;
            var AllAcademicYearList = (List<SUP_ACADEMIC_YEAR_LIST>)CMSHandler.FetchData<SUP_ACADEMIC_YEAR_LIST>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList), sAcademicYear).DataSource.Data;
            AllAcademicYearList.OrderBy(O => Convert.ToInt32(O.AC_YEAR));
            string sq1 = string.Empty;
            string sq2 = string.Empty;
            string sUnion = "UNION ALL ";
            string SFinalQuery = string.Empty;
            string sEndQuery = string.Empty;
            foreach (var AcYearlist in AllAcademicYearList)
            {
                if (Convert.ToInt32(AcYearlist.AC_YEAR) <= Convert.ToInt32(sAcademicYear) && Convert.ToInt32(AcYearlist.AC_YEAR) >= 2015)
                {
                    if (!string.IsNullOrEmpty(sq1))
                    {
                        sq1 += sUnion + ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFailQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    else
                    {
                        sq1 = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFailQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    if (!string.IsNullOrEmpty(sq2))
                    {
                        sq2 += sUnion + ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchPassQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                    else
                    {
                        sq2 = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchPassQueryConstruction1).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sActiveSemester).Replace(Common.Delimiter.QUS + Common.ACADEMIC_YEAR.AC_YEAR, AcYearlist.AC_YEAR);
                    }
                }

            }
            sEndQuery = @" ON T1.STUDENT_ID = T2.STUDENT_ID
                                AND T1.COURSE_ID = T2.COURSE_ID
                            WHERE
                                T2.SEMESTER_MARK_ID IS NULL) AS T3
                            GROUP BY COURSE_ID) AS T4
                                INNER JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = T4.COURSE_ID
                                INNER JOIN
                            CP_COURSE_PATTERN AS CP ON CP.COURSE_ID = T4.COURSE_ID
                                AND CP.ACADEMIC_YEAR = ?AC_YEAR
                                INNER JOIN
                            cp_course_structure AS CS ON CS.COURSE_STRUCTURE_ID = CP.COURSE_STRUCTURE_ID
                                AND CS.PROGRAMME_LEVEL = ?PROGRAMME_LEVEL
                                AND CS.PROGRAMME_YEAR = ?PROGRAMME_YEAR
                        GROUP BY T4.COURSE_ID;";
            SFinalQuery = @"SELECT 
                    T4.COUNTS AS STUDENT_COUNT,
                    T4.COURSE_ID,
                    T4.COURSE_CODE,
                    CS.PROGRAMME_LEVEL,
                    CS.PROGRAMME_YEAR
                   -- CP.COURSE_ORDER
                FROM
                    (SELECT 
                        T3.SEMESTER_MARK_ID,
                            COUNT(T3.STUDENT_ID) AS COUNTS,
                            T3.COURSE_ID,
                            T3.COURSE_CODE,
                            T3.RESULT,
                            T3.M_PASS
                    FROM
                        (SELECT 
                        T1.SEMESTER_MARK_ID,
                            T1.STUDENT_ID,
                            T1.COURSE_ID,
                            T1.COURSE_CODE,
                            T1.RESULT,
                            T1.M_PASS
                    FROM
                        ( " + sq1 + ")  AS T1 LEFT JOIN (" + sq2 + ") AS T2 " + sEndQuery;

            return SFinalQuery;
        }

