        public JsonResult ManageBunles()
        {
            int Pocketno = 0;
            double EXPocketCount = 0;

            string sQuery1 = string.Empty;
            string sQuery2 = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingByAcitveId), sAcademicYear).DataSource.Data;
                    Pocketno = Convert.ToInt16(20);
                    var ExamTTCourse = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamTTCourseByActiveExamSetting), sAcademicYear).DataSource.Data;
                    if (ExamTTCourse != null && ExamTTCourse.Count > 0)
                    {
                        foreach (var item in ExamTTCourse)
                        {
                            var StudentListRegular = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new EXAM_TIMETABLE() { COURSE_ID = item.COURSE_ID, EXAM_SETTING_ID = ExamSetting.FirstOrDefault().EXAM_SETTING_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchRegularExamStudentByCourseIdForBundling), sAcademicYear).DataSource.Data;
                            var StudentListArrear = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new EXAM_TIMETABLE() { COURSE_ID = item.COURSE_ID, EXAM_SETTING_ID = ExamSetting.FirstOrDefault().EXAM_SETTING_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearExamStudentByCourseIdForBundling), sAcademicYear).DataSource.Data;
                            if (StudentListRegular != null && StudentListRegular.Count > 0)
                            {
                                int RunnigCount = 0;
                                sQuery1 = @"INSERT INTO EXAM_BUNDLE_STUDENTS (BUNDLE_ID, STUDENT_ID, DUMMY_NO, ACADEMIC_YEAR) VALUES";
                                double totalPockets = Math.Round(StudentListRegular.Count() / Convert.ToDouble(Pocketno));
                                for (int i = 1; i <= totalPockets; i++)
                                {
                                    EXPocketCount = EXPocketCount + 1;
                                    sQuery2 = @"INSERT INTO EXAM_BUNDLES (EXAM_BUNDLE_NO, POCKET_NO, POCKET_CATEGORY, COURSE_ID, IS_ARREAR, EXAM_SETTING_ID, ACADEMIC_YEAR) VALUES ('" + item.COURSE_CODE + "',LPAD(" + EXPocketCount + ",5,0),'R" + i + "'," + item.COURSE_ID + ",0," + ExamSetting.FirstOrDefault().EXAM_SETTING_ID + ",?AC_YEAR)";
                                    resultArgs = CMSHandler.SaveOrUpdate(null, sQuery2, sAcademicYear, true);
                                    string Bundle_id = resultArgs.RowUniqueId.ToString();
                                    var StudentLists = StudentListRegular.Skip(RunnigCount).Take(Pocketno).ToList();
                                    RunnigCount = RunnigCount + StudentLists.Count();
                                    if (StudentLists != null && StudentLists.Count > 0)
                                    {
                                        int counts = 0;
                                        foreach (var Stitem in StudentLists)
                                        {
                                            counts++;
                                            sQuery1 += "(" + Bundle_id + "," + Stitem.STUDENT_ID + ",LPAD(" + counts + ",2,0)," + sAcademicYear + "),";
                                        }
                                    }
                                }
                                using (MySQLHandler objHandler = new MySQLHandler())
                                {
                                    sQuery1 = sQuery1.TrimEnd(',');
                                    sQuery1 = sQuery1 + ";";
                                    resultArgs = objHandler.ExecuteAsScripts(sQuery1);
                                }
                            }
                            if (StudentListArrear != null && StudentListArrear.Count > 0)
                            {
                                int RunnigCount = 0;
                                sQuery1 = @"INSERT INTO EXAM_BUNDLE_STUDENTS (BUNDLE_ID, STUDENT_ID, DUMMY_NO, ACADEMIC_YEAR) VALUES";
                                double totalPockets = Math.Round(StudentListArrear.Count() / Convert.ToDouble(Pocketno));
                                for (int i = 1; i <= totalPockets; i++)
                                {
                                    EXPocketCount = EXPocketCount + 1;
                                    sQuery2 = @"INSERT INTO EXAM_BUNDLES (EXAM_BUNDLE_NO, POCKET_NO, POCKET_CATEGORY, COURSE_ID, IS_ARREAR, EXAM_SETTING_ID, ACADEMIC_YEAR) VALUES ('" + item.COURSE_CODE + "',LPAD(" + EXPocketCount + ",5,0),'A" + i + "'," + item.COURSE_ID + ",1," + ExamSetting.FirstOrDefault().EXAM_SETTING_ID + ",?AC_YEAR)";
                                    resultArgs = CMSHandler.SaveOrUpdate(null, sQuery2, sAcademicYear, true);
                                    string Bundle_id = resultArgs.RowUniqueId.ToString();
                                    var StudentLists = StudentListArrear.Skip(RunnigCount).Take(Pocketno).ToList();
                                    RunnigCount = RunnigCount + StudentLists.Count();
                                    if (StudentLists != null && StudentLists.Count > 0)
                                    {
                                        int counts = 0;
                                        foreach (var Stitem in StudentLists)
                                        {
                                            counts++;
                                            sQuery1 += "(" + Bundle_id + "," + Stitem.STUDENT_ID + ",LPAD(" + counts + ",2,0)," + sAcademicYear + "),";
                                        }
                                    }
                                }
                                using (MySQLHandler objHandler = new MySQLHandler())
                                {
                                    sQuery1 = sQuery1.TrimEnd(',');
                                    sQuery1 = sQuery1 + ";";
                                    objHandler.ExecuteAsScripts(sQuery1);
                                }
                            }
                        }
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "ManageBunles", ex.Message);
                    }
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.RequestTimeout;
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
