        public ActionResult BindExamQuestionPaperByExamSetting(string sExamSettingId, string sCourseId, string sQuestionLevel, string sSectionId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            var examquestions = new List<EXAM_QUESTIONS>();
            string sSQL = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchDeptSettingByCourseIdForddl).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.COURSE_ID, sCourseId);
                    ObjViewModel.liExamDeptQuestionSetting = (List<EXAM_DEPT_QUESTION_PAPER_SETTING>)CMSHandler.FetchData<EXAM_DEPT_QUESTION_PAPER_SETTING>(null, sSQL, sAcademicYear).DataSource.Data;

                    sSQL = string.Empty;
                    //Fech All Question paper  by courseid
                    sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamQuestionpapersByCourseId).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.COURSE_ID, sCourseId);
                    var liquestionpaper = (List<EXAM_QUESTION_PAPER>)CMSHandler.FetchData<EXAM_QUESTION_PAPER>(new EXAM_QUESTION_PAPER() { EXAM_SETTING_ID = sExamSettingId, QUESTION_LEVEL_ID = sQuestionLevel }, sSQL, sAcademicYear).DataSource.Data;
                    //Fetch Exam Question Papers
                    ObjViewModel.liExamQuestionPaper = (List<EXAM_QUESTION_PAPER>)CMSHandler.FetchData<EXAM_QUESTION_PAPER>(new EXAM_QUESTION_PAPER() { EXAM_SETTING_ID = sExamSettingId, COURSE_ID = sCourseId, QUESTION_LEVEL_ID = sQuestionLevel }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamQuestionpapersBySettingandCourseId), sAcademicYear).DataSource.Data;
                    //Fetch Questions

                    var liexamquestions = (List<EXAM_QUESTIONS>)CMSHandler.FetchData<EXAM_QUESTIONS>(new EXAM_QUESTION_PAPER() { COURSE_ID = sCourseId, QUESTION_LEVEL_ID = sQuestionLevel, SECTION_ID = sSectionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllExamQuestionsByCourseId), sAcademicYear).DataSource.Data;
                    liexamquestions.ToList().ForEach(o => { o.QUESTION = System.Text.ASCIIEncoding.ASCII.GetString(System.Convert.FromBase64String(o.QUESTION)).ToString(); });
                    if (liexamquestions != null && liexamquestions.Count > 0)
                    {
                        foreach (var item in liexamquestions)
                        {
                            if (!string.IsNullOrEmpty(item.NOT_REPEAT_YEAR))
                            {
                                var liquspaper = liquestionpaper.Where(o => o.QUESTION_ID == item.QUESTION_ID && o.EXAM_SETTING_ID != sExamSettingId).ToList();
                                if (liquspaper != null && liquspaper.Count > 0)
                                {
                                    foreach (var question in liquspaper)
                                    {
                                        if ((Convert.ToInt32(question.ACADEMIC_YEAR) + Convert.ToInt32(question.NOT_REPEAT_YEAR)) > Convert.ToInt32(sAcademicYear))
                                        {
                                            examquestions.Add(new EXAM_QUESTIONS() { QUESTION_ID = question.QUESTION_ID });
                                        }
                                    }

                                }
                            }
                            if (!string.IsNullOrEmpty(item.REPEAT_YEAR))
                            {
                                var liquspaper = liquestionpaper.Where(o => o.QUESTION_ID == item.QUESTION_ID && o.EXAM_SETTING_ID != sExamSettingId).ToList();
                                if (liquspaper != null && liquspaper.Count > 0)
                                {
                                    foreach (var quespaper in liquspaper)
                                    {
                                        if ((Convert.ToInt32(quespaper.ACADEMIC_YEAR) + Convert.ToInt32(quespaper.REPEAT_YEAR)) != Convert.ToInt32(sAcademicYear))
                                        {
                                            examquestions.Add(new EXAM_QUESTIONS() { QUESTION_ID = quespaper.QUESTION_ID });
                                        }
                                    }

                                }
                            }

                        }
                        if (examquestions != null && examquestions.Count > 0)
                        {
                            foreach (var item in examquestions)
                            {
                                liexamquestions.RemoveAll(o => o.QUESTION_ID == item.QUESTION_ID);
                            }
                        }
                        ObjViewModel.Questions = new SelectList(liexamquestions, Common.EXAM_QUESTIONS.QUESTION_ID, Common.EXAM_QUESTIONS.QUESTION);
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindExamQuestionPaperByExamSetting", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

