        public JsonResult SaveExamQuestionPaper(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            string sSQL = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var liExamquestionpaper = JsonConvert.DeserializeObject<SaveExamDetails>(sJsonData);
                    if (liExamquestionpaper != null)
                    {
                        sSQL = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamQuestionsPaper);
                        foreach (var item in liExamquestionpaper.ExamQuestionpaper)
                        {
                            if (!string.IsNullOrEmpty(item.QUESTION_PAPER_ID))
                            {
                                resultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamQuestionsPaper));
                            }
                            else
                            {
                                sSQL += "('" + item.COURSE_ID + "','" + item.QUESTION_LEVEL_ID + "','" + item.QUESTION_ID + "','" + item.EXAM_SETTING_ID + "'),";
                            }
                        }
                        sSQL = sSQL.TrimEnd(',');
                        sSQL = sSQL + ";";
                        resultArgs = CMSHandler.SaveOrUpdate(null, sSQL, sAcademicYear);
                        if (resultArgs.Success)
                            ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                        else
                            ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                    }
                }
                catch (Exception ex)
