        public JsonResult SaveOnlineExamObjectiveQuestions(string sQuestion, string sOPtions)
        {
            JsonResultData ObjJsonData = new JsonResultData();

            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<JSON_SAVE_QUIZ>(sOPtions);
                    var ObjSaveQuestion = JsonConvert.DeserializeObject<ONLINE_OBJECTIVE_QUESTIONS>(sQuestion);
                    if (Result.liMF_Option != null && Result.liMF_Option.Count > 0)
                    {

                        ObjSaveQuestion.STAFF_ID = sUserId;
                        string Quiz_Id = string.Empty;

                        // Objective Type ...
                        var HasItem = Result.liMF_Option.Where(x => x.OPTION == ObjSaveQuestion.ANSWER_ID).ToList();
                        if (HasItem != null && HasItem.Count > 0)
                        {

                            ObjSaveQuestion.QUESTION = ObjSaveQuestion.QUESTION;

                            // Save Questions ...
                            var sSaveQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamQuestions), sAcademicYear, true);
                            if (sSaveQuestions.Success)
                            {
                                Quiz_Id = sSaveQuestions.RowUniqueId.ToString();
                                ObjSaveQuestion.QUESTION_ID = Quiz_Id;
                                foreach (var item in Result.liMF_Option)
                                {

                                    item.QUESTION_ID = Quiz_Id;
                                    item.OPTIONS = item.OPTION;
                                    item.ACADEMIC_YEAR = ObjSaveQuestion.ACADEMIC_YEAR;
                                    var sSaveQuizOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineQuestionOptions), sAcademicYear);
                                }

                                var FetchOptionIdByAnswer = (List<ONLINE_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<ONLINE_OBJECTIVE_QUESTIONS>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOnlineExamQuestionsOptionIdByOption), sAcademicYear).DataSource.Data;
                                if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                {
                                    ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                    var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateAnswerForObjectiveQuestions), sAcademicYear);
                                }
                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objErrorLog = new ErrorLog())
                    {
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message, "Qury is Empty !");
                        objErrorLog.WriteError("ExaminationController", "SaveMatchTheFollowing", "Err.Msg:" + ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
