        public JsonResult FetchPartandUnitByStaff(string sAcyear, string sExamSettingId, string sCourseId)
        {
            var objModel = new ONLINE_EXAM_PARTWISE_STAFF();
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string sPart = string.Empty;
            string sUnit = string.Empty;

            if (!string.IsNullOrEmpty(sAcyear) && !string.IsNullOrEmpty(sExamSettingId) && !string.IsNullOrEmpty(sCourseId))
            {

                objModel.STAFF_ID = sUserId;
                objModel.EXAM_SETTING_ID = sExamSettingId;
                objModel.COURSE_ID = sCourseId;
                //Part
                var lipart = (List<SUP_PART>)CMSHandler.FetchData<SUP_PART>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchPartByStaff), sAcyear).DataSource.Data;
                if (lipart != null && lipart.Count > 0)
                {
                    foreach (var part in lipart)
                    {
                        sPart += "<option value='" + part.PART_ID + "'>" + part.PART + " </option>";
                    }
                }
                //Unit
                var liunit = (List<SUP_UNIT>)CMSHandler.FetchData<SUP_UNIT>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchUnitByStaff), sAcyear).DataSource.Data;
                if (liunit != null && liunit.Count > 0)
                {
                    foreach (var unit in liunit)
                    {
                        sUnit += "<option value='" + unit.UNIT_ID + "'>" + unit.UNIT_NAME + " </option>";
                    }
                }
                objModel.UNIT_ID = sUnit;
                objModel.PART_ID = sPart;

            }

            return Json(objModel, JsonRequestBehavior.AllowGet);
        }
