        public ActionResult BindCIAcheckingByStudent(string sAcademicYear)
        {
            // string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            string sStudentId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    var liCIATotal = new List<CIA_TOTAL>();
                    // Fetch Regular Papers .
                    var liRegularCourses = (List<EXAM_REGISTRATION>)CMS.DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sStudentId },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchExamRegistration), sAcademicYear).DataSource.Data;

                    // Fetch Optional Papers .
                    var liOptionalCourses = (List<EXAM_REGISTRATION>)DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sStudentId },
                                 SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOptionalCourses), sAcademicYear).DataSource.Data;

                    // Loop Optional Papers  To Remove Unnecessary Courses...
                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                    {
                        foreach (var item in liOptionalCourses)
                        {
                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (IsExist != null && IsExist.Count > 0)
                            {
                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                liRegularCourses.Add(item);
                            }
                        }
                    }

                    ObjViewModel.liExamRegistrationList = liRegularCourses;
                    if (liRegularCourses != null && liRegularCourses.Count > 0)
                    {
                        foreach (var item in liRegularCourses)
                        {
                            item.STUDENT_ID = sStudentId;
                            item.COURSE_ID = item.COURSE_ROOT_ID;
                            var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATotalByStudentAndCourseId), sAcademicYear).DataSource.Data;
                            if (liCIA_Total != null && liCIA_Total.Count > 0)
                            {
                                liCIA_Total.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                                if (liCIA_Total != null && liCIA_Total.Count > 0)
                                {
                                    liCIATotal = (liCIATotal != null && liCIATotal.Count > 0) ? liCIATotal.Concat(liCIA_Total).ToList() : liCIA_Total;
                                }
                            }

                            // Checked Validation
                            var liCourseValidation = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsCiaMarkVerifiedByCourseAndStudentId), sAcademicYear).DataSource.Data;
                            if (liCourseValidation != null && liCourseValidation.Count > 0)
                            {
                                item.STATUS = "1";
                                item.CIA_GROUP_MARK_CHECKING_ID = liCourseValidation.FirstOrDefault().CIA_GROUP_MARK_CHECKING_ID;
                            }
                            else
                            {
                                item.CIA_GROUP_MARK_CHECKING_ID = string.Empty;
                            }
                        }

                        ObjViewModel.liCIA_Total = liCIATotal;



                        // fetch cia marks
                        //var liCiaMark = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(new CIA_GROUP_MARK_CHECKING() { STUDENT_ID = sUserId }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIAMarksByStudentAndAcademicYear), sAcademicYear).DataSource.Data;
                        //if (liCiaMark != null && liCiaMark.Count > 0)
                        //{
                        //    ObjViewModel.liCIA_Total = liCiaMark;
                        //}
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "CIAcheckingByStudent", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

        public JsonResult UpdateCIACheckingByStudentId(string sJsonData)
        {

            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var Result = JsonConvert.DeserializeObject<JSON_FILEDS>(sJsonData);
            int sSuccessCount = 0;
            int sFailedCount = 0;

            try
            {

                if (Result.liCiaGroupChecking != null)
                {
                    foreach (var item in Result.liCiaGroupChecking)
                    {
                        if (!string.IsNullOrEmpty(item.CIA_GROUP_MARK_CHECKING_ID))
                        {
                            var sResultArgs = CMSHandler.SaveOrUpdate(new CIA_GROUP_MARK_CHECKING() { CIA_GROUP_MARK_CHECKING_ID = item.CIA_GROUP_MARK_CHECKING_ID, STATUS = item.STATUS }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateCiaGroupMarkChecking), sAcademicYear);
                            if (sResultArgs.Success && sResultArgs.RowsAffected != 0)
                            {
                                sSuccessCount++;
                            }
                            else
                            {
                                sFailedCount++;
                            }
                        }
                        else
                        {

                            var sResultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.AddCiaGroupMarkChecking), sAcademicYear);
                            if (sResultArgs.Success && sResultArgs.RowsAffected != 0)
                            {
                                sSuccessCount++;
                            }
                            else
                            {
                                sFailedCount++;
                            }

                        }
                    }

                    if (sSuccessCount > 0)
                    {
                        ObjJsonData.Message = " " + sSuccessCount + "  Records Saved Successfully!.";
                    }
                    if (sFailedCount > 0)
                    {
                        ObjJsonData.Message += "\n" + sFailedCount + "  Records Failed to Save!.";
                    }
                }
            }

            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "UpdateCIACheckingByStudentId", ex.Message);
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

