        public JsonResult FetchQuestioncountandPatternsectionId(string sQuestionpatternid, string sSectionId, string sQuestiontype, string sExamsettingId, string sCourseId, string sSetId)
        {

            var liquestionenterd = new List<EXAM_OBJECTIVE_QUESTIONS>();
            var objModel = new EXAM_QUESTION_PATTERN_SECTION();
            try
            {
                string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

                if (!string.IsNullOrEmpty(sQuestionpatternid) && !string.IsNullOrEmpty(sSectionId) && !string.IsNullOrEmpty(sQuestiontype))
                {
                    //Fetch patternid and noof questions
                    var lipattensection = (List<EXAM_QUESTION_PATTERN_SECTION>)CMSHandler.FetchData<EXAM_QUESTION_PATTERN_SECTION>(new EXAM_QUESTION_PATTERN_SECTION() { QUESTION_PATTERN_ID = sQuestionpatternid, SECTION_ID = sSectionId, QUESTION_TYPE = sQuestiontype, }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuestionpatternsectionId), sAcademicYear).DataSource.Data;
                    if (lipattensection != null && lipattensection.Count > 0)
                    {
                        if (sQuestiontype == Common.Question_Type.ObjectiveType)
                        {
                            liquestionenterd = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_OBJECTIVE_QUESTIONS() { PATTERN_SECTION_ID = lipattensection.FirstOrDefault().PATTERN_SECTION_ID, COURSE_ID = sCourseId, EXAM_SETTING_ID = sExamsettingId, SET_ID = sSetId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEnteredExamObjectiveQuestions), sAcademicYear).DataSource.Data;
                        }
                        else if (sQuestiontype == Common.Question_Type.FillInTheBlank)
                        {
                            liquestionenterd = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_OBJECTIVE_QUESTIONS() { PATTERN_SECTION_ID = lipattensection.FirstOrDefault().PATTERN_SECTION_ID, COURSE_ID = sCourseId, EXAM_SETTING_ID = sExamsettingId, SET_ID = sSetId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEnteredExamFilltheblankQuestions), sAcademicYear).DataSource.Data;
                        }
                        else if (sQuestiontype == Common.Question_Type.MatchTheFollowing)
                        {
