                        }
                    }
                    if (lipattensection != null && liquestionenterd != null && lipattensection.Count > 0 && liquestionenterd.Count > 0)
                    {
                        objModel.PATTERN_SECTION_ID = lipattensection.FirstOrDefault().PATTERN_SECTION_ID;
