        public JsonResult UpdateAlltypeExamQuestions(string Question, string Options)
        {
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<JSON_SAVE_QUIZ>(Options);
                    var ObjSaveQuestion = JsonConvert.DeserializeObject<EXAM_OBJECTIVE_QUESTIONS>(Question);
                    if (Result.liMF_Option != null && Result.liMF_Option.Count > 0)
                    {
                        ObjSaveQuestion.ENTRY_ID = sUserId;
                        if (ObjSaveQuestion.QUESTION_TYPE == Common.Question_Type.MatchTheFollowing)
                        {

                            // Save  Questions .
                            var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateMathTheFollowingExamQuestions), sAcademicYear, true);
                            if (SaveMFQuestions.Success)
                            {
                                // Save  Options .
                                foreach (var item in Result.liMF_Option)
                                {
                                    item.QUIZ_ID = ObjSaveQuestion.QUIZ_ID;
                                    if (!string.IsNullOrEmpty(item.OPTION_ID))
                                    {
                                        // Update ...
                                        var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateMathTheFollowingExamOptions), sAcademicYear);
                                    }
                                    else
                                    {
                                        // Insert ...
                                        var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamMathTheFollowingOptions), sAcademicYear);
                                    }

                                }
                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            }
                        }
                        // Fill In The Blank Questions ....
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Question_Type.FillInTheBlank)
                        {

                            var HasItem = Result.liMF_Option.Where(x => x.OPTION == ObjSaveQuestion.ANSWER_ID).ToList();
                            if (HasItem != null && HasItem.Count > 0)
                            {

                                // Save  Questions ...
                                var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamFillInTheBlankQuestionByQuizId), sAcademicYear, true);
                                if (SaveMFQuestions.Success)
                                {
                                    // Save  Options ...
                                    foreach (var item in Result.liMF_Option)
                                    {
                                        item.QUIZ_ID = ObjSaveQuestion.QUIZ_ID;
                                        item.OPTIONS = item.OPTION;
                                        if (!string.IsNullOrEmpty(item.OPTION_ID))
                                        {
                                            // Update ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamFillInTheBlankOptions), sAcademicYear);
                                        }
                                        else
                                        {
                                            // Insert ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamFillInBlankOptions), sAcademicYear);
                                        }
                                    }
                                    // Fetch Option Id For Update Answer ...
                                    var FetchOptionIdByAnswer = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamFillInBlankOptionIdByOption), sAcademicYear).DataSource.Data;

                                    if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                    {
                                        ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                        var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamAnswerForFillInBlankQuestions), sAcademicYear);
                                    }
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "Your Answer Not Valuable ! Please Check You Input !";
                            }
                        }
                        // Objective Type Questions ....
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Question_Type.ObjectiveType)
                        {
                            //check option and answer if any option is equal to answer
                            var HasItem = Result.liMF_Option.Where(x => x.OPTION == ObjSaveQuestion.ANSWER_ID).ToList();
                            if (HasItem != null && HasItem.Count > 0)
                            {

                                // Save  Questions ...
                                var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateObjectiveExamQuestionByQuizId), sAcademicYear, true);
                                if (SaveMFQuestions.Success)
                                {
                                    // Save  Options ...
                                    foreach (var item in Result.liMF_Option)
                                    {
                                        item.QUIZ_ID = ObjSaveQuestion.QUIZ_ID;
                                        if (!string.IsNullOrEmpty(item.OPTION_ID))
                                        {
                                            // Update ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatExamObjectiveOptions), sAcademicYear);
                                        }
                                        else
                                        {
                                            // Insert ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamObjectiveOption), sAcademicYear);
                                        }
                                    }

                                    // Fetch Option Id For Update Answer ...
                                    var FetchOptionIdByAnswer = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(ObjSaveQuestion,
                                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveOptionIdByOption), sAcademicYear).DataSource.Data;

                                    if (FetchOptionIdByAnswer != null && FetchOptionIdByAnswer.Count > 0)
                                    {
                                        ObjSaveQuestion.ANSWER_ID = FetchOptionIdByAnswer.FirstOrDefault().OPTION_ID;
                                        var sUpdateAnswer = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForObjectiveExamQuestions), sAcademicYear);
                                    }
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = "Your Answer Not Valuable ! Please Check You Input !";
                            }

                        }
                        // Either Type Questions ....
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Question_Type.EitherQuestions)
                        {
                            // Save  Questions ...
                            var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateEitherExamQuestionByQuizId), sAcademicYear, true);
                            if (SaveMFQuestions.Success)
                            {
                                // Save  Options ...
                                if (Options != "")
                                {
                                    foreach (var item in Result.liMF_Option)
                                    {
                                        item.QUIZ_ID = ObjSaveQuestion.QUIZ_ID;
                                        if (!string.IsNullOrEmpty(item.OPTION_ID))
                                        {
                                            // Update ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatExamEitherOptions), sAcademicYear);
                                        }
                                        else
                                        {
                                            // Insert ...
                                            var SaveMFOptions = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamEitheOptions), sAcademicYear);
                                        }
                                    }
                                }


                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            }
                        }

                        // Choice Based Type Questions ....
                        else if (ObjSaveQuestion.QUESTION_TYPE == Common.Question_Type.ChooseBasedQuestions)
                        {
                            // Save  Questions ...
                            var SaveMFQuestions = CMSHandler.SaveOrUpdate(ObjSaveQuestion, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateChoiceBasedExamQuestionByQuizId), sAcademicYear, true);
