                     ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamFillInTheBlankQuestionAndAnswerByQuizId), sAcademicYear).DataSource.Data;
                }
                else if (sQuestionTypeId == Common.Question_Type.ObjectiveType)
                {
                    liQuizDetails = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(ObjModel,
                     ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamObjectiveQuestionAndAnswerByQuizId), sAcademicYear).DataSource.Data;
                }
                else if (sQuestionTypeId == Common.Question_Type.EitherQuestions)
                {
                    liQuizDetails = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(ObjModel,
                     ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamEitherQuestionAndAnswerByQuizId), sAcademicYear).DataSource.Data;
                }
            }
            else
            {
                ObjViewModel.sErrorMessage = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(liQuizDetails, JsonRequestBehavior.AllowGet);
        }
        public JsonResult DeleteExamQuestionsByType(string sQuestionId, string sQuestionType)
        {
            if (!string.IsNullOrEmpty(sQuestionId) && !string.IsNullOrEmpty(sQuestionType))
            {
                try
                {
                    if (sQuestionType == Common.Question_Type.ObjectiveType)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = sQuestionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamObjectiveQuestions));
                    }
                    else if (sQuestionType == Common.Question_Type.FillInTheBlank)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = sQuestionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamFillInBlank));
                    }
                    else if (sQuestionType == Common.Question_Type.MatchTheFollowing)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = sQuestionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamMatchTheFollowing));
                    }
                    else if (sQuestionType == Common.Question_Type.EitherQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = sQuestionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamEitherQuestions));
                    }
                    else if (sQuestionType == Common.Question_Type.ChooseBasedQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = sQuestionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteExamChoiceBasedQuestions));
                    }

                    objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordDeletedSuccessfully : Common.Messages.FailedToDeletedTryAgain;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "DeleteExamQuestionsByType", ex.Message);
                    }
                    objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
