        public JsonResult UpdateReuploadingAnswerSheets(string sQuizSaveId, string sImagedata, string sQuestiontype)
        {
            string sSQL = string.Empty;
            string sImagePath = string.Empty;
            string sDatetime = string.Empty;
            string _sDirectorypath = string.Empty;
            var objModel = new EXAM_OBJECTIVE_QUESTIONS();
            if (!string.IsNullOrEmpty(sQuizSaveId) && !string.IsNullOrEmpty(sImagedata) && !string.IsNullOrEmpty(sQuestiontype))
            {
                try
                {

                    _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.EXAM_ANSWER_PATH;

                    if (!Directory.Exists(_sDirectorypath))
                    {
                        Directory.CreateDirectory(_sDirectorypath);
                    }
                    sDatetime = "_" + DateTime.Now.ToString("HH:mm:ss").Replace(":", "-") + ".png";
                    sImagePath = Server.MapPath("\\" + Common.URLPages.EXAM_ANSWER_PATH) + "\\" + sQuizSaveId + sDatetime;
                    objModel.IMAGE_PATH = "\\" + Common.URLPages.EXAM_ANSWER_PATH + "\\" + sQuizSaveId + sDatetime;
                    using (FileStream fs = new FileStream(sImagePath, FileMode.Create))
                    {
                        using (BinaryWriter bw = new BinaryWriter(fs))
                        {
                            byte[] data = Convert.FromBase64String(sImagedata);
                            bw.Write(data);
                            bw.Close();
                        }
                    }
                    objModel.QUIZ_SAVE_ID = sQuizSaveId;
                    if (Common.Question_Type.EitherQuestions == sQuestiontype)
                    {
                        //UPDATE Either question and answers
                        resultArgs = CMSHandler.SaveOrUpdate(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateEitherQuestionandAnswer));


                    }
                    else if (Common.Question_Type.ChooseBasedQuestions == sQuestiontype)
                    {
                        //UPDATE Choose based question and answers
                        resultArgs = CMSHandler.SaveOrUpdate(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateChooseBasedQuestionandAnswer));


                    }
                    if (resultArgs.Success)
                        objJsonData.Message = Common.Messages.RecordsUpdatedSuccessfully;
                    else
                        objJsonData.Message = Common.Messages.FailedToSaveRecords;

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "UpdateReuploadingAnswerSheets", ex.Message);
                    }
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }

            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
