        public ActionResult BindQuestionsBySectionandsetId(string sCourseId, string sExamsettingid, string sSetid, string sSectionId, string sAcademicYear, string sUserId)
        {
            var ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            var StudentController = new StudentController();
            var liMatchTheFollowingOptions = new List<EXAM_OBJECTIVE_OPTIONS>();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                ObjViewModel.sAcyear = sAcademicYear;
                ObjViewModel.sUserId = sUserId;

                try
                {

                    #region Match The Following Questin & Answer
                    // Fetch Match The Following  Questions and options ...
                    var liMatchTheFollowingQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                        new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchTheFollowingExamQuestionsandoptions), sAcademicYear).DataSource.Data;

                    // Fetch Match The Following  Options ...
                    if (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0)
                    {
                        liMatchTheFollowingOptions = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(
                          new EXAM_OBJECTIVE_OPTIONS() { QUIZ_ID = liMatchTheFollowingQuestions.FirstOrDefault().QUIZ_ID },
                           SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchTheFollowingExamOptions), sAcademicYear).DataSource.Data;
                    }
                    #endregion

                    #region Objective Type Questions And Answers

                    // Fetch Objective  Questions and options ...
                    var liObjectiveQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                       new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectivesExamQuestionsandoptions), sAcademicYear).DataSource.Data;
                    if (liObjectiveQuestions != null && liObjectiveQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liObjectiveQuestions).ToList() : liObjectiveQuestions;
                    }

                    // Fetch Objective  Options ...
                    if (liObjectiveQuestions != null && liObjectiveQuestions.Count > 0)
                    {
                        var liObjectiveOptions = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(
                        new EXAM_OBJECTIVE_OPTIONS() { QUIZ_ID = liObjectiveQuestions.FirstOrDefault().QUIZ_ID },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectivesExamOptions), sAcademicYear).DataSource.Data;
                        if (liObjectiveOptions != null && liObjectiveOptions.Count > 0)
                        {
                            liMatchTheFollowingOptions = (liMatchTheFollowingOptions != null && liMatchTheFollowingOptions.Count > 0) ? liMatchTheFollowingOptions.Concat(liObjectiveOptions).ToList() : liObjectiveOptions;
                        }
                    }
                    #endregion

                    #region Fill In The Blank Questions And Answers

                    // Fetch Fill In The Blank  Questions options ...
                    var liFillInTheBlankQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                          new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId },
                             SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFillInTheBlankExamQuestionsandoptions), sAcademicYear).DataSource.Data;
                    if (liFillInTheBlankQuestions != null && liFillInTheBlankQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liFillInTheBlankQuestions).ToList() : liFillInTheBlankQuestions;
                    }
                    // Fetch Fill In The Blank  Options ...
                    if (liFillInTheBlankQuestions != null && liFillInTheBlankQuestions.Count > 0)
                    {
                        var liFillInTheBlankOptions = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(
                        new EXAM_OBJECTIVE_OPTIONS() { QUIZ_ID = liFillInTheBlankQuestions.FirstOrDefault().QUIZ_ID },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFillInTheBlankOptions), sAcademicYear).DataSource.Data;
                        if (liFillInTheBlankOptions != null && liFillInTheBlankOptions.Count > 0)
                        {
                            liMatchTheFollowingOptions = (liMatchTheFollowingOptions != null && liMatchTheFollowingOptions.Count > 0) ? liMatchTheFollowingOptions.Concat(liFillInTheBlankOptions).ToList() : liFillInTheBlankOptions;
                        }
                    }

                    #endregion

                    #region Either 

                    // Fetch  Either Questions  and options...
                    var liEitherQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                           new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId },
                             SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEitherExamQuestionsandoptions), sAcademicYear).DataSource.Data;
                    if (liEitherQuestions != null && liEitherQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liEitherQuestions).ToList() : liEitherQuestions;
                    }
                    // Fetch Either   Options ...
                    if (liEitherQuestions != null && liEitherQuestions.Count > 0)
                    {
                        var liEitherOptions = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(
                        new EXAM_OBJECTIVE_OPTIONS() { QUIZ_ID = liEitherQuestions.FirstOrDefault().QUIZ_ID },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEitherOptions), sAcademicYear).DataSource.Data;
                        if (liEitherOptions != null && liEitherOptions.Count > 0)
                        {
                            liMatchTheFollowingOptions = (liMatchTheFollowingOptions != null && liMatchTheFollowingOptions.Count > 0) ? liMatchTheFollowingOptions.Concat(liEitherOptions).ToList() : liEitherOptions;
                        }
                    }
                    #endregion

                    #region Choose Based Questions
                    var lichoosebasedquestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                          new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEitherExamChooseBasedQuestions), sAcademicYear).DataSource.Data;
                    if (lichoosebasedquestions != null && lichoosebasedquestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(lichoosebasedquestions).ToList() : lichoosebasedquestions;
                    }
                    #endregion

                    //Fetch Question Count Status
                    var liquestioncountstatus = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAttendedQuestionCount), sAcademicYear).DataSource.Data;
                    if (liquestioncountstatus != null && liquestioncountstatus.Count > 0)
                    {
                        ObjViewModel.Attendedcount = !string.IsNullOrEmpty(liquestioncountstatus.FirstOrDefault().QUIZ_SAVE_ID) ? liquestioncountstatus.FirstOrDefault().QUIZ_SAVE_ID : "0";
                    }
                    var liquestioncount = (List<EXAM_QUESTION_PATTERN_SECTION>)CMSHandler.FetchData<EXAM_QUESTION_PATTERN_SECTION>(new EXAM_OBJECTIVE_QUESTIONS() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId, SET_ID = sSetid, SECTION_ID = sSectionId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTotalQuestionCount), sAcademicYear).DataSource.Data;
                    if (liquestioncount != null && liquestioncount.Count > 0)
                    {
                        ObjViewModel.Totalcount = !string.IsNullOrEmpty(liquestioncount.FirstOrDefault().TO_BE_ATTEND) ? liquestioncount.FirstOrDefault().TO_BE_ATTEND : "0";

                    }
                    else
                        ObjViewModel.Totalcount = "0";
                    //Check Is Suspended
                    var lisuspended = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_INVIGILATION() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsStudentSuspended), sAcademicYear).DataSource.Data;

                    //Check Is Exam Is Active
                    var licheckisactive = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_INVIGILATION() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingid, COURSE_ID = sCourseId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsExamActive), sAcademicYear).DataSource.Data;

                    ObjViewModel.liexaminvigilationinfo = licheckisactive;
                    ObjViewModel.liexaminvigilation = lisuspended;
                    ObjViewModel.liquestionpatternsession = liquestioncount;
                    ObjViewModel.Liexamquesions = liMatchTheFollowingQuestions;

                    ObjViewModel.liexamoptions = liMatchTheFollowingOptions;

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "BindQuestionsBySectionandsetId", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }
        public async Task<JsonResult> SaveStudentExamQuestionandAnswer(string sJsonSave, string sExamsettingId, string sCourseId, string sUserId, string sAcademicYear, string sTimeSpend)
        {
            var ObjJsonData = new JsonResultData();
            string sSQL = string.Empty;

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjJson = JsonConvert.DeserializeObject<JSON_SAVE_EXAM_ANSWER>(sJsonSave);

                    await Task.Run(() =>
                    {
                        if (ObjJson.liOnlineExamanswer != null && ObjJson.liOnlineExamanswer.Count > 0)
                        {

                            var limatchthefollowing = ObjJson.liOnlineExamanswer.Where(o => o.QUESTION_TYPE == Common.Question_Type.MatchTheFollowing).ToList();
                            if (limatchthefollowing != null && limatchthefollowing.Count > 0)
                            {
                                sSQL = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamMatchTheFollowingByStudent);
                                foreach (var item in limatchthefollowing)
                                {
                                    sSQL += "('" + item.COURSE_ID + "','" + item.STUDENT_ID + "','" + item.QUIZ_ID + "','" + item.OPTION_ID + "','" + item.ANSWER_ID + "','" + item.STATUS + "','" + sAcademicYear + "','" + item.MINUTES + "'),";
                                }
                                sSQL = sSQL.TrimEnd(',');
                                sSQL = sSQL + ";";
                                resultArgs = CMSHandler.SaveOrUpdate(null, sSQL, sAcademicYear);
                            }
                            var lifillintheblank = ObjJson.liOnlineExamanswer.Where(o => o.QUESTION_TYPE == Common.Question_Type.FillInTheBlank).ToList();
                            if (lifillintheblank != null && lifillintheblank.Count > 0)
                            {
                                sSQL = string.Empty;
                                sSQL = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamFillInTheBlankByStudent);
                                foreach (var item in lifillintheblank)
                                {
                                    sSQL += "('" + item.COURSE_ID + "','" + item.STUDENT_ID + "','" + item.QUIZ_ID + "','" + item.OPTION_ID + "','" + item.ANSWER_ID + "','" + item.STATUS + "','" + sAcademicYear + "','" + item.MINUTES + "'),";
                                }
                                sSQL = sSQL.TrimEnd(',');
                                sSQL = sSQL + ";";
                                resultArgs = CMSHandler.SaveOrUpdate(null, sSQL, sAcademicYear);
                            }
                            var liobjectivetype = ObjJson.liOnlineExamanswer.Where(o => o.QUESTION_TYPE == Common.Question_Type.ObjectiveType).ToList();
                            if (liobjectivetype != null && liobjectivetype.Count > 0)
                            {
                                sSQL = string.Empty;
                                sSQL = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamObjectiveQuizByStudent);
                                foreach (var item in liobjectivetype)
                                {
                                    sSQL += "('" + item.COURSE_ID + "','" + item.STUDENT_ID + "','" + item.QUIZ_ID + "','" + item.OPTION_ID + "','" + item.ANSWER_ID + "','" + item.STATUS + "','" + sAcademicYear + "','" + item.MINUTES + "'),";
                                }
                                sSQL = sSQL.TrimEnd(',');
                                sSQL = sSQL + ";";
                                resultArgs = CMSHandler.SaveOrUpdate(null, sSQL, sAcademicYear);
                            }
                            ObjJsonData.Message = (resultArgs.Success) ? "Answers Submitted Successfully !" : "Failed to Save Answers Try Again !";
                            ObjJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.BadRequest;


                        }
                    });
                    if (!string.IsNullOrEmpty(sTimeSpend))
                    {
                        var liexaminvigilationid = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_INVIGILATION() { STUDENT_ID = sUserId, EXAM_SETTING_ID = sExamsettingId, COURSE_ID = sCourseId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamInvigilationId), sAcademicYear).DataSource.Data;
                        if (liexaminvigilationid != null && liexaminvigilationid.Count > 0)
                        {
                            var Result = CMSHandler.SaveOrUpdate(new EXAM_INVIGILATION() { EXAM_INVIGILATION_ID = liexaminvigilationid.FirstOrDefault().EXAM_INVIGILATION_ID, MINUTES_SECONDS = sTimeSpend }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveTimeSpend));
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveStudentExamQuestionandAnswer", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        public JsonResult SaveEitherQuestionAnswer(string sJsonData, string sImagedata, string sQuestiontype)
        {

            string sSQL = string.Empty;
            string sImagePath = string.Empty;
            string _sDirectorypath = string.Empty;
            string sDatetime = string.Empty;
            var liuploadedimage = new List<EXAM_OBJECTIVE_QUESTIONS>();
            if (!string.IsNullOrEmpty(sJsonData) && !string.IsNullOrEmpty(sImagedata))
            {
                try
                {
                    var ObjJson = JsonConvert.DeserializeObject<EXAM_OBJECTIVE_QUESTIONS>(sJsonData);
                    if (ObjJson != null)
                    {

                        _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.EXAM_ANSWER_PATH;

                        if (!Directory.Exists(_sDirectorypath))
                        {
                            Directory.CreateDirectory(_sDirectorypath);
                        }
                        sDatetime = "_" + DateTime.Now.ToString("HH:mm:ss").Replace(":", "-") + ".png";
                        sImagePath = Server.MapPath("\\" + Common.URLPages.EXAM_ANSWER_PATH) + "\\" + ObjJson.EXAM_SETTING_ID + "_" + ObjJson.QUIZ_ID + "_" + ObjJson.OPTION_ID + "_" + ObjJson.STUDENT_ID + sDatetime;
                        sImagePath = sImagePath.Replace(" ", "_");
                        using (FileStream fs = new FileStream(sImagePath, FileMode.Create))
                        {
                            using (BinaryWriter bw = new BinaryWriter(fs))
                            {
                                byte[] data = Convert.FromBase64String(sImagedata);
                                bw.Write(data);
                                bw.Close();
                            }
                        }
                        ObjJson.IMAGE_PATH = ("\\" + Common.URLPages.EXAM_ANSWER_PATH + "\\" + ObjJson.EXAM_SETTING_ID + "_" + ObjJson.QUIZ_ID + "_" + (ObjJson.OPTION_ID != " " ? ObjJson.OPTION_ID : "_") + "_" + ObjJson.STUDENT_ID + sDatetime).Replace(" ", "_");
                        if (Common.Question_Type.EitherQuestions == sQuestiontype)
                        {
                            //Save Either question and answers
                            var Result = CMSHandler.SaveOrUpdate(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveEitherQuestionandAnswer));

                            //Fetch Image Uploaded
                            if (!string.IsNullOrEmpty(ObjJson.QUIZ_ID) && !string.IsNullOrEmpty(ObjJson.OPTION_ID) && ObjJson.OPTION_ID != " ")
                            {
                                liuploadedimage = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchuploadedimageByQuestionandoptionId)).DataSource.Data;
                                liuploadedimage.ForEach(o => o.QUESTION_TYPE_ID = Common.Question_Type.EitherQuestions);
                            }
                            else
                            {
                                liuploadedimage = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchuploadedimageByQuestionId)).DataSource.Data;
                                liuploadedimage.ForEach(o => o.QUESTION_TYPE_ID = Common.Question_Type.EitherQuestions);
                            }

                        }
                        else if (Common.Question_Type.ChooseBasedQuestions == sQuestiontype)
                        {
                            //Save Choose based question and answers
                            var Result = CMSHandler.SaveOrUpdate(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveChooseBasedQuestionandAnswer));

                            //Fetch Image Uploaded
                            if (!string.IsNullOrEmpty(ObjJson.QUIZ_ID))
                            {
                                liuploadedimage = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchChoosebaseduploadedimageByQuestionId)).DataSource.Data;
                                liuploadedimage.ForEach(o => o.QUESTION_TYPE_ID = Common.Question_Type.ChooseBasedQuestions);
                            }
                        }
                        if (!string.IsNullOrEmpty(ObjJson.MINUTES))
                        {
                            var liexaminvigilationid = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(ObjJson, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamInvigilationId)).DataSource.Data;
                            if (liexaminvigilationid != null && liexaminvigilationid.Count > 0)
                            {
                                var Result = CMSHandler.SaveOrUpdate(new EXAM_INVIGILATION() { EXAM_INVIGILATION_ID = liexaminvigilationid.FirstOrDefault().EXAM_INVIGILATION_ID, MINUTES_SECONDS = ObjJson.MINUTES }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveTimeSpend));
                            }
                        }

                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveEitherQuestionAnswer", ex.Message);
                    }
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }

            return Json(liuploadedimage, JsonRequestBehavior.AllowGet);
        }
        public JsonResult SaveTimeUp(string sCourseId, string sExamsettingId, string sUserId, string sAcademicYear, string sTimeSpend)
