        public JsonResult AssignPreviewForStudent(string sQuizsaveId, string sQuestiontypeId, string sStudentId)
        {
            if (!string.IsNullOrEmpty(sQuizsaveId) && !string.IsNullOrEmpty(sQuestiontypeId))
            {
                try
                {
                    //Fetch Student Info
                    var listudentinfo = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_INVIGILATION() { EXAM_INVIGILATION_ID = sStudentId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentInfoForSMS)).DataSource.Data;
                    if (listudentinfo != null && listudentinfo.Count > 0)
                    {
                        CommunicationController cm = new CommunicationController();
                        cm.sReceipientNo = listudentinfo.FirstOrDefault().MOBILE_NO;
                        cm.sTextMessage = "Dear " + listudentinfo.FirstOrDefault().FIRST_NAME + " Please login again and reupload answer sheet for this course: " + listudentinfo.FirstOrDefault().COURSE_TITLE + "";
                        cm.SendSMSFromDovesoft();

                    }
                    if (sQuestiontypeId == Common.Question_Type.EitherQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_SAVE_ID = sQuizsaveId, QUESTION_TYPE_ID = sQuestiontypeId, IS_PREVIEW = Common.IsActiveFalg.IsActive }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatePreviewFlagInEitherType));
                    }
                    else if (sQuestiontypeId == Common.Question_Type.ChooseBasedQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_SAVE_ID = sQuizsaveId, QUESTION_TYPE_ID = sQuestiontypeId, IS_PREVIEW = Common.IsActiveFalg.IsActive }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatePreviewFlagInChoiceBased));

                    }
                    objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "AssignPreviewForStudent", ex.Message);
                    }
                    objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
        public JsonResult UpdatePreviewStatus(string sQuizsaveId, string sQuestiontypeId, string sStudentId)
        {
            if (!string.IsNullOrEmpty(sQuizsaveId) && !string.IsNullOrEmpty(sQuestiontypeId))
            {
                try
                {

                    if (sQuestiontypeId == Common.Question_Type.EitherQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_SAVE_ID = sQuizsaveId, QUESTION_TYPE_ID = sQuestiontypeId, IS_PREVIEW = Common.IsActiveFalg.IsNotActive }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatePreviewFlagInEitherType));
                    }
                    else if (sQuestiontypeId == Common.Question_Type.ChooseBasedQuestions)
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_SAVE_ID = sQuizsaveId, QUESTION_TYPE_ID = sQuestiontypeId, IS_PREVIEW = Common.IsActiveFalg.IsNotActive }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdatePreviewFlagInChoiceBased));

                    }
                    objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "AssignPreviewForStudent", ex.Message);
                    }
                    objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
