        public JsonResult ActivateOrDeActivateExamByInvigilator(string sExamSettingId, string sCourseId, string sInvigilatorId, string sIsActive, string sTimeTableId)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                var ObjModel = new EXAM_INVIGILATION();
                ObjModel.EXAM_SETTING_ID = sExamSettingId;
                ObjModel.COURSE_ID = sCourseId;
                ObjModel.EXAM_INVIGILATOR_ID = sInvigilatorId;
                ObjModel.TIMETABLE_ID = sTimeTableId;
                ObjModel.IS_ACTIVE = (sIsActive == "1") ? Common.IsActiveFalg.IsNotActive : Common.IsActiveFalg.IsActive;
                var ActivateOrDeActivate = CMSHandler.SaveOrUpdate(ObjModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.ActiveOrDeActiveInvigilation));
                if (ActivateOrDeActivate.Success && ActivateOrDeActivate.RowsAffected != 0)
                {
                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                }
                else
                {
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "ActivateOrDeActivateExamByInvigilator", ex.Message);
                }
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

