        public ActionResult BindShuffleStudentInvigilation(string sExamSettingId, string sTimetableId, string sAcademicYear, string sExamtype, string sOnlineExamsettingId)
        {

            string sSQL = string.Empty;
            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    if (sExamtype == Common.EXAM_TYPE.EXTERNAL)
                    {
                        // timetable by id 
                        ObjViewModel.liExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { TIMETABLE_ID = sTimetableId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTimeTableByTimetableId)).DataSource.Data;
                        if (ObjViewModel.liExamTimeTable != null && ObjViewModel.liExamTimeTable.Count > 0)
                        {
                            //  Course List ...,
                            ObjViewModel.liCourseRoot = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseRootInfoByCourseId)).DataSource.Data;
                            // Shuffled Student Count ...,
                            ObjViewModel.liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamSettingId, COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID, ONLINE_EXAM_SETTING_ID = sOnlineExamsettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchShuffledStudentCountbyCourseAndSettingId)).DataSource.Data;
                            // UnShuffled Student List...,
                            ObjViewModel.liexaminvigilation = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindShuffleStudentInvigilation), sAcademicYear).DataSource.Data;

                        }
                    }
                    else if (sExamtype == Common.EXAM_TYPE.INTERNAL)
                    {
                        // timetable by id 
                        ObjViewModel.liExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { TIMETABLE_ID = sTimetableId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATimeTableByTimetableId)).DataSource.Data;
                        if (ObjViewModel.liExamTimeTable != null && ObjViewModel.liExamTimeTable.Count > 0)
                        {


                            //  Course List ...,
                            ObjViewModel.liCourseRoot = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseRootInfoByCourseId)).DataSource.Data;
                            // Shuffled Student Count ...,
                            ObjViewModel.liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamSettingId, ONLINE_EXAM_SETTING_ID = sOnlineExamsettingId, COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchShuffledStudentCountbyCourseAndSettingId)).DataSource.Data;
                            // UnShuffled Student List...,
                            //Fetch Classess
                            var liclassess = (List<CP_CLASS_COURSE_STAFF>)CMSHandler.FetchData<CP_CLASS_COURSE_STAFF>(new CP_CLASS_COURSE_STAFF() { COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchClassessByCourse), sAcademicYear).DataSource.Data;
                            if (liclassess != null && liclassess.Count > 0)
                            {
                                sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindInternalExamShuffleStudentInvigilation).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.CLASS_ID, string.Join(",", liclassess.Select(o => o.CLASS_ID)));
                                ObjViewModel.liexaminvigilation = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamSettingId, ONLINE_EXAM_SETTING_ID = sOnlineExamsettingId, TIMETABLE_ID = sTimetableId, COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, sSQL, sAcademicYear).DataSource.Data;
                            }

                        }
                    }


                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindShuffleStudentInvigilation", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

