                            objModel.TOTAL_HOURS = liexaminvigilation.FirstOrDefault().TOTAL_HOURS;
                            objModel.EXAM_DATE = liexaminvigilation.FirstOrDefault().EXAM_DATE;
                            objModel.START_TIME = liexaminvigilation.FirstOrDefault().START_TIME;
                            objModel.END_TIME = liexaminvigilation.FirstOrDefault().END_TIME;


