                        if (liclass != null && liclass.Count > 0)
                        {
                            objModel.CLASS_ID = "<option value=0> -- Select -- </option>";
                            foreach (var item in liclass)
                            {
                                objModel.CLASS_ID += "<option value='" + item.CLASS_ID + "'>" + item.CLASS_NAME + "</option>";
                            }


                        }
                        //Fetch Timetable Info
                        var liexaminvigilation = (List<EXAM_INVIGILATION>)CMSHandler.FetchData<EXAM_INVIGILATION>(new EXAM_TIMETABLE() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATimetableInfoById), sAcademicYear).DataSource.Data;
