        #region examLog
        public JsonResult ExamStudentLog(string sLogInfo)
        {
            if (!string.IsNullOrEmpty(sLogInfo))
            {
                try
                {
                    string sImagePath = string.Empty;
                    string _sDirectorypath = string.Empty;
                    EXAM_STUDENT_LOG_INFO studentLog = JsonConvert.DeserializeObject<EXAM_STUDENT_LOG_INFO>(sLogInfo);
                    if (!string.IsNullOrEmpty(studentLog.ACADEMIC_YEAR))
                    {
                        if (!string.IsNullOrEmpty(studentLog.IMAGE_PATH))
                        {
                            _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.EXAM_STUDENT_LOG;

                            if (!Directory.Exists(_sDirectorypath))
                            {
                                Directory.CreateDirectory(_sDirectorypath);
                            }
                            sImagePath = Server.MapPath("\\" + Common.URLPages.EXAM_STUDENT_LOG) + "\\" + studentLog.EXAM_ID + "_" + studentLog.INVIGILATION_ID + "_" + studentLog.COURSE_ID + "_" + studentLog.STUDENT_ID + "_" + DateTime.Now.ToString("HH:mm:ss").Replace(":", "-") + ".png";
                            sImagePath = sImagePath.Replace(" ", "_");
                            using (FileStream fs = new FileStream(sImagePath, FileMode.Create))
                            {
                                using (BinaryWriter bw = new BinaryWriter(fs))
                                {
                                    byte[] data = Convert.FromBase64String(studentLog.IMAGE_PATH.Split(',')[1]);
                                    bw.Write(data);
                                    bw.Close();
                                }
                            }
                            studentLog.IMAGE_PATH = "\\" + Common.URLPages.EXAM_STUDENT_LOG + "\\" + studentLog.EXAM_ID + "_" + studentLog.INVIGILATION_ID + "_" + studentLog.COURSE_ID + "_" + studentLog.STUDENT_ID + "_" + DateTime.Now.ToString("HH:mm:ss").Replace(":", "-") + ".png";

                        }
                        resultArgs = CMSHandler.SaveOrUpdate(studentLog, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamStudentLogInfo), studentLog.ACADEMIC_YEAR);
                        objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                        objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                    }
                    else
                    {
                        objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        objJsonData.Message = Common.Messages.InvalidUserCredentials;
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "ExamStudentLog", ex.Message);
                    }
                    objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    objJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                objJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                objJsonData.Message = Common.Messages.InvalidUserCredentials;
            }
            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
