        public ActionResult BindAnswersandSheetsBySectionandInvigilation(string sSectionId, string sInvigilationId, string sEvaluationtype)
        {
            var ObjViewModel = new ExaminationViewModel();
            string sSql = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {

                // Fetch Invigilation Info ...
                var liinvigilation = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_INVIGILATION() { EXAM_INVIGILATION_ID = sInvigilationId },
                  SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoForByInvigilationId), sAcademicYear).DataSource.Data;
                if (liinvigilation != null && liinvigilation.Count > 0)
                {
                    //Match The Following Questin & Answer               
                    var liMatchTheFollowingQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                        new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMatchTheFollowingQuestionandAnswer), sAcademicYear).DataSource.Data;

                    //Objective Type Questions And Answers          
                    var liObjectiveQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                       new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                         SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectivesQuestionsandAnswer), sAcademicYear).DataSource.Data;
                    if (liObjectiveQuestions != null && liObjectiveQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liObjectiveQuestions).ToList() : liObjectiveQuestions;
                    }

                    // Fill In The Blank Questions And Answers              
                    var liFillInTheBlankQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                          new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                             SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFillInTheBlankQuestionsandAnswer), sAcademicYear).DataSource.Data;
                    if (liFillInTheBlankQuestions != null && liFillInTheBlankQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liFillInTheBlankQuestions).ToList() : liFillInTheBlankQuestions;
                    }

                    // Fetch  Either Questions  and Answers
                    var liEitherQuestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                           new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                             SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEitherExamQuestionsandAnswer), sAcademicYear).DataSource.Data;
                    if (liEitherQuestions != null && liEitherQuestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(liEitherQuestions).ToList() : liEitherQuestions;
                    }

                    //Fetch Either Question Option

                    if (liEitherQuestions != null && liEitherQuestions.Count > 0)
                    {
                        var quizids = string.Join(",", liEitherQuestions.Select(o => o.QUIZ_ID));
                        sSql = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchEitherOptionsByQuestionId).Replace(Common.Delimiter.QUS + Common.EXAM_QUESTIONS.QUIZ_ID, quizids);
                        var liEitherOptions = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(null, sSql, sAcademicYear).DataSource.Data;
                        if (liEitherOptions != null && liEitherOptions.Count > 0)
                        {
                            ObjViewModel.liexamoptions = liEitherOptions;
                        }
                    }

                    //Choose Based Questions & Answers
                    var lichoosebasedquestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                          new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchChooseBasedQuestionsandAnswer), sAcademicYear).DataSource.Data;
                    if (lichoosebasedquestions != null && lichoosebasedquestions.Count > 0)
                    {
                        liMatchTheFollowingQuestions = (liMatchTheFollowingQuestions != null && liMatchTheFollowingQuestions.Count > 0) ? liMatchTheFollowingQuestions.Concat(lichoosebasedquestions).ToList() : lichoosebasedquestions;
                    }
                    //Fetch All the Choice based Questions
                    var lichoosebasedallquestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(
                          new EXAM_EVALUATION() { SET_ID = liinvigilation.FirstOrDefault().SET_ID, INVIGILATION_ID = sInvigilationId, SECTION_ID = sSectionId, COURSE_ID = liinvigilation.FirstOrDefault().COURSE_ID, STUDENT_ID = liinvigilation.FirstOrDefault().STUDENT_ID, EVALUATION_TYPE = sEvaluationtype, EXAM_SETTING_ID = liinvigilation.FirstOrDefault().EXAM_SETTING_ID },
                            SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllChoiceBasedQuestions), sAcademicYear).DataSource.Data;
                    ObjViewModel.liexamquestionandanswerdetails = lichoosebasedallquestions;
                    ObjViewModel.Liexamquesions = liMatchTheFollowingQuestions;
                }

            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
        public JsonResult SaveEvaluationMarks(string sJsonData, string Evaluationtype, string sEvaluationId, string sInvigilationId)
        {
            var ObjJsonData = new JsonResultData();
            string sSQL = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjJson = JsonConvert.DeserializeObject<JSON_SAVE_EXAM_ANSWER>(sJsonData);


                    if (ObjJson.liEvaluationmark != null && ObjJson.liEvaluationmark.Count > 0)
                    {

                        foreach (var item in ObjJson.liEvaluationmark)
                        {
                            item.EVALUATION_ID = sEvaluationId;
                            item.EVALUATION_TYPE = Evaluationtype;
                            item.INVIGILATION_ID = sInvigilationId;

                            var CheckIsExist = (List<EXAM_EVALUATION_MARKS>)CMSHandler.FetchData<EXAM_EVALUATION_MARKS>(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsEvaluationMarksExist), sAcademicYear).DataSource.Data;
                            if (CheckIsExist != null && CheckIsExist.Count > 0)
                            {
                                //Update code has write
                            }
                            else
                            {
                                resultArgs = CMSHandler.SaveOrUpdate(item, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamEvaluationMarks), sAcademicYear);
                            }
                        }
                        ObjJsonData.Message = (resultArgs.Success) ? "Answers Submitted Successfully !" : "Failed to Save Answers Try Again !";
                        ObjJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.BadRequest;


                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveEvaluationMarks", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
