        public JsonResult SaveAutoEvaluationMarks(string sExamSettingId)
        {
            var ObjJsonData = new JsonResultData();
            string sSQL = string.Empty;
            string sSaveMarkSQL = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    //Check Is Auto Evaluation                
                    var CheckIsAutoEvaluation = (List<EXAM_ONLINE_EXAM_SETTING>)CMSHandler.FetchData<EXAM_ONLINE_EXAM_SETTING>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchOnlineExamSettingByExamSettingId), sAcademicYear).DataSource.Data;
                    if (CheckIsAutoEvaluation != null && CheckIsAutoEvaluation.Count > 0)
                    {
                        if (CheckIsAutoEvaluation.FirstOrDefault().IS_AUTO_EVALUATION == Common.IsActiveFalg.IsActive)
                        {
                            //Check Is Eligiable for Auto Evaluation
                            var lipatternsections = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamquestionpatternsection), sAcademicYear).DataSource.Data;
                            if (lipatternsections != null && lipatternsections.Count > 0)
                            {
                                string patternsectionids = string.Join(",", lipatternsections.Select(o => o.PATTERN_SECTION_ID));
                                string questiontype = Common.Question_Type.EitherQuestions + "," + Common.Question_Type.ChooseBasedQuestions;
                                sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsEligableforAutoEvaluation).Replace(Common.Delimiter.QUS + Common.EXAM_QUESTION_PATTERN.PATTERN_SECTION_ID, patternsectionids).Replace(Common.Delimiter.QUS + Common.EXAM_QUESTION_PATTERN.QUESTION_TYPE, questiontype);
                                var CheckIsEligible = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, sSQL, sAcademicYear).DataSource.Data;
                                if (CheckIsEligible != null && CheckIsEligible.Count > 0)
                                {
                                    //
                                    ObjJsonData.Message = "Please Check the question type for Auto Evaluation...!";
                                }
                                else
                                {
                                    sSaveMarkSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveAutoEvaluationMarks);
                                    //Objective Type Questions
                                    var liobjectivequestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchObjectiveQuestionsByExamSettingId), sAcademicYear).DataSource.Data;
                                    if (liobjectivequestions != null && liobjectivequestions.Count > 0)
                                    {
                                        var groupedcourse = liobjectivequestions.GroupBy(o => o.COURSE_ID).ToList();
                                        foreach (var course in groupedcourse)
                                        {
                                            //Fetch Students
                                            var listudent = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_INVIGILATION() { EXAM_SETTING_ID = sExamSettingId, COURSE_ID = course.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentListByCourseId), sAcademicYear).DataSource.Data;
                                            if (listudent != null && listudent.Count > 0)
                                            {
                                                foreach (var student in listudent)
                                                {


                                                    var coursequestion = liobjectivequestions.Where(o => o.COURSE_ID == course.FirstOrDefault().COURSE_ID);
                                                    foreach (var question in coursequestion)
                                                    {
                                                        var CheckIsEvaluationMarksExist = (List<EXAM_EVALUATION_MARKS>)CMSHandler.FetchData<EXAM_EVALUATION_MARKS>(new EXAM_EVALUATION_MARKS() { INVIGILATION_ID = listudent.FirstOrDefault().EXAM_INVIGILATION_ID, EVALUATION_ID = Common.IsActiveFalg.IsNotActive, EVALUATION_TYPE = Common.IsActiveFalg.IsNotActive, QUESTION_TYPE = question.QUESTION_TYPE, EXAM_SETTING_ID = sExamSettingId, QUESTION_ID = question.QUIZ_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsEvaluationMarksExist), sAcademicYear).DataSource.Data;
                                                        if (CheckIsEvaluationMarksExist != null && CheckIsEvaluationMarksExist.Count > 0)
                                                        {
                                                            //
                                                        }
                                                        else
                                                        {
                                                            //Fetch Student Save Answer
                                                            var listudentanswer = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = question.QUIZ_ID, COURSE_ID = question.COURSE_ID, STUDENT_ID = student.STUDENT_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.Fetchobjectiveanswers), sAcademicYear).DataSource.Data;
                                                            if (listudentanswer != null && listudentanswer.Count > 0)
                                                            {
                                                                if (listudentanswer.FirstOrDefault().STATUS == Common.IsActiveFalg.IsActive)
                                                                {
                                                                    sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','" + question.MARK_FOR_EACH_QUESTION + "','" + sExamSettingId + "','1','" + sAcademicYear + "'),";
                                                                }
                                                                else
                                                                {
                                                                    sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','0','" + sExamSettingId + "','1','" + sAcademicYear + "'),";

                                                                }
                                                            }
                                                            else
                                                            {
                                                                sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','0','" + sExamSettingId + "','1','" + sAcademicYear + "'),";

                                                            }

                                                        }

                                                    }
                                                }
                                            }

                                        }
                                        using (MySQLHandler ObjHandler = new MySQLHandler())
                                        {
                                            sSaveMarkSQL = sSaveMarkSQL.TrimEnd(',') + ";";
                                            var nExecuteQuery = ObjHandler.ExecuteAsScripts(sSaveMarkSQL);
                                            if (nExecuteQuery.Success && nExecuteQuery.RowsAffected != 0)
                                            {
                                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                            }
                                            else
                                            {
                                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                            }
                                        }

                                    }
                                    sSaveMarkSQL = string.Empty;
                                    sSaveMarkSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveAutoEvaluationMarks);
                                    //Fill the Blanks Type Questions
                                    var lifilltheblanksquestions = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFilltheBlanksQuestionsByExamSettingId), sAcademicYear).DataSource.Data;
                                    if (lifilltheblanksquestions != null && lifilltheblanksquestions.Count > 0)
                                    {
                                        var groupedcourse = lifilltheblanksquestions.GroupBy(o => o.COURSE_ID).ToList();
                                        foreach (var course in groupedcourse)
                                        {
                                            //Fetch Students
                                            var listudent = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_INVIGILATION() { EXAM_SETTING_ID = sExamSettingId, COURSE_ID = course.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentListByCourseId), sAcademicYear).DataSource.Data;
