                                                        var CheckIsEvaluationMarksExist = (List<EXAM_EVALUATION_MARKS>)CMSHandler.FetchData<EXAM_EVALUATION_MARKS>(new EXAM_EVALUATION_MARKS() { INVIGILATION_ID = listudent.FirstOrDefault().EXAM_INVIGILATION_ID, EVALUATION_ID = Common.IsActiveFalg.IsNotActive, EVALUATION_TYPE = Common.IsActiveFalg.IsNotActive, QUESTION_TYPE = question.QUESTION_TYPE, EXAM_SETTING_ID = sExamSettingId, QUESTION_ID = question.QUIZ_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsEvaluationMarksExist), sAcademicYear).DataSource.Data;
                                                        if (CheckIsEvaluationMarksExist != null && CheckIsEvaluationMarksExist.Count > 0)
                                                        {
                                                            //
                                                        }
                                                        else
                                                        {
                                                            //Fetch Student Save Answer
                                                            var listudentanswer = (List<EXAM_OBJECTIVE_QUESTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_QUESTIONS>(new EXAM_OBJECTIVE_QUESTIONS() { QUIZ_ID = question.QUIZ_ID, COURSE_ID = question.COURSE_ID, STUDENT_ID = student.STUDENT_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.Fetchobjectiveanswers), sAcademicYear).DataSource.Data;
                                                            if (listudentanswer != null && listudentanswer.Count > 0)
                                                            {
                                                                if (listudentanswer.FirstOrDefault().STATUS == Common.IsActiveFalg.IsActive)
                                                                {
                                                                    sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','" + question.MARK_FOR_EACH_QUESTION + "','" + sExamSettingId + "','1','" + sAcademicYear + "'),";
                                                                }
                                                                else
                                                                {
                                                                    sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','0','" + sExamSettingId + "','1','" + sAcademicYear + "'),";

                                                                }
                                                            }
                                                            else
                                                            {
                                                                sSaveMarkSQL += "('" + student.EXAM_INVIGILATION_ID + "',0,'" + question.QUIZ_ID + "','" + question.QUESTION_TYPE + "','" + question.MARK_FOR_EACH_QUESTION + "','0','" + sExamSettingId + "','1','" + sAcademicYear + "'),";

                                                            }

                                                        }

                                                    }
                                                }
                                            }

                                        }
                                        using (MySQLHandler ObjHandler = new MySQLHandler())
                                        {
                                            sSaveMarkSQL = sSaveMarkSQL.TrimEnd(',') + ";";
                                            var nExecuteQuery = ObjHandler.ExecuteAsScripts(sSaveMarkSQL);
                                            if (nExecuteQuery.Success && nExecuteQuery.RowsAffected != 0)
                                            {
                                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
