        public ActionResult BindExamEvaluationEntry(string sExamSettingId, string sTimetableId, string sAcademicYear, string sExamEvaluationType, string sExamtype)
        {

            var ObjViewModel = new ExaminationViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    if (sExamtype == Common.EXAM_TYPE.EXTERNAL)
                    {
                        // timetable by id FetchExamTimeTableById
                        ObjViewModel.liExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { TIMETABLE_ID = sTimetableId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchTimeTableByTimetableId)).DataSource.Data;
                        if (ObjViewModel.liExamTimeTable != null && ObjViewModel.liExamTimeTable.Count > 0)
                        {

                            //  Course List ...,
                            ObjViewModel.liCourseRoot = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseRootInfoByCourseId)).DataSource.Data;

                            // Entered Student Count ...,
                            ObjViewModel.liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new EXAM_EVALUATION() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, EVALUATION_TYPE = sExamEvaluationType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAssignedEvaluationStudentCount)).DataSource.Data;

                            // Did not Enter Student List...,
                            ObjViewModel.LiExamEvaluation = (List<EXAM_EVALUATION>)CMSHandler.FetchData<EXAM_EVALUATION>(new EXAM_EVALUATION() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, EVALUATION_TYPE = sExamEvaluationType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchBindExamEvaluationEntry), sAcademicYear).DataSource.Data;
                        }
                    }
                    else if (sExamtype == Common.EXAM_TYPE.INTERNAL)
                    {
                        // timetable by id FetchExamTimeTableById
                        ObjViewModel.liExamTimeTable = (List<EXAM_TIMETABLE>)CMSHandler.FetchData<EXAM_TIMETABLE>(new EXAM_TIMETABLE() { TIMETABLE_ID = sTimetableId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCIATimeTableByTimetableId)).DataSource.Data;
                        if (ObjViewModel.liExamTimeTable != null && ObjViewModel.liExamTimeTable.Count > 0)
                        {

                            //  Course List ...,
                            ObjViewModel.liCourseRoot = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_ID = ObjViewModel.liExamTimeTable.FirstOrDefault().COURSE_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseRootInfoByCourseId)).DataSource.Data;

                            // Entered Student Count ...,
                            ObjViewModel.liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new EXAM_EVALUATION() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, EVALUATION_TYPE = sExamEvaluationType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAssignedEvaluationStudentCount)).DataSource.Data;

                            // Did not Enter Student List...,
                            ObjViewModel.LiExamEvaluation = (List<EXAM_EVALUATION>)CMSHandler.FetchData<EXAM_EVALUATION>(new EXAM_EVALUATION() { EXAM_SETTING_ID = sExamSettingId, TIMETABLE_ID = sTimetableId, EVALUATION_TYPE = sExamEvaluationType }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchBindExamEvaluationEntry), sAcademicYear).DataSource.Data;
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindShuffleStudentInvigilation", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }

        public JsonResult SaveExamEvaluationEntry(string sJson, string sExamSettingId)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            int dummy = 0;
            string sdummy = string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var ObjJson = JsonConvert.DeserializeObject<SaveExamDetails>(sJson);
                    if (ObjJson.liJsonExamEvaluation != null && ObjJson.liJsonExamEvaluation.Count > 0)
                    {
                        string sSQL = @"INSERT INTO EXAM_EVALUATION (INVIGILATION_ID, EVALUATOR_ID, EVALUATION_TYPE, EVALUATION_DATE, DUMMY_NO, ACADEMIC_YEAR)VALUES";
                        var FetchLastDummyNo = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchLastUpdateDummyNo), sAcademicYear).DataSource.Data;
                        if (FetchLastDummyNo != null && FetchLastDummyNo.Count > 0)
                            dummy = Convert.ToInt32(FetchLastDummyNo.FirstOrDefault().DUMMY_NO);
                        foreach (var item in ObjJson.liJsonExamEvaluation)
                        {
                            dummy++;
                            item.DUMMY_NO = (dummy.ToString().PadLeft(5, '0'));
                            sSQL += "('" + item.INVIGILATION_ID + "','" + item.EVALUATOR_ID + "','" + item.EVALUATION_TYPE + "','" + CommonMethods.DateConvertionForPayU(item.EVALUATION_DATE) + "','" + item.DUMMY_NO + "','" + sAcademicYear + "'),";
                            dummy = Convert.ToInt32(item.DUMMY_NO);
                            sdummy = item.DUMMY_NO;
                        }
                        var UpdateDummyNO = CMSHandler.SaveOrUpdate(new EXAM_SETTING() { EXAM_SETTING_ID = sExamSettingId, DUMMY_NO = sdummy }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateLastDummyNoByExamSetting));
                        using (MySQLHandler ObjHandler = new MySQLHandler())
                        {
                            sSQL = sSQL.TrimEnd(',') + ";";
                            var nExecuteQuery = ObjHandler.ExecuteAsScripts(sSQL);
                            if (nExecuteQuery.Success && nExecuteQuery.RowsAffected != 0)
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                ObjJsonData.Message = "( " + ObjJson.liJsonExamEvaluation.Count + " )" + Common.Messages.RecordsSavedSuccessfully;
                            }
                            else
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                ObjJsonData.Message = "( " + ObjJson.liJsonExamEvaluation.Count + " )" + Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }
                    else
                    {
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        ObjJsonData.Message = "Json value is invalied !";
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExamEvaluationEntry", ex.Message);
                    }
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

