        public string UpdateExamMarks(string sJsonData)
        {

            var ObjViewModel = new ExaminationViewModel();
            string sSQL = string.Empty;
            try
            {
                var ObjJson = JsonConvert.DeserializeObject<JSON_SAVE_EXAM_ANSWER>(sJsonData);
                if (ObjJson.liEvaluationmark != null && ObjJson.liEvaluationmark.Count > 0)
                {
                    foreach (var item in ObjJson.liEvaluationmark)
                    {
                        sSQL += @"UPDATE EXAM_EVALUATION_MARKS SET SECURED_MARK = '" + item.SECURED_MARK + "' WHERE EXAM_EVALUATION_MARK_ID ='" + item.EXAM_EVALUATION_MARK_ID + "';";
                    }
                }
                using (MySQLHandler mySQLHandler = new MySQLHandler())
                {
                    resultArgs = mySQLHandler.ExecuteAsScripts(sSQL);
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "UpdateExamMarks", ex.Message);
                }
            }

            return (resultArgs.Success) ? "Success" : "Failed";
        }
