        public JsonResult SaveorUpdateOnlineExamSettings(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    var Result = JsonConvert.DeserializeObject<EXAM_ONLINE_EXAM_SETTING>(sJsonData);
                    if (!string.IsNullOrEmpty(Result.ONLINE_EXAM_SETTING_ID))
                    {
                        resultArgs = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamOnlineExamSetting), sAcademicYear);
                        objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                        objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;

                    }
                    else
                    {

                        //Check Is Exist
                        var CheckIsExist = (List<EXAM_ONLINE_EXAM_SETTING>)CMSHandler.FetchData<EXAM_ONLINE_EXAM_SETTING>(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckIsOnlneExamSettingExist), sAcademicYear).DataSource.Data;
                        if (CheckIsExist != null && CheckIsExist.Count > 0)
                        {
                            objJsonData.Message = "Setting is exist for this Exam...!";
                        }
                        else
                        {
                            resultArgs = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveExamOnlineExamSetting), sAcademicYear);
                            objJsonData.ErrorCode = (resultArgs.Success) ? Common.ErrorCode.Accepted : Common.ErrorCode.NotAcceptable;
                            objJsonData.Message = (resultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        }
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveorUpdateOnlineExamSettings", ex.Message);
                    }
                }

            }
            else
            {
                objJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }

            return Json(objJsonData, JsonRequestBehavior.AllowGet);
        }
        public JsonResult ActivateOrDeActivateOnlineexamSettings(string sSettingid, string sFieldname, string sValue)
        {
            string sSQL = string.Empty;
            var ObjJsonData = new JsonResultData();
            try
            {

                sSQL = @"UPDATE EXAM_ONLINE_EXAM_SETTING 
                            SET 
                                " + sFieldname + " =" + sValue + " WHERE ONLINE_EXAM_SETTING_ID = " + sSettingid + ";";
                var ActivateOrDeActivate = CMSHandler.SaveOrUpdate(null, sSQL);
                if (ActivateOrDeActivate.Success && ActivateOrDeActivate.RowsAffected != 0)
                {
                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                }
                else
                {
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("ExaminationController", "ActivateOrDeActivateExamByInvigilator", ex.Message);
                }
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
