                        objViewModel.ClassList = new SelectList(ClassList, Common.CP_CLASSES_2017.CLASS_ID, Common.CP_CLASSES_2017.CLASS_NAME);
                    var courseList = (List<cp_Course_Root_2017>)CMSHandler.FetchData<cp_Course_Root_2017>(new CourseWiseStaffList() { STAFF_ID = sUser_Id },

                            ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseListbySemesterType), sAcademicYear).DataSource.Data;
                    if (courseList != null && courseList.Count > 0)
                        objViewModel.CourseList = new SelectList(courseList, Common.CP_COURSE_ROOT_2017.COURSE_ROOT_ID, Common.CP_COURSE_ROOT_2017.COURSE_TITLE);

                    //Fetch Set List 
