        public JsonResult SaveQuizQuestionImportadmin()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserid = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            var ObjViewModel = new ExaminationViewModel();
            int questioncount = 0;
            string sSQLquestion = string.Empty;
            string sSQLoption = string.Empty;

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var sClassId = Request.Form["sClassId"];
                    var sCourseId = Request.Form["sCourseId"];
                    var sSettingId = Request.Form["sSettingId"];
                    var sExcit = DapperHandler.FetchAll<QUIZ_QUESTIONS_2017>(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizQuestionBySettingId), new { SETTING_ID = sSettingId }, sAcademicYear).ToList();
                    if (sExcit != null && sExcit.Count > 0)
                    {
                        var deleted = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.DeleteQuizBySettingId), new { SETTING_ID = sSettingId });
                    }

                    if (Request.Files.Count > 0)
                    {
                        string[] validFileTypes = { ".xls", ".xlsx" };
                        string path1 = Server.MapPath($"~/Content/Uploads/Quizquestions/SettingId_{sSettingId}/{Request.Files[0].FileName}");
                        string extension = System.IO.Path.GetExtension(Request.Files[0].FileName).ToLower();

                        if (!Directory.Exists(Server.MapPath($"~/Content/Uploads/Quizquestions/SettingId_{sSettingId}")))
                        {
                            Directory.CreateDirectory(Server.MapPath($"~/Content/Uploads/Quizquestions/SettingId_{sSettingId}"));
                        }

                        if (validFileTypes.Contains(extension))
                        {
                            if (System.IO.File.Exists(path1))
                            {
                                System.IO.File.Delete(path1);
                            }
                            Request.Files[0].SaveAs(path1);

                            ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                            using (var package = new ExcelPackage(new FileInfo(path1)))
                            {
                                ExcelWorksheet worksheet = package.Workbook.Worksheets[0];
                                int rowCount = worksheet.Dimension.Rows;
                                for (int row = 2; row <= rowCount; row++)
                                {
                                    string code = worksheet.Cells[row, 3].Text;
                                    string questionText = worksheet.Cells[row, 2].Text;
                                    string mark = worksheet.Cells[row, 12].Text;
                                    string set = worksheet.Cells[row, 11].Text;
                                    string answer = worksheet.Cells[row, 10].Text;
                                    string optionA = worksheet.Cells[row, 4].Text;
                                    string optionB = worksheet.Cells[row, 5].Text;
                                    string optionC = worksheet.Cells[row, 6].Text;
                                    string optionD = worksheet.Cells[row, 7].Text;
                                    string optionE = worksheet.Cells[row, 8].Text;
                                    string optionF = worksheet.Cells[row, 9].Text;

                                    if (!string.IsNullOrEmpty(code))
                                    {
                                        sSQLquestion = @"INSERT INTO QUIZ_OBJECTIVE_QUESTIONS(ENTRY_ID,CLASS_ID,COURSE_ID,QUESTION,MARK,SET_ID,QUESTION_TYPE,ACADEMIC_YEAR,SEMESTER_ID,SETTING_ID) VALUES";
                                        sSQLoption = @"INSERT INTO QUIZ_OBJECTIVE_OPTIONS(`OPTION`,QUIZ_ID,SET_ID,SETTING_ID) VALUES";

                                        if (!string.IsNullOrEmpty(questionText))
                                        {
                                            questionText = string.Concat("<p>", questionText, "</p>");
                                            var liCourseList = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(new CP_COURSE_ROOT() { COURSE_CODE = code }, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseInfoByCode), sAcademicYear).DataSource.Data;

                                            if (liCourseList != null && liCourseList.Count > 0)
                                            {
                                                sSQLquestion += "('" + sUserid + "','" + sClassId + "','" + sCourseId + "','" + ObjViewModel.DecodeStrigToBase64String(questionText) + "','" + mark + "','" + set + "',1,'" + sAcademicYear + "','" + liCourseList.FirstOrDefault().SEMESTER_ID + "','" + sSettingId + "'),";
                                                sSQLquestion = sSQLquestion.TrimEnd(',') + ";";
                                                var savequestion = CMSHandler.SaveOrUpdate(null, sSQLquestion, sAcademicYear, true);

                                                if (savequestion.Success)
                                                {
                                                    sSQLoption += BuildOptionSQL(optionA, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);
                                                    sSQLoption += BuildOptionSQL(optionB, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);
                                                    sSQLoption += BuildOptionSQL(optionC, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);
                                                    sSQLoption += BuildOptionSQL(optionD, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);
                                                    sSQLoption += BuildOptionSQL(optionE, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);
                                                    sSQLoption += BuildOptionSQL(optionF, savequestion.RowUniqueId.ToString(), set, sSettingId, ObjViewModel);

                                                    sSQLoption = sSQLoption.TrimEnd(',') + ";";
                                                    var saveoption = CMSHandler.SaveOrUpdate(null, sSQLoption, sAcademicYear);

                                                    if (saveoption.Success)
                                                    {
                                                        string selectedAnswer = GetSelectedAnswer(answer, optionA, optionB, optionC, optionD, optionE, optionF);
                                                        selectedAnswer = string.Concat("<p>", selectedAnswer, "</p>");
                                                        var answeroption = (List<EXAM_OBJECTIVE_OPTIONS>)CMSHandler.FetchData<EXAM_OBJECTIVE_OPTIONS>(new EXAM_OBJECTIVE_OPTIONS() { ANSWER = ObjViewModel.DecodeStrigToBase64String(selectedAnswer), QUIZ_ID = savequestion.RowUniqueId.ToString() }, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchObjectiveOptionIdByOptionForQuiz), sAcademicYear).DataSource.Data;

                                                        if (answeroption != null && answeroption.Count > 0)
                                                        {
                                                            var sUpdateAnswer = CMSHandler.SaveOrUpdate(new EXAM_OBJECTIVE_QUESTIONS() { ANSWER_ID = answeroption.FirstOrDefault().OPTION_ID, QUIZ_ID = savequestion.RowUniqueId.ToString() }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateQuizAnswerForObjExamQuestions), sAcademicYear);
                                                        }
                                                    }
                                                    questioncount++;
                                                }
                                            }
                                            else
                                            {
                                                ObjJsonData.Message += code + ",";
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveQuizQuestionImport", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            ObjJsonData.Message = questioncount + " Questions Saved..!";
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        private string BuildOptionSQL(string optionText, string quizId, string set, string settingId, ExaminationViewModel viewModel)
        {
            if (!string.IsNullOrEmpty(optionText))
            {
                optionText = string.Concat("<p>", optionText, "</p>");
                return $"('{viewModel.DecodeStrigToBase64String(optionText)}','{quizId}','{set}','{settingId}'),";
            }
            return string.Empty;
        }

        private string GetSelectedAnswer(string answer, string optionA, string optionB, string optionC, string optionD, string optionE, string optionF)
        {
            string selectedAnswer = string.Empty;

            switch (answer)
            {
                case "A":
                    selectedAnswer = optionA;
                    break;
                case "B":
                    selectedAnswer = optionB;
                    break;
                case "C":
                    selectedAnswer = optionC;
                    break;
                case "D":
                    selectedAnswer = optionD;
                    break;
                case "E":
                    selectedAnswer = optionE;
                    break;
                case "F":
                    selectedAnswer = optionF;
                    break;
                default:
                    selectedAnswer = string.Empty;
                    break;
            }

            return selectedAnswer;
        }
