                    //ObjModel.CLASS_YEAR = sClassYearId;
                    ObjModel.APPLICATION_TYPE_ID = sApplicationType;
                    ObjModel.CLASS_YEAR = sClassYearId;
                    ObjModel.SEMESTER_TYPE_ID = sSemesterTypeId;
                    ObjModel.SEMESTER_ID = sSemesterId;
                    ObjViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                    // Fetch Courses From Course Pattern .
                    string sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseByYearAndClassIdAndSemesterIdforHOD).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId).Replace("?CLASS_ID", sClassID);
                    var liCourseInfo = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL, sAcYear).DataSource.Data;

                    if (liCourseInfo != null && liCourseInfo.Count > 0)
                    {
                        //liCourseInfo.RemoveAll(x => x.UGC_COURSE_TYPE == "17");
                        //liCourseInfo.RemoveAll(x => x.COURSE_ROOT_ID!="369" && x.COURSE_ROOT_ID!="423" && x.COURSE_ROOT_ID != "83");
                        ObjViewModel.liCourseInfo = liCourseInfo;
                        //ObjModel.COURSE_ID = item.COURSE_ROOT_ID;

                        sSQL = string.Empty;
                        sSQL = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindYearWishCIAFailMarksForHOD).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId).Replace("?CLASS_ID", sClassID);
                        liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(ObjModel, sSQL, sAcYear).DataSource.Data;


                        //liCIATotal = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(ObjModel,
                        //    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.BindYearCIAMarksForCOESJC), sAcYear).DataSource.Data;

                        if (liCIATotal != null && liCIATotal.Count > 0)
                        {
                            liCIATotal.ForEach(o => o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString());
                            ObjViewModel.liCIA_Total = (ObjViewModel.liCIA_Total != null) ? ObjViewModel.liCIA_Total.Concat(liCIATotal).ToList() : liCIATotal;
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindClassWiseCIAMark", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
            }
            return View(ObjViewModel);
        }
