        public JsonResult SaveOrUpdateExamHallticket()
        {
            FeeTransactionViewModel ObjViewModel = new FeeTransactionViewModel();
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStaffId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var filename = Request.Files[0].FileName;
            HttpPostedFileBase file = Request.Files[filename];
            var sFilename = Request.Files[0].FileName.Split('.');
            string columnName = string.Empty;
            string paidDateColumn = string.Empty;
            int SuccessCount = 0;
            int FailCount = 0;
            string sMessage = string.Empty;
            string updateSQL = string.Empty;
            string insertSQL = string.Empty;
            var CurrentDate = DateTime.Now.ToString("yyyy-MM-dd");

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    string ExamSettingId = Request.Form["ExamSetting"];
                    string extension = System.IO.Path.GetExtension(Request.Files[0].FileName).ToLower();

                    string[] validFileTypes = { ".xls", ".xlsx", ".csv" };
                    string path1 = string.Format("{0}/{1}", Server.MapPath("~/Content/Uploads/HallTicket/" + sAcademicYear), Request.Files[0].FileName);

                    if (!Directory.Exists(path1))
                    {
                        Directory.CreateDirectory(Server.MapPath("~/Content/Uploads/HallTicket/" + sAcademicYear));
                    }
                    // Save File
                    if (System.IO.File.Exists(path1))
                    {
                        System.IO.File.Delete(path1);
                    }
                    Request.Files[0].SaveAs(path1);

                    byte[] fileBytes;
                    using (var binaryReader = new BinaryReader(Request.Files[0].InputStream))
                    {
                        fileBytes = binaryReader.ReadBytes(Request.Files[0].ContentLength);
                    }

                    if (validFileTypes.Contains(extension))
                    {
                        var objExamHallTicketList = new STU_HALL_TICKET();

                        using (var package = new ExcelPackage(new MemoryStream(fileBytes)))
                        {
                            ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                            var worksheet = package.Workbook.Worksheets[0];
                            var studentHallTicketDetails = new List<STU_HALL_TICKET>();
                            var objHall = new STU_HALL_TICKET();
                            if (worksheet.Dimension.End.Row <= 1 || worksheet.Dimension.End.Column < 2)
                            {
                                ObjJsonData.Message = "The uploaded file is empty or improperly formatted.";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                return Json(ObjJsonData);
                            }
                            else
                            {
                                for (int row = 2; row <= worksheet.Dimension.End.Row; row++)
                                {
                                    bool isValidRow = !string.IsNullOrWhiteSpace(worksheet.Cells[row, 1].Text);
                                    if (isValidRow)
                                    {
                                        var liStuHallticketList = new STU_HALL_TICKET
                                        {
                                            ROLL_NO = worksheet.Cells[row, 1].Text,
                                            FIRST_NAME = worksheet.Cells[row, 2].Text,
                                            DATE_OF_BIRTH = worksheet.Cells[row, 3].Text,
                                            REGISTER_NO = worksheet.Cells[row, 4].Text,
                                            COURSE_CODE = worksheet.Cells[row, 5].Text,
                                            DATE_OF_EXAM = worksheet.Cells[row, 6].Text,
                                            SESSION_NAME = worksheet.Cells[row, 7].Text,
                                            HALL_NAME = worksheet.Cells[row, 8].Text,
                                            ELIGIBLE_TYPE = worksheet.Cells[row, 9].Text,
                                        };
                                        studentHallTicketDetails.Add(liStuHallticketList);
                                    }
                                }
                            }
                            if (studentHallTicketDetails != null && studentHallTicketDetails.Count > 0)
                            {
                                var semesterActiveType = (List<SUP_SEMESTER_TYPE>)CMSHandler.FetchData<SUP_SEMESTER_TYPE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.GetActiveSemesterType), sAcademicYear).DataSource.Data;
                                if (semesterActiveType != null)
                                {
                                    var liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(null, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentInfo), sAcademicYear).DataSource.Data;
                                    //var liStudentList = DapperHandler.FetchAll<STU_PERSONAL_INFO>(SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchDemoTestTable)).ToList();
                                    var liCourseList = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(null, SQL.SupportData.SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourse), sAcademicYear).DataSource.Data;
                                    var semester_type = semesterActiveType.FirstOrDefault().SEMESTER_TYPE_ID;
                                    var CheckHallTicketExistOrNot = (List<STU_HALL_TICKET>)CMSHandler.FetchData<STU_HALL_TICKET>(new STU_HALL_TICKET() { EXAM_SETTING_ID = ExamSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckHallTicketExistOrNot), sAcademicYear).DataSource.Data;

                                    foreach (var dr in studentHallTicketDetails)
                                    {
                                        dr.ROLL_NO = dr.ROLL_NO.ToUpper().Replace(" ", "");
                                        dr.REGISTER_NO = dr.REGISTER_NO.ToUpper().Replace(" ", "");
                                        dr.DATE_OF_BIRTH = dr.DATE_OF_BIRTH.Replace(" ", "");
                                        dr.COURSE_CODE = dr.COURSE_CODE.ToUpper().Replace(" ", "");
                                        dr.DATE_OF_EXAM = dr.DATE_OF_EXAM.Replace(" ", "");
                                        dr.SESSION_NAME = dr.SESSION_NAME.ToUpper().Replace(" ", "");
                                        var courseId = liCourseList.Where(o => o.COURSE_TITLE == dr.COURSE_CODE).ToList();
                                        var student_id = liStudentList.Where(o => o.ROLL_NO == dr.ROLL_NO).ToList();
                                        if (student_id != null && student_id.Count > 0)
                                        {
                                            if (courseId != null && courseId.Count > 0)
                                            {
                                                //var listuHallTicket = (List<STU_HALL_TICKET>)CMSHandler.FetchData<STU_HALL_TICKET>(new STU_HALL_TICKET() { COURSE_CODE = dr.COURSE_CODE, ROLL_NO = dr.ROLL_NO, SEMESTER_TYPE = semester_type }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallticketDAlreadyExistOrNot), sAcademicYear).DataSource.Data;
                                                //if (hallTicketExist != null && hallTicketExist.Count > 0)
                                                //{
                                                if (dr.ELIGIBLE_TYPE == "Eligible")
                                                {
                                                    objHall.ELIGIBLE_TYPE = "1";
                                                }
                                                else
                                                {
                                                    objHall.ELIGIBLE_TYPE = "2";
                                                }
                                                if (dr.DATE_OF_EXAM != "")
                                                {
                                                    dr.DATE_OF_EXAM = CommonMethods.DateConvertionForPayU(dr.DATE_OF_EXAM);

                                                }
                                                if (dr.DATE_OF_BIRTH != "")
                                                {
                                                    if (dr.DATE_OF_BIRTH != "__/__/____")
                                                    {
                                                        dr.DATE_OF_BIRTH = CommonMethods.DateConvertionForPayU(dr.DATE_OF_BIRTH);
                                                    }

                                                }
                                                //objHall.STUDENT_ID = listuHallTicket.FirstOrDefault().STUDENT_ID;
                                                objHall.STUDENT_ID = student_id.FirstOrDefault().STUDENT_ID;
                                                objHall.COURSE_ID = courseId.FirstOrDefault().COURSE_ROOT_ID;
                                                //objHall.COURSE_ID = listuHallTicket.FirstOrDefault().COURSE_ID;
                                                objHall.FIRST_NAME = dr.FIRST_NAME;
                                                objHall.REGISTER_NO = dr.REGISTER_NO;
                                                if (dr.DATE_OF_BIRTH != "__/__/____")
                                                {
                                                    objHall.DATE_OF_BIRTH = dr.DATE_OF_BIRTH;
                                                }
                                                objHall.DATE_OF_EXAM = dr.DATE_OF_EXAM;
                                                objHall.SESSION_NAME = dr.SESSION_NAME;
                                                objHall.HALL_NAME = dr.HALL_NAME;
                                                objHall.EXAM_SETTING_ID = ExamSettingId;
                                                objHall.SEMESTER_TYPE = semester_type;
                                                objHall.ACADEMIC_YEAR = sAcademicYear;
                                                if (CheckHallTicketExistOrNot != null)
                                                {
                                                    var hallTicketExist = CheckHallTicketExistOrNot.Where(x => x.COURSE_ID == courseId.FirstOrDefault().COURSE_ROOT_ID && x.STUDENT_ID == student_id.FirstOrDefault().STUDENT_ID).ToList();
                                                    if (!string.IsNullOrEmpty(hallTicketExist.FirstOrDefault().HALL_TICKET_ID))
                                                    {
                                                        objHall.HALL_TICKET_ID = hallTicketExist.FirstOrDefault().HALL_TICKET_ID;

                                                    }
                                                }
                                                if (!string.IsNullOrEmpty(objHall.HALL_TICKET_ID))
                                                {
                                                    var UpdateExamHallTicketList = CMSHandler.SaveOrUpdate(objHall, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateStuHallTicket));

                                                    if (UpdateExamHallTicketList.Success)
                                                    {
                                                        SuccessCount++;
                                                    }
                                                    else
                                                    {
                                                        FailCount++;
                                                        sMessage = "Fail To Update Record Roll No :" + dr.ROLL_NO + ":: Course Code : " + dr.COURSE_CODE;

                                                        using (ErrorLog ObjLog = new ErrorLog())
                                                        {
                                                            ObjLog.examHallTicketLog(sMessage, CurrentDate);
                                                        }
                                                    }
                                                }
                                                else
                                                {
                                                    var InsertExamHallTicketList = CMSHandler.SaveOrUpdate(objHall, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveStuHallTicket));

                                                    if (InsertExamHallTicketList.Success)
                                                    {
                                                        SuccessCount++;
                                                    }
                                                    else
                                                    {
                                                        FailCount++;
                                                        sMessage = "Fail To Save Record Roll No :" + dr.ROLL_NO + ":: Course Code : " + dr.COURSE_CODE;

                                                        using (ErrorLog ObjLog = new ErrorLog())
                                                        {
                                                            ObjLog.examHallTicketLog(sMessage, CurrentDate);
                                                        }
                                                    }
                                                }
                                                //}
                                                //else
                                                //{
                                                //    FailCount++;
                                                //    sMessage = "Given Course Code Not Exist :" + dr.ROLL_NO + " :: Course Code : " + dr.COURSE_CODE;

                                                //    using (ErrorLog ObjLog = new ErrorLog())
                                                //    {
                                                //        ObjLog.examHallTicketLog(sMessage, CurrentDate);
                                                //    }
                                                //}
                                            }
                                            else
                                            {
                                                FailCount++;
                                                sMessage = "Given Roll No Not Exist :" + dr.ROLL_NO + " :: Course Code : " + dr.COURSE_CODE;

                                                using (ErrorLog ObjLog = new ErrorLog())
                                                {
                                                    ObjLog.examHallTicketLog(sMessage, CurrentDate);
                                                }
                                            }

                                        }
                                        else
                                        {
                                            FailCount++;
                                            sMessage = "Given Roll No or Course Code Not Exist :" + dr.ROLL_NO + " :: Course Code : " + dr.COURSE_CODE;

                                            using (ErrorLog ObjLog = new ErrorLog())
                                            {
                                                ObjLog.examHallTicketLog(sMessage, CurrentDate);
                                            }
                                        }
                                    }
                                    ObjJsonData.ErrorCode = (SuccessCount != 0) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                                    ObjJsonData.Message = SuccessCount + " Record(s) Saved Successfully !!! , " + FailCount + " Failed To Save Record(s) !!!";
                                }
                                else
                                {
                                    ObjJsonData.Message = "Active Semester Type not Found";
                                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                }


                            }
                            else
                            {
                                ObjJsonData.Message = "Oops! File Con't be Read";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }

                        }

                    }
                    else
                    {
                        ObjJsonData.Message = "In Valid File Type Oops! { '.xls', '.xlsx', '.csv' } This format Only Accepted";
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }
                }
                catch (Exception ex)
                {
                    sMessage = ex.Message;

                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.FeeDueFileLog(sMessage, CurrentDate);
                    }
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Fee", "SaveFeePaymentUpdates", ex.Message);
                        ObjJsonData.Message = ex.Message;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;

                        return Json(ObjJsonData);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            if (string.IsNullOrEmpty(ObjJsonData.Message))
            {
                ObjJsonData.Message = "No Changes Made !";
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData);
        }
        #endregion

