        public ActionResult ApproveToGetExamHallTicket(string sStudentID, string sexamSetting, string sApprovalStatus, string sAcYear, string sDaysCount, string sRemark)
        {
            FeeTransactionViewModel ObjViewModel = new FeeTransactionViewModel();
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string userId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var objModel = new EXAM_HALLTICKET_SPECIAL_APPROVALS();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    if (sStudentID != null && sexamSetting != null && sApprovalStatus != null)
                    {
                        var ValidTo = DateTime.Now.AddDays(Convert.ToInt64(sDaysCount)).ToString("yyyy-MM-dd");
                        var CurrentDate = DateTime.Now.ToString("yyyy-MM-dd");
                        var CurrentDatetime = DateTime.Now.ToString("yyyy-MM-dd hh:mm:ss");
                        objModel.EXAM_SETTING_ID = sexamSetting;
                        objModel.STUDENT_ID = sStudentID;
                        objModel.IS_APPROVED = sApprovalStatus;
                        objModel.ACADEMIC_YEAR = sAcYear;
                        objModel.APPROVED_BY = userId;
                        objModel.APPROVAL_REASON = sRemark;
                        objModel.APPROVAL_DAYS = sDaysCount;
                        objModel.APPROVAL_DATE = CurrentDatetime;
                        objModel.VALID_TO = CurrentDate;
                        objModel.VALID_FROM = Convert.ToString(ValidTo);

                        var checkAlreadyExist = (List<EXAM_HALLTICKET_SPECIAL_APPROVALS>)CMSHandler.FetchData<EXAM_HALLTICKET_SPECIAL_APPROVALS>(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHTSpecialApprovalsForCheckExist), sAcademicYear).DataSource.Data;

                        if (checkAlreadyExist != null && checkAlreadyExist.Count > 0)
                        {
                            objModel.APPROVAL_ID = checkAlreadyExist.FirstOrDefault().APPROVAL_ID;

                            var UpdateExamHallticketSpecialApproval = CMSHandler.SaveOrUpdate(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExamHTSpecialApprovals), sAcYear);
                            if (UpdateExamHallticketSpecialApproval.Success)
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                ObjJsonData.Message = " Record(s) Updated Successfully !!! ";
                            }
                            else
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                ObjJsonData.Message = "Fail To update Record ";
                            }
                        }
                        else
                        {
                            var saveExamVerificationStatus = CMSHandler.SaveOrUpdate(objModel, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.saveExamHTSpecialApprovals), sAcYear);
                            if (saveExamVerificationStatus.Success)
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                ObjJsonData.Message = " Record(s) Saved Successfully !!! ";
                            }
                            else
                            {
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                ObjJsonData.Message = "Fail To Save Record ";
                            }
                        }


                    }
                    else
                    {
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                        ObjJsonData.Message = "Please Check Data Mismatch !!! ";
                    }
                }
                catch (Exception ex)
                {
                    ObjJsonData.Message = ex.Message;

                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Fee", "UpdateExamVerifyStatus", ex.Message);
                        ObjJsonData.Message = ex.Message;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;

                        return Json(ObjJsonData);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                return RedirectToAction("ErrorMessage", "error");
            }

            if (string.IsNullOrEmpty(ObjJsonData.Message))
            {
                ObjJsonData.Message = "No Changes Made !";
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData);
        }

