        public JsonResult SaveExamInvigilationfromExcelUpload()
        {
            FeeTransactionViewModel ObjViewModel = new FeeTransactionViewModel();
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStaffId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var filename = Request.Files[0].FileName;
            HttpPostedFileBase file = Request.Files[filename];
            var sFilename = Request.Files[0].FileName.Split('.');
            string columnName = string.Empty;
            string paidDateColumn = string.Empty;
            int SuccessCount = 0;
            int FailCount = 0;
            string sMessage = string.Empty;
            string updateSQL = string.Empty;
            string insertSQL = string.Empty;
            int UpdateCount = 0;
            int InsertCount = 0;
            var CurrentDate = DateTime.Now.ToString("yyyy-MM-dd");

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    string ExamSetting = Request.Form["ExamSetting"];
                    string AcademicYear = Request.Form["AcademicYear"];
                    string extension = System.IO.Path.GetExtension(Request.Files[0].FileName).ToLower();

                    string[] validFileTypes = { ".xls", ".xlsx", ".csv" };
                    string path1 = string.Format("{0}/{1}", Server.MapPath("~/Content/Uploads/Exam/" + sAcademicYear), Request.Files[0].FileName);

                    if (!Directory.Exists(path1))
                    {
                        Directory.CreateDirectory(Server.MapPath("~/Content/Uploads/Exam/" + sAcademicYear));
                    }
                    // Save File
                    if (System.IO.File.Exists(path1))
                    {
                        System.IO.File.Delete(path1);
                    }
                    Request.Files[0].SaveAs(path1);

                    byte[] fileBytes;
                    using (var binaryReader = new BinaryReader(Request.Files[0].InputStream))
                    {
                        fileBytes = binaryReader.ReadBytes(Request.Files[0].ContentLength);
                    }
                    var StaffList = (List<STF_PERSONAL_INFO>)CMSHandler.FetchData<STF_PERSONAL_INFO>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamInvigilatorStaffList), sAcademicYear).DataSource.Data;
                    var supSession = (List<SUP_SESSION>)CMSHandler.FetchData<SUP_SESSION>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSupSession), sAcademicYear).DataSource.Data;
                    var liExamInvilList = (List<EXAM_INVIGILATION_STAFF_WISE>)CMSHandler.FetchData<EXAM_INVIGILATION_STAFF_WISE>(new EXAM_INVIGILATION_STAFF_WISE() { EXAM_SETTING_ID = ExamSetting, ACADEMIC_YEAR = AcademicYear }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAllExamInvigilationBySettingId), sAcademicYear).DataSource.Data;

                    if (validFileTypes.Contains(extension))
                    {
                        //var objFeeDueList = new FEE_STUDENT_DUE();

                        using (var package = new ExcelPackage(new MemoryStream(fileBytes)))
                        {
                            ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                            var worksheet = package.Workbook.Worksheets[0];
                            var examInvigilationId = new List<EXAM_INVIGILATION_STAFF_WISE>();
                            if (worksheet.Dimension.End.Row <= 1 || worksheet.Dimension.End.Column < 2)
                            {
                                ObjJsonData.Message = "The uploaded file is empty or improperly formatted.";
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                                return Json(ObjJsonData);
                            }
                            else
                            {
                                for (int row = 2; row <= worksheet.Dimension.End.Row; row++)
                                {
                                    bool isValidRow = !string.IsNullOrWhiteSpace(worksheet.Cells[row, 2].Text);
                                    if (isValidRow)
                                    {
                                        var liExamInvigilationList = new EXAM_INVIGILATION_STAFF_WISE
                                        {
                                            STAFF_CODE = worksheet.Cells[row, 2].Text,
                                            EXAM_DATE = worksheet.Cells[row, 3].Text,
                                            HALL_NAME = worksheet.Cells[row, 4].Text,
                                            SESSION = worksheet.Cells[row, 5].Text,
                                        };
                                        examInvigilationId.Add(liExamInvigilationList);
                                    }
                                }
                            }//

                            if (examInvigilationId != null && examInvigilationId.Count > 0)
                            {
                                foreach (var dr in examInvigilationId)
                                {
                                    dr.EXAM_SETTING_ID = ExamSetting;
                                    dr.ACADEMIC_YEAR = AcademicYear;
                                    dr.STAFF_CODE = dr.STAFF_CODE.Trim();
                                    dr.EXAM_DATE = dr.EXAM_DATE.Replace(" ", "");
                                    dr.SESSION = dr.SESSION.Trim();
                                    dr.CREATED_BY = sStaffId;
                                    var SessionID = supSession.Where(o => o.SESSION_NAME == dr.SESSION).ToList();
                                    if (SessionID != null && SessionID.Count > 0)
                                    {
                                        dr.SESSION = SessionID.FirstOrDefault().SESSION_ID;
                                    }
                                    else
                                    {
                                        sMessage = "The given Staff Code " + dr.STAFF_CODE + " Exam Date " + dr.EXAM_DATE + " session mismatch " + dr.SESSION + " does not exist. Please check the Staff Code.";
                                        using (ErrorLog ObjLog = new ErrorLog())
                                        {
                                            ObjLog.ExamInvigilationFileLog(sMessage, CurrentDate);
                                        }
                                        FailCount++;
                                        continue;
                                    }
                                    dr.EXAM_DATE = CommonMethods.ConvertdatetoyearFromat(dr.EXAM_DATE);


                                    var staffID = StaffList.Where(o => o.STAFF_CODE == dr.STAFF_CODE).ToList();
                                    if (staffID != null && staffID.Count > 0)
                                    {
                                        dr.EXAM_INVIGILATOR_ID = staffID.FirstOrDefault().STAFF_ID;
                                    }
                                    else
                                    {
                                        sMessage = "The given Staff Code " + dr.STAFF_CODE + " does not exist. Please check the Staff Code.";
                                        using (ErrorLog ObjLog = new ErrorLog())
                                        {
                                            ObjLog.ExamInvigilationFileLog(sMessage, CurrentDate);
                                        }
                                        FailCount++;
                                        continue;
                                    }
                                    if (liExamInvilList != null && liExamInvilList.Count > 0)
                                    {
                                        var checkExistInvigilatorList = liExamInvilList.Where(o => o.EXAM_INVIGILATOR_ID == dr.EXAM_INVIGILATOR_ID && o.SESSION == dr.SESSION && Convert.ToDateTime(o.EXAM_DATE) == Convert.ToDateTime(dr.EXAM_DATE)).ToList();

                                        dr.EXAM_INVIGILATOR_ID = staffID.FirstOrDefault().STAFF_ID;
                                        if (checkExistInvigilatorList != null && checkExistInvigilatorList.Count > 0)
                                        {
                                            dr.EXAM_INVIGILATION_ID = checkExistInvigilatorList.FirstOrDefault().EXAM_INVIGILATION_ID;

                                            updateSQL += "UPDATE EXAM_INVIGILATION_STAFF_WISE SET EXAM_SETTING_ID = " + dr.EXAM_SETTING_ID +
                                      ",EXAM_DATE = '" + dr.EXAM_DATE + "', HALL_NAME = '" + dr.HALL_NAME + "',MODIFIED_BY = '" + dr.CREATED_BY + "' WHERE EXAM_INVIGILATION_ID = " + dr.EXAM_INVIGILATION_ID + ";";

                                            UpdateCount += 1;

                                        }
                                        else
                                        {

                                            insertSQL += "INSERT INTO exam_invigilation_staff_wise (EXAM_SETTING_ID,EXAM_DATE,EXAM_INVIGILATOR_ID,HALL_NAME,SESSION,ACADEMIC_YEAR,CREATED_BY) VALUES (" + dr.EXAM_SETTING_ID + ", '" + dr.EXAM_DATE + "', " +
                                      dr.EXAM_INVIGILATOR_ID + ", '" + dr.HALL_NAME + "', '" + dr.SESSION + "', '" + dr.ACADEMIC_YEAR + "', '" + dr.CREATED_BY + "');";

                                            InsertCount += 1;
                                        }
                                    }
                                    else
                                    {
                                        insertSQL += "INSERT INTO exam_invigilation_staff_wise (EXAM_SETTING_ID,EXAM_DATE,EXAM_INVIGILATOR_ID,HALL_NAME,SESSION,ACADEMIC_YEAR,CREATED_BY) VALUES (" + dr.EXAM_SETTING_ID + ", '" + dr.EXAM_DATE + "', " +
                                    dr.EXAM_INVIGILATOR_ID + ", '" + dr.HALL_NAME + "', '" + dr.SESSION + "', '" + dr.ACADEMIC_YEAR + "', '" + dr.CREATED_BY + "');";

                                        InsertCount += 1;
                                    }
                                }
                                if (updateSQL != null && updateSQL.Count() > 0)
                                {
                                    var UpdateDueList = CMSHandler.SaveOrUpdate(null, updateSQL);


                                }
                                if (insertSQL != null && insertSQL.Count() > 0)
                                {
                                    var InsertDueList = CMSHandler.SaveOrUpdate(null, insertSQL);


                                }


                            }
                        }
                        ObjJsonData.ErrorCode = (SuccessCount != 0) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                        ObjJsonData.Message = SuccessCount + " Record(s) Saved Successfully !!! , " + FailCount + " Failed To Save Record(s) !!!";

                    }
                    else
                    {
                        ObjJsonData.Message = "In Valid File Type Oops! { '.xls', '.xlsx', '.csv' } This format Only Accepted"; ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }

                }

                catch (Exception ex)
                {
                    sMessage = ex.Message;

                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.ExamInvigilationFileLog(sMessage, CurrentDate);
                    }
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveExamInvigilationfromExcelUpload", ex.Message);
                        ObjJsonData.Message = ex.Message;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;

                        return Json(ObjJsonData);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            if (string.IsNullOrEmpty(ObjJsonData.Message))
            {
                ObjJsonData.Message = "No Changes Made !";
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData);
        }
