        [HttpPost]
        public JsonResult GetInvigilationSessionsBySettingAndDate(string sSettingId, string sExamDate)
        {
            string sOptions = "<option value=\"\">-- All Sessions --</option>";
            try
            {
                if (!string.IsNullOrEmpty(sSettingId) && sSettingId != "--- Select ---")
                {
                    string query = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchInvigilationSessionsBySettingAndDate)
                        .Replace("?EXAM_SETTING_ID", sSettingId.Replace("'", "''"));

                    if (!string.IsNullOrEmpty(sExamDate) && sExamDate != "--- Select ---" && sExamDate != "-- All Dates --")
                    {
                        query = query.Replace("?DATE_FILTER", "AND EIS.EXAM_DATE = '" + sExamDate.Replace("'", "''") + "'");
                    }
                    else
                    {
                        query = query.Replace("?DATE_FILTER", "");
                    }

                    var sessions = DapperHandler.FetchAll<EXAM_INVIGILATION_STAFF_WISE>(query, null);
                    if (sessions != null && sessions.Count > 0)
                    {
                        foreach (var s in sessions)
                        {
                            string sessionDisplay = FormatSessionDisplayName(s.SESSION_NAME);
                            sOptions += "<option value=\"" + s.SESSION + "\">" + sessionDisplay + "</option>";
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "GetInvigilationSessionsBySettingAndDate", ex.Message);
                }
            }
            return Json(sOptions);
        }

        public static string FormatSessionDisplayName(string sessionName)
        {
            if (string.IsNullOrWhiteSpace(sessionName)) return "";
            string s = sessionName.Trim();
            if (s.StartsWith("09:", StringComparison.OrdinalIgnoreCase))
                return "1 (" + s + ")";
            if (s.StartsWith("11:", StringComparison.OrdinalIgnoreCase))
                return "2 (" + s + ")";
            if (s.StartsWith("02:", StringComparison.OrdinalIgnoreCase) || s.StartsWith("2:", StringComparison.OrdinalIgnoreCase) || s.StartsWith("14:", StringComparison.OrdinalIgnoreCase))
                return "3 (" + s + ")";
            if (string.Equals(s, "FN", StringComparison.OrdinalIgnoreCase))
                return "1 (FN - 09:30 AM To 12:30 PM)";
            if (string.Equals(s, "AN", StringComparison.OrdinalIgnoreCase))
                return "2 (AN - 01:30 PM To 04:30 PM)";
            return s;
        }

