                    if (!string.IsNullOrEmpty(sExamDate) && sExamDate != "--- Select ---" && sExamDate != "-- All Dates --")
                    {
                        query = query.Replace("?DATE_FILTER", "AND EIS.EXAM_DATE = '" + sExamDate.Replace("'", "''") + "'");
                    }
                    else
                    {
                        query = query.Replace("?DATE_FILTER", "");
                    }

                    if (!string.IsNullOrEmpty(sSession) && sSession != "--- Select ---" && sSession != "-- All Sessions --")
                    {
                        query = query.Replace("?SESSION_FILTER", "AND EIS.SESSION = '" + sSession.Replace("'", "''") + "'");
                    }
                    else
                    {
                        query = query.Replace("?SESSION_FILTER", "");
                    }

                    var rawList = DapperHandler.FetchAll<EXAM_INVIGILATION_STAFF_WISE>(query, null);
                    if (rawList != null && rawList.Count > 0)
                    {
                        var groups = rawList.GroupBy(x => new { x.EXAM_DATE, x.SESSION }).ToList();
                        foreach (var g in groups)
                        {
                            var firstItem = g.FirstOrDefault();
                            string examTitle = "";
                            if (firstItem != null)
                            {
                                if (!string.IsNullOrEmpty(firstItem.EXAM_NAME) && !string.IsNullOrEmpty(firstItem.M_EXAM))
                                {
                                    if (firstItem.M_EXAM.IndexOf(firstItem.EXAM_NAME, StringComparison.OrdinalIgnoreCase) >= 0)
                                        examTitle = firstItem.M_EXAM.ToUpper();
                                    else
                                        examTitle = (firstItem.EXAM_NAME + " EXAM " + firstItem.M_EXAM).ToUpper();
                                }
                                else if (!string.IsNullOrEmpty(firstItem.EXAM_NAME))
                                {
                                    examTitle = firstItem.EXAM_NAME.ToUpper();
                                }
                                else if (!string.IsNullOrEmpty(firstItem.M_EXAM))
                                {
                                    examTitle = firstItem.M_EXAM.ToUpper();
                                }
                            }

                            string sessionDisplay = FormatSessionDisplayName(firstItem != null ? firstItem.SESSION_NAME : "");

                            var itemsList = g.ToList();
                            const int pageSize = 25;
                            var pages = new List<List<EXAM_INVIGILATION_STAFF_WISE>>();
                            for (int i = 0; i < itemsList.Count; i += pageSize)
                            {
                                pages.Add(itemsList.Skip(i).Take(pageSize).ToList());
                            }

                            objViewModel.LiDateSessionWiseInvigilationGroups.Add(new DateSessionWiseInvigilationGroup()
                            {
                                ExamDate = g.Key.EXAM_DATE,
                                SessionId = g.Key.SESSION,
                                SessionName = firstItem != null ? firstItem.SESSION_NAME : "",
                                SessionDisplayName = sessionDisplay,
                                ExamTitle = examTitle,
                                Pages = pages,
                                TotalCount = itemsList.Count
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "BindDateAndSessionWiseInvigilationReport", ex.Message);
                }
            }

            return PartialView("_BindDateAndSessionWiseInvigilationReport", objViewModel);
        }

