        public JsonResult SavesmcExaminarDetails(string sJsonData)
        {
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<EXAMINARS_INFO>(sJsonData);
                    if (Result != null)
                    {

                        if (!string.IsNullOrEmpty(Result.EXAMINAR_ENTRY_ID))
                        {
                            // Updtae ,...
                            var UpdateExaminarDetails = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExaminarEntryDetails));
                            if (UpdateExaminarDetails.Success)
                            {
                                ObjJsonData.Message = Common.Messages.RecordsUpdatedSuccessfully;
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToUpdatedRecords;
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }
                        }
                        else
                        {
                            ResultArgs SaveSeminorWorkshopForStaff = new ResultArgs();
                            int count = 0;
                            var COURSELIST = Result.COURSE_ID.Split(',').ToList();
                            foreach (var items in COURSELIST)
                            {
                                Result.COURSE_ID = items;
                                // Insert ,...
                                var checkexist = (List<EXAMINARS_INFO>)CMSHandler.FetchData<EXAMINARS_INFO>(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.IsExistForExaminarInfoCourseEntry)).DataSource.Data;
                                if (checkexist == null)
                                {
                                    SaveSeminorWorkshopForStaff = CMSHandler.SaveOrUpdate(Result, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertExaminarEntryDetails), sAcademicYear, true);
                                    if (SaveSeminorWorkshopForStaff.Success)
                                    {

                                        count += 1;

                                    }
                                }
                            }
                            if (SaveSeminorWorkshopForStaff.Success)
                            {
                                ObjJsonData.sResult = count.ToString();
                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "SaveExaminarDetails", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
