        public JsonResult FetchExaminarODForm(string sProgramme, string sFromDate, string sToDate, string sRole, string sResultMonth, string sExaminarId, string Fetchtype)
        {
            string sOption = string.Empty;
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";

            try
            {
                if (!string.IsNullOrEmpty(sAcademicYear))
                {
                    string role = sRole;
                    string sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExaminarDetailsByDateandRole).Replace(Common.Delimiter.QUS + "PROGRAMME_ID", sProgramme);
                    if (sRole == "1")
                    {
                        sql = string.Concat(sql, " AND EN.IS_QUESTIONSETTER = 1 AND EN.EXAMINAR_ID = ?EXAMINAR_ID;");
                    }
                    else if (sRole == "2" && Fetchtype == "1")
                    {
                        sql = string.Concat(sql, "AND EN.FROM_DATE BETWEEN ?FROM_DATE AND ?TO_DATE  OR EN.TO_DATE BETWEEN ?FROM_DATE AND ?TO_DATE AND EN.IS_EXAMINAR = 1;");
                    }
                    else if (sRole == "2" && Fetchtype == "2")
                    {
                        sql = string.Concat(sql, "AND EN.IS_EXAMINAR = 1 AND EN.EXAMINAR_ID = ?EXAMINAR_ID;");
                    }
                    else if (sRole == "3" && Fetchtype != "1")
                    {
                        sql = string.Concat(sql, "AND EN.FROM_DATE BETWEEN ?FROM_DATE AND ?TO_DATE  OR EN.TO_DATE BETWEEN ?FROM_DATE AND ?TO_DATE AND EN.IS_PRACTICAL = 1;");
                    }
                    else if (sRole == "3" && Fetchtype == "")
                    {
                        sql = string.Concat(sql, "AND  EN.IS_PRACTICAL = 1 AND EN.EXAMINAR_ID = ?EXAMINAR_ID;");
                    }
                    else
                    {
                        sql = string.Concat(sql, ";");
                    }
                    var LiExaminar = (List<EXAMINARS_INFO>)CMSHandler.FetchData<EXAMINARS_INFO>(new EXAMINARS_INFO { FROM_DATE = sFromDate, TO_DATE = sToDate, EXAM_SETTING_ID = sResultMonth, EXAMINAR_ID = sExaminarId }, sql).DataSource.Data;
                    if (LiExaminar != null && LiExaminar.Count > 0)
                    {
                        foreach (var item in LiExaminar)
                        {
                            sOption += "<option value='" + item.EXAMINAR_ENTRY_ID + "' >" + item.EXAMINAR_NAME + "</option>";
                        }
                    }
                    return Json(sOption);
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("FetchExaminarODForm", "Examination", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("FetchExaminarODForm", "Examination", ex.Message);
                }
            }
            return Json(sOption);
        }
