            {
                try
                {
                    var objmodel = new EXAMINARS_INFO();
                    objmodel.IS_EXAMINAR = "0";
                    objmodel.IS_QUESTIONSETTER = "0";
                    objmodel.IS_PRACTICAL = "0";
                    objmodel.EXAM_SETTING_ID = sExamsetting;
                    if (sRoles == "1")
                    {
                        objmodel.IS_QUESTIONSETTER = "1";
                    }
                    else if (sRoles == "2")
                    {
                        objmodel.IS_EXAMINAR = "1";
                    }
                    else
                    {
                        objmodel.IS_PRACTICAL = "1";
                    }
                    string Sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExaminarDetailsByProgrammeAndRole).Replace(Common.Delimiter.QUS + "PROGRAMME_ID", sProgramme);
                    var LiExaminar = (List<EXAMINARS_INFO>)CMSHandler.FetchData<EXAMINARS_INFO>(objmodel, Sql).DataSource.Data;
                    if (LiExaminar != null && LiExaminar.Count > 0)
                    {
                        foreach (var item in LiExaminar)
                        {
                            sOption += "<option value=" + item.EXAMINAR_ID + "  >" + item.EXAMINAR + "</option>";
                        }
                    }
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("Examination", "FetchsmcExaminarByprogramme", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("Examination", "FetchsmcExaminarByprogramme", Ex.Message);
                    }
                }
            }
            return sOption;
        }
