        public JsonResult SaveOrUpdateExaminerStaff(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
            JSON_STU_PERSONAL_INFO objJson = serializer.Deserialize<JSON_STU_PERSONAL_INFO>(sJsonData);
            try
            {
                if (objJson.LI_EXAMINER_ORDER != null && objJson.LI_EXAMINER_ORDER.Count > 0)
                {
                    foreach (var item in objJson.LI_EXAMINER_ORDER)
                    {
                        item.ORDER_DATE = CommonMethods.DateConvertionForPayU(item.ORDER_DATE);
                        item.DUE_DATE = CommonMethods.DateConvertionForPayU(item.DUE_DATE);
                        var sStaff = item.STAFF_ID.Split(',');
                        if (!string.IsNullOrEmpty(item.STAFF_ID))
                        {
                            foreach (var staffitem in sStaff)
                            {
                                item.STAFF_ID = staffitem;

                                if (!string.IsNullOrEmpty(item.STAFF_ALLOTED_ID))
                                {
                                    var alreadyExcit = DapperHandler.FetchAll<EXAM_EXAMINER_ORDER>(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.CheckExaminerOrderByStaffId), new { STAFF_ID = item.STAFF_ID, EXAM_SETTING_ID = item.EXAM_SETTING_ID, DEPARTMENT_ID = item.DEPARTMENT_ID }).ToList();
                                    if (alreadyExcit != null && alreadyExcit.Count > 0)
                                    {
                                        var Update = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateExaminerOrder), item, sAcademicYear);
                                    }
                                    else
                                    {
                                        var Insert = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InertExaminerOrder), item, sAcademicYear);
                                    }
                                }
                                else
                                {
                                    var Insert = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InertExaminerOrder), item, sAcademicYear);

                                }
                            }

                        }

                    }
                }

            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Examination", "SaveOrUpdate", ex.Message);
                }
            }
            return Json(ObjJsonData);
        }
