        public JsonResult SaveOrUpdatestaffpacketreference(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            System.Web.Script.Serialization.JavaScriptSerializer serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
            JSON_STU_PERSONAL_INFO objJson = serializer.Deserialize<JSON_STU_PERSONAL_INFO>(sJsonData);
            try
            {
                if (objJson.LI_EXAMINER_ADD != null && objJson.LI_EXAMINER_ADD.Count > 0)
                {
                    foreach (var item in objJson.LI_EXAMINER_ADD)
                    {
                        var sStaff = item.STAFF_ID.Split(',');
                        if (!string.IsNullOrEmpty(item.STAFF_ID))
                        {
                            foreach (var staffitem in sStaff)
                            {
                                item.STAFF_ID = staffitem;

                                if (!string.IsNullOrEmpty(item.MAPPING_ID))
                                {
                                    var mappingIds = item.MAPPING_ID.Split(',');

                                    foreach (var mappingId in mappingIds)
                                    {
                                        item.MAPPING_ID = mappingId;

                                        var Update = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateaddExaminer), item, sAcademicYear);
                                    }
                                    var Insert = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertaddExaminer), item, sAcademicYear);
                                }
                                else
                                {
                                    var Insert = DapperHandler.SaveOrUpdate(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.InsertaddExaminer), item, sAcademicYear);

                                }
                            }

                        }

                    }
                }

            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Examination", "SaveOrUpdate", ex.Message);
                }
            }
            return Json(ObjJsonData);
        }



