        #region External User Question Entry
        public ActionResult ExternalUserQuestionentry()
        {
            string sSql = string.Empty;
            string sSql2 = string.Empty;
            string sSql3 = string.Empty;
            var ObjViewModel = new StudentViewModel();
            try
            {
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR]?.ToString();
                string sUserId = Session[Common.SESSION_VARIABLES.USER_ID]?.ToString();
                string sRoleid = Session[Common.SESSION_VARIABLES.USER_ROLE_ID]?.ToString();

                if (string.IsNullOrEmpty(sAcademicYear) || string.IsNullOrEmpty(sUserId) || string.IsNullOrEmpty(sRoleid))
                {
                    return View(ObjViewModel);
                }
                if (sRoleid == "10")
                {
                    ObjViewModel.liExternalordercopydetails = DapperHandler.FetchAll<EXAM_EXAMINER_ORDER>(ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchexternalcourseInfo), new { ACADEMIC_YEAR = sAcademicYear, STAFF_ID = sUserId });
                    if (ObjViewModel.liExternalordercopydetails != null && ObjViewModel.liExternalordercopydetails.Count > 0)
                    {
                        ObjViewModel.liCollegeDetails = DapperHandler.FetchAll<CollegeDetails>(SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), null);

                        var examSettings = CMSHandler.FetchData<EXAM_SETTING>(null, OBESQL.GetOBESQL(OBESQLCommands.FetchExamSettingForQuestionEntry), sAcademicYear).DataSource?.Data as List<EXAM_SETTING>;
                        if (examSettings != null) ViewBag.ExamSettings = new SelectList(examSettings, "EXAM_SETTING_ID", "EXAM_NAME");

                        // Fetch Courses
                        var courses = CMSHandler.FetchData<CourseList>(new STF_PERSONAL_INFO() { STAFF_ID = sUserId }, OBESQL.GetOBESQL(OBESQLCommands.FetchCourseForQuestionEntryForExternalUser).Replace("?EXAM_SETTING_ID", examSettings.FirstOrDefault().EXAM_SETTING_ID), sAcademicYear).DataSource?.Data as List<CourseList>;
                        if (courses != null) ViewBag.Courses = new SelectList(courses, "COURSE_ID", "COURSE_CODE");

                        // Fetch Units
                        var units = CMSHandler.FetchData<SUP_OBE_UNIT>(null, OBESQL.GetOBESQL(OBESQLCommands.FetchUnitForQuestionEntry), sAcademicYear).DataSource?.Data as List<SUP_OBE_UNIT>;
                        if (units != null) ViewBag.Units = new SelectList(units, "OBE_UNIT_ID", "OBE_UNIT");

                        // Fetch Question Levels mapping
                        var levels = CMSHandler.FetchData<OBE_QUESTION_LEVEL>(null, OBESQL.GetOBESQL(OBESQLCommands.FetchQuestionLevelsForEntry), sAcademicYear).DataSource?.Data as List<OBE_QUESTION_LEVEL>;
                        if (levels != null) ViewBag.Levels = new SelectList(levels, "QUESTION_LEVEL_ID", "QUESTION_LEVEL");

                        // Fetch K Levels for Sidebar
                        var blooms = (List<BLOOMS_TAXONOMY_MASTER>)CMSHandler.FetchData<BLOOMS_TAXONOMY_MASTER>(null, OBESQL.GetOBESQL(OBESQLCommands.FetchBloomsTaxonomyMaster), sAcademicYear).DataSource?.Data;
                        if (blooms != null) ViewBag.BloomsTaxonomy = blooms;
                    }
                    else
                    {
                        ObjViewModel.liExternalordercopydetails = new List<EXAM_EXAMINER_ORDER>();
                        ObjViewModel.liExternalordercopydetails.Add(new EXAM_EXAMINER_ORDER { ERROR = "You are not eligible for convocation registration" });// STRING USED IN VIEW PAGE DON'T CHANGE
                    }
                }
                return View(ObjViewModel);
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Student", "Certificate", ex.ToString());
                }
                return RedirectToAction("ErrorMessage", "error"); ;
            }
        }
