        #region Student Arrear Registration
        public ActionResult StudentArrearRegistration()
        {
            string sUserId = string.Empty;
            if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
            {
                sUserId = Session[Common.SESSION_VARIABLES.USER_ID].ToString();
            }
            else if (Session["USER_ID"] != null)
            {
                sUserId = Session["USER_ID"].ToString();
            }

            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

            if (!string.IsNullOrEmpty(sUserId) && !string.IsNullOrEmpty(sAcademicYear))
            {
                string sSql1 = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentDetailsByStudentIdForarrear);
                var liStudentPersonalInfo = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(null, sSql1.Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;

                if (liStudentPersonalInfo != null && liStudentPersonalInfo.Count > 0)
                {
                    var student = liStudentPersonalInfo.FirstOrDefault();
                    ViewBag.StudentName = (student.FIRST_NAME + " " + student.LAST_NAME).Trim();
                    ViewBag.RegisterNumber = !string.IsNullOrEmpty(student.REGISTER_NO) ? student.REGISTER_NO : student.ROLL_NO;
                    ViewBag.ClassName = student.CLASS_NAME;
                    ViewBag.ProgrammeGroupId = student.PROGRAM_ID;

                    // Fetch Frequency ID (FEE_MODE = 12) dynamically
                    string getFrequencySql = "SELECT FEE_FREQUENCY_FEE_MODE_ID FROM fee_frequency_fee_mode WHERE FEE_MODE = 12 AND ACADEMIC_YEAR = @ACADEMIC_YEAR";
                    var frequencyResult = DapperHandler.FetchAll<dynamic>(getFrequencySql, new { ACADEMIC_YEAR = sAcademicYear }, null).FirstOrDefault();
                    ViewBag.FrequencyId = frequencyResult != null ? Convert.ToString(frequencyResult.FEE_FREQUENCY_FEE_MODE_ID) : "Arrear";
                }
            }

            if (ViewBag.StudentName == null) ViewBag.StudentName = Session[Common.SESSION_VARIABLES.USER_NAME] != null ? Session[Common.SESSION_VARIABLES.USER_NAME].ToString() : "Student Portal";
            if (ViewBag.RegisterNumber == null) ViewBag.RegisterNumber = "Loading...";
            if (ViewBag.ClassName == null) ViewBag.ClassName = "Outgone Arrear Batch";
            if (ViewBag.ProgrammeGroupId == null) ViewBag.ProgrammeGroupId = "";
            if (ViewBag.FrequencyId == null) ViewBag.FrequencyId = "Arrear";

            ViewBag.StudentId = sUserId;

            return View();
        }

        [HttpPost]
        public JsonResult GetStudentArrearCourses(string StudentId)
        {
            // If StudentId is empty, get from session or fallback to 237
            if (string.IsNullOrEmpty(StudentId))
            {

                StudentId = Session[Common.SESSION_VARIABLES.USER_ID] != null ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : "";
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
                if (string.IsNullOrEmpty(StudentId))
                {
                    StudentId = Session["USER_ID"] != null ? Session["USER_ID"].ToString() : "";
                }
            }


            var ObjJsonData = new JsonResultData();
            try
            {
                string sql = @"
                    SELECT 
                        EAR.REGISTRATION_ID,
                        EAR.COURSE_ID,
                        C.COURSE_TITLE,
                        C.COURSE_CODE,
                        EAR.IS_REGISTERED,
                        EAR.IS_CANCEL,
                        EAR.IS_ACTIVE,
                        EAR.EXAM_SETTING_ID,
                        EAR.IS_PAID
                    FROM EXAM_REGISTRATION_ARREAR EAR
                    LEFT JOIN CP_COURSE_ROOT C ON EAR.COURSE_ID = C.COURSE_ROOT_ID
                    WHERE EAR.STUDENT_ID = ?STUDENT_ID and ear.ACADEMIC_YEAR=?ACADEMIC_YEAR AND EAR.IS_ACTIVE = '1' ORDER BY IS_PAID";
                // 1. Fetch Frequency ID (FEE_MODE = 12)
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                string getFrequencySql = "SELECT FEE_FREQUENCY_FEE_MODE_ID FROM fee_frequency_fee_mode WHERE FEE_MODE = 12 AND ACADEMIC_YEAR = @ACADEMIC_YEAR";
                var frequencyResult = DapperHandler.FetchAll<dynamic>(getFrequencySql, new { ACADEMIC_YEAR = sAcademicYear }, null).FirstOrDefault();
                string frequencyId = frequencyResult != null ? Convert.ToString(frequencyResult.FEE_FREQUENCY_FEE_MODE_ID) : "";

                // 2. Fetch Application Type ID (CLASS_LEVEL)
                string appTypeSql = @"SELECT 
                                                APPTYPE_ID AS APPLICATION_TYPE_ID
                                            FROM
                                                stu_personal_info
                                            WHERE
                                                STUDENT_ID = @STUDENT_ID  AND IS_DELETED != 1;";
                var appTypeResult = DapperHandler.FetchAll<dynamic>(appTypeSql, new { STUDENT_ID = StudentId, ACADEMIC_YEAR = sAcademicYear }, null).FirstOrDefault();
                string applicationTypeId = appTypeResult != null ? Convert.ToString(appTypeResult.APPLICATION_TYPE_ID) : "";
                // 2b. Fetch active fee settings for this application type
                string feeSettingsSql = @"
                    SELECT COURSE_ID, START_DATE, END_DATE 
                    FROM arrear_course_fee_setting 
                    WHERE APPLICATION_TYPE = @APPLICATION_TYPE 
                      AND IS_ACTIVE = '1' 
                      AND IS_DELETED = '0'";
                var feeSettingsList = DapperHandler.FetchAll<dynamic>(feeSettingsSql, new { APPLICATION_TYPE = applicationTypeId }, null);
                // 3. Fetch FEE_MAIN_HEAD_ID
                string mainHeadSql = @"
                    SELECT FEE_MAIN_HEAD_ID 
                    FROM fee_main_heads 
                    WHERE FREQUENCY_ID = @FREQUENCY_ID 
                      AND APPLICATION_TYPE_ID = @APPLICATION_TYPE_ID 
                      AND ACADEMIC_YEAR = @ACADEMIC_YEAR 
                      AND IS_DELETED != 1";
                var mainHeadResult = DapperHandler.FetchAll<dynamic>(mainHeadSql, new
                {
                    FREQUENCY_ID = frequencyId,
                    APPLICATION_TYPE_ID = applicationTypeId,
                    ACADEMIC_YEAR = sAcademicYear
                }, null).FirstOrDefault();
                string feeMainHeadId = mainHeadResult != null ? Convert.ToString(mainHeadResult.FEE_MAIN_HEAD_ID) : "";

                // 4. Fetch unit AMOUNT from fee_structure
                int unitFee = 0;
                if (!string.IsNullOrEmpty(feeMainHeadId))
                {
                    string feeStructureSql = @"
                        SELECT AMOUNT 
                        FROM fee_structure 
                        WHERE FEE_MAIN_HEAD_ID = @FEE_MAIN_HEAD_ID 
                          AND ACADEMIC_YEAR = @ACADEMIC_YEAR 
                          AND IS_DELETED != 1";
                    var feeStructureResult = DapperHandler.FetchAll<dynamic>(feeStructureSql, new
                    {
                        FEE_MAIN_HEAD_ID = feeMainHeadId,
                        ACADEMIC_YEAR = sAcademicYear
                    }, null).FirstOrDefault();
                    if (feeStructureResult != null)
                    {
                        unitFee = Convert.ToInt32(feeStructureResult.AMOUNT);
                    }
                }

                // Fallback to ARREAR_COURSE_FEE_SETTING
                if (unitFee == 0)
                {
                    string feeSettingSql = @"SELECT 
                                                    F.AMOUNT
                                                FROM
                                                    ARREAR_COURSE_FEE_SETTING F
                                                        INNER JOIN
                                                    STU_PERSONAL_INFO C ON F.APPLICATION_TYPE = C.APPTYPE_ID
                                                WHERE
                                                    C.STUDENT_ID = @STUDENT_ID
                                                        AND F.IS_ACTIVE = '1'
                                                        AND C.IS_DELETED != 1
                                                        AND F.IS_DELETED != 1;";
                    var feeSettingResult = DapperHandler.FetchAll<dynamic>(feeSettingSql, new { STUDENT_ID = StudentId }, null).FirstOrDefault();
                    unitFee = feeSettingResult != null ? Convert.ToInt32(feeSettingResult.AMOUNT) : 0;
                }

                // 5. Fetch actual total AMOUNT registered from fee_student_account
                int totalRegisteredFee = 0;
                if (!string.IsNullOrEmpty(frequencyId))
                {
                    string totalRegisteredSql = @"
                        SELECT SUM(IFNULL(CREDIT, 0) - IFNULL(DEBIT, 0)) AS TOTAL_BALANCE 
                        FROM fee_student_account 
                        WHERE STUDENT_ID = @STUDENT_ID 
                          AND FREQUENCY_ID = @FREQUENCY_ID 
                          AND ACADEMIC_YEAR = @ACADEMIC_YEAR
                          AND IS_DELETED != 1";
                    var totalRegisteredResult = DapperHandler.FetchAll<dynamic>(totalRegisteredSql, new
                    {
                        STUDENT_ID = StudentId,
                        FREQUENCY_ID = frequencyId,
                        ACADEMIC_YEAR = sAcademicYear
                    }, null).FirstOrDefault();
                    if (totalRegisteredResult != null && totalRegisteredResult.TOTAL_BALANCE != null)
                    {
                        totalRegisteredFee = Convert.ToInt32(totalRegisteredResult.TOTAL_BALANCE);
                    }
                }
                DateTime today = DateTime.Today;

                string feeAmount = unitFee.ToString();

                // Fetch data using CMSHandler
                var resultArgs = CMSHandler.FetchData<StudentArrearCourseModel>(new { STUDENT_ID = StudentId, ACADEMIC_YEAR = sAcademicYear }, sql);
                if (resultArgs.Success && resultArgs.DataSource.Data != null)
                {
                    var courses = (List<StudentArrearCourseModel>)resultArgs.DataSource.Data;
                    ObjJsonData.sResultS = feeAmount;
                    ObjJsonData.Message = totalRegisteredFee.ToString();

                    ObjJsonData.oResult = courses.Select(c =>
                    {
                        var setting = feeSettingsList != null ? (feeSettingsList.FirstOrDefault(s => Convert.ToString(s.COURSE_ID) == c.COURSE_ID)
                                      ?? feeSettingsList.FirstOrDefault(s => Convert.ToString(s.COURSE_ID) == "0")) : null;

                        bool isLocked = true;
                        string startDateStr = "";
                        string endDateStr = "";

                        if (setting != null)
                        {
                            startDateStr = Convert.ToString(setting.START_DATE);
                            endDateStr = Convert.ToString(setting.END_DATE);

                            DateTime startDate = DateTime.MinValue;
                            DateTime endDate = DateTime.MaxValue;

                            bool hasStart = DateTime.TryParse(startDateStr, out startDate);
                            bool hasEnd = DateTime.TryParse(endDateStr, out endDate);

                            if (hasStart && hasEnd)
                            {
                                if (today >= startDate.Date && today <= endDate.Date)
                                {
                                    isLocked = false;
                                }
                            }
                            else if (hasStart)
                            {
                                if (today >= startDate.Date)
                                {
                                    isLocked = false;
                                }
                            }
                            else if (hasEnd)
                            {
                                if (today <= endDate.Date)
                                {
                                    isLocked = false;
                                }
                            }
                            else
                            {
                                isLocked = false;
                            }
                        }

                        return new
                        {
                            REGISTRATION_ID = c.REGISTRATION_ID,
                            COURSE_ID = c.COURSE_ID,
                            COURSE_TITLE = c.COURSE_TITLE,
                            COURSE_CODE = c.COURSE_CODE,
                            IS_REGISTERED = string.IsNullOrEmpty(c.IS_REGISTERED) ? "0" : c.IS_REGISTERED,
                            IS_CANCEL = string.IsNullOrEmpty(c.IS_CANCEL) ? "0" : c.IS_CANCEL,
                            EXAM_SETTING_ID = string.IsNullOrEmpty(c.EXAM_SETTING_ID) ? "0" : c.EXAM_SETTING_ID,
                            IS_PAID = string.IsNullOrEmpty(c.IS_PAID) ? "0" : c.IS_PAID,
                            IS_LOCKED = isLocked ? "1" : "0",
                            START_DATE = startDateStr,
                            END_DATE = endDateStr
                        };
                    }).ToList();
                    ObjJsonData.sResult = "True";

                    // Project data to dynamic objects matching original UI structure and null fallbacks
                    //ObjJsonData.oResult = courses.Select(c => new {
                    //    REGISTRATION_ID = c.REGISTRATION_ID,
                    //    COURSE_ID = c.COURSE_ID,
                    //    COURSE_TITLE = c.COURSE_TITLE,
                    //    COURSE_CODE = c.COURSE_CODE,
                    //    IS_REGISTERED = string.IsNullOrEmpty(c.IS_REGISTERED) ? "0" : c.IS_REGISTERED,
                    //    IS_CANCEL = string.IsNullOrEmpty(c.IS_CANCEL) ? "0" : c.IS_CANCEL,
                    //    EXAM_SETTING_ID = string.IsNullOrEmpty(c.EXAM_SETTING_ID) ? "0" : c.EXAM_SETTING_ID,
                    //    IS_PAID = string.IsNullOrEmpty(c.IS_PAID) ? "0" : c.IS_PAID
                    //}).ToList();
                    //ObjJsonData.sResult = "True";
                }
                else
                {
                    ObjJsonData.sResult = "False";
                    ObjJsonData.Message = resultArgs.Message ?? "Failed to fetch arrear courses.";
                }
            }
            catch (Exception ex)
            {
                ObjJsonData.sResult = "False";
                ObjJsonData.Message = ex.Message;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        [HttpPost]
        public JsonResult ToggleArrearCourseRegistration(string RegistrationId, string Action)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                // Validate date window before allowing registration or cancellation
                string getCourseAndStudentSql = "SELECT COURSE_ID, STUDENT_ID FROM EXAM_REGISTRATION_ARREAR WHERE REGISTRATION_ID = @REGISTRATION_ID";
                var courseStudentResult = DapperHandler.FetchAll<dynamic>(getCourseAndStudentSql, new { REGISTRATION_ID = RegistrationId }, null).FirstOrDefault();

                if (courseStudentResult == null)
                {
                    ObjJsonData.sResult = "False";
                    ObjJsonData.Message = "Registration record not found.";
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }

                string courseId = Convert.ToString(courseStudentResult.COURSE_ID);
                string studentId = Convert.ToString(courseStudentResult.STUDENT_ID);

                string appTypeSql = @"
                    SELECT APPTYPE_ID 
                    FROM stu_personal_info
                    WHERE STUDENT_ID = @STUDENT_ID AND IS_DELETED != 1;";
                var appTypeResult = DapperHandler.FetchAll<dynamic>(appTypeSql, new { STUDENT_ID = studentId }, null).FirstOrDefault();
                string applicationTypeId = appTypeResult != null ? Convert.ToString(appTypeResult.APPTYPE_ID) : "";

                string feeSettingsSql = @"
                    SELECT COURSE_ID, START_DATE, END_DATE 
                    FROM arrear_course_fee_setting 
                    WHERE APPLICATION_TYPE = @APPLICATION_TYPE 
                      AND IS_ACTIVE = '1' 
                      AND IS_DELETED = '0'";
                var feeSettingsList = DapperHandler.FetchAll<dynamic>(feeSettingsSql, new { APPLICATION_TYPE = applicationTypeId }, null);

                var setting = feeSettingsList != null ? (feeSettingsList.FirstOrDefault(s => Convert.ToString(s.COURSE_ID) == courseId)
                              ?? feeSettingsList.FirstOrDefault(s => Convert.ToString(s.COURSE_ID) == "0")) : null;

                bool isLocked = true;
                if (setting != null)
                {
                    string startDateStr = Convert.ToString(setting.START_DATE);
                    string endDateStr = Convert.ToString(setting.END_DATE);

                    DateTime startDate = DateTime.MinValue;
                    DateTime endDate = DateTime.MaxValue;

                    bool hasStart = DateTime.TryParse(startDateStr, out startDate);
                    bool hasEnd = DateTime.TryParse(endDateStr, out endDate);
                    DateTime today = DateTime.Today;

                    if (hasStart && hasEnd)
                    {
                        if (today >= startDate.Date && today <= endDate.Date)
                        {
                            isLocked = false;
                        }
                    }
                    else if (hasStart)
                    {
                        if (today >= startDate.Date)
                        {
                            isLocked = false;
                        }
                    }
                    else if (hasEnd)
                    {
                        if (today <= endDate.Date)
                        {
                            isLocked = false;
                        }
                    }
                    else
                    {
                        isLocked = false;
                    }
                }

                if (isLocked)
                {
                    ObjJsonData.sResult = "False";
                    ObjJsonData.Message = "Registration/cancellation is not allowed outside the scheduled date window.";
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
                string isRegistered = Action == "REGISTER" ? "1" : "0";
                string isCancel = Action == "CANCEL" ? "1" : "0";
                string registerDate = Action == "REGISTER" ? DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") : string.Empty;
                string sql = @"UPDATE EXAM_REGISTRATION_ARREAR 
                               SET IS_REGISTERED = ?IS_REGISTERED, 
                                   IS_CANCEL = ?IS_CANCEL,
                                   REGISTER_DATE = CASE WHEN ?REGISTER_DATE = '' THEN NULL ELSE ?REGISTER_DATE END
                               WHERE REGISTRATION_ID = ?REGISTRATION_ID";
                // Map anonymous parameters matching placeholders in query
                var updateParams = new
                {
                    IS_REGISTERED = isRegistered,
                    IS_CANCEL = isCancel,
                    REGISTER_DATE = registerDate,
                    REGISTRATION_ID = RegistrationId
                };
                var resultArgs = CMSHandler.SaveOrUpdate(updateParams, sql);

                if (resultArgs.Success)
                {
                    //string studentSql = "SELECT STUDENT_ID FROM EXAM_REGISTRATION_ARREAR WHERE REGISTRATION_ID = @REGISTRATION_ID";
                    //var studentResult = DapperHandler.FetchAll<dynamic>(studentSql, new { REGISTRATION_ID = RegistrationId }, null).FirstOrDefault();
                    //string studentId = studentResult != null ? Convert.ToString(studentResult.STUDENT_ID) : "";

                    if (!string.IsNullOrEmpty(studentId))
                    {
                        string sAcademicYear = (System.Web.HttpContext.Current.Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? System.Web.HttpContext.Current.Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

                        // 1. Fetch Frequency ID (FEE_MODE = 12)
                        string getFrequencySql = "SELECT FEE_FREQUENCY_FEE_MODE_ID FROM fee_frequency_fee_mode WHERE FEE_MODE = 12 AND ACADEMIC_YEAR = @ACADEMIC_YEAR";
                        var frequencyResult = DapperHandler.FetchAll<dynamic>(getFrequencySql, new { ACADEMIC_YEAR = sAcademicYear }, null).FirstOrDefault();
                        string frequencyId = frequencyResult != null ? Convert.ToString(frequencyResult.FEE_FREQUENCY_FEE_MODE_ID) : "";

                        //// 2. Fetch Application Type ID (CLASS_LEVEL)
                        //string appTypeSql = @"
                        //                    SELECT 
                        //                        APPTYPE_ID AS APPLICATION_TYPE_ID
                        //                    FROM
                        //                        stu_personal_info
                        //                    WHERE
                        //                        STUDENT_ID = @STUDENT_ID  AND IS_DELETED != 1;";
                        //var appTypeResult = DapperHandler.FetchAll<dynamic>(appTypeSql, new { STUDENT_ID = studentId, ACADEMIC_YEAR = sAcademicYear }, null).FirstOrDefault();
                        //string applicationTypeId = appTypeResult != null ? Convert.ToString(appTypeResult.APPLICATION_TYPE_ID) : "";

                        // 3. Fetch FEE_MAIN_HEAD_ID and HEAD_ID (HEAD) from fee_main_heads
                        string mainHeadSql = @"
                            SELECT FEE_MAIN_HEAD_ID, HEAD_ID 
                            FROM fee_main_heads 
                            WHERE FREQUENCY_ID = @FREQUENCY_ID 
                              AND APPLICATION_TYPE_ID = @APPLICATION_TYPE_ID 
                              AND ACADEMIC_YEAR = @ACADEMIC_YEAR 
                              AND IS_DELETED != 1";
                        var mainHeadResult = DapperHandler.FetchAll<dynamic>(mainHeadSql, new
                        {
                            FREQUENCY_ID = frequencyId,
                            APPLICATION_TYPE_ID = applicationTypeId,
                            ACADEMIC_YEAR = sAcademicYear
                        }, null).FirstOrDefault();

                        string feeMainHeadId = mainHeadResult != null ? Convert.ToString(mainHeadResult.FEE_MAIN_HEAD_ID) : "";
                        string headId = mainHeadResult != null ? Convert.ToString(mainHeadResult.HEAD_ID) : "";

                        // 4. Fetch AMOUNT from fee_structure using FEE_MAIN_HEAD_ID
                        int feeAmount = 0;
                        if (!string.IsNullOrEmpty(feeMainHeadId))
                        {
                            string feeStructureSql = @"
                                SELECT AMOUNT 
                                FROM fee_structure 
                                WHERE FEE_MAIN_HEAD_ID = @FEE_MAIN_HEAD_ID 
                                  AND ACADEMIC_YEAR = @ACADEMIC_YEAR 
                                  AND IS_DELETED != 1";
                            var feeStructureResult = DapperHandler.FetchAll<dynamic>(feeStructureSql, new
                            {
                                FEE_MAIN_HEAD_ID = feeMainHeadId,
                                ACADEMIC_YEAR = sAcademicYear
                            }, null).FirstOrDefault();

                            if (feeStructureResult != null)
                            {
                                feeAmount = Convert.ToInt32(feeStructureResult.AMOUNT);
                            }
                        }

                        // Fallback if not found in fee_structure
                        if (feeAmount == 0)
                        {
                            string feeSql = @"
                                                SELECT 
                                                    F.AMOUNT
                                                FROM
                                                    ARREAR_COURSE_FEE_SETTING F
                                                        INNER JOIN
                                                    STU_PERSONAL_INFO C ON F.APPLICATION_TYPE = C.APPTYPE_ID
                                                WHERE
                                                    C.STUDENT_ID = @STUDENT_ID
                                                        AND F.IS_ACTIVE = '1'
                                                        AND F.IS_DELETED != 1
                                                        AND C.IS_DELETED != 1;";
                            var feeResult = DapperHandler.FetchAll<dynamic>(feeSql, new { STUDENT_ID = studentId }, null).FirstOrDefault();
                            feeAmount = feeResult != null ? Convert.ToInt32(feeResult.AMOUNT) : 0;
                        }

                        // 5. Insert/Update FEE_STUDENT_ACCOUNT
                        if (feeAmount > 0 && !string.IsNullOrEmpty(frequencyId) && !string.IsNullOrEmpty(headId))
                        {
                            string checkAccountSql = @"
                                SELECT F_STUDENT_AC_ID, CREDIT 
                                FROM FEE_STUDENT_ACCOUNT 
                                WHERE STUDENT_ID = @STUDENT_ID 
                                  AND ACADEMIC_YEAR = @ACADEMIC_YEAR 
                                  AND FREQUENCY_ID = @FREQUENCY_ID 
                                  AND HEAD = @HEAD 
                                  AND FEE_MAIN_HEAD_ID = @FEE_MAIN_HEAD_ID";
                            var accountResult = DapperHandler.FetchAll<dynamic>(checkAccountSql, new
                            {
                                STUDENT_ID = studentId,
                                ACADEMIC_YEAR = sAcademicYear,
                                FREQUENCY_ID = frequencyId,
                                HEAD = headId,
                                FEE_MAIN_HEAD_ID = feeMainHeadId
                            }, null).FirstOrDefault();

                            if (accountResult == null)
                            {
                                if (Action == "REGISTER")
                                {
                                    string insertSql = @"
                                        INSERT INTO FEE_STUDENT_ACCOUNT 
                                        (STUDENT_ID, ACADEMIC_YEAR, FREQUENCY_ID, HEAD, CREDIT, DEBIT, FEE_MAIN_HEAD_ID) 
                                        VALUES (?STUDENT_ID, ?ACADEMIC_YEAR, ?FREQUENCY_ID, ?HEAD, ?CREDIT, 0, ?FEE_MAIN_HEAD_ID)";
                                    CMSHandler.SaveOrUpdate(new
                                    {
                                        STUDENT_ID = studentId,
                                        ACADEMIC_YEAR = sAcademicYear,
                                        FREQUENCY_ID = frequencyId,
                                        HEAD = headId,
                                        CREDIT = feeAmount.ToString(),
                                        FEE_MAIN_HEAD_ID = feeMainHeadId
                                    }, insertSql);
                                }
                            }
                            else
                            {
                                int currentCredit = accountResult.CREDIT != null ? Convert.ToInt32(accountResult.CREDIT) : 0;
                                int newCredit = Action == "REGISTER" ? currentCredit + feeAmount : currentCredit - feeAmount;
                                if (newCredit < 0) newCredit = 0;

                                string updateAccountSql = @"
                                    UPDATE FEE_STUDENT_ACCOUNT 
                                    SET CREDIT = ?CREDIT 
                                    WHERE F_STUDENT_AC_ID = ?F_STUDENT_AC_ID";
                                CMSHandler.SaveOrUpdate(new
                                {
                                    CREDIT = newCredit.ToString(),
                                    F_STUDENT_AC_ID = Convert.ToString(accountResult.F_STUDENT_AC_ID)
                                }, updateAccountSql);
                            }
                        }
                    }
                }

                ObjJsonData.sResult = resultArgs.Success ? "True" : "False";
                ObjJsonData.Message = resultArgs.Success ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                ObjJsonData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
            }
            catch (Exception ex)
            {
                ObjJsonData.sResult = "False";
                ObjJsonData.Message = ex.Message;
                ObjJsonData.ErrorCode = Common.ErrorCode.ExpectationFailed;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

