        [HttpPost]
        public JsonResult GetArrearRegistrations(string sFromDate, string sToDate)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (string.IsNullOrEmpty(sAcademicYear) || string.IsNullOrEmpty(sFromDate) || string.IsNullOrEmpty(sToDate))
            {
                return Json(new { Success = false, Message = "Missing required parameters" }, JsonRequestBehavior.AllowGet);
            }

            try
            {

                string fromDateParam = CommonMethods.DateConvertionForPayU(sFromDate);
                string toDateParam = CommonMethods.DateConvertionForPayU(sToDate);

                string classSummarySql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearClassSummaryReport)
                    .Replace("?FROM_DATE", "'" + fromDateParam + "'")
                    .Replace("?TO_DATE", "'" + toDateParam + "'");

                string courseSummarySql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearCourseSummaryReport)
                    .Replace("?FROM_DATE", "'" + fromDateParam + "'")
                    .Replace("?TO_DATE", "'" + toDateParam + "'");

                string detailedSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearDetailedReport)
                    .Replace("?FROM_DATE", "'" + fromDateParam + "'")
                    .Replace("?TO_DATE", "'" + toDateParam + "'");

                var classSummaryResult = CMSHandler.FetchData<ArrearClassSummaryModel>(
                    null,
                    classSummarySql,
                    sAcademicYear);
                var classSummary = classSummaryResult.Success ? (List<ArrearClassSummaryModel>)classSummaryResult.DataSource.Data : new List<ArrearClassSummaryModel>();

                var courseSummaryResult = CMSHandler.FetchData<ArrearCourseSummaryModel>(
                    null,
                    courseSummarySql,
                    sAcademicYear);
                var courseSummary = courseSummaryResult.Success ? (List<ArrearCourseSummaryModel>)courseSummaryResult.DataSource.Data : new List<ArrearCourseSummaryModel>();

                var detailedResult = CMSHandler.FetchData<ArrearDetailedRegistrationModel>(
                    null,
                    detailedSql,
                    sAcademicYear);
                var detailedRegistrations = detailedResult.Success ? (List<ArrearDetailedRegistrationModel>)detailedResult.DataSource.Data : new List<ArrearDetailedRegistrationModel>();

                return Json(new
                {
                    Success = true,
                    ClassSummary = classSummary,
                    CourseSummary = courseSummary,
                    Detailed = detailedRegistrations
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("Examination", "GetArrearRegistrations", ex.Message);
                }
                return Json(new { Success = false, Message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        public JsonResult GetArrearCourseWiseSummary()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (string.IsNullOrEmpty(sAcademicYear))
                return Json(new { Success = false, Message = "Academic year session expired." }, JsonRequestBehavior.AllowGet);
            try
            {
                string sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearCourseWiseSummary)
                    .Replace("?AC_YEAR", "'" + sAcademicYear + "'");
                var result = CMSHandler.FetchData<ArrearCourseWiseSummaryModel>(null, sql, sAcademicYear);
                var data = result.Success ? (List<ArrearCourseWiseSummaryModel>)result.DataSource.Data : new List<ArrearCourseWiseSummaryModel>();
                return Json(new { Success = true, Data = data }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                    objHandler.WriteError("Examination", "GetArrearCourseWiseSummary", ex.Message);
                return Json(new { Success = false, Message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        public JsonResult GetArrearStudentsByCourse(string sCourseCode)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (string.IsNullOrEmpty(sAcademicYear) || string.IsNullOrEmpty(sCourseCode))
                return Json(new { Success = false, Message = "Missing required parameters." }, JsonRequestBehavior.AllowGet);
            try
            {
                string sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearStudentsByCourse)
                    .Replace("?AC_YEAR", "'" + sAcademicYear + "'")
                    .Replace("?COURSE_CODE", "'" + sCourseCode.Replace("'", "''") + "'");
                var result = CMSHandler.FetchData<ArrearStudentByCourseModel>(null, sql, sAcademicYear);
                var data = result.Success ? (List<ArrearStudentByCourseModel>)result.DataSource.Data : new List<ArrearStudentByCourseModel>();
                return Json(new { Success = true, Data = data }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                    objHandler.WriteError("Examination", "GetArrearStudentsByCourse", ex.Message);
                return Json(new { Success = false, Message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

