        public ActionResult ArrearExamRegistrationReceiptForStudent()
        {
            string sUserId = string.Empty;
            if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
            {
                sUserId = Session[Common.SESSION_VARIABLES.USER_ID].ToString();
            }
            else if (Session["USER_ID"] != null)
            {
                sUserId = Session["USER_ID"].ToString();
            }
            else
            {
                sUserId = "237";
            }

            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (string.IsNullOrEmpty(sAcademicYear))
            {
                sAcademicYear = "2025-2026";
            }

            ViewBag.StudentId = sUserId;
            ViewBag.AcademicYear = sAcademicYear;

            try
            {
                string sSql1 = SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentDetailsByStudentId);
                var liStudentPersonalInfo = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(null, sSql1.Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;

                if (liStudentPersonalInfo != null && liStudentPersonalInfo.Count > 0)
                {
                    var student = liStudentPersonalInfo.FirstOrDefault();
                    ViewBag.StudentName = (student.FIRST_NAME + " " + student.LAST_NAME).Trim();
                    ViewBag.RegisterNumber = !string.IsNullOrEmpty(student.REGISTER_NO) ? student.REGISTER_NO : student.ROLL_NO;
                    ViewBag.ClassName = student.CLASS_NAME;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("Examination", "ArrearExamRegistrationReceiptForStudent_FetchStudent", ex.Message);
                }
            }

            if (ViewBag.StudentName == null) ViewBag.StudentName = Session[Common.SESSION_VARIABLES.USER_NAME] != null ? Session[Common.SESSION_VARIABLES.USER_NAME].ToString() : "Student Portal";
            if (ViewBag.RegisterNumber == null) ViewBag.RegisterNumber = "23UCO101";
            if (ViewBag.ClassName == null) ViewBag.ClassName = "III B.Com. A";

            List<FEE_TRANSACTION> listReceipts = new List<FEE_TRANSACTION>();
            try
            {
                string sqlReceipts = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchArrearExamReceiptsByStudentId)
                    .Replace("?STUDENT_ID", sUserId);

                var result = CMSHandler.FetchData<FEE_TRANSACTION>(null, sqlReceipts, sAcademicYear);
                if (result.Success && result.DataSource.Data != null)
                {
                    listReceipts = (List<FEE_TRANSACTION>)result.DataSource.Data;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("Examination", "ArrearExamRegistrationReceiptForStudent_FetchReceipts", ex.Message);
                }
            }

            var objViewModel = new ExaminationViewModel();
            objViewModel.liFeeTransaction = listReceipts;

            return View(objViewModel);
        }

        public ActionResult DownloadFeeReceiptPDF(string sFrequencyId, string sStudentId, string sTransactionId)
        {
            FeeTransactionViewModel objViewModel = new FeeTransactionViewModel();
            try
            {
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
                if (string.IsNullOrEmpty(sAcademicYear))
                {
                    sAcademicYear = "2025-2026";
                }

                var objFeeStudentAccountModel = new FEE_STUDENT_ACCOUNT();
                objFeeStudentAccountModel.FREQUENCY_ID = sFrequencyId;
                objFeeStudentAccountModel.STUDENT_ID = sStudentId;
                objFeeStudentAccountModel.TRANSACTION_ID = sTransactionId;

                // 1. Fetch transaction details first to obtain actual student ID
                var FetchTotalBalance = (List<FEE_TRANSACTION>)CMSHandler.FetchData<FEE_TRANSACTION>(objFeeStudentAccountModel,
                    FeeSQL.GetFeeSQL(FeeSQLCommands.FetchTotalDebitByTransactionId)).DataSource.Data;

                if (FetchTotalBalance != null && FetchTotalBalance.Count > 0)
                {
                    objViewModel.liFeeTransaction = FetchTotalBalance;
                    string actualStudentId = FetchTotalBalance.FirstOrDefault().STUDENT_ID;
                    if (!string.IsNullOrEmpty(actualStudentId))
                    {
                        objFeeStudentAccountModel.STUDENT_ID = actualStudentId;
                    }
                }

                // 2. Fetch other details using the verified actual student ID
                var FetchCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                    ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;

                var FetchStudentInfo = (List<Student_Personal_Info>)CMSHandler.FetchData<Student_Personal_Info>(objFeeStudentAccountModel,
                    SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentInfoByStudentId), sAcademicYear).DataSource.Data;

                var FetchFeeStudentAccount = (List<FEE_STUDENT_ACCOUNT>)CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(objFeeStudentAccountModel,
                    FeeSQL.GetFeeSQL(FeeSQLCommands.FetchFeeStudentAccountByTransactionId), sAcademicYear).DataSource.Data;

                if (FetchCollegeDetails != null && FetchCollegeDetails.Count > 0)
                    objViewModel.liCollegeDetails = FetchCollegeDetails;
                if (FetchStudentInfo != null && FetchStudentInfo.Count > 0)
                    objViewModel.lstStudentPersonalInfo = FetchStudentInfo;
                if (FetchFeeStudentAccount != null && FetchFeeStudentAccount.Count > 0)
                    objViewModel.liFeeStudentAccount = FetchFeeStudentAccount;
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("Examination", "DownloadFeeReceiptPDF", ex.Message);
                }
            }

            var pdfResult = new Rotativa.ViewAsPdf("~/Views/Examination/GenerateArrearExamReceiptPDF.cshtml", objViewModel)
            {
                FileName = "Receipt_" + sTransactionId + ".pdf"
            };
            return pdfResult;
        }
