        #region Exam Fee Payment & Outstanding Due Enforcement
        public ActionResult PayExamFee(string sExamSettingId = null)
        {
            var viewModel = new ExamFeePaymentViewModel();
            try
            {
                if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] == null)
                {
                    return RedirectToAction("ErrorMessage", "Error");
                }

                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                string sUserId = Session[Common.SESSION_VARIABLES.USER_ID] != null ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

                if (string.IsNullOrEmpty(sUserId))
                {
                    return RedirectToAction("ErrorMessage", "Error");
                }

                // 1. Resolve Exam Setting (if not provided, fetch latest active)
                if (string.IsNullOrEmpty(sExamSettingId))
                {
                    var activeSettings = DapperHandler.FetchAll<EXAM_SETTING>(
                        "SELECT EXAM_SETTING_ID, EXAM_NAME FROM EXAM_SETTING WHERE IS_ACTIVE = 1 AND IS_DELETED <> 1 ORDER BY EXAM_SETTING_ID DESC LIMIT 1;");
                    if (activeSettings != null && activeSettings.Count > 0)
                    {
                        sExamSettingId = activeSettings[0].EXAM_SETTING_ID;
                        viewModel.ExamSettingName = activeSettings[0].EXAM_NAME;
                    }
                }
                else
                {
                    var settingList = DapperHandler.FetchAll<EXAM_SETTING>(
                        "SELECT EXAM_SETTING_ID, EXAM_NAME FROM EXAM_SETTING WHERE EXAM_SETTING_ID = @ID LIMIT 1;",
                        new { ID = sExamSettingId });
                    if (settingList != null && settingList.Count > 0)
                    {
                        viewModel.ExamSettingName = settingList[0].EXAM_NAME;
                    }
                }
                viewModel.ExamSettingId = sExamSettingId;
                viewModel.AcademicYear = sAcademicYear;

                // 2. Fetch Student Profile Details
                string studentSql = @"
                    SELECT 
                        SPI.STUDENT_ID, SPI.ROLL_NO, SPI.REGISTER_NO,
                        CONCAT(IFNULL(SPI.FIRST_NAME, ''), ' ', IFNULL(SPI.LAST_NAME, '')) AS FULL_NAME,
                        CC.CLASS_NAME
                    FROM STU_PERSONAL_INFO SPI
                    LEFT JOIN STU_CLASS SC ON SC.STUDENT_ID = SPI.STUDENT_ID AND SC.IS_DELETED <> 1 AND SC.ACADEMIC_YEAR = @AC_YEAR
                    LEFT JOIN CP_CLASSES CC ON CC.CLASS_ID = SC.CLASS_ID
                    WHERE (SPI.STUDENT_ID = @STU_ID OR SPI.ROLL_NO = @STU_ID OR SPI.REGISTER_NO = @STU_ID)
                      AND SPI.IS_DELETED <> 1
                    LIMIT 1;";

                var studentInfoList = DapperHandler.FetchAll<dynamic>(studentSql, new { STU_ID = sUserId, AC_YEAR = sAcademicYear });
                if (studentInfoList != null && studentInfoList.Count > 0)
                {
                    var stu = studentInfoList[0];
                    viewModel.StudentId = Convert.ToString(stu.STUDENT_ID);
                    viewModel.RollNo = Convert.ToString(stu.ROLL_NO);
                    viewModel.RegisterNo = Convert.ToString(stu.REGISTER_NO);
                    viewModel.StudentName = Convert.ToString(stu.FULL_NAME);
                    viewModel.ClassName = Convert.ToString(stu.CLASS_NAME);
                }
                else
                {
                    viewModel.StudentId = sUserId;
                }

                // 3. Fetch College Details
                var collegeList = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(
                    null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;
                viewModel.CollegeInfo = collegeList != null ? collegeList.FirstOrDefault() : null;

                // 4. Calculate Outstanding Fee Dues (College, Hostel, Bus, Old/Arrear)
                var dueSummary = FeeDueHelper.GetStudentFeeDueSummary(viewModel.StudentId, sAcademicYear);
                viewModel.StudentDues = dueSummary;
                viewModel.HasOutstandingDues = dueSummary.HasDues;

                // 5. Check Active Permission Bypass
                viewModel.HasActivePermission = FeeDueHelper.HasActiveExamFeePermission(viewModel.StudentId, sExamSettingId, sAcademicYear);
                if (viewModel.HasActivePermission)
                {
                    var permList = FeeDueHelper.GetPermissions(sAcademicYear, sExamSettingId, viewModel.StudentId);
                    viewModel.ActivePermission = permList != null ? permList.FirstOrDefault() : null;
                }

                // 6. Fetch Exam Fee Heads for this student from FEE_STUDENT_ACCOUNT
                List<FEE_STUDENT_ACCOUNT> examFeeAccounts = new List<FEE_STUDENT_ACCOUNT>();

                // First check FEE_STUDENT_ACCOUNT via FetchAllFeeDuesByStudentId (same method used by PayStudentDues)
                var allDuesRes = CMSHandler.FetchData<FEE_STUDENT_ACCOUNT>(
                    new FEE_STUDENT_ACCOUNT() { STUDENT_ID = viewModel.StudentId },
                    FeeSQL.GetFeeSQL(FeeSQLCommands.FetchAllFeeDuesByStudentId),
                    sAcademicYear);

                if (allDuesRes != null && allDuesRes.DataSource != null && allDuesRes.DataSource.Data != null)
                {
                    var allList = (List<FEE_STUDENT_ACCOUNT>)allDuesRes.DataSource.Data;
                    var examDues = allList.Where(x => x.FREQUENCY_TYPE_ID == Common.FrequencyType.ExamFee).ToList();
                    if (examDues != null && examDues.Count > 0)
                    {
                        examFeeAccounts.AddRange(examDues);
                    }
                }

                // If not found via FetchAllFeeDuesByStudentId, query FEE_STUDENT_ACCOUNT directly for exam fee accounts
                if (examFeeAccounts.Count == 0)
                {
                    string fsaDirectSql = @"
                        SELECT 
                            FS.FREQUENCY_ID,
                            FS.STUDENT_ID,
                            SUM(IFNULL(FS.CREDIT, 0) - IFNULL(FS.DEBIT, 0)) AS BALANCE,
                            SUM(IFNULL(FS.DEBIT, 0)) AS DEBIT,
                            SUM(IFNULL(FS.CREDIT, 0)) AS CREDIT,
                            MAX(FS.TRANSACTION_ID) AS TRANSACTION_ID,
                            IFNULL(H.HEAD, 'Exam Fee') AS HEAD,
                            IFNULL(H.HEAD, 'Exam Fee') AS HEAD_NAME,
                            H.HEAD_ID,
                            FS.ACADEMIC_YEAR,
                            IFNULL(FS.FEE_ROOT_ID, '1') AS FEE_ROOT_ID,
                            '1' AS FREQUENCY_TYPE_ID,
                            'Exam Fee' AS FREQUENCY_TYPE
                        FROM FEE_STUDENT_ACCOUNT FS
                        INNER JOIN SUP_HEAD H ON H.HEAD_ID = FS.HEAD
                        WHERE FS.STUDENT_ID = @STUDENT_ID 
                          AND FS.IS_DELETED != 1
                          AND (FS.FREQUENCY_ID IN (SELECT FEE_FREQUENCY_FEE_MODE_ID FROM FEE_FREQUENCY_FEE_MODE WHERE FEE_MODE = '1')
                               OR FS.FREQUENCY_ID = '1'
                               OR H.HEAD LIKE '%EXAM%')
                        GROUP BY FS.STUDENT_ID, FS.FREQUENCY_ID, FS.HEAD;";

                    var directList = DapperHandler.FetchAll<FEE_STUDENT_ACCOUNT>(fsaDirectSql, new { STUDENT_ID = viewModel.StudentId });
                    if (directList != null && directList.Count > 0)
                    {
                        examFeeAccounts.AddRange(directList);
                    }
                }

                // If still not found, check EXAM_HEADS configuration
                if (examFeeAccounts.Count == 0)
                {
                    string examHeadsSql = @"
                        SELECT 
                            FM.FEE_MAIN_HEAD_ID,
                            FM.FREQUENCY_ID,
                            FM.ACADEMIC_YEAR,
                            SH.HEAD_ID,
                            SH.HEAD AS HEAD_NAME,
                            SH.HEAD,
                            EH.COST AS CREDIT,
                            0 AS DEBIT,
                            EH.COST AS BALANCE
                        FROM FEE_MAIN_HEADS FM
                        INNER JOIN EXAM_HEADS EH ON EH.ACADEMIC_YEAR = FM.ACADEMIC_YEAR
                            AND EH.FREQUENCY_ID = FM.FREQUENCY_ID
                            AND EH.FEE_MAIN_HEAD_ID = FM.FEE_MAIN_HEAD_ID
                        INNER JOIN SUP_HEAD SH ON SH.HEAD_ID = FM.HEAD_ID
                        INNER JOIN STU_CLASS SC ON SC.ACADEMIC_YEAR = FM.ACADEMIC_YEAR
                            AND SC.STUDENT_ID = @STUDENT_ID
                            AND SC.IS_DELETED <> 1
                        INNER JOIN CP_PROGRAMME_GROUP CP ON CP.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                            AND CP.SHIFT = EH.SHIFT_ID
                            AND CP.APPTYPE_ID = EH.PROGRAMME_TYPE_ID
                        INNER JOIN CP_CLASSES CC ON CC.CLASS_ID = SC.CLASS_ID
                            AND CC.CLASS_YEAR = EH.PROGRAMME_LEVEL_ID
                        WHERE FM.IS_DELETED <> 1
                          AND FM.FREQUENCY_ID IN (
                              SELECT FREQUENCY_ID FROM FEE_FREQUENCY_FEE_MODE 
                              WHERE FEE_MODE = '1' AND ACADEMIC_YEAR = @AC_YEAR
                          );";

                    var headsDynamic = DapperHandler.FetchAll<dynamic>(examHeadsSql, new { STUDENT_ID = viewModel.StudentId, AC_YEAR = sAcademicYear });
                    if (headsDynamic != null && headsDynamic.Count > 0)
                    {
                        foreach (var hd in headsDynamic)
                        {
                            examFeeAccounts.Add(new FEE_STUDENT_ACCOUNT
                            {
                                STUDENT_ID = viewModel.StudentId,
                                HEAD_ID = Convert.ToString(hd.HEAD_ID),
                                HEAD = Convert.ToString(hd.HEAD),
                                HEAD_NAME = Convert.ToString(hd.HEAD_NAME),
                                CREDIT = Convert.ToString(hd.CREDIT),
                                DEBIT = "0",
                                BALANCE = Convert.ToString(hd.BALANCE),
                                FREQUENCY_ID = Convert.ToString(hd.FREQUENCY_ID),
                                ACADEMIC_YEAR = Convert.ToString(hd.ACADEMIC_YEAR),
                                FREQUENCY_TYPE_ID = Common.FrequencyType.ExamFee,
                                FEE_ROOT_ID = Common.FeeRoot.CollegeFee
                            });
                        }
                    }
                }

                // Check if any transaction has already paid these heads
                string paidTxnSql = @"
                    SELECT 
                        FT.TRANSACTION_ID,
                        FT.RECEIPT_NO,
                        FC.HEAD,
                        FC.PAID_AMOUNT
                    FROM FEE_TRANSACTION FT
                    INNER JOIN FEE_COLLECTION FC ON FC.TRANSACTION_ID = FT.TRANSACTION_ID AND FC.IS_DELETED <> 1
                    INNER JOIN FEE_FREQUENCY_FEE_MODE FFF ON FFF.FREQUENCY_ID = FT.FREQUENCY AND FFF.FEE_MODE = '1'
                    WHERE FT.STUDENT_ID = @STUDENT_ID
                      AND FT.IS_DELETED <> 1;";

                var paidTxns = DapperHandler.FetchAll<dynamic>(paidTxnSql, new { STUDENT_ID = viewModel.StudentId });
                if (paidTxns != null && paidTxns.Count > 0)
                {
                    foreach (var acc in examFeeAccounts)
                    {
                        var match = paidTxns.FirstOrDefault(p => Convert.ToString(p.HEAD) == acc.HEAD_ID || Convert.ToString(p.HEAD) == acc.HEAD);
                        if (match != null)
                        {
                            acc.TRANSACTION_ID = Convert.ToString(match.TRANSACTION_ID);
                            acc.RECEIPT_NO = Convert.ToString(match.RECEIPT_NO);
                            acc.DEBIT = Convert.ToString(match.PAID_AMOUNT);
                            acc.BALANCE = "0";
                        }
                    }
                }

                // Fallback: If still no accounts in FEE_STUDENT_ACCOUNT or EXAM_HEADS, load from EXAM_REGISTRATION preview
                // but resolve dynamic HEAD from SUP_HEAD and active FREQUENCY_ID from FEE_FREQUENCY_FEE_MODE
                if (examFeeAccounts.Count == 0)
                {
                    var previewList = (List<FetchHallTicket>)CMSHandler.FetchData<FetchHallTicket>(
                        new GET_ACTIVE_SEMESTER_BATCH { STUDENT_ID = viewModel.StudentId },
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketListPreview),
                        sAcademicYear).DataSource.Data;

                    if (previewList != null && previewList.Count > 0)
                    {
                        string firstAmtStr = previewList.FirstOrDefault(x => !string.IsNullOrEmpty(x.AMOUNT) && x.AMOUNT != "0")?.AMOUNT
                                             ?? previewList.FirstOrDefault()?.AMOUNT ?? "0";
                        double parsedAmt = 0;
                        double.TryParse(firstAmtStr, out parsedAmt);
                        if (parsedAmt > 0)
                        {
                            var examHeadRow = DapperHandler.FetchAll<dynamic>(
                                "SELECT HEAD_ID, HEAD FROM SUP_HEAD WHERE HEAD LIKE '%EXAM%' AND IS_DELETED != 1 ORDER BY HEAD_ID ASC LIMIT 1;");
                            string resolvedHeadId = examHeadRow != null && examHeadRow.Count > 0 ? Convert.ToString(examHeadRow[0].HEAD_ID) : "1";
                            string resolvedHeadName = examHeadRow != null && examHeadRow.Count > 0 ? Convert.ToString(examHeadRow[0].HEAD) : "Examination Fee";

                            var freqRow = DapperHandler.FetchAll<dynamic>(
                                "SELECT FEE_FREQUENCY_FEE_MODE_ID FROM FEE_FREQUENCY_FEE_MODE WHERE FEE_MODE = '1' AND IS_DELETED != 1 ORDER BY FEE_FREQUENCY_FEE_MODE_ID DESC LIMIT 1;");
                            string resolvedFreqId = freqRow != null && freqRow.Count > 0 ? Convert.ToString(freqRow[0].FEE_FREQUENCY_FEE_MODE_ID) : "1";

                            examFeeAccounts.Add(new FEE_STUDENT_ACCOUNT
                            {
                                STUDENT_ID = viewModel.StudentId,
                                HEAD = resolvedHeadName,
                                HEAD_NAME = resolvedHeadName,
                                HEAD_ID = resolvedHeadId,
                                BALANCE = parsedAmt.ToString("0.00"),
                                CREDIT = parsedAmt.ToString("0.00"),
                                DEBIT = "0",
                                FREQUENCY_ID = resolvedFreqId,
                                FREQUENCY_TYPE_ID = Common.FrequencyType.ExamFee,
                                FEE_ROOT_ID = Common.FeeRoot.CollegeFee,
                                ACADEMIC_YEAR = sAcademicYear
                            });
                        }
                    }
                }

                viewModel.ExamFeeAccounts = examFeeAccounts
                    .OrderBy(s => (Convert.ToDouble(string.IsNullOrEmpty(s.BALANCE) ? "0" : s.BALANCE) <= 0 ? 1 : 0))
                    .ThenBy(s => s.HEAD)
                    .ToList();

                viewModel.TotalExamFee = viewModel.ExamFeeAccounts.Sum(a =>
                {
                    decimal bal = 0;
                    decimal.TryParse(a.BALANCE, out bal);
                    return bal;
                });
            }
            catch (Exception ex)
            {
                using (ErrorLog log = new ErrorLog())
                {
                    log.WriteError("ExaminationController", "PayExamFee", ex.Message);
                }
            }

            return View(viewModel);
        }

        [HttpGet]
        public JsonResult GetExamFeeReceipt(string transactionId)
        {
            try
            {
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR]?.ToString() ?? "";
                string sUserId = Session[Common.SESSION_VARIABLES.USER_ID]?.ToString() ?? "";

                if (string.IsNullOrEmpty(sUserId) || string.IsNullOrEmpty(transactionId))
                {
                    return Json(new { status = false, Message = "Invalid request or session expired." }, JsonRequestBehavior.AllowGet);
                }

                // 1. Fetch College Details
                var collegeDetailsList = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(
                    null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;
                var collegeDetails = collegeDetailsList?.FirstOrDefault();

                // 2. Fetch Student Info
                var studentInfoList = DapperHandler.FetchAll<dynamic>(
                    "SELECT FIRST_NAME, LAST_NAME, REGISTER_NO, ROLL_NO FROM STU_PERSONAL_INFO WHERE (STUDENT_ID = @STUDENT_ID OR ROLL_NO = @STUDENT_ID) LIMIT 1",
                    new { STUDENT_ID = sUserId });
                var student = studentInfoList?.FirstOrDefault();

                // 3. Fetch Transaction Info
                var transactionList = DapperHandler.FetchAll<dynamic>(
                    "SELECT TRANSACTION_ID, RECEIPT_NO, COLLECTED, DATE_FORMAT(PAYMENT_DATE, '%d/%m/%Y') AS PAYMENT_DATE, PAYMENT_MODE, CF_ORDER_ID FROM FEE_TRANSACTION WHERE TRANSACTION_ID = @TRANSACTION_ID",
                    new { TRANSACTION_ID = transactionId });
                var transaction = transactionList?.FirstOrDefault();

                if (transaction == null)
                {
                    return Json(new { status = false, Message = "Transaction details not found." }, JsonRequestBehavior.AllowGet);
                }

                // 4. Fetch Fee Breakdowns for this transaction
                string breakdownSql = @"
                    SELECT 
                        FC.PAID_AMOUNT, 
                        H.HEAD AS HEAD_NAME
                    FROM FEE_COLLECTION FC
                    INNER JOIN SUP_HEAD H ON H.HEAD_ID = FC.HEAD
                    WHERE FC.TRANSACTION_ID = @TRANSACTION_ID 
                      AND FC.IS_DELETED <> 1;";

                var breakdowns = DapperHandler.FetchAll<dynamic>(breakdownSql, new { TRANSACTION_ID = transactionId });

                return Json(new
                {
                    status = true,
                    college = new
                    {
                        name = collegeDetails?.COLLEGE_NAME,
                        address = collegeDetails?.COLLEGE_ADDRESS,
                        phone = "",
                        email = ""
                    },
                    student = new
                    {
                        name = student != null ? (Convert.ToString(student.FIRST_NAME) + " " + Convert.ToString(student.LAST_NAME)).Trim() : "",
                        registerNo = student != null ? Convert.ToString(student.REGISTER_NO) : "",
                        rollNo = student != null ? Convert.ToString(student.ROLL_NO) : ""
                    },
                    payment = new
                    {
                        transactionId = Convert.ToString(transaction.TRANSACTION_ID),
                        receiptNo = Convert.ToString(transaction.RECEIPT_NO),
                        amount = Convert.ToString(transaction.COLLECTED),
                        date = Convert.ToString(transaction.PAYMENT_DATE),
                        mode = Convert.ToString(transaction.PAYMENT_MODE),
                        orderId = Convert.ToString(transaction.CF_ORDER_ID)
                    },
                    items = breakdowns
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "GetExamFeeReceipt", ex.Message);
                }
                return Json(new { status = false, Message = "Error loading receipt details." }, JsonRequestBehavior.AllowGet);
            }
        }

        // Staff Permission Management Actions
        public ActionResult ExamFeePaymentPermission()
        {
            try
            {
                if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] == null)
                {
                    return RedirectToAction("ErrorMessage", "Error");
                }

                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();

                var academicYears = (List<AcademicYearModel>)CMSHandler.FetchData<AcademicYearModel>(
                    null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList)).DataSource.Data;
                ViewBag.AcademicYears = new SelectList(academicYears ?? new List<AcademicYearModel>(), "AC_YEAR", "AC_YEAR", sAcademicYear);
                ViewBag.DefaultAcademicYear = sAcademicYear;

                var examSettings = FeeDueHelper.GetExamSettingsByAcademicYear(sAcademicYear);
                ViewBag.ExamSettings = new SelectList(examSettings ?? new List<EXAM_SETTING>(), "EXAM_SETTING_ID", "EXAM_NAME");

                return View();
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("ExaminationController", "ExamFeePaymentPermission", ex.Message);
                }
                return RedirectToAction("ErrorMessage", "Error");
            }
        }

