        [HttpPost]
        public JsonResult SaveExamFeePermission(EXAM_FEE_PERMISSION model)
        {
            try
            {
                if (model == null || string.IsNullOrWhiteSpace(model.student_id))
                {
                    return Json(new { success = false, message = "Student ID / Roll No is required." });
                }

                string currentUser = Session[Common.SESSION_VARIABLES.USER_ID]?.ToString() ?? "Staff";

                bool result;
                if (model.exam_fee_id > 0)
                {
                    result = FeeDueHelper.UpdatePermission(model);
                }
                else
                {
                    result = FeeDueHelper.SavePermission(model, currentUser);
                }

                if (result)
                {
                    return Json(new { success = true, message = (model.exam_fee_id > 0 ? "Permission updated successfully." : "Permission granted successfully.") });
                }
                else
                {
                    return Json(new { success = false, message = "Unable to save permission record." });
                }
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }

