                }
            }
            return View(objViewModel);
        }

        [HttpPost]
        public JsonResult UploadAttendanceMarkExcel(HttpPostedFileBase excelFile, string academicYear, string semesterType)
        {
            try
            {
                if (excelFile == null || excelFile.ContentLength == 0)
                {
                    return Json(new { success = false, message = "Please select an Excel file to upload." });
                }

                if (string.IsNullOrWhiteSpace(academicYear))
                {
                    return Json(new { success = false, message = "Please select Academic Year." });
                }

                if (string.IsNullOrWhiteSpace(semesterType))
                {
                    return Json(new { success = false, message = "Please select Semester Type." });
                }

                string ext = (!string.IsNullOrEmpty(excelFile.FileName)) ? Path.GetExtension(excelFile.FileName).ToLower() : string.Empty;
                if (ext != ".xlsx" && ext != ".xls")
                {
                    return Json(new { success = false, message = "Invalid file type. Please upload a valid Excel file (.xlsx or .xls)." });
                }

                string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : "0";

                int totalCount = 0;
                int successCount = 0;
                List<string> notFoundRollNos = null;
                string errorMsg = null;

                bool ok = AttendanceMarkHelper.UploadAttendanceMarks(excelFile.InputStream, academicYear, semesterType, sUserId,
                    out totalCount, out successCount, out notFoundRollNos, out errorMsg);

                if (!ok)
                {
                    return Json(new { success = false, message = (!string.IsNullOrEmpty(errorMsg)) ? errorMsg : "Failed to process Excel file." });
                }

                int notFoundCount = (notFoundRollNos != null) ? notFoundRollNos.Count : 0;
                string successMsg = string.Format("Processed {0} records. {1} attendance marks uploaded successfully.", totalCount, successCount);
                if (notFoundCount > 0)
                {
                    successMsg += string.Format(" ({0} roll numbers not found in system).", notFoundCount);
                }

                return Json(new
                {
                    success = true,
                    totalCount = totalCount,
                    successCount = successCount,
                    notFoundCount = notFoundCount,
                    notFoundRollNos = notFoundRollNos,
                    message = successMsg
                });
            }
            catch (Exception ex)
            {
                using (ErrorLog log = new ErrorLog())
                {
                    log.WriteError("ExaminationController", "UploadAttendanceMarkExcel", ex.Message);
                }
                return Json(new { success = false, message = ex.Message });
            }
        }

