        [HttpPost]
        public JsonResult PushAttendanceMarksToCIA(string academicYear, int examSettingId)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(academicYear))
                {
                    return Json(new { success = false, message = "Academic Year is required." });
                }

                if (examSettingId <= 0)
                {
                    return Json(new { success = false, message = "Please select a valid Exam Setting." });
                }

                string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : "0";

                int updatedCount = 0;
                int insertedCount = 0;
                string errorMsg = null;

                bool ok = AttendanceMarkHelper.PushAttendanceMarksToCIA(academicYear, examSettingId, sUserId,
                    out updatedCount, out insertedCount, out errorMsg);

                if (!ok)
                {
                    return Json(new { success = false, message = (!string.IsNullOrEmpty(errorMsg)) ? errorMsg : "Failed to push attendance marks to CIA." });
                }

                int totalPushed = updatedCount + insertedCount;
                string message = string.Format("Attendance marks pushed to CIA successfully!\n\nRecords Updated: {0}\nRecords Inserted: {1}\nTotal Processed: {2}", updatedCount, insertedCount, totalPushed);

                return Json(new
                {
                    success = true,
                    updatedCount = updatedCount,
                    insertedCount = insertedCount,
                    totalPushed = totalPushed,
                    message = message
                });
            }
            catch (Exception ex)
            {
                using (ErrorLog log = new ErrorLog())
                {
                    log.WriteError("ExaminationController", "PushAttendanceMarksToCIA", ex.Message);
                }
                return Json(new { success = false, message = ex.Message });
            }
        }
